// Italian translations of SAA_QUESTION_BANK, keyed by question id — managed with scripts/translations.js.
// AWS service and feature names stay in English. h = hash of the English text the translation was made from.

const SAA_QUESTION_BANK_IT = {
  "1001": {"h":"930326c2","question":"Un'applicazione di analisi viene eseguita su istanze Amazon EC2 nell'account A e deve leggere oggetti da un bucket Amazon S3 nell'account B. Il team di sicurezza vieta credenziali a lungo termine sulle istanze. Quale soluzione soddisferà questi requisiti nel modo PIÙ sicuro?","options":["Creare un utente IAM nell'account B e memorizzarne le access key nel file di configurazione dell'applicazione.","Creare un IAM role nell'account B che consideri attendibile l'account A e consentire al ruolo dell'istanza di assumerlo.","Rendere pubblico il bucket e limitare le letture con una condizione della bucket policy sugli indirizzi IP delle istanze.","Memorizzare le access key di un utente IAM dell'account B in AWS Secrets Manager e recuperarle all'avvio dell'istanza."],"explanation":"Un IAM role cross-account nell'account B che considera attendibile l'account A (con il ruolo dell'istanza autorizzato a chiamare sts:AssumeRole) fornisce all'applicazione credenziali temporanee a scadenza automatica, con accesso al bucket secondo il privilegio minimo. Memorizzare le chiavi di un utente IAM in Secrets Manager sembra sicuro, ma si basa comunque su credenziali a lungo termine, vietate dal requisito.","optionExplanations":["Questo colloca credenziali a lungo termine sulle istanze, cosa esplicitamente vietata dal team di sicurezza.","Corretto — l'instance profile fornisce credenziali temporanee e l'assunzione di un ruolo cross-account nell'account B restituisce credenziali di breve durata limitate al bucket.","Rendere pubblico il bucket è un'esposizione grave e le condizioni basate sull'IP sono un controllo debole rispetto ai principal IAM.","Secrets Manager protegge le chiavi a riposo, ma restano credenziali a lungo termine di un utente IAM usate dalle istanze."]},
  "1002": {"h":"3d4ffea8","question":"Un'azienda ha 40 account AWS in AWS Organizations. I dipendenti si autenticano già con Microsoft Entra ID. L'azienda vuole che i dipendenti usino il single sign-on per accedere a qualsiasi account a cui hanno diritto, con permessi gestiti centralmente. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Abilitare IAM Identity Center, collegare Entra ID come identity provider esterno e assegnare permission set ai gruppi.","Creare utenti IAM in ogni account e sincronizzarne le password con una funzione AWS Lambda pianificata.","Configurare un identity provider SAML e i relativi IAM role separatamente in ciascuno dei 40 account membri.","Distribuire AWS Managed Microsoft AD in ogni account e creare una relazione di trust con la directory aziendale."],"explanation":"IAM Identity Center è il metodo consigliato per offrire al personale il single sign-on su tutti gli account di un'organizzazione; si federa con Entra ID e gestisce centralmente i permission set assegnati ai gruppi. Anche la federazione SAML per singolo account funziona tecnicamente, ma va configurata e mantenuta in tutti i 40 account, con un carico operativo molto maggiore.","optionExplanations":["Corretto — IAM Identity Center si integra con un identity provider esterno SAML/SCIM ed effettua il provisioning dei permission set come ruoli in ogni account assegnato, da un unico punto.","Questo crea migliaia di identità a lungo termine su 40 account e richiede codice di sincronizzazione personalizzato, l'opposto di un basso carico operativo.","Funziona, ma ogni account e ogni ruolo vanno configurati e mantenuti singolarmente anziché centralmente.","Eseguire una directory in ogni account aggiunge costi e lavoro di gestione e comunque non offre un'assegnazione centralizzata dei permessi."]},
  "1003": {"h":"d72ee263","question":"Un'azienda deve garantire che nessun account della sua organizzazione AWS possa creare risorse in AWS Region al di fuori dell'Unione Europea. Il controllo deve valere anche per gli amministratori degli account membri. Quale soluzione soddisferà questi requisiti?","options":["Associare una IAM policy che neghi le Region extra-UE a ogni utente e ruolo IAM in ciascun account membro.","Distribuire in ogni account regole AWS Config che rilevino le risorse create al di fuori delle Region UE.","Associare alla root dell'organizzazione una SCP che neghi le richieste verso Region al di fuori dell'UE.","Usare AWS CloudTrail con regole Amazon EventBridge che terminino le risorse avviate al di fuori dell'UE."],"explanation":"Una service control policy con un deny su aws:RequestedRegion è un guardrail preventivo che si applica a ogni principal IAM negli account membri, compresi i loro amministratori (i servizi globali vengono di solito esclusi con NotAction). Le IAM policy in ogni account sembrano simili, ma un amministratore dell'account membro potrebbe rimuoverle, quindi non garantiscono la restrizione.","optionExplanations":["Gli amministratori degli account membri possono scollegare o modificare le IAM policy nei propri account, quindi la restrizione non è garantita.","AWS Config è un controllo di rilevamento; segnala le risorse non conformi dopo la loro creazione invece di impedirla.","Corretto — le SCP fissano i permessi massimi per ogni principal negli account membri, amministratori compresi, e non possono essere modificate dall'interno di quegli account.","Si tratta di automazione personalizzata reattiva; le risorse vengono prima create e potrebbero sfuggire o essere ripulite solo in parte."]},
  "1004": {"h":"6158f8c4","question":"Gli sviluppatori devono poter creare IAM role per le proprie funzioni AWS Lambda. Il team di sicurezza deve garantire che qualsiasi ruolo creato da uno sviluppatore non possa mai avere più permessi di un massimo definito, senza approvare manualmente ogni ruolo. Quale soluzione soddisfa questi requisiti?","options":["Concedere agli sviluppatori accesso IAM completo e revisionare ogni settimana i nuovi ruoli tramite i finding di IAM Access Analyzer.","Richiedere agli sviluppatori di inviare le richieste di ruolo al team di sicurezza, che crea manualmente ogni ruolo.","Applicare una SCP che neghi l'azione iam:CreateRole a tutti i principal nell'account di sviluppo.","Consentire la creazione di ruoli solo quando al nuovo ruolo è associato uno specifico permissions boundary."],"explanation":"I permissions boundary consentono di delegare in sicurezza la creazione dei ruoli: la policy degli sviluppatori permette iam:CreateRole solo quando è associato il boundary richiesto, quindi ogni nuovo ruolo è limitato dal boundary a prescindere dalle policy che riceve. Le revisioni settimanali con Access Analyzer intercetterebbero i ruoli con privilegi eccessivi solo a posteriori, senza garantire che non superino mai il massimo.","optionExplanations":["La revisione settimanale è un controllo di rilevamento e ritardato; uno sviluppatore potrebbe creare un ruolo con privilegi eccessivi e usarlo prima della revisione.","Questo viola il requisito di evitare l'approvazione manuale di ogni ruolo e rallenta lo sviluppo.","Questo impedisce agli sviluppatori di creare qualsiasi ruolo, quindi non possono distribuire le loro funzioni.","Corretto — un permissions boundary limita i permessi effettivi di qualsiasi ruolo creato e la condition key iam:PermissionsBoundary obbliga gli sviluppatori ad associarlo."]},
  "1005": {"h":"b8354dd4","question":"Un'applicazione su Amazon EC2 scrive in una tabella Amazon DynamoDB usando access key di un utente IAM memorizzate in un file di configurazione. Un audit ha segnalato questa pratica. Quale soluzione risolverà il rilievo nel modo PIÙ sicuro e con il MINOR carico operativo?","options":["Memorizzare le access key in AWS Secrets Manager con rotazione e recuperarle all'avvio dell'applicazione.","Associare alle istanze, tramite un instance profile, un IAM role con i permessi DynamoDB necessari.","Cifrare il file di configurazione con una chiave AWS KMS e decifrarlo all'avvio dell'applicazione.","Passare le access key tramite lo user data dell'istanza e ruotarle con una funzione AWS Lambda pianificata."],"explanation":"Un IAM role fornito tramite instance profile dà all'applicazione credenziali temporanee che l'AWS SDK recupera e ruota automaticamente, eliminando del tutto le chiavi memorizzate. Memorizzare le chiavi in Secrets Manager con rotazione migliora la gestione, ma usa ancora credenziali di un utente IAM e richiede una rotazione personalizzata, quindi non è né l'opzione più sicura né quella con il minor carico.","optionExplanations":["Questo aggiunge la logica di rotazione ma continua a usare credenziali a lungo termine di un utente IAM, meno sicure e più onerose di un ruolo.","Corretto — l'SDK ottiene e rinnova automaticamente le credenziali temporanee dai metadati dell'istanza, senza chiavi da memorizzare o ruotare.","Le chiavi restano credenziali a lungo termine e ora richiedono anche logica di decifratura aggiuntiva e gestione delle chiavi.","Lo user data è leggibile dall'istanza e non è un archivio di segreti; inoltre le credenziali restano a lungo termine."]},
  "1006": {"h":"4e9e47bf","question":"Un'azienda possiede una funzione AWS Lambda che un'applicazione partner, in esecuzione nell'account AWS del partner, deve invocare direttamente. L'azienda non vuole creare né gestire utenti o ruoli IAM nel proprio account per il partner. Quale soluzione soddisfa questi requisiti?","options":["Creare un utente IAM per il partner nell'account dell'azienda e condividerne in modo sicuro le access key.","Creare un IAM role nell'account dell'azienda che il partner possa assumere per invocare la funzione.","Aggiungere alla resource-based policy della funzione uno statement che consenta all'account del partner di invocarla.","Aggiungere alla policy dell'execution role della funzione uno statement che consenta all'account del partner di invocare la funzione."],"explanation":"Le resource-based policy concedono accesso cross-account direttamente sulla risorsa, quindi aggiungere l'account del partner alla policy della funzione Lambda consente l'invocazione senza nuove identità IAM nell'account dell'azienda. Anche un ruolo cross-account funzionerebbe, ma richiede di creare e mantenere un ruolo, cosa che l'azienda vuole esplicitamente evitare.","optionExplanations":["Questo crea un'identità IAM con credenziali a lungo termine nell'account dell'azienda, vietata dal requisito.","Un ruolo cross-account funziona, ma richiede di creare e gestire un ruolo nell'account dell'azienda.","Corretto — una resource-based policy di Lambda può concedere lambda:InvokeFunction direttamente a un altro account; il partner poi delega quel permesso ai propri principal.","L'execution role definisce cosa può fare la funzione, non chi può invocarla, quindi non può concedere l'invocazione al partner."]},
  "1007": {"h":"837c9d58","question":"Un'azienda vuole che i suoi amministratori svolgano il lavoro di routine in sola lettura senza MFA, ma qualsiasi azione che termini istanze EC2 o elimini bucket S3 deve essere eseguita solo in sessioni autenticate con MFA. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere uno statement di IAM policy che neghi quelle azioni quando aws:MultiFactorAuthPresent è false o assente.","Abilitare l'MFA sul root user e richiedere agli amministratori di accedere come root per le azioni distruttive.","Abilitare MFA Delete su tutti i bucket S3 e la protezione dalla terminazione su tutte le istanze EC2.","Creare una SCP che neghi quelle azioni a tutti i principal in ogni account membro."],"explanation":"Uno statement di deny IAM che usa la condition key aws:MultiFactorAuthPresent (con BoolIfExists) consente agli amministratori di lavorare normalmente ma blocca la terminazione delle istanze e l'eliminazione dei bucket se la sessione non è stata stabilita con MFA. MFA Delete sembra pertinente, ma riguarda solo l'eliminazione definitiva delle versioni degli oggetti e la modifica dello stato del versioning, non l'eliminazione dei bucket o la terminazione di EC2.","optionExplanations":["Corretto — un deny esplicito condizionato alla context key dell'MFA blocca le azioni distruttive se la sessione non è autenticata con MFA, mentre le altre azioni continuano a funzionare.","Usare il root user per l'amministrazione di routine viola le best practice ed elimina la responsabilità individuale.","MFA Delete protegge solo l'eliminazione delle versioni degli oggetti e la protezione dalla terminazione non è legata all'MFA, quindi nessuna delle due impone l'MFA per queste azioni.","Un deny incondizionato blocca le azioni per tutti, compresi gli amministratori che si sono autenticati con MFA."]},
  "1008": {"h":"dc1ec140","question":"Un'azienda sta avviando una strategia multi-account. Ha bisogno di una landing zone con logging centralizzato, provisioning automatizzato degli account e guardrail preventivi e di rilevamento, e vuole essere operativa rapidamente. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Creare gli account con le API di AWS Organizations e scrivere template CloudFormation personalizzati per ogni controllo.","Configurare AWS Control Tower e abilitare i controlli necessari sulle unità organizzative.","Creare gli account manualmente e distribuire conformance pack di AWS Config in ogni account.","Usare un unico account con un VPC separato per ogni team e IAM policy per isolare i workload."],"explanation":"AWS Control Tower è il modo gestito per configurare una landing zone multi-account ben progettata: crea il logging centralizzato, fornisce Account Factory per i nuovi account e offre controlli preventivi (basati su SCP) e di rilevamento (basati su Config). Realizzare lo stesso con le API di Organizations e template personalizzati è possibile, ma richiede molto più lavoro di progettazione e manutenzione.","optionExplanations":["Si può realizzare, ma progettare, codificare e mantenere ogni controllo e la configurazione del logging è un impegno continuo significativo.","Corretto — Control Tower distribuisce una landing zone con account di log archive e di audit, Account Factory per il provisioning e controlli gestiti preventivi e di rilevamento.","La creazione manuale degli account non scala e i conformance pack offrono solo controlli di rilevamento, senza guardrail preventivi.","Questo non crea una landing zone multi-account e offre un isolamento e un contenimento del raggio d'impatto più deboli rispetto ad account separati."]},
  "1009": {"h":"2e61f0d1","question":"Un bucket Amazon S3 contiene dati di riferimento condivisi che ogni account dell'organizzazione AWS dell'azienda deve poter leggere, compresi gli account creati in futuro. Nessun principal esterno all'organizzazione deve poterli leggere. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Elencare ogni ID account nella bucket policy e aggiornare la policy ogni volta che viene aggiunto un account.","Creare un IAM role cross-account nell'account del bucket e far sì che ogni account lo assuma.","Replicare il bucket in ogni account membro con S3 Replication e concedere lì l'accesso locale.","Aggiungere una bucket policy che consenta s3:GetObject quando aws:PrincipalOrgID corrisponde all'ID dell'organizzazione."],"explanation":"La condition key globale aws:PrincipalOrgID consente a un unico statement della bucket policy di concedere l'accesso a tutti i principal dell'organizzazione, così i nuovi account sono coperti automaticamente e gli esterni sono esclusi. Anche elencare gli ID account limita correttamente l'accesso, ma va aggiornato ogni volta che si aggiungono account, aumentando il carico operativo.","optionExplanations":["Funziona, ma richiede una modifica della policy a ogni creazione di account, un impegno manuale continuo e soggetto a errori.","Ogni nuovo account deve essere aggiunto alla trust policy del ruolo e configurato per assumerlo, con un aggravio operativo.","Questo moltiplica i costi di storage e la configurazione della replica per ogni account, compresi quelli futuri.","Corretto — la condizione aws:PrincipalOrgID include automaticamente ogni account attuale e futuro dell'organizzazione ed esclude tutti gli altri."]},
  "1010": {"h":"bbec2dc3","question":"Una revisione di sicurezza di un nuovo account AWS ha rilevato che gli amministratori usano il root user per il lavoro quotidiano e che il root user ha access key attive. Quali azioni dovrebbe raccomandare un solutions architect per seguire le best practice AWS? (Seleziona DUE)","options":["Eliminare le access key del root user e abilitare l'MFA sul root user.","Ruotare regolarmente le access key del root user e memorizzarle in AWS Secrets Manager.","Fornire agli amministratori utenti IAM Identity Center o IAM role per il lavoro quotidiano, riservando il root ai task che lo richiedono.","Associare al root user una IAM policy che neghi tutte le azioni per disabilitarlo in modo permanente.","Consentire l'accesso del root user solo da un bastion host il cui security group ammetta l'intervallo IP aziendale."],"explanation":"AWS raccomanda di eliminare le access key del root user, abilitare l'MFA sul root user e usare IAM Identity Center o IAM role per l'amministrazione quotidiana. Ruotare le chiavi root è una mezza misura allettante, ma le chiavi root non dovrebbero proprio esistere perché danno accesso illimitato all'account.","optionExplanations":["Corretto — le access key del root non dovrebbero esistere e l'MFA protegge l'accesso del root user per i rari task che lo richiedono.","Le access key del root vanno eliminate, non ruotate; qualsiasi chiave root a lungo termine è un rischio inutile.","Corretto — l'amministrazione quotidiana dovrebbe usare identità con permessi a privilegio minimo, limitando l'uso del root ai pochi task che solo lui può eseguire.","Non è possibile associare IAM policy al root user; le restrizioni sul root negli account membri derivano dalle SCP o dalla gestione centralizzata dell'accesso root.","I security group controllano il traffico di rete verso le istanze, non l'autenticazione del root user alla console o alle API."]},
  "1011": {"h":"ddebabff","question":"Un team di sicurezza deve identificare in modo continuo i bucket Amazon S3, le chiavi AWS KMS, gli IAM role e le funzioni AWS Lambda le cui policy concedono accesso a principal esterni all'organizzazione AWS dell'azienda. Quale soluzione soddisfa questo requisito?","options":["Abilitare Amazon Macie per analizzare tutti i bucket e le chiavi e segnalare qualsiasi condivisione con account AWS esterni.","Generare regolarmente i credential report IAM e revisionare ogni principal con accesso alle risorse.","Abilitare IAM Access Analyzer con l'organizzazione come zona di attendibilità e revisionarne i finding.","Abilitare Amazon GuardDuty per rilevare le risorse le cui policy concedono accesso ad account esterni."],"explanation":"L'analisi dell'accesso esterno di IAM Access Analyzer esamina le resource-based policy di bucket S3, chiavi KMS, trust policy degli IAM role, funzioni Lambda e altro, e genera finding per qualsiasi accesso concesso al di fuori della zona di attendibilità (l'organizzazione). Macie può segnalare bucket S3 accessibili pubblicamente o condivisi, ma non copre chiavi KMS, IAM role o funzioni Lambda.","optionExplanations":["Macie si concentra sull'individuazione di dati sensibili e sulla postura di sicurezza dei bucket S3; non analizza le policy di chiavi KMS, IAM role o Lambda.","I credential report elencano gli utenti IAM e lo stato delle loro credenziali; non analizzano le resource-based policy per l'accesso esterno.","Corretto — Access Analyzer applica il ragionamento automatico alle policy delle risorse e segnala qualsiasi risorsa condivisa con principal esterni alla zona di attendibilità.","GuardDuty rileva minacce a partire da log e attività; non valuta le policy delle risorse per l'accesso esterno."]},
  "1012": {"h":"1af21d23","question":"Un'azienda esegue diversi microservizi come task Amazon ECS su AWS Fargate nello stesso cluster. Ogni servizio ha bisogno di accedere a risorse AWS diverse. La compromissione di un servizio non deve dare accesso alle risorse degli altri servizi. Quale soluzione soddisfa questi requisiti?","options":["Concedere tutti i permessi necessari a un unico task execution role condiviso da tutti i servizi.","Iniettare in ogni servizio, come variabili d'ambiente, le access key di un utente IAM distinto.","Eseguire ogni servizio nella propria subnet e limitare l'accesso alle API AWS con le network ACL.","Assegnare a ogni task definition un proprio IAM task role con i soli permessi necessari."],"explanation":"I task role di ECS forniscono a ogni task definition un proprio IAM role e credenziali temporanee, così ogni microservizio ottiene solo i permessi necessari e una compromissione resta circoscritta. Mettere i permessi su un execution role condiviso sembra più semplice, ma quel ruolo è destinato all'agente ECS e condividerlo permetterebbe a qualsiasi servizio compromesso di raggiungere le risorse di tutti gli altri.","optionExplanations":["L'execution role è usato dall'agente ECS per scaricare le immagini e scrivere i log, e condividere permessi ampi rompe l'isolamento tra i servizi.","Questo si basa su credenziali a lungo termine che possono trapelare e vanno ruotate manualmente.","Le network ACL filtrano il traffico IP e non possono esprimere un'autorizzazione per singolo servizio verso le API AWS.","Corretto — i task role danno a ogni servizio credenziali temporanee separate e limitate alle proprie risorse, applicando il privilegio minimo per servizio."]},
  "1013": {"h":"8162bd78","question":"Un'azienda ha centinaia di progetti e ogni settimana ne vengono creati di nuovi. Gli sviluppatori devono poter accedere solo alle risorse AWS contrassegnate con il tag del proprio progetto. Il team di sicurezza vuole evitare di scrivere o aggiornare IAM policy per ogni nuovo progetto. Quale soluzione soddisfa questi requisiti?","options":["Creare una IAM policy per progetto e associarla al gruppo di sviluppatori corrispondente.","Usare ABAC: assegnare a principal e risorse un tag di progetto e consentire l'accesso quando i tag coincidono.","Creare un account AWS separato per ogni progetto e concedere l'accesso tramite ruoli cross-account.","Usare su ogni risorsa resource-based policy che elenchino gli ARN degli sviluppatori di quel progetto."],"explanation":"L'attribute-based access control (ABAC) usa tag sia sui principal IAM sia sulle risorse, con una condizione di policy che ne richiede la corrispondenza, così un'unica policy scala a qualsiasi numero di progetti. Le policy per progetto sono l'approccio RBAC tradizionale, ma richiedono di creare e associare una nuova policy ogni volta che si aggiunge un progetto.","optionExplanations":["Ogni nuovo progetto richiede una nuova policy e un nuovo gruppo, esattamente la manutenzione continua delle policy che il team vuole evitare.","Corretto — l'attribute-based access control usa un'unica policy che confronta aws:PrincipalTag con i tag delle risorse, quindi i nuovi progetti richiedono solo tag, non nuove policy.","Centinaia di account con aggiunte settimanali e ruoli per account comportano un forte aggravio per un problema risolvibile con i tag.","Molti servizi non supportano resource-based policy e mantenere elenchi di principal su ogni risorsa scala male."]},
  "1014": {"h":"9f2b07b4","question":"Un fornitore SaaS di monitoraggio ha bisogno di accesso in sola lettura alle metriche Amazon CloudWatch di un'azienda dal proprio account AWS. L'azienda vuole seguire le best practice AWS e proteggersi dal problema del confused deputy. Quale soluzione soddisfa questi requisiti?","options":["Creare un utente IAM con permessi CloudWatch in sola lettura e inviarne le access key al fornitore.","Creare un IAM role che consideri attendibili tutti gli account AWS e limitarlo con una permissions policy in sola lettura.","Creare un IAM role che consideri attendibile l'account del fornitore e richieda l'MFA per le chiamate AssumeRole del fornitore.","Creare un IAM role che consideri attendibile l'account del fornitore e richieda una condizione di external ID."],"explanation":"L'accesso di terze parti dovrebbe usare un ruolo cross-account che consideri attendibile l'account del fornitore, con una condizione sts:ExternalId che impedisce a un altro cliente del fornitore di indurlo ad accedere a questo account. Richiedere l'MFA sembra più robusto, ma non risolve il problema del confused deputy ed è impraticabile per un servizio automatizzato.","optionExplanations":["Condividere access key a lungo termine con una terza parte non è consigliato e non affronta il rischio di confused deputy.","Considerare attendibili tutti gli account AWS permette a chiunque conosca l'ARN del ruolo di assumerlo, il che non è sicuro.","Un servizio automatizzato del fornitore non può fornire l'MFA in modo pratico e l'MFA non impedisce che il fornitore venga indotto ad agire per conto di un altro cliente.","Corretto — la condizione di external ID garantisce che il fornitore assuma il ruolo solo per conto di questo specifico cliente, mitigando il problema del confused deputy."]},
  "1015": {"h":"000b8955","question":"Uno sviluppatore in un account membro di un'organizzazione AWS ha associata la managed policy AdministratorAccess. Lo sviluppatore riceve un errore di accesso negato quando crea un'istanza DB Amazon RDS in una specifica Region, mentre gli altri servizi funzionano normalmente. Qual è la causa PIÙ probabile?","options":["All'utente IAM dello sviluppatore non è ancora stato associato un permissions boundary.","Il service-linked role di RDS deve prima essere creato dal root user dell'account membro.","Una SCP associata all'account o alla sua OU nega esplicitamente le azioni RDS o quella Region.","La policy AdministratorAccess esclude Amazon RDS, quindi serve una policy RDS separata."],"explanation":"Nella valutazione delle policy, un deny esplicito in qualsiasi punto prevale e le SCP definiscono i permessi massimi disponibili negli account membri, quindi una SCP che limita RDS o quella Region prevale su AdministratorAccess. L'assenza di un permissions boundary non può causare un diniego, perché i boundary limitano solo quando sono associati.","optionExplanations":["L'assenza di un permissions boundary non limita i permessi; un boundary può limitarli solo quando è presente.","I service-linked role vengono creati automaticamente dal servizio o da qualsiasi principal con i permessi IAM adeguati, non solo dal root user.","Corretto — le SCP limitano i permessi massimi negli account membri e un deny esplicito prevale perfino su AdministratorAccess.","AdministratorAccess consente tutte le azioni su tutte le risorse, compreso Amazon RDS."]},
  "1016": {"h":"174401a4","question":"Istanze Amazon EC2 sono in esecuzione in subnet private in due Availability Zone e devono scaricare patch del sistema operativo da internet. Le istanze non devono essere raggiungibili da internet e l'accesso in uscita deve continuare anche in caso di guasto di una Availability Zone. Quale soluzione soddisfa questi requisiti?","options":["Distribuire un NAT Gateway in una subnet pubblica in ogni AZ e instradare ogni subnet privata verso il NAT Gateway locale.","Distribuire un unico NAT Gateway in una subnet pubblica e instradare entrambe le subnet private attraverso di esso.","Collegare un egress-only internet gateway e instradare verso di esso il traffico IPv4 delle subnet private.","Spostare le istanze in subnet pubbliche e rimuovere tutte le regole in ingresso dai loro security group."],"explanation":"Un NAT Gateway in ogni Availability Zone, con ogni subnet privata instradata verso il NAT Gateway della propria AZ, fornisce accesso a internet IPv4 solo in uscita che resiste alla perdita di una AZ. Anche un unico NAT Gateway fornisce accesso in uscita, ma è una risorsa zonale e diventa un single point of failure.","optionExplanations":["Corretto — i NAT Gateway consentono solo connessioni IPv4 avviate in uscita e averne uno per AZ elimina la dipendenza da una singola AZ.","Un NAT Gateway è zonale; se la sua AZ si guasta, le istanze nell'altra AZ perdono l'accesso a internet.","Gli egress-only internet gateway supportano solo traffico IPv6, quindi i download delle patch via IPv4 fallirebbero.","Le istanze con IP pubblici in subnet pubbliche sono indirizzabili da internet, in contrasto con il requisito di collocazione privata."]},
  "1017": {"h":"c0bfb137","question":"Un'applicazione su istanze Amazon EC2 in subnet private legge file riservati da un bucket Amazon S3 tramite un gateway VPC endpoint per S3. Il team di sicurezza deve garantire che il bucket sia accessibile SOLO tramite questo specifico endpoint, anche da parte di utenti con credenziali IAM valide altrove. Quale soluzione soddisfa questo requisito?","options":["Aggiungere una bucket policy che neghi le richieste non provenienti da quell'ID di endpoint.","Associare al gateway endpoint un security group che consenta il traffico solo dalle istanze.","Abilitare S3 Block Public Access sul bucket e sull'account che lo possiede.","Cifrare il bucket con una customer managed key AWS KMS usata solo dal ruolo dell'applicazione."],"explanation":"Una bucket policy con un Deny esplicito quando la condition key aws:SourceVpce è diversa dall'ID dell'endpoint blocca ogni richiesta che non arrivi tramite quel VPC endpoint, indipendentemente dai permessi IAM del chiamante. I gateway endpoint non supportano security group e Block Public Access blocca solo l'accesso pubblico, senza limitare i principal autenticati che arrivano da altre reti.","optionExplanations":["Corretto — un Deny esplicito sulle richieste in cui aws:SourceVpce differisce dall'ID dell'endpoint limita il bucket al solo traffico che passa da quell'endpoint.","Ai gateway VPC endpoint non si possono associare security group; sono destinazioni nelle route table, quindi questo controllo non è possibile.","Block Public Access impedisce l'accesso pubblico (anonimo o pubblico cross-account), ma i principal IAM autenticati potrebbero comunque raggiungere il bucket da fuori del VPC.","Una customer managed key limita chi può decifrare gli oggetti, ma non vincola il percorso di rete; i principal autorizzati potrebbero comunque chiamare S3 da qualsiasi luogo."]},
  "1018": {"h":"eaf3f505","question":"Funzioni AWS Lambda sono collegate a subnet private per poter raggiungere un database Amazon RDS. Le subnet non hanno una route verso internet e il team di sicurezza vieta di aggiungerne una. Ora le funzioni devono recuperare le credenziali del database da AWS Secrets Manager. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere un NAT Gateway e limitare l'egress del security group agli intervalli IP di Secrets Manager.","Creare un gateway VPC endpoint per Secrets Manager e aggiungerlo alle route table.","Rimuovere le funzioni dal VPC in modo che possano chiamare direttamente Secrets Manager.","Creare un interface VPC endpoint per Secrets Manager con il DNS privato abilitato."],"explanation":"Un interface VPC endpoint basato su AWS PrivateLink fornisce accesso privato a Secrets Manager da subnet senza connettività internet e il DNS privato evita modifiche al codice. Un gateway endpoint potrebbe sembrare più economico, ma i gateway endpoint supportano solo S3 e DynamoDB.","optionExplanations":["Questo aggiunge una route verso internet, vietata dal team di sicurezza.","I gateway endpoint esistono solo per Amazon S3 e Amazon DynamoDB, non per Secrets Manager.","Le funzioni perderebbero la connettività privata verso il database RDS nel VPC.","Corretto — un interface endpoint (AWS PrivateLink) espone Secrets Manager su IP privati nelle subnet e il DNS privato consente all'SDK di usarlo senza modifiche."]},
  "1019": {"h":"fb8b6082","question":"Un'applicazione pubblica è in esecuzione su istanze Amazon EC2 in una subnet pubblica. I log mostrano traffico malevolo proveniente da uno specifico intervallo di indirizzi IP. L'azienda deve bloccare subito quell'intervallo continuando a consentire tutto l'altro traffico internet. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere al security group delle istanze una regola di deny in ingresso per l'intervallo di indirizzi IP.","Aggiungere alla network ACL della subnet una regola di deny per l'intervallo IP con un numero di regola basso.","Sostituire la regola 0.0.0.0/0 del security group con regole di allow per ogni intervallo IP legittimo.","Abilitare Amazon GuardDuty per bloccare automaticamente il traffico dall'intervallo di indirizzi IP malevolo."],"explanation":"Le network ACL sono filtri stateless a livello di subnet che supportano regole di deny elaborate in ordine crescente di numero di regola, quindi un deny per l'intervallo posto prima della regola di allow lo blocca mentre tutto l'altro traffico continua. I security group sono il firewall abituale delle istanze, ma hanno solo regole di allow e quindi non possono esprimere un deny.","optionExplanations":["I security group supportano solo regole di allow, quindi non è possibile creare una regola di deny.","Corretto — le network ACL supportano regole di deny esplicite valutate in ordine di numero di regola, quindi un deny con numero basso blocca l'intervallo prima della regola di allow generale.","Elencare tutti i client internet legittimi è impraticabile per un'applicazione pubblica.","GuardDuty genera finding; da solo non blocca il traffico."]},
  "1020": {"h":"ef768be9","question":"Un'API REST pubblica è in esecuzione dietro un Application Load Balancer. L'API riceve tentativi di SQL injection e improvvise ondate di richieste da singoli indirizzi IP. Quale combinazione di passaggi mitigherà entrambe le minacce con il MINOR carico operativo? (Seleziona DUE)","options":["Distribuire una flotta di istanze EC2 proxy che ispezionino le richieste prima che raggiungano l'ALB.","Associare all'ALB una web ACL di AWS WAF che includa il managed rule group AWS per i database SQL.","Abilitare Amazon Inspector sull'ALB per bloccare in tempo reale le richieste malevole.","Aggiungere alla web ACL una rate-based rule che blocchi gli indirizzi IP che superano una soglia di richieste.","Configurare regole del security group sull'ALB per scartare le richieste che contengono parole chiave SQL."],"explanation":"AWS WAF associato all'ALB può usare il managed rule group per i database SQL per fermare la SQL injection e una rate-based rule per bloccare gli IP che inviano ondate di richieste, entrambi completamente gestiti. Amazon Inspector suona come un servizio di sicurezza pertinente, ma è uno scanner di vulnerabilità e non filtra il traffico in tempo reale.","optionExplanations":["I proxy autogestiti aggiungono un carico operativo significativo rispetto a un web application firewall gestito.","Corretto — i managed rule group AWS bloccano i pattern comuni di SQL injection senza scrivere regole personalizzate.","Inspector analizza i workload alla ricerca di vulnerabilità; non ispeziona né blocca le richieste HTTP.","Corretto — le rate-based rule bloccano automaticamente gli IP di origine che superano la frequenza di richieste configurata.","I security group filtrano per IP, porta e protocollo e non possono ispezionare il contenuto delle richieste HTTP."]},
  "1021": {"h":"7a39c47b","question":"Il sito web pubblico di un'azienda usa Amazon CloudFront, Amazon Route 53 e un Application Load Balancer ed è stato bersaglio di attacchi DDoS su larga scala. L'azienda vuole accesso 24/7 agli esperti AWS di risposta ai DDoS e protezione dagli aumenti di costo causati dallo scaling durante gli attacchi. Quale soluzione soddisfa questi requisiti?","options":["Sottoscrivere AWS Shield Advanced e proteggere le risorse CloudFront, Route 53 e ALB.","Affidarsi ad AWS Shield Standard e abilitare lo standard logging di CloudFront per le analisi forensi.","Abilitare Amazon GuardDuty e usare Amazon EventBridge per scalare i target dell'ALB durante gli attacchi.","Distribuire AWS Network Firewall nel VPC davanti all'Application Load Balancer."],"explanation":"AWS Shield Advanced fornisce una protezione DDoS avanzata per risorse CloudFront, Route 53 ed ELB, accesso 24/7 allo Shield Response Team e protezione dei costi per lo scaling causato dagli attacchi. Shield Standard è già incluso senza costi, ma non offre il team di risposta né la protezione dei costi di cui l'azienda ha bisogno.","optionExplanations":["Corretto — Shield Advanced aggiunge un rilevamento avanzato, l'accesso allo Shield Response Team e la protezione dei costi per lo scaling legato agli attacchi.","Shield Standard fornisce una protezione di base automatica, ma senza accesso al team di risposta né protezione dei costi.","GuardDuty è un servizio di rilevamento delle minacce; non mitiga gli attacchi DDoS né offre protezione dei costi.","Network Firewall filtra il traffico del VPC ma non fornisce esperti di risposta ai DDoS né protezione dei costi."]},
  "1022": {"h":"7e3ec233","question":"Un'azienda vuole rilevare in modo continuo istanze Amazon EC2 compromesse, ad esempio per mining di criptovalute o comunicazioni con indirizzi IP malevoli noti, e attività API insolite in tutti gli account della sua organizzazione. La soluzione deve richiedere una configurazione minima. Quale soluzione soddisfa questi requisiti?","options":["Abilitare Amazon GuardDuty per l'organizzazione tramite un account di amministratore delegato.","Installare un sistema di rilevamento delle intrusioni su ogni istanza e inoltrare gli avvisi a CloudWatch Logs.","Abilitare Amazon Inspector in ogni account per analizzare il traffico di rete alla ricerca di pattern malevoli.","Abilitare AWS Config in ogni account con regole personalizzate per ogni tipo di attività sospetta."],"explanation":"Amazon GuardDuty è un servizio gestito di rilevamento delle minacce che analizza le sorgenti di log fondamentali senza agenti e può essere abilitato a livello di organizzazione tramite un amministratore delegato. Anche Amazon Inspector è un servizio di sicurezza gestito, ma individua vulnerabilità anziché rilevare compromissioni attive o chiamate API anomale.","optionExplanations":["Corretto — GuardDuty analizza CloudTrail, VPC Flow Logs e log DNS con threat intelligence e ML e può essere abilitato centralmente per tutti gli account.","Agenti autogestiti su ogni istanza in tutti gli account comportano un impegno significativo di configurazione e manutenzione.","Inspector cerca vulnerabilità software e raggiungibilità di rete; non rileva minacce attive nel traffico o nelle attività API.","AWS Config valuta le configurazioni delle risorse, non il comportamento a runtime o le anomalie nelle API."]},
  "1023": {"h":"69bc9085","question":"Un'azienda memorizza milioni di documenti in Amazon S3 su molti bucket. Per adempiere agli obblighi del GDPR, deve individuare quali bucket contengono dati personali come numeri di passaporto e numeri di carta di credito. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Usare Amazon Inspector per analizzare i bucket alla ricerca di oggetti che contengono dati sensibili.","Usare Amazon S3 Storage Lens per classificare gli oggetti in base al tipo di contenuto.","Usare Amazon Macie per eseguire l'individuazione dei dati sensibili sui bucket.","Usare Amazon Athena con espressioni regolari per cercare nel contenuto di ogni oggetto."],"explanation":"Amazon Macie individua e segnala automaticamente dati sensibili come le PII in S3 usando managed data identifier, senza codice personalizzato. Athena con espressioni regolari potrebbe trovare alcuni pattern in file strutturati, ma richiede query personalizzate e non gestisce formati di documento eterogenei, con un carico molto maggiore.","optionExplanations":["Inspector analizza i workload di calcolo alla ricerca di vulnerabilità; non classifica il contenuto degli oggetti S3.","Storage Lens fornisce metriche di utilizzo e attività dello storage, non i dati sensibili contenuti negli oggetti.","Corretto — Macie usa managed data identifier per trovare PII come numeri di passaporto e di carta di credito negli oggetti S3.","Athena interroga dati strutturati, richiederebbe pattern personalizzati e non riesce a interpretare facilmente formati di documento eterogenei."]},
  "1024": {"h":"05af9cc1","question":"Un'azienda ha bisogno di una scansione delle vulnerabilità automatizzata e continua delle sue istanze Amazon EC2 e delle immagini container in Amazon ECR. I finding devono aggiornarsi automaticamente quando vengono pubblicate nuove CVE. Quale soluzione soddisfa questi requisiti?","options":["Abilitare Amazon GuardDuty Malware Protection per le istanze EC2 e i repository ECR.","Distribuire regole gestite di AWS Config che verifichino le CVE note su istanze e immagini.","Abilitare Amazon Macie per analizzare le istanze e le immagini container alla ricerca di vulnerabilità.","Attivare Amazon Inspector con la scansione EC2 e l'enhanced scanning di ECR."],"explanation":"Amazon Inspector fornisce una gestione delle vulnerabilità continua e automatizzata per istanze EC2, immagini container ECR e funzioni Lambda, e rivaluta le risorse quando compaiono nuove CVE. Anche GuardDuty Malware Protection analizza i workload, ma cerca malware, non vulnerabilità software.","optionExplanations":["Malware Protection cerca malware nei volumi, non vulnerabilità software (CVE) in pacchetti e immagini.","Le regole di Config valutano le configurazioni delle risorse e non possono analizzare i pacchetti software alla ricerca di CVE.","Macie individua dati sensibili in S3 e non esegue scansioni delle vulnerabilità.","Corretto — Inspector analizza continuamente istanze EC2 e immagini ECR alla ricerca di CVE e ripete la scansione quando vengono pubblicate nuove vulnerabilità."]},
  "1025": {"h":"919ae623","question":"Un'azienda sta realizzando un'applicazione web rivolta ai clienti dietro un Application Load Balancer. Gli utenti devono potersi registrare e accedere con un indirizzo email o con il proprio account Google. L'azienda vuole scrivere meno codice di autenticazione possibile. Quale soluzione soddisfa questi requisiti?","options":["Creare utenti IAM per i clienti e federare gli account Google tramite IAM Identity Center.","Usare un Amazon Cognito user pool con federazione Google e abilitare l'autenticazione utenti sull'ALB.","Usare solo un Amazon Cognito identity pool per memorizzare profili e password degli utenti.","Realizzare su EC2 un servizio di autenticazione personalizzato che memorizzi gli hash delle password in DynamoDB."],"explanation":"Un Amazon Cognito user pool è una directory gestita di identità dei clienti con registrazione, accesso e identity provider social come Google, e una regola del listener dell'ALB può autenticare gli utenti tramite essa senza codice applicativo. Gli identity pool sono una fonte comune di confusione, ma emettono credenziali AWS temporanee e non gestiscono registrazione o password degli utenti.","optionExplanations":["Gli utenti IAM e IAM Identity Center sono pensati per l'accesso del personale ad AWS, non per milioni di clienti di un'applicazione.","Corretto — i Cognito user pool forniscono registrazione, accesso e federazione social e l'ALB può autenticare nativamente gli utenti sullo user pool.","Gli identity pool scambiano token con credenziali AWS; non forniscono una directory utenti né un flusso di registrazione.","Un servizio di autenticazione personalizzato richiede molto codice e impegno sul fronte della sicurezza, cosa che l'azienda vuole evitare."]},
  "1026": {"h":"9944c796","question":"Un'applicazione si connette a un database Amazon RDS for MySQL usando credenziali scritte direttamente nel codice sorgente. L'azienda ora richiede che le credenziali vengano ruotate automaticamente ogni 30 giorni senza modifiche all'applicazione dopo ogni rotazione. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Memorizzare le credenziali come SecureString in Parameter Store e ruotarle con un cron job personalizzato.","Cifrare le credenziali con AWS KMS e memorizzarle in un bucket Amazon S3 letto dall'applicazione.","Memorizzare le credenziali in AWS Secrets Manager con rotazione gestita e recuperare il segreto a runtime.","Memorizzare le credenziali su un volume EBS cifrato e ruotarle manualmente dalla console RDS."],"explanation":"AWS Secrets Manager ruota nativamente le credenziali di Amazon RDS secondo una pianificazione, aggiornando sia il segreto sia il database, e l'applicazione recupera il segreto corrente a runtime. Anche SecureString di Parameter Store memorizza valori cifrati, ma non ha una rotazione integrata, quindi servirebbe un'automazione personalizzata.","optionExplanations":["Parameter Store non ha una rotazione integrata, quindi bisogna scrivere, pianificare e mantenere un job personalizzato.","Questo protegge il valore memorizzato ma non prevede alcuna rotazione della password del database.","Corretto — Secrets Manager ruota le credenziali RDS secondo una pianificazione e aggiorna il database, e l'applicazione legge sempre il valore corrente.","La rotazione manuale è un carico operativo, è soggetta a errori e non soddisfa il requisito di rotazione automatica."]},
  "1027": {"h":"6bc3e0d8","question":"Un'azienda vuole eliminare i propri bastion host. Gli amministratori hanno bisogno di accesso shell interattivo a istanze Amazon EC2 in subnet private prive di accesso a internet. Non possono essere aperte porte in ingresso e tutte le sessioni devono essere registrate. Le AMI includono già l'SSM Agent. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Aprire la porta 22 in ingresso dall'intervallo CIDR aziendale nei security group delle istanze.","Associare un instance profile che includa la managed policy AmazonSSMManagedInstanceCore.","Creare un gateway VPC endpoint per AWS Systems Manager nelle route table delle subnet private.","Assegnare indirizzi Elastic IP alle istanze in modo che Session Manager possa connettersi.","Creare nel VPC interface VPC endpoint per i servizi di Systems Manager."],"explanation":"Session Manager richiede che l'istanza abbia un IAM role con i permessi SSM di base e un percorso privato verso il servizio Systems Manager, fornito dagli interface VPC endpoint quando non c'è accesso a internet; le sessioni possono essere registrate in CloudWatch Logs o S3. Aprire la porta 22 dall'intervallo aziendale è l'approccio tradizionale, ma viola il requisito di nessuna porta in ingresso.","optionExplanations":["Il requisito vieta l'apertura di porte in ingresso e Session Manager non ne ha bisogno.","Corretto — l'SSM Agent necessita di questi permessi per registrarsi presso Systems Manager e stabilire le sessioni di Session Manager.","I gateway endpoint sono disponibili solo per Amazon S3 e Amazon DynamoDB.","Le connessioni di Session Manager vengono avviate in uscita dall'agente; gli IP pubblici non servono e aumentano l'esposizione.","Corretto — senza accesso a internet, l'SSM Agent raggiunge Systems Manager tramite interface endpoint (ssm, ssmmessages, ec2messages)."]},
  "1028": {"h":"37a7158d","question":"Un provider SaaS esegue un'API dietro un Network Load Balancer e deve offrirla in modo privato a centinaia di VPC dei clienti. Molti VPC dei clienti usano intervalli CIDR sovrapposti a quello del VPC del provider. I clienti devono raggiungere solo l'API, non il resto della rete del provider. Quale soluzione soddisfa questi requisiti?","options":["Creare un VPC endpoint service basato su AWS PrivateLink e lasciare che i clienti creino interface endpoint.","Creare una connessione VPC peering tra il VPC del provider e ciascun VPC dei clienti.","Collegare tutti i VPC a un Transit Gateway e condividerlo con i clienti tramite AWS RAM.","Esporre l'API tramite un NLB pubblico e consentire nei security group solo gli intervalli IP dei clienti."],"explanation":"AWS PrivateLink consente a un provider di pubblicare un endpoint service basato su NLB che i consumer raggiungono tramite interface endpoint nei propri VPC, esponendo solo quel servizio e funzionando anche con intervalli IP sovrapposti. Il VPC peering è un'opzione comune di connettività privata, ma non supporta CIDR sovrapposti e apre il routing tra interi VPC.","optionExplanations":["Corretto — PrivateLink espone solo il servizio dietro l'NLB tramite endpoint nei VPC dei clienti e funziona con CIDR sovrapposti.","Il peering non è possibile con intervalli CIDR sovrapposti ed espone una parte della rete più ampia di un singolo servizio.","I CIDR sovrapposti compromettono il routing tramite il Transit Gateway e i clienti otterrebbero un'ampia raggiungibilità di rete.","Il traffico passerebbe per endpoint pubblici, il che non soddisfa il requisito di connettività privata."]},
  "1029": {"h":"b9140fb1","question":"Un'azienda collega il proprio data center a un VPC con una connessione AWS Direct Connect. Una nuova regola di compliance richiede che tutto il traffico tra il data center e il VPC sia cifrato in transito, e l'azienda vuole mantenere le prestazioni di rete costanti di Direct Connect. Quale soluzione soddisfa questi requisiti?","options":["Mantenere la configurazione attuale, perché Direct Connect cifra tutto il traffico per impostazione predefinita.","Sostituire Direct Connect con una connessione AWS Site-to-Site VPN sulla rete internet pubblica.","Aggiungere una seconda connessione Direct Connect in una location diversa per la ridondanza.","Eseguire una connessione AWS Site-to-Site VPN sopra la connessione Direct Connect esistente."],"explanation":"Eseguire una Site-to-Site VPN IPsec sopra la connessione Direct Connect aggiunge la cifratura in transito mentre il traffico continua a usare il collegamento dedicato e le sue prestazioni costanti. Anche una VPN via internet cifra il traffico, ma rinuncia alla latenza e al throughput prevedibili che l'azienda vuole mantenere.","optionExplanations":["Direct Connect fornisce un collegamento privato dedicato ma non cifra il traffico per impostazione predefinita.","Questo cifra il traffico ma perde le prestazioni costanti della connessione dedicata.","Una seconda connessione migliora la resilienza ma non fa nulla per la cifratura in transito.","Corretto — una VPN IPsec sopra Direct Connect cifra il traffico mantenendo il percorso di rete dedicato e costante."]},
  "1030": {"h":"b375c0a2","question":"Un'applicazione three-tier usa un Application Load Balancer rivolto a internet in subnet pubbliche, istanze applicative Amazon EC2 in subnet private e un database Amazon RDS in subnet isolate. Quali configurazioni dei security group seguono il principio del privilegio minimo? (Seleziona DUE)","options":["Consentire il traffico in ingresso sulla porta applicativa verso il security group dell'app solo dal security group dell'ALB.","Consentire il traffico in ingresso sulla porta del database verso il security group del DB dall'intero intervallo CIDR del VPC.","Consentire il traffico in ingresso sulla porta applicativa verso il security group dell'app da 0.0.0.0/0.","Collocare il database in subnet pubbliche e affidarsi alla password master del database per la protezione.","Consentire il traffico in ingresso sulla porta del database verso il security group del DB solo dal security group dell'app."],"explanation":"Concatenare i security group per riferimento (dall'ALB al tier applicativo, dal tier applicativo al database) fa sì che ogni tier riceva traffico solo dal tier immediatamente precedente, indipendentemente dagli indirizzi IP. Consentire l'intero CIDR del VPC verso il database sembra restrittivo perché è interno, ma concede l'accesso a ogni workload del VPC.","optionExplanations":["Corretto — fare riferimento al security group dell'ALB consente solo al traffico del load balancer di raggiungere le istanze, a prescindere dai cambi di IP.","Questo consente a ogni risorsa del VPC di raggiungere il database, un accesso più ampio del necessario.","La collocazione in subnet private non giustifica una regola aperta; qualsiasi risorsa in grado di instradare fin lì potrebbe connettersi.","Questo espone il database a internet e ne affida la protezione a un'unica credenziale.","Corretto — solo il tier applicativo può aprire connessioni verso il database, l'accesso più ristretto necessario."]},
  "1031": {"h":"9c24540c","question":"Un'azienda ha un'istanza DB Amazon RDS for PostgreSQL esistente e non cifrata. Una nuova policy richiede che il database sia cifrato a riposo con una chiave AWS KMS. Quale combinazione di passaggi dovrebbe eseguire un solutions architect? (Seleziona TRE)","options":["Modificare l'istanza DB esistente e abilitare sul posto la cifratura a riposo.","Creare uno snapshot manuale dell'istanza DB non cifrata.","Creare una read replica cifrata dell'istanza DB non cifrata e promuoverla.","Copiare lo snapshot e abilitare sulla copia la cifratura con la chiave KMS.","Ripristinare una nuova istanza DB dallo snapshot cifrato e puntarvi l'applicazione."],"explanation":"Poiché la cifratura non può essere attivata su un'istanza RDS esistente non cifrata, il percorso standard è snapshot, copia cifrata dello snapshot e ripristino su una nuova istanza cifrata. Creare una read replica cifrata sembra una scorciatoia con meno downtime, ma RDS non supporta repliche cifrate di origini non cifrate.","optionExplanations":["La cifratura non può essere abilitata su un'istanza DB RDS esistente non cifrata.","Corretto — uno snapshot cattura i dati correnti in modo da poterne creare una copia cifrata.","RDS non consente una read replica cifrata di un'istanza DB non cifrata.","Corretto — la copia di uno snapshot è il momento in cui si può applicare la cifratura ai dati RDS.","Corretto — un'istanza DB ripristinata da uno snapshot cifrato è cifrata a riposo e l'applicazione passa al suo endpoint."]},
  "1032": {"h":"c69b853d","question":"Un'azienda memorizza file sensibili in Amazon S3 con cifratura SSE-S3. Un nuovo requisito di compliance stabilisce che un team di sicurezza separato deve controllare la chiave di cifratura, ogni utilizzo della chiave deve essere registrato in AWS CloudTrail e la chiave deve poter essere disabilitata immediatamente. Quale soluzione soddisfa questi requisiti?","options":["Passare il bucket a SSE-KMS con la AWS managed key per Amazon S3.","Passare il bucket a SSE-KMS con una customer managed key amministrata dal team di sicurezza.","Mantenere SSE-S3 e abilitare sul bucket l'S3 server access logging per l'audit.","Usare la cifratura lato client con chiavi memorizzate localmente su ogni server applicativo e ruotate tramite script."],"explanation":"Una customer managed key per SSE-KMS dà pieno controllo sulla key policy (consentendo la separazione dei compiti), registra ogni operazione crittografica in CloudTrail e può essere disabilitata o pianificata per l'eliminazione. Anche la AWS managed key registra l'utilizzo in CloudTrail, ma i clienti non possono modificarne la policy né disabilitarla.","optionExplanations":["Le AWS managed key non consentono al cliente di modificare la key policy o di disabilitarle, quindi il team di sicurezza non può controllarle.","Corretto — le customer managed key hanno una key policy controllata dal team di sicurezza, registrano ogni utilizzo in CloudTrail e possono essere disabilitate in qualsiasi momento.","Le chiavi SSE-S3 sono interamente gestite da S3; il team di sicurezza non può controllarle né disabilitarle.","Chiavi sparse sui server sono difficili da controllare centralmente e il loro utilizzo non viene registrato in CloudTrail."]},
  "1033": {"h":"0b3bd2bd","question":"Un'applicazione in us-east-1 cifra i dati lato client con AWS KMS e replica i dati cifrati in eu-west-1 per il disaster recovery. Durante un'interruzione a livello di Region in us-east-1, l'applicazione in eu-west-1 deve decifrare i dati senza chiamare KMS in us-east-1. Quale soluzione soddisfa questi requisiti?","options":["Creare chiavi KMS separate in ogni Region e assegnare loro lo stesso nome di alias.","Esportare il materiale della chiave di us-east-1 e importarlo in una nuova chiave in eu-west-1.","Creare una chiave primaria KMS multi-Region e una replica di quella chiave in eu-west-1.","Usare in ogni Region la AWS managed key di KMS per cifrare e decifrare i dati."],"explanation":"Le chiavi KMS multi-Region sono chiavi interoperabili con lo stesso materiale crittografico in più Region, quindi il testo cifrato prodotto in us-east-1 può essere decifrato dalla chiave replica in eu-west-1 senza chiamate cross-Region. Alias uguali fanno sembrare le chiavi identiche, ma ogni chiave standard ha materiale unico e non può decifrare i dati dell'altra.","optionExplanations":["Gli alias sono solo nomi; chiavi separate hanno materiale crittografico diverso e non possono decifrare l'una il testo cifrato dell'altra.","KMS non consente di esportare il materiale delle chiavi generato da KMS.","Corretto — le chiavi multi-Region condividono key ID e materiale crittografico, quindi i dati cifrati in una Region possono essere decifrati localmente nell'altra.","Le AWS managed key sono specifiche di ogni Region e diverse in ciascuna, quindi la decifratura cross-Region fallisce."]},
  "1034": {"h":"617dc8bd","question":"Un'azienda finanziaria deve conservare i record delle transazioni in Amazon S3 per 7 anni in formato WORM. Durante il periodo di conservazione, nessun utente, compreso il root user dell'account, può eliminare o sovrascrivere i record. Quale soluzione soddisfa questi requisiti?","options":["Abilitare S3 Object Lock in governance mode con un periodo di conservazione di 7 anni.","Abilitare S3 Versioning con MFA Delete e limitare le eliminazioni con una bucket policy.","Spostare gli oggetti in S3 Glacier Flexible Retrieval e negare le eliminazioni nella bucket policy.","Abilitare S3 Object Lock in compliance mode con un periodo di conservazione predefinito di 7 anni."],"explanation":"S3 Object Lock in compliance mode impone una protezione WORM che nessun utente, compreso il root user, può aggirare fino alla scadenza del periodo di conservazione. La governance mode sembra equivalente, ma i principal con il permesso di bypass possono eliminare gli oggetti o ridurre la conservazione.","optionExplanations":["Gli utenti con permessi speciali possono aggirare la conservazione in governance mode, quindi l'eliminazione non è del tutto impedita.","Il root user può modificare la bucket policy e, con l'MFA, eliminare le versioni, quindi il WORM non è garantito.","Una bucket policy può essere modificata da utenti privilegiati, quindi non impone una conservazione immutabile.","Corretto — in compliance mode nessuno, compreso il root user, può eliminare o sovrascrivere una versione di oggetto bloccata o ridurne la conservazione."]},
  "1035": {"h":"d7f765b0","question":"Un'azienda distribuisce un sito web statico da un bucket Amazon S3 privato tramite Amazon CloudFront. Gli utenti hanno scoperto di poter aggirare CloudFront usando direttamente gli URL degli oggetti S3. Il bucket usa la cifratura SSE-KMS. Il contenuto deve essere accessibile solo tramite CloudFront. Quale soluzione soddisfa questi requisiti?","options":["Abilitare l'S3 static website hosting e consentire l'accesso solo quando è presente un header Referer segreto.","Configurare l'origin access control sulla distribuzione e consentire solo quella distribuzione nella bucket policy.","Rendere pubblico il bucket e richiedere signed URL di CloudFront per ogni richiesta al sito.","Configurare una origin access identity legacy e concederle l'accesso in lettura nella bucket policy."],"explanation":"L'origin access control (OAC) di CloudFront consente a CloudFront di firmare le richieste verso S3, funziona con SSE-KMS (dopo aver concesso alla distribuzione kms:Decrypt nella key policy) e la bucket policy può consentire solo quella distribuzione. L'origin access identity ottiene una restrizione simile per contenuti non cifrati o con SSE-S3, ma è legacy e non supporta SSE-KMS.","optionExplanations":["Un header Referer può essere falsificato e l'endpoint del sito web non supporta oggetti cifrati con SSE-KMS.","Corretto — OAC firma le richieste verso l'origine, supporta SSE-KMS e una bucket policy limitata alla distribuzione blocca l'accesso diretto a S3.","I signed URL limitano l'accesso tramite CloudFront, ma un bucket pubblico può comunque essere letto direttamente da S3.","OAI è il meccanismo legacy e non supporta oggetti cifrati con SSE-KMS."]},
  "1036": {"h":"5832865a","question":"Un'applicazione web consente ai clienti autenticati di scaricare le proprie fatture, memorizzate in un bucket Amazon S3 privato. I link di download devono scadere dopo pochi minuti, il bucket deve restare privato e i clienti non devono ricevere credenziali AWS. Quale soluzione soddisfa questi requisiti?","options":["Far generare al backend dell'applicazione presigned URL S3 con un breve tempo di scadenza.","Rendere pubblici gli oggetti delle fatture e assegnare loro chiavi oggetto lunghe e generate casualmente.","Creare un utente IAM per ogni cliente con accesso in lettura al prefisso di quel cliente.","Copiare ogni fattura in un bucket pubblico ed eliminarla dopo un giorno con una regola S3 Lifecycle."],"explanation":"I presigned URL consentono al backend di concedere un accesso di breve durata a singoli oggetti privati, così il bucket resta privato e i clienti non gestiscono mai credenziali AWS. Oggetti pubblici con chiavi casuali possono sembrare difficili da indovinare, ma restano pubblici e i link non scadono mai.","optionExplanations":["Corretto — i presigned URL concedono un accesso a tempo limitato a un oggetto specifico usando i permessi del backend, senza rendere pubblico il bucket.","Gli oggetti pubblici violano il requisito del bucket privato e i link non scadono mai.","Questo fornisce ai clienti credenziali AWS e non scala su molti clienti.","I dati diventano leggibili pubblicamente e la scadenza tramite lifecycle non può imporre una finestra di pochi minuti."]},
  "1037": {"h":"c997beb2","question":"Un'azienda con molti account AWS ha avuto di recente un incidente in cui uno sviluppatore ha reso pubblico un bucket Amazon S3. L'azienda deve impedire che qualsiasi bucket in qualsiasi account venga reso pubblico, anche da parte degli amministratori degli account. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Abilitare Amazon Macie in ogni account per ricevere avvisi quando i bucket diventano accessibili pubblicamente.","Distribuire una regola AWS Config che rilevi i bucket pubblici e avvisi il team di sicurezza.","Abilitare la cifratura predefinita SSE-KMS su ogni bucket in ogni account.","Abilitare S3 Block Public Access a livello di account e negarne le modifiche con una SCP."],"explanation":"S3 Block Public Access a livello di account impedisce ACL e policy pubbliche per ogni bucket di un account e una SCP che nega le modifiche a questa impostazione impedisce anche agli amministratori degli account membri di disattivarla. Il rilevamento con AWS Config è utile per la visibilità, ma reagisce solo quando un bucket è già pubblico.","optionExplanations":["Macie segnala l'esposizione dei bucket ma non impedisce che un bucket venga reso pubblico.","Le regole di Config sono di rilevamento; quando il team viene avvisato, il bucket è già pubblico.","La cifratura a riposo non impedisce che gli oggetti vengano condivisi pubblicamente.","Corretto — Block Public Access a livello di account prevale su bucket policy e ACL pubbliche e la SCP impedisce agli amministratori di disattivarlo."]},
  "1038": {"h":"ebb147d3","question":"Un'azienda distribuisce il proprio sito web tramite Amazon CloudFront con un nome di dominio personalizzato. L'origine è un Application Load Balancer in eu-central-1. L'azienda richiede HTTPS dai viewer verso CloudFront e da CloudFront verso l'ALB, con rinnovo automatico dei certificati. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Richiedere certificati ACM pubblici in us-east-1 per CloudFront e in eu-central-1 per l'ALB.","Richiedere un unico certificato ACM in eu-central-1 e associarlo sia a CloudFront sia all'ALB.","Importare un certificato di terze parti in ACM in entrambe le Region e sostituirlo prima di ogni scadenza.","Generare certificati autofirmati sulle istanze e impostare il viewer protocol su solo HTTPS."],"explanation":"ACM fornisce certificati pubblici gratuiti con rinnovo automatico; CloudFront richiede il proprio certificato in us-east-1, mentre l'ALB ne richiede uno nella propria Region (eu-central-1). Usare un unico certificato in eu-central-1 sembra più semplice, ma CloudFront non può usare certificati di Region diverse da us-east-1.","optionExplanations":["Corretto — CloudFront usa certificati ACM di us-east-1, gli ALB usano certificati della propria Region e ACM rinnova automaticamente i certificati pubblici.","CloudFront può usare solo certificati ACM richiesti o importati in us-east-1.","I certificati importati non vengono rinnovati automaticamente, quindi il rinnovo manuale aggiunge carico operativo e rischio.","I browser non considerano attendibili i certificati autofirmati, che vanno inoltre gestiti e rinnovati manualmente."]},
  "1039": {"h":"2632a666","question":"Un'azienda soggetta a regolamentazione deve eseguire il backup di database Amazon RDS, volumi Amazon EBS e tabelle Amazon DynamoDB. I backup devono essere immutabili, in modo che nessuno possa eliminarli prima della fine della conservazione, e le copie devono sopravvivere alla perdita di un'intera Region. Quale combinazione di passaggi soddisferà questi requisiti con il MINOR carico operativo? (Seleziona DUE)","options":["Scrivere funzioni AWS Lambda che creino ogni notte snapshot di ciascuna risorsa e le contrassegnino con tag per la conservazione.","Esportare tutti gli snapshot in un bucket Amazon S3 con il versioning abilitato.","Creare un backup plan di AWS Backup che memorizzi i recovery point in un vault con Vault Lock in compliance mode.","Abilitare deployment RDS Multi-AZ e l'auto scaling di DynamoDB per proteggersi dalla perdita di dati.","Aggiungere al backup plan una regola di copia cross-Region che punti a un vault in un'altra Region."],"explanation":"AWS Backup pianifica centralmente i backup di RDS, EBS e DynamoDB; Vault Lock in compliance mode rende i recovery point immutabili per la durata della conservazione e una regola di copia cross-Region protegge da un disastro a livello di Region. Anche script Lambda personalizzati per gli snapshot possono creare backup, ma aggiungono carico operativo e non offrono immutabilità.","optionExplanations":["Gli script personalizzati aggiungono carico operativo e non rendono immutabili gli snapshot.","Il versioning non impedisce agli utenti privilegiati di eliminare le versioni e l'esportazione aggiunge lavoro.","Corretto — AWS Backup protegge centralmente questi servizi e Vault Lock in compliance mode impedisce a chiunque di eliminare anzitempo i recovery point.","Multi-AZ e auto scaling migliorano disponibilità e capacità, ma non sono backup e non resistono a un'eliminazione logica.","Corretto — le copie cross-Region mantengono disponibili i recovery point in caso di perdita della Region primaria."]},
  "1040": {"h":"1a1185bf","question":"Un'azienda richiede che ogni nuovo volume Amazon EBS nelle Region che utilizza sia cifrato con una specifica chiave AWS KMS, compresi i volumi creati da sviluppatori che dimenticano di selezionare la cifratura. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Distribuire una regola AWS Config che rilevi i volumi EBS non cifrati e ne avvisi i proprietari.","Abilitare la cifratura EBS predefinita in ogni Region utilizzata e impostare la chiave KMS come predefinita.","Usare una funzione AWS Lambda attivata dagli eventi di creazione dei volumi per eliminare i volumi non cifrati.","Formare gli sviluppatori e imporre tramite una IAM policy un tag «encrypted» sui volumi."],"explanation":"La cifratura EBS predefinita è un'impostazione dell'account per singola Region che cifra automaticamente tutti i nuovi volumi con la chiave KMS configurata, indipendentemente da ciò che seleziona l'utente. Una regola AWS Config fornisce visibilità, ma è di rilevamento e lascia che i volumi non cifrati vengano corretti manualmente.","optionExplanations":["Questo rileva i volumi non cifrati solo dopo che esistono e i proprietari devono correggerli manualmente.","Corretto — con la cifratura predefinita, ogni nuovo volume e ogni copia di snapshot in quella Region viene cifrato automaticamente con la chiave scelta.","Eliminare i volumi interrompe i workload e richiede codice personalizzato da realizzare e mantenere.","Un tag non determina la cifratura e la formazione non può garantire la conformità."]},
  "1041": {"h":"d6adad46","question":"Un'azienda usa AWS Organizations e deve registrare l'attività API di tutti gli account attuali e futuri in un account centrale di log archive. Gli auditor devono poter verificare se un file di log è stato modificato o eliminato dopo la consegna. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Creare nel management account un organization trail che consegni a un bucket S3 nell'account di log archive.","Creare manualmente un trail separato in ogni account membro al momento della sua creazione.","Abilitare AWS Config in ogni account per registrare tutte le chiamate API verso l'account centrale.","Abilitare sul trail la convalida dell'integrità dei file di log di CloudTrail.","Abilitare i VPC Flow Logs in ogni VPC e consegnarli all'account di log archive."],"explanation":"Un organization trail cattura l'attività API di ogni account dell'organizzazione, compresi quelli futuri, in un bucket centrale, e la convalida dell'integrità dei file di log produce digest file firmati che rivelano qualsiasi modifica o eliminazione. AWS Config viene spesso confuso con CloudTrail, ma traccia lo stato delle configurazioni anziché ogni chiamata API.","optionExplanations":["Corretto — un organization trail registra automaticamente tutti gli account membri, compresi quelli nuovi, nel bucket centrale.","Questo è soggetto a errori, aggiunge carico operativo e i nuovi account potrebbero essere dimenticati.","AWS Config registra le modifiche alla configurazione delle risorse, non una cronologia completa delle chiamate API.","Corretto — i digest file con hash e firme consentono agli auditor di rilevare file di log modificati o eliminati.","I Flow Logs catturano i metadati del traffico di rete, non l'attività API."]},
  "1042": {"h":"11b4491b","question":"La policy di sicurezza di un'azienda richiede che tutte le richieste a uno specifico bucket Amazon S3 usino la cifratura in transito. Qualsiasi richiesta inviata in semplice HTTP deve essere rifiutata. Quale soluzione soddisfa questo requisito?","options":["Abilitare sul bucket la cifratura predefinita con SSE-KMS.","Aggiungere una bucket policy che neghi tutte le azioni S3 quando aws:SecureTransport è false.","Abilitare sul bucket le impostazioni di S3 Block Public Access.","Creare un gateway VPC endpoint per S3 e instradare attraverso di esso tutto il traffico dei client verso il bucket."],"explanation":"Una bucket policy che nega esplicitamente le richieste in cui aws:SecureTransport è false obbliga tutti gli accessi a usare HTTPS. La cifratura predefinita con SSE-KMS sembra riguardare la cifratura, ma copre i dati a riposo, non il protocollo usato in transito.","optionExplanations":["La cifratura predefinita protegge i dati a riposo e non rifiuta le richieste HTTP non cifrate.","Corretto — questa condition key è false per le richieste HTTP, quindi il deny esplicito rifiuta qualsiasi richiesta non effettuata tramite TLS.","Block Public Access controlla i permessi pubblici, non il protocollo di trasporto utilizzato.","Un endpoint mantiene privato il traffico ma non impone TLS, e i client esterni al VPC non ne sono interessati."]},
  "1043": {"h":"001a73a9","question":"Un'azienda deve proteggere oggetti Amazon S3 critici da sovrascritture ed eliminazioni accidentali. L'eliminazione definitiva di una versione di un oggetto o la sospensione del versioning devono richiedere un fattore di autenticazione aggiuntivo. Gli oggetti devono restare aggiornabili, quindi uno storage WORM non è accettabile. Quale soluzione soddisfa questi requisiti?","options":["Abilitare S3 Object Lock in compliance mode con un periodo di conservazione predefinito.","Abilitare S3 Cross-Region Replication verso un bucket in un altro account AWS.","Abilitare S3 Versioning sul bucket e configurare MFA Delete.","Abilitare SSE-KMS con una customer managed key la cui key policy richieda l'MFA."],"explanation":"S3 Versioning conserva le versioni precedenti quando gli oggetti vengono sovrascritti o eliminati, e MFA Delete richiede l'autenticazione a più fattori per eliminare definitivamente una versione o modificare lo stato del versioning, mentre gli oggetti restano aggiornabili. Anche Object Lock impedisce l'eliminazione, ma impone una conservazione WORM, in contrasto con il requisito.","optionExplanations":["La compliance mode rende immutabili le versioni degli oggetti, cioè uno storage WORM che l'azienda non vuole.","La replica crea copie ma non richiede l'MFA per eliminare le versioni o modificare il versioning.","Corretto — il versioning conserva le versioni precedenti in caso di sovrascrittura o eliminazione e MFA Delete richiede l'MFA per eliminare definitivamente le versioni o sospendere il versioning.","Le key policy regolano le operazioni crittografiche, non l'eliminazione delle versioni S3 o le modifiche al versioning."]},
  "1044": {"h":"096c1984","question":"Un bucket Amazon S3 riceve ogni giorno milioni di piccoli oggetti e usa SSE-KMS con una customer managed key. I costi delle richieste ad AWS KMS sono elevati e l'azienda deve continuare a usare la stessa customer managed key. Quale soluzione soddisferà questi requisiti nel modo PIÙ conveniente?","options":["Abilitare sul bucket le S3 Bucket Keys per SSE-KMS.","Passare la cifratura predefinita del bucket a SSE-S3.","Richiedere una quota di richieste KMS più alta e mantenere la configurazione attuale.","Cifrare ogni oggetto lato client con una nuova data key generata da KMS."],"explanation":"Le S3 Bucket Keys consentono a S3 di usare una chiave di breve durata a livello di bucket, derivata dalla chiave KMS, per creare le data key, riducendo notevolmente il traffico di richieste e i costi KMS mentre la customer managed key resta in uso. Passare a SSE-S3 ridurrebbe anch'esso i costi, ma viola il requisito di mantenere la customer managed key.","optionExplanations":["Corretto — una chiave a livello di bucket derivata dalla chiave KMS riduce il numero di richieste da S3 a KMS, abbassando i costi e mantenendo la stessa chiave.","SSE-S3 eliminerebbe i costi KMS ma smetterebbe di usare la customer managed key richiesta.","Una quota più alta risolve il throttling, non i costi; ogni oggetto genera comunque richieste KMS.","Generare una data key per oggetto chiama comunque KMS per ogni oggetto e aggiunge complessità lato client."]},
  "1045": {"h":"2bca985b","question":"Un'istanza Amazon EC2 ha un volume dati Amazon EBS non cifrato. Una nuova policy richiede che i dati siano cifrati a riposo con una customer managed key AWS KMS. Quale soluzione soddisfa questo requisito?","options":["Modificare le impostazioni del volume esistente per attivare la cifratura a riposo con la customer managed key KMS.","Abilitare la cifratura EBS predefinita in modo che il volume esistente venga cifrato automaticamente.","Aggiungere il volume alla key policy KMS in modo che i suoi dati vengano cifrati alla scrittura successiva.","Creare uno snapshot del volume, copiarlo cifrato con la chiave KMS, creare un volume e sostituirlo."],"explanation":"Poiché un volume EBS non cifrato non può essere cifrato sul posto, l'approccio standard è crearne uno snapshot, copiare lo snapshot con cifratura usando la customer managed key, creare un nuovo volume dalla copia e collegarlo al posto dell'originale. Abilitare la cifratura predefinita sembra più semplice, ma riguarda solo i volumi creati successivamente.","optionExplanations":["Un volume EBS esistente non cifrato non può essere cifrato sul posto.","La cifratura predefinita si applica solo ai volumi creati da quel momento, non a quelli esistenti.","Le key policy controllano chi può usare una chiave; non possono cifrare un volume esistente.","Corretto — una copia cifrata dello snapshot produce un volume cifrato che sostituisce il volume dati originale."]},
  "1046": {"h":"6ae19394","question":"Il web tier di un'azienda di e-commerce invia in modo sincrono ogni nuovo ordine a una flotta di istanze EC2 che si occupano dell'elaborazione degli ordini. Durante le vendite lampo la flotta di elaborazione viene sovraccaricata, le richieste vanno in timeout e alcuni ordini vanno persi. L'azienda vuole garantire che nessun ordine vada perso e consentire al tier di elaborazione di scalare indipendentemente dal web tier. Quale soluzione soddisferà questi requisiti?","options":["Spostare la flotta di elaborazione su tipi di istanza più grandi e abilitare il monitoraggio dettagliato per attivare prima gli allarmi.","Inserire una coda Amazon SQS tra i tier e far sì che le istanze di elaborazione interroghino la coda per ricevere gli ordini.","Collocare davanti alle istanze di elaborazione un Application Load Balancer con bilanciamento del carico cross-zone.","Pubblicare ogni ordine su un topic Amazon SNS che lo invii via HTTPS direttamente alle istanze di elaborazione."],"explanation":"Una coda SQS memorizza in modo durevole gli ordini, così il web tier può accettarli anche quando l'elaborazione è satura, e il tier di elaborazione li consuma al proprio ritmo e può scalare in base alla profondità della coda. Un load balancer si limita a distribuire richieste sincrone; quando tutti i target sono sovraccarichi, le richieste vanno comunque in timeout e gli ordini si perdono.","optionExplanations":["Lo scaling verticale alza solo il limite; un picco abbastanza grande sovraccarica comunque il tier sincrono e gli ordini continuano a perdersi.","Corretto — la coda disaccoppia i tier, conserva gli ordini in modo durevole finché non vengono elaborati e consente ai consumer di scalare in modo indipendente.","Un load balancer distribuisce le richieste ma non offre alcun buffer, quindi i target sovraccarichi causano comunque timeout e ordini persi.","La consegna push di SNS non ha un backlog durevole per i consumer; se gli endpoint restano sovraccarichi, i tentativi di consegna finiscono per esaurirsi."]},
  "1047": {"h":"79b2d31c","question":"Un'azienda di servizi finanziari sta realizzando un servizio che applica le transazioni dei conti. Le transazioni dello stesso conto devono essere elaborate esattamente nell'ordine in cui sono state inviate e i retry dei producer non devono far applicare due volte una transazione. Le transazioni di conti diversi possono essere elaborate in parallelo. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Usare una coda Amazon SQS FIFO con l'ID del conto come message group ID e la deduplicazione abilitata.","Usare una coda Amazon SQS standard e far ordinare ai consumer i messaggi per timestamp prima di applicarli.","Usare un topic Amazon SNS standard con una coda Amazon SQS standard sottoscritta per i consumer.","Usare Amazon Kinesis Data Streams con consumer EC2 che tengano traccia dei sequence number per scartare i record ripetuti."],"explanation":"Una coda SQS FIFO preserva l'ordine all'interno di ogni message group e deduplica i messaggi reinviati entro l'intervallo di deduplicazione, quindi usare l'ID del conto come group ID garantisce l'ordinamento per conto con parallelismo tra conti diversi. Kinesis può preservare l'ordine per shard, ma i duplicati dovuti ai retry dei producer vanno gestiti con codice personalizzato nei consumer su istanze autogestite, con un aggravio operativo.","optionExplanations":["Corretto — i message group garantiscono un ordinamento rigoroso per conto, gruppi diversi vengono elaborati in parallelo e la deduplicazione sopprime gli invii ripetuti.","Le code standard offrono un ordinamento best-effort e una consegna at-least-once, quindi l'ordinamento nel consumer non può impedire in modo affidabile riordini o duplicati.","I topic SNS standard e le code SQS standard non garantiscono né l'ordinamento né l'elaborazione exactly-once.","Si può far funzionare, ma richiede logica di deduplicazione personalizzata e la gestione delle istanze consumer, con un maggiore carico operativo."]},
  "1048": {"h":"6e0ededa","question":"Un'azienda media usa worker EC2 che leggono job da una coda Amazon SQS standard e transcodificano video. Ogni job può richiedere diversi minuti. Il team nota che molti video vengono transcodificati due o tre volte, anche se nessun worker si è guastato. La coda usa le impostazioni predefinite. Cosa dovrebbe fare un solutions architect per risolvere il problema?","options":["Abilitare il long polling sulla coda in modo che i worker attendano i messaggi invece di ricevere risposte vuote.","Configurare un delivery delay sulla coda in modo che i nuovi messaggi restino nascosti per diversi minuti dopo l'arrivo.","Aumentare il visibility timeout della coda oltre il tempo massimo necessario per elaborare un job.","Sostituire la coda standard con una coda SQS FIFO in modo che ogni messaggio venga consegnato a un solo worker."],"explanation":"Mentre un worker elabora un messaggio, questo resta nascosto solo per la durata del visibility timeout; se l'elaborazione dura di più, il messaggio torna visibile e un altro worker lo preleva. Impostare il visibility timeout oltre il tempo massimo di elaborazione evita il problema. Passare a FIFO non aiuta, perché anche un messaggio FIFO torna visibile quando il visibility timeout scade prima dell'eliminazione.","optionExplanations":["Il long polling riduce le ricezioni vuote e i costi, ma non impedisce ai messaggi in elaborazione di tornare visibili.","Un delivery delay rinvia solo la prima consegna; non estende il tempo per cui un messaggio resta nascosto durante l'elaborazione.","Corretto — il messaggio resta invisibile per tutto il tempo di elaborazione, quindi nessun altro worker lo riceve prima che venga eliminato.","Anche le code FIFO riconsegnano un messaggio il cui visibility timeout scade prima dell'eliminazione, quindi i duplicati continuerebbero."]},
  "1049": {"h":"e5884b3c","question":"Un'applicazione elabora i messaggi di una coda Amazon SQS con AWS Lambda. Di tanto in tanto un messaggio malformato fa fallire la funzione ogni volta, per cui il messaggio viene ritentato ripetutamente, spreca concorrenza e ritarda il resto del lavoro. Il team di sviluppo vuole conservare questi messaggi per un'analisi successiva senza scrivere codice personalizzato. Quale soluzione soddisferà questi requisiti?","options":["Ridurre il periodo di conservazione dei messaggi della coda in modo che i messaggi in errore scadano e vengano rimossi automaticamente.","Aumentare il visibility timeout in modo che i messaggi in errore vengano ritentati meno spesso dalla funzione Lambda.","Aggiungere alla funzione Lambda codice che elimini qualsiasi messaggio fallito più di una volta.","Configurare una dead-letter queue che riceva i messaggi dopo un numero massimo di ricezioni fallite."],"explanation":"Una dead-letter queue con una redrive policy sposta automaticamente un messaggio ricevuto un numero prestabilito di volte senza essere eliminato, isolando i poison message per l'analisi senza codice personalizzato. Ridurre il periodo di conservazione rimuoverebbe i messaggi, ma andrebbero persi anziché essere conservati per l'analisi.","optionExplanations":["I messaggi scaduti vengono eliminati definitivamente, quindi il team non potrebbe analizzarli e anche messaggi validi ma lenti potrebbero andare persi.","Un visibility timeout più lungo rallenta soltanto il ciclo di retry; il poison message continua a ripresentarsi all'infinito.","Questo richiede codice personalizzato e scarta i messaggi invece di conservarli per l'analisi.","Corretto — dopo il numero di ricezioni configurato, SQS sposta il messaggio nella dead-letter queue, dove può essere esaminato e reinoltrato in seguito."]},
  "1050": {"h":"f78ee783","question":"Quando un cliente effettua un ordine, un servizio di inventario, un servizio di spedizione e un servizio di analytics devono ricevere ciascuno una copia dell'evento dell'ordine. Ogni servizio elabora gli eventi al proprio ritmo e qualsiasi servizio può restare non disponibile per manutenzione fino a un'ora senza perdere eventi. Quale architettura soddisferà questi requisiti?","options":["Pubblicare gli eventi degli ordini su un topic Amazon SNS con una coda Amazon SQS sottoscritta per ogni servizio.","Inviare gli eventi degli ordini a un'unica coda Amazon SQS standard che tutti e tre i servizi interrogano per i nuovi messaggi.","Pubblicare gli eventi degli ordini su un topic Amazon SNS con una sottoscrizione a un endpoint HTTPS per ogni servizio.","Inviare gli eventi degli ordini a un'unica coda Amazon SQS FIFO che usa un message group per ogni servizio."],"explanation":"Il fan-out da SNS a SQS consegna una copia di ogni evento a ciascuna coda sottoscritta e ogni coda conserva in modo durevole gli eventi finché il relativo servizio non li consuma, anche durante un'interruzione. Con un'unica coda condivisa, ogni messaggio viene consumato da uno solo dei servizi, quindi gli altri lo perderebbero.","optionExplanations":["Corretto — ogni servizio riceve la propria copia durevole e può elaborare o recuperare il ritardo in modo indipendente.","Un messaggio in una coda viene consegnato a un solo consumer ed eliminato da esso, quindi ogni evento raggiungerebbe un solo servizio.","Le consegne push via HTTPS vengono ritentate per un tempo limitato; un servizio offline per un periodo prolungato può perdere eventi.","I message group partizionano i messaggi anziché copiarli; ogni evento verrebbe comunque elaborato da un solo consumer."]},
  "1051": {"h":"022b3391","question":"Un'azienda vuole reagire automaticamente agli eventi provenienti da un'applicazione SaaS di help desk di terze parti e da servizi AWS, come le variazioni di stato delle istanze EC2. I diversi tipi di evento devono essere instradati verso target differenti, tra cui funzioni Lambda e state machine di Step Functions, in base ai campi contenuti nell'evento. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Scrivere una funzione Lambda pianificata che interroga periodicamente l'API SaaS e AWS CloudTrail e poi invoca i target.","Inviare tutti gli eventi a una coda Amazon SQS ed eseguire consumer EC2 che esaminano ogni evento e chiamano i target.","Usare Amazon EventBridge con una partner event source e regole che usano event pattern per individuare ciascun target.","Pubblicare tutti gli eventi su un topic Amazon SNS e aggiungere codice personalizzato che inoltra gli eventi SaaS al topic."],"explanation":"Amazon EventBridge riceve nativamente eventi dai partner SaaS supportati e dai servizi AWS, e le regole con event pattern basati sul contenuto instradano ogni evento verso numerosi target AWS senza codice personalizzato. SNS può filtrare i messaggi, ma non ha un'integrazione nativa con i partner SaaS, quindi servirebbe comunque codice di inoltro personalizzato.","optionExplanations":["Il polling aggiunge latenza e codice personalizzato sia per le due sorgenti sia per la logica di instradamento, aumentando l'onere operativo.","Consumer autogestiti che implementano la logica di instradamento aggiungono infrastruttura e codice da mantenere.","Corretto — le partner event source e le regole con event pattern offrono un instradamento basato sul contenuto verso molti target, senza server né codice di collegamento.","L'integrazione SaaS richiede codice di inoltro personalizzato, che aggiunge un onere evitato da EventBridge."]},
  "1052": {"h":"79ec9e51","question":"Una banca sta realizzando un workflow di approvazione dei prestiti composto da diverse funzioni Lambda. Il workflow richiede ramificazioni condizionali, retry automatici con exponential backoff e un passaggio che attende fino a diversi giorni che un funzionario approvi o rifiuti la richiesta. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Concatenare le funzioni Lambda in modo che ciascuna invochi in modo sincrono la successiva e ne attenda la risposta.","Usare un workflow AWS Step Functions Standard con un task di callback che attende la decisione del funzionario.","Collegare i passaggi con code Amazon SQS e memorizzare lo stato del workflow di ogni richiesta in DynamoDB.","Usare un workflow AWS Step Functions Express che interroga una tabella DynamoDB finché non compare la decisione del funzionario."],"explanation":"I workflow Step Functions Standard supportano esecuzioni di lunga durata, retry integrati con backoff, stati Choice per le ramificazioni e un pattern wait-for-callback che sospende l'esecuzione finché una persona non restituisce un task token. I workflow Express sono pensati per esecuzioni brevi e ad alto volume e non possono restare in pausa per giorni.","optionExplanations":["Le funzioni Lambda hanno una durata massima di esecuzione molto inferiore a diversi giorni, e le chiamate sincrone concatenate richiedono codice personalizzato per retry e ramificazioni.","Corretto — i workflow Standard offrono ramificazioni, retry e lunghe attese di approvazione umana come funzionalità gestite.","Funziona, ma richiede codice personalizzato per orchestrazione, retry e tracciamento dello stato, aumentando l'onere operativo.","I workflow Express sono pensati per esecuzioni brevi, quindi non possono attendere diversi giorni un'approvazione."]},
  "1053": {"h":"49c8e5fe","question":"Una startup sta lanciando una REST API per un'app mobile. Il traffico è imprevedibile, con lunghi periodi di inattività durante la notte e picchi improvvisi dopo le campagne di marketing. Il team non vuole gestire server né pagare capacità inutilizzata, e l'API deve scalare automaticamente. Quale soluzione soddisfa questi requisiti nel modo PIÙ conveniente?","options":["Distribuire l'API su istanze EC2 in un Auto Scaling group con un minimo di due istanze dietro un ALB.","Eseguire l'API come task Amazon ECS su un cluster basato su EC2 che usa un capacity provider per scalare.","Distribuire l'API con AWS Elastic Beanstalk in un ambiente con load balancer e auto scaling abilitato.","Esporre l'API tramite Amazon API Gateway con funzioni AWS Lambda che implementano ciascuna operazione."],"explanation":"API Gateway con Lambda è completamente serverless, scala automaticamente con il volume di richieste e addebita per richiesta e per tempo di esecuzione, quindi i periodi di inattività non costano quasi nulla. Le opzioni basate su EC2 mantengono le istanze in esecuzione anche durante l'inattività e richiedono comunque la gestione dei server.","optionExplanations":["Le istanze minime restano in esecuzione e vengono addebitate anche quando sono inattive, e il team deve gestire i sistemi operativi.","Le container instance EC2 vengono addebitate anche quando sono inattive e devono essere aggiornate e gestite dal team.","Elastic Beanstalk semplifica il deployment, ma esegue comunque istanze EC2 che generano costi durante l'inattività.","Corretto — nessun server da gestire, scalabilità automatica e prezzi a consumo sono adatti a un traffico a picchi e spesso inattivo."]},
  "1054": {"h":"3a64a75a","question":"Un'azienda esegue tre microservizi containerizzati su Amazon ECS: orders, users e payments. I client devono raggiungere tutti i servizi tramite un unico endpoint HTTPS, con le richieste a /orders, /users e /payments inviate al servizio corrispondente. Ogni servizio deve scalare in modo indipendente. Quale soluzione soddisfa questi requisiti?","options":["Creare un Network Load Balancer con una porta di listener separata per il target group di ciascun microservizio.","Creare record Route 53 multivalue answer che restituiscono gli indirizzi IP dei task di ciascun servizio.","Creare un Application Load Balancer le cui regole basate sul path instradano verso un target group per servizio.","Posizionare un Gateway Load Balancer davanti al cluster ECS e registrare ogni task come target."],"explanation":"Un Application Load Balancer opera al livello 7 e può instradare le richieste in base al path dell'URL verso target group separati, ciascuno associato al proprio servizio ECS che scala in modo indipendente. Un Network Load Balancer opera al livello 4 e non può esaminare i path, quindi i client dovrebbero usare porte diverse invece di un unico endpoint con path.","optionExplanations":["Gli NLB instradano per porta e protocollo, non per path dell'URL, quindi il requisito di un unico endpoint con instradamento per path non è soddisfatto.","I record DNS non possono instradare per path dell'URL ed esporrebbero gli IP dei task, che cambiano man mano che i task scalano.","Corretto — le regole basate sul path inviano ogni path al proprio target group e servizio ECS dietro un unico endpoint HTTPS.","I Gateway Load Balancer servono a inserire appliance di rete di terze parti, non a instradare per path HTTP verso i servizi."]},
  "1055": {"h":"39eeb804","question":"Un'azienda di giochi online esegue server di gioco su istanze EC2 in più Availability Zone. I server comunicano con i giocatori tramite UDP e devono gestire milioni di richieste al secondo con latenza molto bassa. Un partner richiede un indirizzo IP fisso per Availability Zone da aggiungere alla allow list del proprio firewall. Quale soluzione di load balancing soddisfa questi requisiti?","options":["Un Network Load Balancer con un indirizzo Elastic IP assegnato in ciascuna Availability Zone.","Un Application Load Balancer con cross-zone load balancing e AWS WAF abilitati.","Una HTTP API di Amazon API Gateway integrata privatamente con i server di gioco EC2.","Un Gateway Load Balancer che inoltra il traffico UDP ai server di gioco in ogni zona."],"explanation":"I Network Load Balancer supportano UDP, offrono un throughput molto elevato con bassa latenza e possono avere un indirizzo Elastic IP per Availability Zone da inserire nelle allow list. Gli Application Load Balancer gestiscono solo HTTP e HTTPS e non forniscono indirizzi IP statici.","optionExplanations":["Corretto — gli NLB supportano UDP su scala molto elevata e consentono un Elastic IP statico per Availability Zone.","Gli ALB non supportano UDP e i loro indirizzi IP cambiano nel tempo, quindi non possono essere inseriti in modo affidabile in una allow list.","API Gateway serve API basate su HTTP e non supporta il traffico di gioco UDP.","I Gateway Load Balancer sono progettati per far passare il traffico attraverso appliance di sicurezza, non per bilanciare il carico dei server di gioco."]},
  "1056": {"h":"7bb45c1b","question":"Un'azienda esegue un'applicazione web su istanze EC2 in un Auto Scaling group. Il traffico varia durante la giornata senza un andamento prevedibile. Il team operativo vuole che il gruppo mantenga l'utilizzo medio della CPU vicino al 50% aggiungendo e rimuovendo istanze automaticamente, con la minor messa a punto possibile. Quale approccio di scaling dovrebbe raccomandare un solutions architect?","options":["Una simple scaling policy che aggiunge un'istanza ogni volta che un allarme CloudWatch segnala CPU sopra il 50%.","Una target tracking scaling policy sull'utilizzo medio della CPU del gruppo con un target del 50%.","Azioni di scheduled scaling che aumentano la capacità in orario lavorativo e la riducono di notte.","Step scaling policy con diversi allarmi CloudWatch che aggiungono più istanze man mano che la CPU sale."],"explanation":"Il target tracking crea e gestisce autonomamente gli allarmi CloudWatch e regola la capacità in proporzione allo scostamento dal valore target, in modo simile a un termostato. Lo step scaling può ottenere risultati simili, ma il team deve definire e mettere a punto manualmente allarmi e incrementi.","optionExplanations":["Il simple scaling aggiunge incrementi fissi e attende i cooldown, reagendo lentamente, e non esegue lo scale-in da solo.","Corretto — il target tracking mantiene la metrica vicino al target e gestisce gli allarmi automaticamente con una messa a punto minima.","Il traffico non ha un andamento prevedibile, quindi orari fissi porterebbero a sovra o sotto dimensionamento.","Lo step scaling funziona, ma richiede di progettare e mantenere diversi allarmi e dimensioni degli step, cioè più messa a punto."]},
  "1057": {"h":"136f4eec","question":"Un'azienda di biglietteria sa che le vendite per un grande concerto apriranno in una data e un'ora precise il mese prossimo e prevede che il traffico salga a molte volte il livello normale nel giro di pochi secondi. Le sue istanze EC2 in un Auto Scaling group impiegano diversi minuti per essere pronte. Quale soluzione garantisce che sia disponibile capacità sufficiente all'apertura delle vendite?","options":["Affidarsi alla target tracking policy esistente, abbassando però il valore target della CPU per scalare prima.","Abilitare il predictive scaling in modo che il gruppo preveda il carico atteso dalle metriche storiche.","Aumentare il default cooldown period in modo che le nuove istanze abbiano più tempo per iniziare a servire.","Creare una scheduled action che aumenta la capacità minima e desiderata del gruppo poco prima della vendita."],"explanation":"Lo scheduled scaling è pensato per eventi noti, singoli o ricorrenti: la capacità viene aumentata a un orario prestabilito, quindi le istanze sono già pronte prima dell'arrivo del traffico. Il predictive scaling fa previsioni dagli andamenti storici, quindi un evento singolo mai verificatosi prima non verrebbe anticipato.","optionExplanations":["Il target tracking reagisce solo dopo che la metrica è salita e, con tempi di avvio lunghi, il picco arriverebbe prima.","Il predictive scaling apprende dallo storico ricorrente; un evento singolo assente dallo storico non verrebbe previsto.","I cooldown influenzano la frequenza delle attività di scaling e non aggiungono capacità prima del picco.","Corretto — la capacità viene aumentata in anticipo rispetto all'evento noto, quindi le istanze sono pronte all'apertura delle vendite."]},
  "1058": {"h":"a1d71fd1","question":"Un Auto Scaling group esegue un'applicazione aziendale il cui carico sale bruscamente ogni mattina dei giorni feriali e cala ogni sera. L'andamento giornaliero si sposta gradualmente nel corso dell'anno. Le istanze impiegano molto tempo per inizializzarsi, quindi l'attuale target tracking policy aggiunge capacità troppo tardi ogni mattina. Il team non vuole mantenere pianificazioni manualmente. Cosa dovrebbe fare un solutions architect?","options":["Sostituire il target tracking con una step scaling policy con soglie di CPU più basse per ogni step.","Creare scheduled action per ogni mattina dei giorni feriali e aggiornarle ogni volta che l'andamento cambia.","Aggiungere una predictive scaling policy che prevede il carico dallo storico e avvia capacità prima della domanda.","Passare a un tipo di istanza più grande in modo che servano meno istanze durante la mattina."],"explanation":"Il predictive scaling analizza il carico storico per individuare i cicli giornalieri e settimanali e avvia le istanze prima dell'aumento previsto, adattandosi man mano che l'andamento evolve. Le scheduled action potrebbero predisporre la capacità in anticipo, ma andrebbero mantenute manualmente al variare dell'andamento, cosa che il team vuole evitare.","optionExplanations":["Lo step scaling resta reattivo, quindi i lunghi tempi di inizializzazione lascerebbero comunque un buco ogni mattina.","Potrebbe funzionare, ma tenere allineate le pianificazioni a un andamento che cambia è proprio lo sforzo manuale che il team vuole evitare.","Corretto — il predictive scaling predispone capacità in anticipo per una domanda ciclica ricorrente e adegua automaticamente le previsioni.","Istanze più grandi non riducono il tempo di inizializzazione né anticipano lo scaling reattivo."]},
  "1059": {"h":"51f10cff","question":"Un sito di e-commerce gira su istanze EC2 in un Auto Scaling group dietro un Application Load Balancer con sticky session abilitate. I dati del carrello sono memorizzati in memoria su ciascuna istanza. Quando il gruppo esegue lo scale-in o un'istanza si guasta, i clienti perdono il carrello. L'azienda vuole che il livello web scali liberamente senza perdere i dati di sessione. Quale soluzione soddisfa questi requisiti?","options":["Memorizzare i dati di sessione in un cluster Amazon ElastiCache ed eliminare la dipendenza dalle sticky session.","Aumentare la durata della stickiness sul target group in modo che i clienti restino più a lungo sulla stessa istanza.","Scrivere i dati di sessione sul volume EBS di ciascuna istanza ed eseguire snapshot dei volumi ogni ora.","Disattivare lo scale-in per l'Auto Scaling group in modo che le istanze con sessioni restino in esecuzione."],"explanation":"Spostare lo stato di sessione in uno store condiviso a bassa latenza come ElastiCache rende stateless le istanze web, quindi qualsiasi istanza può servire qualsiasi richiesta e le istanze possono essere aggiunte, rimosse o sostituite senza perdere i carrelli. Una stickiness più lunga lega comunque una sessione a una sola istanza e non protegge da scale-in o guasti.","optionExplanations":["Corretto — le sessioni esternalizzate rendono stateless le istanze, quindi scaling e guasti non fanno più perdere i carrelli.","La stickiness mantiene gli utenti su un'istanza, ma la sessione va comunque persa quando quell'istanza viene terminata.","I volumi EBS sono legati all'istanza e gli snapshot orari perderebbero le modifiche recenti, quindi i carrelli scomparirebbero comunque.","Disabilitare lo scale-in spreca capacità e fa comunque perdere le sessioni ogni volta che un'istanza si guasta."]},
  "1060": {"h":"51998ac5","question":"Un sito di notizie distribuisce immagini, file CSS e JavaScript da istanze EC2 dietro un Application Load Balancer in una singola Region. I lettori di tutto il mondo segnalano caricamenti lenti delle pagine, e gran parte del carico sulle istanze deriva dalla distribuzione di questi file statici. Quale soluzione migliora le prestazioni e riduce il carico sull'origine con il MINOR onere operativo?","options":["Distribuire ulteriori copie dell'intero stack applicativo in Region vicine ai gruppi di lettori più numerosi.","Creare una distribuzione CloudFront con l'ALB come origine per mettere in cache i file statici nelle edge location.","Aggiungere un cluster Amazon ElastiCache che l'applicazione usa per tenere in cache i file statici in memoria.","Posizionare AWS Global Accelerator davanti all'ALB per instradare i lettori sulla rete globale AWS."],"explanation":"CloudFront mette in cache i contenuti statici nelle edge location vicine ai lettori, riducendo la latenza e servendo la maggior parte delle richieste senza raggiungere l'origine. Global Accelerator migliora il percorso di rete verso l'ALB, ma non mette in cache i contenuti, quindi ogni richiesta raggiunge comunque le istanze.","optionExplanations":["Eseguire diversi stack regionali aggiunge costi e onere operativo significativi per contenuti che una CDN può mettere in cache.","Corretto — il caching nelle edge location riduce la latenza per i lettori globali e scarica le richieste statiche dalle istanze.","ElastiCache si trova accanto all'origine, quindi i lettori globali subiscono comunque tutta la latenza di rete e le istanze continuano a servire i file.","Global Accelerator non fa caching, quindi il carico sull'origine resta invariato e la latenza viene affrontata solo in parte."]},
  "1061": {"h":"fdf7ceeb","question":"Un'azienda esegue servizi containerizzati di lunga durata su un cluster Amazon ECS composto da istanze EC2 autogestite. Il team operativo dedica molto tempo all'applicazione di patch agli host e al dimensionamento della capacità del cluster. L'azienda vuole continuare a usare task definition e servizi ECS, ma smettere di gestire server. Cosa dovrebbe raccomandare un solutions architect?","options":["Migrare i servizi ad Amazon EKS con self-managed node group distribuiti tra le Availability Zone.","Mantenere ECS su EC2 e aggiungere un capacity provider basato su Auto Scaling group per gestire automaticamente le istanze.","Riscrivere i servizi come funzioni AWS Lambda pacchettizzate come immagini container e invocarle on demand.","Eseguire i servizi ECS esistenti su AWS Fargate in modo che AWS fornisca e gestisca la capacità di calcolo sottostante."],"explanation":"AWS Fargate esegue i task ECS senza istanze EC2 che il cliente debba aggiornare o dimensionare, mantenendo le stesse task definition e gli stessi servizi. Un capacity provider automatizza lo scaling delle istanze, ma il team resterebbe comunque responsabile degli host EC2 e delle relative patch.","optionExplanations":["I self-managed node group richiedono comunque l'applicazione di patch ai server e il passaggio da ECS a Kubernetes.","I capacity provider aiutano con lo scaling, ma il team continua a gestire e aggiornare le istanze EC2.","Lambda richiede una riscrittura e ha una durata massima di esecuzione non adatta a servizi di lunga durata.","Corretto — Fargate elimina la gestione degli host mantenendo i costrutti ECS esistenti."]},
  "1062": {"h":"0002fc35","question":"Gli utenti caricano immagini in un bucket Amazon S3 e un'applicazione monolitica su una singola istanza EC2 elabora ogni immagine in modo sincrono. Nei periodi di maggiore attività l'applicazione resta indietro e i caricamenti vanno in timeout. L'azienda vuole disaccoppiare l'elaborazione dai caricamenti e farla scalare automaticamente in base alla quantità di lavoro in attesa. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Spostare l'applicazione su un tipo di istanza più grande e abilitare l'enhanced networking sull'istanza.","Configurare le S3 event notification per inviare un messaggio a una coda Amazon SQS per ogni immagine caricata.","Posizionare un Application Load Balancer con sticky session davanti all'istanza di elaborazione.","Eseguire worker di elaborazione in un Auto Scaling group che scala sul backlog della coda per istanza.","Memorizzare le immagini caricate su un volume EBS io2 collegato a più worker tramite Multi-Attach."],"explanation":"Le S3 event notification verso SQS trasformano ogni caricamento in un elemento di lavoro durevole, disaccoppiando i caricamenti dall'elaborazione. Un Auto Scaling group di worker che scala sul backlog per istanza aggiunge o rimuove worker in base alla quantità di lavoro in attesa. Un'istanza più grande alza solo il limite massimo e mantiene lo stretto accoppiamento.","optionExplanations":["Lo scaling verticale continua a elaborare in modo sincrono e non scala automaticamente con il lavoro in attesa.","Corretto — ogni caricamento genera un elemento di lavoro in coda, quindi i caricamenti non dipendono più dalla velocità di elaborazione.","Un load balancer non disaccoppia il lavoro, e le sticky session sono irrilevanti per l'elaborazione delle immagini in background.","Corretto — scalare sul backlog per istanza adegua il numero di worker alla quantità di lavoro in attesa.","I volumi Multi-Attach sono limitati a una sola Availability Zone, richiedono un file system cluster-aware e non disaccoppiano né scalano l'elaborazione."]},
  "1063": {"h":"94ce25e5","question":"Un'API pubblica basata su Amazon API Gateway invoca in modo sincrono una funzione Lambda che chiama un servizio di pagamento di terze parti. Il servizio di terze parti impone un limite rigoroso alla frequenza delle richieste. Durante i picchi di traffico la funzione Lambda scala orizzontalmente, supera il limite e le richieste falliscono. L'azienda deve proteggere il servizio di terze parti e non deve perdere alcuna richiesta. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Integrare API Gateway direttamente con una coda Amazon SQS in modo che le richieste vengano memorizzate in modo durevole all'arrivo.","Aumentare la memoria allocata alla funzione Lambda in modo che ogni invocazione termini più rapidamente.","Pubblicare le richieste su un topic Amazon SNS che invoca la funzione Lambda per ogni messaggio.","Chiedere ai client di ripetere le chiamate fallite con exponential backoff mantenendo il design sincrono.","Elaborare la coda con Lambda e impostare una concorrenza massima che rispetti il rate limit della terza parte."],"explanation":"Scrivere le richieste in una coda SQS assorbe i picchi in modo durevole, e limitare la concorrenza del consumer Lambda pone un tetto alla frequenza delle richieste inviate alla terza parte mentre il backlog si smaltisce. I retry dei client mantengono il design sincrono, quindi il picco raggiunge comunque la terza parte e le richieste possono ancora fallire.","optionExplanations":["Corretto — la coda memorizza ogni richiesta in modo durevole, quindi i picchi vengono assorbiti invece che rifiutati.","Invocazioni più veloci aumenterebbero anzi la frequenza delle richieste e non servono a bufferizzare o limitare il traffico.","SNS invoca Lambda appena arrivano i messaggi, quindi la concorrenza avrebbe comunque dei picchi e SNS non fornisce un backlog.","I retry dipendono dal comportamento dei client e possono amplificare il carico sulla terza parte durante i picchi; le richieste possono comunque andare perse.","Corretto — un limite di concorrenza sul consumer della coda riduce le chiamate a una frequenza accettata dalla terza parte."]},
  "1064": {"h":"e938598e","question":"Un'azienda esegue i propri microservizi su un cluster Kubernetes autogestito nel proprio data center e usa manifest Kubernetes e chart Helm per i deployment. Sta passando ad AWS e vuole un control plane ad alta disponibilità su più Availability Zone senza doverlo gestire direttamente, mantenendo gli strumenti esistenti. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Installare Kubernetes su istanze EC2 in tre Availability Zone e gestire il control plane con strumenti di automazione.","Convertire i manifest in task definition di Amazon ECS ed eseguire i servizi su AWS Fargate.","Distribuire i container con AWS Elastic Beanstalk usando il suo ambiente Docker multicontainer.","Usare Amazon EKS con managed node group in modo che AWS gestisca il control plane Kubernetes."],"explanation":"Amazon EKS fornisce un control plane Kubernetes gestito che opera su più Availability Zone, e i managed node group semplificano il ciclo di vita dei worker, quindi manifest e chart Helm esistenti continuano a funzionare. ECS su Fargate elimina la gestione dei server, ma richiederebbe la conversione di tutti gli strumenti Kubernetes.","optionExplanations":["L'azienda dovrebbe gestire, aggiornare ed eseguire il backup del control plane da sola, aumentando l'onere operativo.","ECS non è Kubernetes, quindi manifest e chart Helm andrebbero riscritti.","Elastic Beanstalk non esegue workload Kubernetes, quindi gli strumenti esistenti non potrebbero essere riutilizzati.","Corretto — EKS esegue un control plane gestito e multi-AZ ed è compatibile con gli strumenti Kubernetes standard."]},
  "1065": {"h":"7331a28d","question":"Un'azienda esegue un parco di istanze EC2 che interrogano continuamente una coda Amazon SQS ed eseguono brevi attività di elaborazione. Il volume di messaggi è basso per la maggior parte della giornata con picchi occasionali, quindi le istanze sono sottoutilizzate e il team deve aggiornarle e scalarle. Quale soluzione riduce l'onere operativo continuando a scalare con il volume di messaggi?","options":["Sostituire il parco con un tipo di istanza più piccolo in un Auto Scaling group che scala sull'utilizzo della CPU.","Eseguire il codice di polling come task AWS Fargate sempre attivi e riavviati in caso di errore.","Configurare una funzione AWS Lambda con la coda come event source per elaborare i messaggi.","Usare una state machine Step Functions con uno stato Wait che controlla la presenza di nuovi messaggi nella coda."],"explanation":"Con un event source mapping SQS, il servizio Lambda interroga la coda, adegua il numero di invocazioni concorrenti al backlog ed elimina i messaggi in caso di successo, quindi non ci sono server da gestire. Fargate elimina le patch degli host, ma i task sempre attivi richiedono comunque una configurazione di scaling e vengono addebitati anche quando sono inattivi.","optionExplanations":["Il team dovrebbe comunque gestire e aggiornare le istanze, e la CPU è un indicatore poco affidabile del backlog della coda.","I task sempre in esecuzione vengono addebitati anche quando sono inattivi e richiedono comunque una logica di scaling legata alla coda.","Corretto — Lambda gestisce polling, scaling ed eliminazione dei messaggi senza infrastruttura da gestire.","Una state machine che interroga la coda è un'orchestrazione personalizzata che aggiunge costi e complessità senza scaling nativo."]},
  "1066": {"h":"c41861a2","question":"Un'azienda esegue il proprio database MySQL di produzione su un'istanza DB Amazon RDS Single-AZ. L'azienda ha bisogno che il database si ripristini automaticamente da un guasto di una Availability Zone con una perdita di dati minima e senza modificare la stringa di connessione dell'applicazione. Quale soluzione soddisfa questi requisiti?","options":["Creare una read replica in un'altra Availability Zone e promuoverla manualmente se la primaria si guasta.","Convertire l'istanza DB in un deployment Multi-AZ con uno standby sincrono in un'altra zona.","Abilitare i backup automatici ed eseguire il ripristino in un'altra Availability Zone con point-in-time recovery.","Copiare ogni ora gli snapshot automatici in un'altra Region e, se necessario, ripristinare dall'ultima copia."],"explanation":"RDS Multi-AZ mantiene uno standby replicato in modo sincrono in un'altra Availability Zone ed esegue il failover automaticamente aggiornando il nome DNS dello stesso endpoint, quindi non si perdono dati e l'applicazione mantiene la propria stringa di connessione. Una read replica usa la replica asincrona, richiede una promozione manuale e ha un endpoint diverso.","optionExplanations":["La promozione è manuale, la replica è asincrona quindi le scritture recenti possono andare perse, e l'endpoint cambia.","Corretto — replica sincrona e failover automatico dietro lo stesso endpoint soddisfano tutti i requisiti.","Un ripristino point-in-time crea una nuova istanza con un nuovo endpoint e richiede molto più tempo.","Il ripristino da copie orarie degli snapshot perde fino a un'ora di dati ed è un processo manuale e lento."]},
  "1067": {"h":"12835836","question":"Un'azienda usa un deployment Amazon RDS for PostgreSQL Multi-AZ DB instance per il proprio sistema di gestione ordini. Ora gli analisti eseguono sul database query di reportistica pesanti che rallentano l'elaborazione degli ordini. I report tollerano dati vecchi di qualche secondo. Quale soluzione isola il workload di reportistica da quello di produzione?","options":["Puntare gli strumenti di reportistica all'istanza standby Multi-AZ in modo che serva il traffico di lettura.","Scalare verticalmente l'istanza DB primaria a una classe più grande per gestire entrambi i workload insieme.","Posizionare Amazon RDS Proxy davanti al database e far passare attraverso di esso le connessioni di reportistica.","Creare una read replica RDS e puntare gli strumenti di reportistica all'endpoint della read replica."],"explanation":"Una read replica riceve aggiornamenti asincroni dalla primaria e serve query di sola lettura su risorse di calcolo separate, quindi la reportistica non compete più con l'elaborazione degli ordini; un leggero ritardo di replica qui è accettabile. In un deployment Multi-AZ DB instance lo standby non può servire traffico di lettura: esiste solo per il failover.","optionExplanations":["Lo standby di un deployment Multi-AZ DB instance non è accessibile in lettura, quindi non può scaricare la reportistica.","Un'istanza più grande può aiutare temporaneamente, ma entrambi i workload competono comunque per le stesse risorse.","RDS Proxy gestisce un pool di connessioni ma invia comunque ogni query alla stessa primaria, quindi la contesa resta.","Corretto — la reportistica viene eseguita su una replica separata, isolata dal workload di produzione."]},
  "1068": {"h":"ae01bf4c","question":"Un'azienda usa un DB cluster Amazon Aurora MySQL che ha solo un'istanza writer. L'azienda vuole ridurre al minimo il downtime in caso di guasto dell'istanza writer o della sua Availability Zone e vuole anche scalare il traffico di lettura all'interno della stessa Region. Quale soluzione soddisfa questi requisiti nel modo PIÙ conveniente?","options":["Aggiungere Aurora Replica in altre Availability Zone e inviare il traffico di lettura al reader endpoint del cluster.","Convertire il cluster in un Aurora global database con un cluster secondario in una seconda Region.","Creare una read replica cross-Region che usa la replica tramite binary log di MySQL a partire dal cluster.","Eseguire frequenti snapshot manuali del cluster e ripristinare l'ultimo snapshot se il writer si guasta."],"explanation":"Le Aurora Replica in altre Availability Zone condividono lo storage del cluster, servono le letture tramite il reader endpoint e vengono promosse automaticamente se il writer si guasta, garantendo un failover rapido all'interno della Region. Un Aurora global database aggiunge una seconda Region, che costa più del necessario per disponibilità e scalabilità delle letture all'interno della Region.","optionExplanations":["Corretto — le repliche forniscono target di failover automatico e scalabilità delle letture all'interno della Region al costo più basso.","I global database sono pensati per il DR cross-Region e per letture globali a bassa latenza, il che qui aggiunge costi inutili.","La replica tramite binary log verso un'altra Region aggiunge ritardo e costi e non fornisce failover automatico all'interno della Region.","Il ripristino da snapshot crea un nuovo cluster, richiede molto più tempo e non aiuta a scalare le letture."]},
  "1069": {"h":"f59b9ddd","question":"Un'azienda globale esegue un database Amazon Aurora PostgreSQL in una Region. Ha bisogno di una soluzione di disaster recovery in una seconda Region con un RPO di circa un secondo e un RTO di circa un minuto. Gli utenti vicini alla seconda Region dovrebbero inoltre ottenere letture a bassa latenza durante il normale funzionamento. Quale soluzione soddisfa questi requisiti?","options":["Copiare gli snapshot automatici di Aurora nella seconda Region e ripristinare il più recente in caso di disastro.","Usare AWS Backup con una regola di copia cross-Region eseguita ogni ora per il cluster Aurora.","Convertire il cluster in un Aurora global database con un cluster secondario nella seconda Region.","Migrare i dati su Amazon DynamoDB global tables e modificare il livello di accesso ai dati dell'applicazione."],"explanation":"Aurora Global Database replica a livello di storage con un ritardo tipicamente inferiore al secondo e consente di promuovere la Region secondaria in circa un minuto, servendo nel frattempo letture locali nella Region secondaria. Le copie di snapshot o backup comportano un RPO misurato in ore e un tempo di ripristino ben superiore a un minuto.","optionExplanations":["Le copie degli snapshot danno un RPO di ore e il ripristino di un cluster richiede molto più di un minuto.","Copie di backup orarie non possono rispettare un RPO di un secondo, e il ripristino è lento.","Corretto — la replica a livello di storage offre un RPO molto basso, un failover regionale rapido e letture locali nella Region secondaria.","Richiede la migrazione a un database diverso e la riscrittura dell'applicazione, il che non è necessario."]},
  "1070": {"h":"99091320","question":"Un gioco mobile memorizza i profili dei giocatori in una tabella Amazon DynamoDB in una Region. I giocatori si trovano in Nord America, Europa e Asia, e il gioco ha bisogno di letture e scritture a bassa latenza in ciascuna area geografica. Il gioco deve continuare ad accettare scritture nelle altre aree se una Region diventa non disponibile. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Aggiungere un cluster DynamoDB Accelerator (DAX) in ogni Region davanti all'attuale tabella in una singola Region.","Convertire la tabella in una DynamoDB global table con repliche in una Region di ciascuna area geografica.","Usare DynamoDB Streams e funzioni Lambda per copiare ogni modifica nelle tabelle delle altre Region.","Posizionare una distribuzione Amazon CloudFront davanti a un'API che legge e scrive sull'unica tabella."],"explanation":"Le DynamoDB global table forniscono una replica completamente gestita, multi-Region e multi-active, quindi ogni Region accetta letture e scritture locali e le Region rimanenti continuano a funzionare se una si guasta. Una pipeline personalizzata con Streams e Lambda potrebbe replicare i dati, ma richiede di realizzare e gestire la replica e la risoluzione dei conflitti.","optionExplanations":["DAX mette in cache le letture nella VPC di una Region e non può fare da front-end a una tabella in un'altra Region; le scritture andrebbero comunque in un'unica Region.","Corretto — la replica active-active gestita offre letture e scritture locali e resiste a un'interruzione regionale.","La replica personalizzata è complessa da realizzare, monitorare e da gestire per i conflitti, il che aggiunge onere operativo.","CloudFront non può mettere in cache le scritture, quindi tutte le scritture dipendono comunque dalla tabella di un'unica Region."]},
  "1071": {"h":"00aae0f6","question":"Un'azienda ospita la propria applicazione web dietro un Application Load Balancer in una Region. Ha anche creato un sito statico di manutenzione in un bucket Amazon S3 in un'altra Region. Se l'applicazione diventa non integra, gli utenti devono essere indirizzati automaticamente al sito di manutenzione e devono essere riportati indietro quando l'applicazione si ripristina. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Configurare l'health checking di Route 53 sull'endpoint ALB primario, ad esempio valutando lo stato di salute del target.","Creare una geolocation routing policy di Route 53 con il sito S3 configurato come record predefinito.","Abbassare il TTL di un record simple routing e aggiornare il record con uno script quando viene rilevata un'interruzione.","Creare record failover di Route 53 con l'ALB come primario e l'endpoint del sito S3 come secondario.","Creare un record multivalue answer di Route 53 che restituisce sia l'ALB sia l'endpoint del sito S3."],"explanation":"Il failover routing restituisce il record primario finché il suo health check ha esito positivo e restituisce automaticamente il record secondario quando fallisce, tornando al primario quando è di nuovo integro. L'health checking dell'ALB, tramite un health check di Route 53 o valutando lo stato di salute dell'alias target, fornisce il segnale. Le risposte multivalue restituiscono più record integri contemporaneamente, quindi gli utenti potrebbero raggiungere il sito di manutenzione anche quando l'applicazione è integra.","optionExplanations":["Corretto — Route 53 ha bisogno di un segnale sullo stato di salute del primario per decidere quando eseguire il failover e il ritorno.","La geolocation instrada in base alla posizione dell'utente, non allo stato di salute, quindi non invierebbe gli utenti alla manutenzione durante un'interruzione.","Un aggiornamento del record tramite script è un meccanismo manuale e personalizzato, più lento e meno affidabile del failover integrato.","Corretto — il failover routing invia traffico al secondario solo mentre il primario non è integro.","Le risposte multivalue invierebbero alcuni utenti al sito di manutenzione anche quando l'applicazione è integra."]},
  "1072": {"h":"b8463239","question":"Un'azienda SaaS ha distribuito copie identiche della propria applicazione in tre Region AWS. L'azienda vuole che ogni utente sia servito dalla Region che gli offre le migliori prestazioni di rete e vuole che il traffico venga spostato automaticamente da una Region se il relativo deployment diventa non integro. Quale configurazione di Route 53 soddisfa questi requisiti?","options":["Record geolocation routing per ogni continente, con un record predefinito che punta alla Region più grande.","Record weighted routing che assegnano lo stesso peso a ciascuno dei tre deployment regionali.","Record geoproximity routing con valori di bias regolati manualmente per spostare il traffico tra le Region.","Record latency-based routing per ogni Region, con health check associati a ciascun record."],"explanation":"Il latency-based routing risponde a ogni query con la Region che ha la latenza misurata più bassa per l'utente, e gli health check associati escludono dalle risposte le Region non integre. La geolocation instrada in base alla posizione dell'utente anziché alla latenza misurata, quindi gli utenti possono essere inviati a una Region più lenta.","optionExplanations":["La geolocation si basa su dove si trovano gli utenti, non sulla latenza di rete misurata, quindi potrebbe non offrire le prestazioni migliori.","Pesi uguali distribuiscono il traffico in modo uniforme indipendentemente da dove si trovano gli utenti, ignorando la latenza.","La geoproximity instrada in base alla distanza più un bias manuale, non alla latenza misurata, e richiede una regolazione continua.","Corretto — gli utenti vengono inviati alla Region con latenza più bassa e gli health check spostano il traffico dalle Region non integre."]},
  "1073": {"h":"02e76dfa","question":"Un'azienda usa una strategia blue/green per rilasciare una nuova versione della propria applicazione. Il nuovo ambiente green gira dietro un proprio Application Load Balancer, separato dall'ambiente blue. L'azienda vuole inizialmente inviare una piccola percentuale di utenti all'ambiente green e poi aumentarla gradualmente, usando il DNS. Quale routing policy di Route 53 dovrebbe usare l'azienda?","options":["Failover routing con l'ambiente blue come primario e l'ambiente green come secondario.","Latency-based routing con record per gli ambienti blue e green nella stessa Region.","Weighted routing con record per entrambi gli ambienti e pesi che vengono modificati nel tempo.","Multivalue answer routing che restituisce a ogni client gli indirizzi di entrambi i load balancer."],"explanation":"Il weighted routing restituisce ciascun record in proporzione al suo peso, quindi il traffico può iniziare con una piccola quota per green e spostarsi gradualmente modificando i pesi. Il failover routing è tutto o niente e invia traffico al secondario solo quando il primario non è integro.","optionExplanations":["Il failover non suddivide il traffico; green riceverebbe utenti solo se blue si guastasse.","Il latency routing sceglie in base alla latenza della Region; due ambienti nella stessa Region non possono essere suddivisi in percentuale in questo modo.","Corretto — i pesi controllano la proporzione delle risposte DNS, consentendo uno spostamento graduale verso green.","Le risposte multivalue restituiscono entrambi gli endpoint in modo casuale e non controllano la percentuale inviata a ciascun ambiente."]},
  "1074": {"h":"bce52ad1","question":"Per requisiti legali, un'azienda media deve servire gli utenti che si trovano in Germania da un deployment dedicato che contiene i contenuti concessi in licenza per quel paese. Gli utenti di tutti gli altri paesi devono essere serviti dal deployment globale dell'azienda. Quale configurazione di routing di Route 53 soddisfa questi requisiti?","options":["Geolocation routing con un record per la Germania e un record predefinito che punta al deployment globale.","Latency-based routing con record per il deployment tedesco e per il deployment globale.","Geoproximity routing con un bias positivo che amplia l'area servita dal deployment tedesco.","Weighted routing che invia al deployment tedesco una quota di traffico pari alla base utenti della Germania."],"explanation":"Il geolocation routing risponde in base al paese da cui proviene la query, quindi un record per la Germania invia gli utenti tedeschi al deployment dedicato e il record predefinito serve tutti gli altri. La geoproximity instrada in base alla distanza tra utenti e risorse, che non segue i confini nazionali e potrebbe includere o escludere utenti in modo errato.","optionExplanations":["Corretto — i record geolocation a livello di paese applicano il confine legale, e il record predefinito copre tutti gli altri.","Il latency routing potrebbe inviare gli utenti tedeschi al deployment globale se risponde più velocemente, violando il requisito.","La geoproximity si basa sulla distanza, quindi i suoi confini non corrispondono a quelli nazionali.","Il weighted routing sceglie i record in modo casuale in base al peso, non in base alla posizione dell'utente."]},
  "1075": {"h":"ae637c53","question":"Un'azienda esegue un'applicazione interna di reportistica su istanze EC2 con un database Amazon RDS. Il business ha fissato un RPO di 24 ore e un RTO di 24 ore per un disastro regionale e vuole il costo più basso possibile per il disaster recovery. Quale strategia di DR dovrebbe raccomandare un solutions architect?","options":["Pilot light, con il database replicato continuamente in una seconda Region e server pronti per essere avviati.","Backup and restore, con i backup copiati in una seconda Region e l'infrastruttura ricreata quando necessario.","Warm standby, con una copia ridimensionata dell'intero ambiente sempre in esecuzione in una seconda Region.","Multi-site active/active, con l'intero ambiente che serve traffico in due Region contemporaneamente."],"explanation":"Backup and restore è la strategia di DR meno costosa ed è adatta a obiettivi di RPO e RTO misurati in ore, perché nella Region di ripristino vengono conservati solo i backup e le risorse vengono create durante il ripristino. Pilot light mantiene dati replicati e risorse principali sempre in esecuzione, il che costa più di quanto giustifichino obiettivi così ampi.","optionExplanations":["La replica continua e le risorse principali sempre attive costano più del necessario per obiettivi di 24 ore.","Corretto — backup giornalieri copiati cross-Region rispettano un RPO e un RTO di 24 ore al costo più basso.","Un ambiente ridimensionato in esecuzione comporta costi continui ben superiori a quanto richiesto dagli obiettivi.","Active/active è la strategia più costosa ed è pensata per un RTO quasi nullo, non per obiettivi di 24 ore."]},
  "1076": {"h":"c4f6a749","question":"Un'azienda deve ripristinare il proprio portale clienti in una seconda Region dopo un disastro regionale con un RPO di pochi minuti e un RTO di poche ore. Per ridurre al minimo i costi, l'azienda non vuole server applicativi in esecuzione nella Region di ripristino durante il normale funzionamento. Quale strategia di DR soddisfa questi requisiti nel modo PIÙ conveniente?","options":["Backup and restore, usando snapshot notturni del database copiati nella Region di ripristino.","Warm standby, con un livello applicativo ridimensionato ma pienamente funzionante sempre in esecuzione.","Pilot light, con dati replicati continuamente e server avviati solo al momento del ripristino.","Multi-site active/active, con entrambe le Region che servono sempre traffico di produzione."],"explanation":"Pilot light mantiene i dati principali replicati continuamente, garantendo un RPO di minuti, mentre i server applicativi vengono avviati da template e immagini predisposti solo durante il ripristino, rispettando un RTO di ore a basso costo. Backup and restore con snapshot notturni perderebbe fino a un giorno di dati, non rispettando l'RPO.","optionExplanations":["Gli snapshot notturni comportano un RPO fino a un giorno, violando il requisito di pochi minuti.","Il warm standby mantiene server applicativi in esecuzione, cosa che l'azienda vuole evitare per motivi di costo.","Corretto — la replica continua dei dati rispetta l'RPO, e i server avviati su richiesta mantengono basso il costo a riposo.","Active/active va ben oltre i requisiti ed è l'opzione più costosa."]},
  "1077": {"h":"4167c749","question":"Un'azienda di logistica ha bisogno che la propria piattaforma di tracciamento ordini si ripristini da un'interruzione regionale entro pochi minuti. L'ambiente di ripristino deve poter servire subito traffico di produzione a capacità ridotta e poi scalare, e l'azienda vuole testarlo continuamente. Una capacità duplicata completa in due Region è troppo costosa. Quale strategia di DR dovrebbe usare l'azienda?","options":["Warm standby, con una copia ridimensionata e pienamente funzionante dell'ambiente in esecuzione in una seconda Region.","Pilot light, con solo il database replicato in esecuzione e le altre risorse avviate durante il ripristino.","Backup and restore, usando le copie di AWS Backup in una seconda Region per ricostruire l'ambiente.","Multi-site active/active, con l'intera capacità di produzione in esecuzione che serve gli utenti in entrambe le Region."],"explanation":"Il warm standby mantiene in esecuzione un ambiente più piccolo ma pienamente funzionante, che quindi può ricevere traffico immediatamente, essere scalato dopo il failover ed essere testato continuamente, rispettando un RTO di minuti. Pilot light richiede di avviare il livello applicativo durante il ripristino, quindi non può servire traffico immediatamente.","optionExplanations":["Corretto — un ambiente ridimensionato in esecuzione serve traffico immediatamente e scala, a un costo inferiore rispetto alla duplicazione completa.","Nel pilot light i server applicativi non sono in esecuzione, quindi l'ambiente non può servire traffico immediatamente.","La ricostruzione dai backup richiede ore, il che non può rispettare un RTO di minuti.","L'intera capacità di produzione in due Region è l'opzione costosa che l'azienda ha escluso."]},
  "1078": {"h":"65b59d67","question":"Un'azienda serve un sito di marketing statico da un bucket Amazon S3 tramite una distribuzione Amazon CloudFront. Il sito deve restare disponibile anche se Amazon S3 nella Region del bucket subisce un'interruzione. I contenuti sono già replicati in un bucket in una seconda Region. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Creare una seconda distribuzione CloudFront per il bucket di replica e cambiare manualmente il record DNS durante un'interruzione.","Abilitare S3 Transfer Acceleration sul bucket primario in modo che le richieste vengano servite tramite le edge location.","Aumentare il TTL di cache di tutti gli oggetti in modo che CloudFront continui a servire i contenuti durante un'interruzione di S3.","Configurare un origin group CloudFront con il bucket primario e il bucket di replica come origine di failover."],"explanation":"Un origin group CloudFront ritenta automaticamente una richiesta sull'origine secondaria quando la primaria restituisce determinati codici di errore o va in timeout, quindi il sito resta disponibile senza interventi manuali. TTL più lunghi aiutano solo per gli oggetti già in cache, quindi i cache miss fallirebbero comunque durante un'interruzione.","optionExplanations":["Le modifiche manuali al DNS aggiungono lavoro operativo e downtime durante il passaggio.","Transfer Acceleration velocizza upload e download verso un bucket, ma non fornisce failover verso un'altra Region.","Gli oggetti non in cache o scaduti fallirebbero comunque, quindi la disponibilità non è garantita.","Corretto — l'origin failover passa automaticamente al bucket di replica quando l'origine primaria si guasta."]},
  "1079": {"h":"582f3361","question":"Un'azienda memorizza documenti importanti in un bucket Amazon S3 in una Region. Una nuova policy di resilienza richiede che ogni oggetto appena caricato venga memorizzato automaticamente anche in un bucket in una Region diversa. Quale combinazione di passaggi deve eseguire un solutions architect per soddisfare questo requisito? (Seleziona DUE)","options":["Abilitare S3 Transfer Acceleration sul bucket di origine in modo che i nuovi oggetti vengano copiati tramite le edge location.","Abilitare S3 Versioning sia sul bucket di origine sia sul bucket di destinazione.","Creare una regola di replica S3 sul bucket di origine che punta al bucket nell'altra Region.","Creare una regola S3 Lifecycle che sposta i nuovi oggetti nel bucket dell'altra Region.","Configurare S3 Same-Region Replication verso un secondo bucket e abilitare l'MFA delete su di esso."],"explanation":"S3 Cross-Region Replication richiede il versioning sia sul bucket di origine sia su quello di destinazione e una regola di replica, con un ruolo IAM, che indichi il bucket di destinazione in un'altra Region. Una volta configurata, i nuovi oggetti vengono replicati automaticamente e in modo asincrono. Le regole Lifecycle cambiano la classe di storage o fanno scadere gli oggetti; non possono spostare oggetti in un altro bucket o in un'altra Region.","optionExplanations":["Transfer Acceleration velocizza i trasferimenti su lunghe distanze, ma non copia gli oggetti in un altro bucket.","Corretto — il versioning deve essere abilitato su entrambi i bucket prima di poter configurare la replica.","Corretto — la regola di replica copia automaticamente i nuovi oggetti nel bucket di destinazione nell'altra Region.","Le regole Lifecycle cambiano la classe di storage o fanno scadere gli oggetti all'interno di un bucket; non possono copiare oggetti tra Region.","La Same-Region Replication mantiene la copia nella stessa Region, il che non soddisfa la policy."]},
  "1080": {"h":"0b532454","question":"Un'azienda esegue workload che usano volumi Amazon EBS, database Amazon RDS e file system Amazon EFS in diversi account AWS. Gli auditor richiedono pianificazioni e conservazione dei backup gestite centralmente, con copie di ogni backup memorizzate in una seconda Region. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Usare piani AWS Backup gestiti tramite AWS Organizations, con una regola che copia i backup in una seconda Region.","Usare policy di Amazon Data Lifecycle Manager che creano snapshot EBS e li copiano in una seconda Region.","Scrivere funzioni Lambda per ogni servizio che creano backup in modo pianificato e li copiano tra Region.","Abilitare i backup automatici cross-Region di RDS, la replica EFS e script separati per gli snapshot EBS."],"explanation":"AWS Backup gestisce centralmente pianificazioni, conservazione e copie cross-Region dei backup per EBS, RDS, EFS e altri servizi, e le backup policy possono essere applicate a più account con AWS Organizations. Data Lifecycle Manager può copiare gli snapshot EBS tra Region, ma non copre RDS né EFS.","optionExplanations":["Corretto — un unico servizio gestito applica pianificazioni, conservazione e copie cross-Region coerenti tra servizi e account.","Data Lifecycle Manager gestisce solo snapshot EBS e AMI, lasciando scoperti RDS ed EFS.","Le funzioni personalizzate per ogni servizio vanno realizzate, monitorate e mantenute, il che comporta un onere elevato.","Combinare diverse funzionalità specifiche dei servizi e script non offre una gestione centralizzata e aggiunge lavoro operativo."]},
  "1081": {"h":"3622f3fb","question":"Un'azienda esegue server applicativi critici Windows e Linux su VMware nel proprio data center on-premises. Ha bisogno di un disaster recovery su AWS con un RPO di secondi e un RTO di minuti, mantenendo basso il costo delle risorse AWS finché non si verifica un disastro. Quale soluzione soddisfa questi requisiti?","options":["Usare AWS Backup per eseguire ogni notte il backup delle macchine virtuali on-premises e ripristinarle come istanze EC2.","Usare gli snapshot di AWS Storage Gateway Volume Gateway e ricostruire i server dai volumi EBS quando necessario.","Usare AWS Elastic Disaster Recovery per una replica continua verso un'area di staging a basso costo.","Usare AWS DataSync per copiare frequentemente i file system dei server su Amazon S3."],"explanation":"AWS Elastic Disaster Recovery replica continuamente i dati a livello di blocco dai server di origine verso un'area di staging leggera, garantendo un RPO di secondi, e avvia le istanze di ripristino in pochi minuti solo quando necessario. I backup notturni comportano un RPO fino a un giorno e un ripristino più lento.","optionExplanations":["I backup notturni danno un RPO fino a 24 ore e il ripristino delle macchine virtuali richiede più di qualche minuto.","Snapshot point-in-time e ricostruzione manuale non possono garantire un RPO di secondi né un RTO di minuti.","Corretto — la replica continua a livello di blocco verso risorse di staging a basso costo garantisce un RPO di secondi e un avvio rapido.","Copiare file su S3 non acquisisce server completi e avviabili e non può rispettare né l'RPO né l'RTO."]},
  "1082": {"h":"a6924c60","question":"Un'applicazione di content management gira su istanze EC2 Linux in un Auto Scaling group distribuito su tre Availability Zone. Tutte le istanze devono leggere e scrivere contemporaneamente lo stesso insieme di file, e lo storage dei file deve restare disponibile se una Availability Zone si guasta. Quale soluzione di storage soddisfa questi requisiti?","options":["Volumi EBS Provisioned IOPS io2 con Multi-Attach abilitato e condivisi da tutte le istanze.","Un file system Amazon EFS con una classe di storage Regional, montato su tutte le istanze.","Un file system Amazon EFS One Zone in una Availability Zone, montato su tutte le istanze.","Volumi instance store su ogni istanza, sincronizzati da un job rsync pianificato."],"explanation":"Amazon EFS con una classe di storage Regional memorizza i dati in modo ridondante su più Availability Zone e supporta l'accesso concorrente da molte istanze Linux in zone diverse. I volumi EBS Multi-Attach possono essere collegati solo a istanze nella stessa Availability Zone e richiedono un file system cluster-aware.","optionExplanations":["Multi-Attach funziona solo all'interno di una Availability Zone, quindi le istanze in altre zone non possono usare il volume e un guasto della AZ ne blocca l'accesso.","Corretto — EFS fornisce un file system POSIX condiviso memorizzato su più Availability Zone.","Lo storage One Zone viene perso o diventa non disponibile se quella Availability Zone si guasta.","I dati dell'instance store sono effimeri, e una sincronizzazione pianificata causa dati incoerenti e possibili perdite."]},
  "1083": {"h":"6f3d83cf","question":"Un'azienda esegue un'applicazione web su istanze EC2 in un Auto Scaling group dietro un Application Load Balancer. A volte il processo applicativo si blocca: l'ALB contrassegna l'istanza come non integra, ma l'istanza non viene mai sostituita. Inoltre gli amministratori applicano le patch alle istanze in loco, causando un configuration drift tra le istanze. Quale combinazione di passaggi migliora resilienza e coerenza? (Seleziona DUE)","options":["Abilitare l'EC2 automatic instance recovery in modo che le istanze guaste vengano riavviate su nuovo hardware sottostante.","Usare AWS Systems Manager Run Command per applicare le patch a tutte le istanze in esecuzione contemporaneamente.","Attivare gli health check di Elastic Load Balancing per l'Auto Scaling group in modo che sostituisca le istanze non integre.","Aumentare l'health check grace period in modo che le istanze abbiano più tempo per ripristinarsi da sole.","Creare una nuova AMI con le patch, aggiornare il launch template e usare un instance refresh per sostituire le istanze."],"explanation":"Per impostazione predefinita un Auto Scaling group usa solo gli status check EC2, quindi un'istanza con l'applicazione bloccata resta in servizio; abilitare gli health check ELB fa sì che il gruppo sostituisca le istanze che non superano gli health check del load balancer. Creare una nuova AMI e distribuirla con un instance refresh segue il principio dell'infrastruttura immutabile, sostituendo le istanze anziché modificarle, il che elimina il drift.","optionExplanations":["L'automatic recovery reagisce ai fallimenti dei system status check, non ai blocchi dell'applicazione, quindi queste istanze non verrebbero sostituite.","Applicare patch in loco è proprio ciò che causa il drift; non porta il parco a istanze identiche e sostituibili.","Corretto — il gruppo considera quindi non integre le istanze che falliscono gli health check dell'ALB e le sostituisce.","Un grace period più lungo ritarda soltanto la valutazione dello stato di salute e non sostituisce le istanze bloccate.","Corretto — distribuire una nuova AMI sostituisce le istanze con altre identiche e aggiornate, eliminando il configuration drift."]},
  "1084": {"h":"6bbc0bbd","question":"Una piccola azienda esegue la propria applicazione web e il database MySQL insieme su una singola istanza EC2 in una Availability Zone. Un guasto dell'istanza ha causato di recente una lunga interruzione. L'azienda vuole che l'applicazione resti disponibile in caso di guasto di un'istanza o di un'intera Availability Zone, con il minor numero possibile di modifiche all'applicazione. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Passare a un tipo di istanza più grande e abilitare l'EC2 automatic instance recovery sull'istanza esistente.","Aggiungere una seconda istanza nella stessa Availability Zone usando uno spread placement group.","Migrare il database a un deployment Amazon RDS for MySQL Multi-AZ.","Eseguire il livello web in un Auto Scaling group su più Availability Zone dietro un ALB.","Creare un record Route 53 simple routing che restituisce gli indirizzi IP pubblici di due istanze."],"explanation":"Spostare il database su RDS Multi-AZ garantisce il failover automatico verso uno standby sincrono in un'altra Availability Zone, e un Auto Scaling group su più zone dietro un ALB sostituisce le istanze web guaste e continua a servire dalle zone integre. Uno spread placement group protegge dai guasti di hardware condiviso, ma tutte le istanze restano in una sola Availability Zone.","optionExplanations":["L'applicazione dipende ancora da una singola istanza in una Availability Zone, quindi un guasto della AZ causa un'interruzione.","Lo spread placement separa l'hardware all'interno della zona, ma non protegge dal guasto di una Availability Zone.","Corretto — il database esegue automaticamente il failover verso uno standby in un'altra Availability Zone.","Corretto — istanze bilanciate su più zone resistono ai guasti sia delle istanze sia delle Availability Zone.","I record simple non hanno health check, quindi i client verrebbero comunque inviati a un'istanza guasta."]},
  "1085": {"h":"8cebb8be","question":"Un'azienda media ha utenti in diversi continenti che caricano file video di diversi gigabyte in un unico bucket Amazon S3 in us-east-1. Gli utenti lontani dalla Region segnalano caricamenti lenti e poco affidabili. L'azienda vuole migliorare la velocità di caricamento per gli utenti distanti con modifiche minime all'applicazione. Quale soluzione soddisfa questi requisiti?","options":["Creare bucket in altre Region, far caricare gli utenti in quello più vicino e replicare gli oggetti verso us-east-1.","Distribuire AWS Global Accelerator davanti al bucket in modo che i caricamenti vengano instradati sul backbone AWS.","Abilitare S3 Transfer Acceleration sul bucket e caricare con multipart upload verso l'endpoint accelerato.","Creare il bucket come directory bucket S3 Express One Zone per aumentare il throughput di caricamento."],"explanation":"S3 Transfer Acceleration consente ai client di caricare verso la edge location più vicina, da cui i dati viaggiano sulla rete AWS ottimizzata fino al bucket; combinato con i multipart upload parallelizza i trasferimenti di grandi dimensioni e ritenta solo le parti fallite. Richiede soltanto un cambio di endpoint. Bucket regionali con replica funzionerebbero, ma aggiungono bucket, logica di instradamento e costi di replica, cioè molte più modifiche del necessario.","optionExplanations":["Più bucket, con logica di selezione della Region e replica, comportano modifiche applicative e operative significative, violando il requisito di modifiche minime.","Gli endpoint di Global Accelerator sono ALB, NLB, istanze EC2 ed Elastic IP; un bucket S3 non può essere configurato direttamente come endpoint dell'accelerator.","Corretto — Transfer Acceleration usa le edge location e il backbone AWS, e il multipart upload parallelizza i caricamenti di grandi dimensioni rendendoli resilienti.","S3 Express One Zone punta a un accesso in millisecondi a una cifra da risorse di calcolo nella stessa Availability Zone; non aiuta i client lontani dalla Region."]},
  "1086": {"h":"58bdcc7c","question":"Un'azienda esegue un database Oracle mission-critical su Amazon EC2. Il database richiede una latenza costante inferiore al millisecondo, la massima durabilità disponibile per i volumi EBS e più IOPS per volume di quanti ne possano offrire i volumi gp3. Quale opzione di storage dovrebbe scegliere un solutions architect?","options":["Effettuare il provisioning di volumi EBS io2 Block Express con gli IOPS richiesti.","Combinare più volumi gp3 in RAID 0 e aumentare gli IOPS di ciascun volume.","Usare volumi instance store NVMe e copiare ogni notte i dati su Amazon S3.","Usare volumi st1 Throughput Optimized HDD dimensionati per il massimo throughput."],"explanation":"io2 Block Express è progettato per i database più esigenti e intensivi in I/O, offrendo il maggior numero di IOPS per volume, latenza inferiore al millisecondo e una durabilità superiore agli altri tipi di volume EBS. Un array RAID 0 di volumi gp3 può aggregare gli IOPS, ma aggiunge complessità di gestione e la perdita di un solo volume distrugge l'intero array, quindi non soddisfa il requisito di durabilità.","optionExplanations":["Corretto — io2 Block Express offre il maggior numero di IOPS per volume, una latenza costante inferiore al millisecondo e la massima durabilità EBS.","Lo striping RAID 0 amplia l'impatto del guasto di un singolo volume e non offre la maggiore durabilità garantita da io2.","I dati dell'instance store vanno persi quando l'istanza si arresta o si guasta, quindi con copie notturne si rischierebbe di perdere un giorno di transazioni confermate.","st1 è un tipo di volume magnetico ottimizzato per un throughput sequenziale elevato, non per l'I/O casuale a bassa latenza di un database transazionale."]},
  "1087": {"h":"545dd6d2","question":"Un'azienda elabora ogni notte diversi terabyte di log dei web server con un job batch su Amazon EC2. Il job legge i dati in modo sequenziale a blocchi di grandi dimensioni e richiede un throughput elevato, mentre le prestazioni in IOPS casuali non sono importanti. I dati devono restare su Amazon EBS. Quale tipo di volume è la scelta PIÙ conveniente?","options":["Volumi gp3 General Purpose SSD con throughput impostato al massimo","Volumi io2 Provisioned IOPS SSD dimensionati per contenere l'intero dataset","Volumi sc1 Cold HDD, perché hanno il costo per GB più basso","Volumi st1 Throughput Optimized HDD dimensionati per contenere il dataset"],"explanation":"I volumi st1 sono volumi HDD a basso costo progettati per workload sequenziali ad alto throughput con accesso frequente, come l'elaborazione di log e i big data. sc1 costa meno per GB, ma è pensato per dati ad accesso poco frequente e offre un throughput inferiore, inadatto a un job che analizza terabyte ogni notte.","optionExplanations":["Lo storage SSD gp3 costa più per GB rispetto agli HDD e i suoi punti di forza in termini di IOPS vengono sprecati in un workload puramente sequenziale.","io2 è il tipo di volume più costoso ed è pensato per IOPS casuali elevati, di cui questo workload non ha bisogno.","sc1 ha un throughput inferiore ed è pensato per dati ad accesso poco frequente, quindi una scansione notturna di diversi terabyte sarebbe più lenta.","Corretto — st1 offre un throughput sequenziale elevato a un basso costo per GB per workload big data ad accesso frequente."]},
  "1088": {"h":"18776a9e","question":"Un parco di istanze EC2 Linux condivide un file system Amazon EFS che contiene un dataset relativamente piccolo. La domanda di throughput è a picchi e imprevedibile, spesso superiore a quanto fornisce la modalità Bursting per la dimensione memorizzata, e il file system esaurisce regolarmente i burst credit. L'azienda vuole che il throughput scali automaticamente senza pianificazione della capacità e pagare solo per ciò che usa. Cosa dovrebbe fare un solutions architect?","options":["Passare il file system alla performance mode Max I/O.","Passare il file system alla throughput mode Elastic.","Passare il file system a Provisioned throughput impostato al valore di picco.","Aggiungere al file system grandi file di riempimento per ottenere più burst credit."],"explanation":"L'Elastic throughput aumenta e riduce automaticamente il throughput in base al workload e addebita il throughput effettivamente usato, il che si adatta a una domanda a picchi e imprevedibile. Il Provisioned throughput eliminerebbe il problema dei crediti, ma richiede di scegliere un livello in anticipo e di pagare il picco anche quando il file system è inattivo.","optionExplanations":["Max I/O è una performance mode per accessi altamente paralleli con latenza maggiore; non cambia la quantità di throughput che il file system può sostenere.","Corretto — l'Elastic throughput scala automaticamente con la domanda e viene addebitato a consumo, senza pianificazione della capacità.","Il Provisioned throughput richiede pianificazione della capacità e addebita sempre il picco configurato, quindi non è a consumo.","I file di riempimento aumentano il costo di storage e sono un espediente fragile rispetto a una throughput mode che scala su richiesta."]},
  "1089": {"h":"03021438","question":"Un'azienda di genomica esegue un workload HPC su migliaia di core di calcolo Linux. I dataset di input sono memorizzati in Amazon S3, e ogni nodo ha bisogno di un accesso condiviso, conforme a POSIX e parallelo con latenza inferiore al millisecondo durante ogni esecuzione. I risultati devono essere riscritti su S3. Quale soluzione di storage offre le prestazioni PIÙ ELEVATE?","options":["Un file system FSx for Lustre collegato al bucket S3 come data repository","Un file system Amazon EFS in modalità Max I/O popolato da S3 con AWS DataSync","Mountpoint for Amazon S3 installato su ogni nodo di calcolo per leggere il bucket","Un file system Amazon FSx for Windows File Server condiviso con i nodi tramite SMB"],"explanation":"FSx for Lustre è un file system parallelo progettato per l'HPC che offre latenza inferiore al millisecondo e un throughput aggregato molto elevato, e una data repository association S3 carica gli oggetti da S3 in modo lazy ed esporta i risultati. EFS in modalità Max I/O è condiviso e conforme a POSIX, ma ha latenza maggiore e throughput inferiore rispetto a Lustre e richiede un passaggio di copia aggiuntivo.","optionExplanations":["Corretto — FSx for Lustre è progettato per l'HPC e si integra nativamente con S3 per importazione ed esportazione.","EFS Max I/O sacrifica la latenza a favore del parallelismo e non può eguagliare le prestazioni di Lustre; DataSync aggiunge una pipeline di copia separata.","Mountpoint for S3 non è un file system condiviso pienamente conforme a POSIX e non offre latenza inferiore al millisecondo per ogni operazione.","FSx for Windows File Server usa SMB ed è pensato per workload Windows, non per cluster HPC Linux che richiedono un file system parallelo."]},
  "1090": {"h":"cf961b86","question":"Un'applicazione di transcodifica video su Amazon EC2 scrive file intermedi di grandi dimensioni durante ogni job. I file vengono eliminati al termine del job e possono essere rigenerati se persi. L'azienda ha bisogno delle massime prestazioni di I/O su disco locale per questi file al costo più basso. Quale soluzione soddisfa questi requisiti?","options":["Collegare volumi EBS io2 con IOPS elevati in provisioning per i file intermedi.","Memorizzare i file intermedi su un file system Amazon EFS con Elastic throughput.","Usare tipi di istanza EC2 con volumi instance store NVMe per i file intermedi.","Scrivere i file intermedi su S3 Standard e rimuoverli con una regola di lifecycle."],"explanation":"I volumi instance store sono fisicamente collegati all'host, offrono prestazioni di I/O molto elevate e sono inclusi nel prezzo dell'istanza, il che li rende ideali per dati temporanei e riproducibili di lavoro. I volumi io2 avrebbero buone prestazioni, ma gli IOPS in provisioning aggiungono costi significativi per dati che non richiedono persistenza.","optionExplanations":["I volumi io2 aggiungono costi per GB e per IOPS per offrire una durabilità di cui i dati temporanei non hanno bisogno.","EFS è uno storage collegato via rete con latenza maggiore rispetto ai dischi NVMe locali e aggiunge costi di storage e throughput.","Corretto — l'instance store NVMe offre il massimo I/O locale senza costi aggiuntivi, e la sua natura effimera è accettabile per file rigenerabili.","S3 è uno storage a oggetti accessibile via rete, quindi non può eguagliare la latenza di un disco locale per scritture intermedie intensive."]},
  "1091": {"h":"d4e04509","question":"Un'azienda sta migrando su AWS uno storage array NetApp on-premises. Le applicazioni Linux accedono ai dataset tramite NFS e le applicazioni Windows accedono agli stessi dataset tramite SMB. L'azienda vuole continuare a usare funzionalità NetApp come gli snapshot e la replica SnapMirror apportando il minor numero di modifiche. Quale soluzione soddisfa questi requisiti?","options":["Amazon FSx for Windows File Server con DFS Namespaces per tutti i client","Amazon EFS per i client Linux e FSx for Windows File Server per Windows","Amazon FSx for OpenZFS con export NFS configurati per tutti i client","Amazon FSx for NetApp ONTAP con accesso multiprotocollo NFS e SMB"],"explanation":"FSx for NetApp ONTAP esegue il file system ONTAP, quindi supporta l'accesso simultaneo NFS e SMB agli stessi dati e le note funzionalità NetApp come snapshot e SnapMirror. Suddividere i dati tra EFS e FSx for Windows creerebbe due copie da mantenere sincronizzate e farebbe perdere gli strumenti NetApp.","optionExplanations":["FSx for Windows File Server serve solo SMB e non offre funzionalità NetApp come SnapMirror.","Due file system separati duplicherebbero i dati, richiederebbero sincronizzazione e abbandonerebbero le funzionalità NetApp esistenti.","FSx for OpenZFS serve client NFS e non offre accesso SMB né NetApp SnapMirror.","Corretto — FSx for NetApp ONTAP offre accesso multiprotocollo e le funzionalità native di gestione dei dati di ONTAP."]},
  "1092": {"h":"808e39d8","question":"Un'applicazione di analisi legge milioni di piccoli oggetti e scarica anche oggetti di diversi gigabyte da un unico bucket Amazon S3. Tutti gli oggetti sono memorizzati sotto un unico prefisso. Nei momenti di picco l'applicazione riceve errori HTTP 503 Slow Down, e i download di grandi dimensioni sono lenti. Quale combinazione di azioni migliora le prestazioni? (Seleziona DUE)","options":["Distribuire gli oggetti su più prefissi in modo da ripartire le richieste.","Abilitare S3 Versioning in modo che S3 possa servire le letture da più versioni degli oggetti.","Usare byte-range fetch per scaricare in parallelo parti degli oggetti di grandi dimensioni.","Spostare gli oggetti in S3 Glacier Instant Retrieval per aumentare la capacità di richieste.","Abilitare S3 Object Lock in governance mode per ridurre la contesa tra le richieste."],"explanation":"La capacità di S3 in termini di frequenza delle richieste scala per prefisso, quindi distribuire gli oggetti su più prefissi consente frequenze aggregate più elevate ed elimina il throttling 503. I byte-range fetch consentono al client di scaricare contemporaneamente segmenti di oggetti di grandi dimensioni, aumentando il throughput. Versioning, cambi di classe di storage e Object Lock non aumentano la capacità di richieste né la velocità di download.","optionExplanations":["Corretto — i limiti di frequenza delle richieste si applicano per prefisso, quindi più prefissi aumentano la capacità totale di richieste.","Il versioning mantiene più versioni per la protezione dei dati; le letture puntano comunque alla versione corrente e la capacità non aumenta.","Corretto — le GET byte-range in parallelo aumentano il throughput per gli oggetti di grandi dimensioni e consentono di ritentare solo gli intervalli falliti.","Glacier Instant Retrieval è una classe più economica per dati ad accesso raro con costi di recupero; non aumenta la capacità di richieste.","Object Lock applica una conservazione WORM per la compliance e non ha alcun effetto sul throttling delle richieste."]},
  "1093": {"h":"b7d70889","question":"Un'azienda esegue una piccola applicazione in cluster su sei istanze Amazon EC2 in una Availability Zone. Ogni istanza deve girare su hardware sottostante distinto, in modo che un singolo guasto hardware interessi al massimo un'istanza. Quale opzione di deployment soddisfa questo requisito?","options":["Avviare tutte e sei le istanze in un cluster placement group.","Avviare tutte e sei le istanze in uno spread placement group.","Avviare tutte e sei le istanze in un partition placement group con una sola partizione.","Avviare tutte e sei le istanze come Dedicated Instances nella stessa Availability Zone."],"explanation":"Uno spread placement group colloca ogni istanza su rack distinti con rete e alimentazione separate, ed è pensato per un piccolo numero di istanze critiche che devono essere isolate da guasti hardware correlati. Le Dedicated Instances garantiscono solo che l'hardware non sia condiviso con altri account AWS; diverse istanze della stessa azienda possono comunque finire sullo stesso host.","optionExplanations":["Un cluster placement group raggruppa le istanze vicine per ottenere bassa latenza, il che aumenta il rischio di guasti correlati.","Corretto — uno spread placement group colloca ogni istanza su hardware distinto.","Con una sola partizione tutte le istanze condividono lo stesso insieme di rack, quindi un guasto può interessarne diverse.","Le Dedicated Instances isolano l'hardware dagli altri account, ma non mantengono le istanze dell'azienda su hardware separato."]},
  "1094": {"h":"be646f5f","question":"Un'azienda sta distribuendo un grande cluster Apache Cassandra con centinaia di istanze Amazon EC2. L'azienda vuole limitare l'impatto di guasti hardware correlati a livello di rack, e il database deve sapere quali istanze condividono i rack in modo da poter collocare le repliche in base alla topologia. Quale strategia di placement dovrebbe essere usata?","options":["Uno spread placement group che contiene tutte le istanze del cluster","Un cluster placement group che contiene tutte le istanze del cluster","Un partition placement group, esponendo a Cassandra i numeri di partizione","Auto Scaling group separati per il cluster in diverse Region AWS"],"explanation":"I partition placement group suddividono le istanze in partizioni logiche che non condividono rack, e il numero di partizione è disponibile tramite i metadati dell'istanza, quindi database distribuiti come Cassandra, HDFS o Kafka possono collocare le repliche su partizioni diverse. Anche gli spread placement group isolano l'hardware, ma supportano solo un piccolo numero di istanze per Availability Zone e non sono adatti a cluster di centinaia di nodi.","optionExplanations":["Gli spread placement group sono limitati a un piccolo numero di istanze per Availability Zone, quindi non possono contenere centinaia di nodi.","I cluster placement group collocano le istanze vicine tra loro, aumentando l'esposizione a guasti correlati dei rack.","Corretto — le partizioni sono isolate a livello di rack e i loro numeri sono visibili all'applicazione per la collocazione delle repliche.","Un deployment multi-Region aggiunge latenza e costi e non fornisce al database informazioni sulla topologia a livello di rack."]},
  "1095": {"h":"b163ad09","question":"Un'applicazione gira in un Amazon EC2 Auto Scaling group. Ogni nuova istanza impiega più di 10 minuti ad avviarsi perché durante il boot carica in memoria un dataset di grandi dimensioni. I picchi di traffico sono imprevedibili e le nuove istanze non sono pronte in tempo durante lo scale-out. L'azienda vuole ridurre il tempo di scale-out mantenendo bassi i costi. Cosa dovrebbe fare un solutions architect?","options":["Configurare per il gruppo un warm pool di istanze preinizializzate e arrestate.","Aumentare la capacità minima per coprire in ogni momento il picco più alto previsto.","Aggiungere una scheduled scaling action che aggiunge istanze ogni mattina.","Abbassare il valore di target tracking in modo che lo scaling inizi a un utilizzo inferiore."],"explanation":"Un warm pool mantiene istanze preinizializzate in stato arrestato (o ibernato), quindi possono essere messe in servizio molto più rapidamente rispetto all'avvio e al boot di nuove istanze, e le istanze arrestate comportano solo costi di storage. Aumentare la capacità minima eliminerebbe anch'esso il ritardo, ma significherebbe pagare la capacità di picco 24 ore su 24.","optionExplanations":["Corretto — le istanze del warm pool hanno già completato la lenta inizializzazione e possono entrare in servizio rapidamente a basso costo.","Mantenere sempre la capacità di picco elimina il ritardo, ma aumenta notevolmente i costi durante il traffico normale.","Le scheduled action sono adatte ad andamenti prevedibili; questi picchi sono imprevedibili, quindi una pianificazione non li coglierebbe.","Scalare prima aiuta leggermente, ma ogni nuova istanza richiede comunque il lungo boot e si mantiene più capacità in esecuzione."]},
  "1096": {"h":"0406fd80","question":"Una funzione AWS Lambda esegue un'elaborazione di immagini intensiva per la CPU. La sua durata di esecuzione è lunga e spesso si avvicina al timeout configurato, sebbene l'utilizzo di memoria sia basso. Gli sviluppatori vogliono ridurre il tempo di esecuzione con il MINOR sforzo. Cosa dovrebbero fare?","options":["Configurare la provisioned concurrency per la funzione.","Aumentare la reserved concurrency della funzione.","Collegare la funzione a una VPC vicina alle sue sorgenti dati.","Aumentare l'impostazione di memoria, che aumenta anche la CPU."],"explanation":"Lambda assegna potenza di CPU in proporzione alla memoria configurata, quindi aumentare la memoria fornisce più capacità di calcolo a una funzione CPU-bound e ne riduce la durata, spesso a un costo totale simile o inferiore. La provisioned concurrency elimina soltanto la latenza di inizializzazione dei cold start e non rende più veloce il calcolo di ogni invocazione.","optionExplanations":["La provisioned concurrency preinizializza gli ambienti di esecuzione per evitare i cold start; non aggiunge CPU a ogni invocazione.","La reserved concurrency garantisce e limita il numero di esecuzioni concorrenti, ma non velocizza una singola esecuzione.","Collegarsi a una VPC non aggiunge potenza di calcolo e non ha relazione con il tempo di elaborazione CPU-bound.","Corretto — più memoria significa proporzionalmente più CPU, il che riduce direttamente l'esecuzione CPU-bound."]},
  "1097": {"h":"9e3ef15b","question":"Un'API sensibile alla latenza usa Amazon API Gateway e AWS Lambda, e le risposte sono personalizzate per ogni utente. Dopo periodi di inattività alcune richieste sono lente perché i nuovi ambienti di esecuzione devono inizializzarsi. L'API deve rispondere in modo costante con bassa latenza durante l'orario lavorativo. Quale soluzione soddisfa questi requisiti?","options":["Aumentare timeout e memoria della funzione ai valori massimi.","Configurare la provisioned concurrency e pianificarla per l'orario lavorativo.","Impostare la reserved concurrency pari alla concorrenza di picco prevista.","Abilitare il caching di API Gateway per tutti i metodi con un TTL lungo."],"explanation":"La provisioned concurrency mantiene inizializzato e pronto un numero configurato di ambienti di esecuzione, eliminando la latenza dei cold start, e Application Auto Scaling può pianificarla solo per l'orario lavorativo per contenere i costi. La reserved concurrency sembra simile, ma si limita a riservare e limitare la capacità; non preinizializza gli ambienti.","optionExplanations":["Un timeout più lungo non influisce sull'inizializzazione, e più memoria riduce ma non elimina la latenza dei cold start.","Corretto — gli ambienti preinizializzati eliminano i cold start, e la pianificazione limita il costo all'orario lavorativo.","La reserved concurrency riserva e limita la concorrenza, ma gli ambienti vengono comunque creati su richiesta, quindi i cold start restano.","Le risposte sono personalizzate per utente, quindi metterle in cache restituirebbe dati errati o produrrebbe pochi cache hit."]},
  "1098": {"h":"c3d19c93","question":"Un'azienda vuole eseguire microservizi containerizzati su Amazon ECS. Il team non vuole effettuare provisioning, patch o scaling degli host EC2, e il carico di ogni servizio varia durante la giornata. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Usare il launch type EC2 di ECS con un capacity provider basato su Auto Scaling group.","Eseguire Docker su istanze EC2 e gestirle con AWS Systems Manager.","Usare il launch type Fargate di ECS con Service Auto Scaling per ogni servizio.","Usare Amazon EKS con self-managed node group in esecuzione su Spot Instances."],"explanation":"Con Fargate, AWS fornisce e gestisce la capacità di calcolo sottostante per ogni task, quindi non ci sono host da aggiornare o scalare, e Service Auto Scaling adegua il numero di task al carico. Il launch type EC2 con un capacity provider automatizza lo scaling del cluster, ma il team resterebbe responsabile delle istanze, delle loro AMI e delle patch.","optionExplanations":["I capacity provider automatizzano lo scaling, ma il team continua a gestire e aggiornare le container instance EC2.","Gli host Docker autogestiti richiedono che il team si occupi da solo di patch, scaling e orchestrazione.","Corretto — Fargate elimina la gestione degli host e Service Auto Scaling segue il carico variabile.","I self-managed node group richiedono che il team gestisca i worker node, e le interruzioni Spot aggiungono ulteriore gestione."]},
  "1099": {"h":"4e34aa4c","question":"Una società di ricerca esegue migliaia di job di simulazione containerizzati e indipendenti, inviati a orari irregolari. Ogni job dura da 1 a 6 ore e può essere ritentato se viene interrotto. La società vuole che la capacità di calcolo venga fornita automaticamente in base ai job in coda, al costo più basso e con una gestione minima. Quale soluzione soddisfa questi requisiti?","options":["AWS Batch con un compute environment gestito che usa Spot Instances","Funzioni AWS Lambda invocate da una coda Amazon SQS per ogni job","Un parco fisso di istanze EC2 On-Demand con uno scheduler basato su cron","Un cluster Amazon EMR di lunga durata con istanze On-Demand per i job"],"explanation":"AWS Batch mette in coda i job e scala automaticamente un compute environment gestito per eseguirli, e le Spot Instances riducono notevolmente i costi per lavori interrompibili e ritentabili. Lambda è serverless e basato su eventi, ma la sua durata massima di esecuzione è molto inferiore a simulazioni di diverse ore.","optionExplanations":["Corretto — Batch gestisce la coda e lo scaling della capacità di calcolo, e Spot è ideale per job che possono essere ritentati.","Le funzioni Lambda non possono essere eseguite per diverse ore, quindi non possono eseguire queste simulazioni.","Un parco fisso On-Demand resta inattivo tra un invio irregolare e l'altro e richiede la gestione di uno scheduler personalizzato.","EMR è progettato per framework big data come Spark, e un cluster On-Demand di lunga durata spreca denaro quando è inattivo."]},
  "1100": {"h":"82117d2f","question":"Un'azienda esegue un cluster Hadoop on-premises con job Apache Spark e Hive che elaborano petabyte di dati. L'azienda vuole migrare su AWS con modifiche minime al codice, disaccoppiare storage e calcolo e dimensionare un cluster per ogni workload. Quale soluzione soddisfa questi requisiti?","options":["Riscrivere i job come job AWS Glue Python shell che leggono da Amazon S3.","Caricare i dati in Amazon Redshift e convertire le query Hive in stored procedure.","Eseguire Hadoop su istanze EC2 autogestite con HDFS memorizzato su volumi EBS.","Usare cluster Amazon EMR che leggono e scrivono dati memorizzati in Amazon S3."],"explanation":"Amazon EMR esegue gli stessi framework Spark e Hive come servizio gestito, e memorizzare i dati in S3 disaccoppia lo storage dal calcolo, così i cluster possono essere dimensionati o terminati per ogni workload. Anche Hadoop autogestito su EC2 eviterebbe modifiche al codice, ma HDFS su EBS lega lo storage al cluster e aggiunge un onere operativo significativo.","optionExplanations":["Riscrivere i job Spark e Hive come job Python shell richiede modifiche sostanziali al codice e non è adatto all'elaborazione su scala di petabyte.","La migrazione a Redshift richiede la conversione della logica Hive e non mantiene i job Spark esistenti.","HDFS su EBS lega i dati al cluster, quindi lo storage non è disaccoppiato e l'azienda deve gestire Hadoop da sola.","Corretto — EMR esegue il codice Spark e Hive esistente, e lo storage su S3 disaccoppia i dati da cluster temporanei."]},
  "1101": {"h":"1e705391","question":"Un'applicazione serverless utilizza funzioni AWS Lambda che si connettono a un database Amazon RDS for MySQL. Durante i picchi di traffico, molte invocazioni concorrenti aprono nuove connessioni e il database restituisce errori di tipo too-many-connections. Quale soluzione risolve il problema con il minor numero di modifiche al codice?","options":["Scalare l'istanza DB a una classe più grande per aumentare il numero massimo di connessioni.","Inserire Amazon RDS Proxy tra le funzioni Lambda e il database.","Aggiungere una read replica RDS e inviare tutto il traffico del database alla replica.","Impostare una reserved concurrency bassa sulle funzioni per limitare le invocazioni."],"explanation":"RDS Proxy mantiene un pool di connessioni al database e vi multiplexa molte connessioni Lambda, assorbendo i picchi senza esaurire le connessioni del database; alle funzioni basta usare l'endpoint del proxy. Scalare l'istanza alza il limite di connessioni, ma il continuo churn di connessioni prosegue e il limite può comunque essere superato, a un costo maggiore.","optionExplanations":["Un'istanza più grande alza solo il tetto e aggiunge costi; la crescita incontrollata delle connessioni da Lambda può comunque esaurirlo.","Corretto — RDS Proxy raggruppa e riutilizza le connessioni, proteggendo il database durante i picchi con il solo cambio di endpoint.","Le read replica sono di sola lettura e non possono accettare le scritture dell'applicazione.","Limitare la concorrenza strozza le richieste durante i picchi, degradando l'applicazione invece di risolvere la gestione delle connessioni."]},
  "1102": {"h":"61c41c72","question":"Un'applicazione di gaming memorizza i profili dei giocatori in Amazon DynamoDB. Il workload è prevalentemente in lettura e gli stessi item vengono letti ripetutamente. L'applicazione ora richiede una latenza di lettura nell'ordine dei microsecondi e gli sviluppatori vogliono continuare a usare l'API di DynamoDB con modifiche minime al codice. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere un cluster DynamoDB Accelerator (DAX) davanti alla tabella.","Abilitare le DynamoDB global tables in Region AWS aggiuntive.","Passare la tabella alla capacità provisioned con una read capacity più alta.","Aggiungere un cluster ElastiCache for Memcached e usare il lazy loading nel codice."],"explanation":"DAX è una cache in memoria per DynamoDB che offre latenze di lettura nell'ordine dei microsecondi ed è compatibile con la sua API, quindi l'applicazione deve solo passare al client DAX. Anche ElastiCache potrebbe mettere in cache gli item, ma gli sviluppatori dovrebbero scrivere e mantenere autonomamente la logica cache-aside e l'invalidazione.","optionExplanations":["Corretto — DAX fornisce letture in microsecondi tramite un'API compatibile con DynamoDB, con modifiche minime.","Le global tables replicano i dati tra Region per l'accesso multi-Region ma non riducono le letture ai microsecondi.","Più read capacity evita il throttling, ma le letture DynamoDB richiedono comunque pochi millisecondi.","Memcached richiede codice di caching personalizzato e logica di invalidazione della cache, cioè più modifiche rispetto a DAX."]},
  "1103": {"h":"7aacee99","question":"Un'azienda sta realizzando una classifica in tempo reale che deve ordinare milioni di giocatori per punteggio con latenza molto bassa. I dati in cache devono sopravvivere al guasto di un nodo tramite failover automatico su una replica in un'altra Availability Zone. Quale soluzione soddisfa questi requisiti?","options":["Amazon ElastiCache for Memcached con nodi distribuiti su più Availability Zone","Amazon DynamoDB con DAX e un global secondary index sull'attributo del punteggio","Amazon ElastiCache (Redis OSS) con repliche Multi-AZ, usando i sorted set","Amazon RDS for MySQL con query ORDER BY messe in cache dall'applicazione"],"explanation":"ElastiCache con il motore Redis OSS offre i sorted set, che mantengono nativamente le classifiche con aggiornamenti e query per intervallo molto rapidi, e supporta repliche con failover automatico Multi-AZ. Memcached è una semplice cache chiave-valore multithread senza replica, persistenza o strutture dati avanzate, quindi non soddisfa né il requisito di classifica né quello di failover.","optionExplanations":["Memcached non ha replica né failover e non dispone di una struttura dati ordinata nativa per le classifiche.","Ordinare milioni di giocatori con un GSI richiede pattern di query costosi, e DAX non fornisce operazioni native di ranking.","Corretto — I sorted set di Redis OSS implementano nativamente le classifiche e le repliche Multi-AZ forniscono il failover automatico.","Query ORDER BY ripetute su un database relazionale non possono offrire una classifica in tempo reale su questa scala."]},
  "1104": {"h":"70482207","question":"Un'applicazione interna usa un database relazionale compatibile con MySQL. Il carico è molto variabile e imprevedibile: il database resta inattivo per ore e poi riceve improvvisi picchi intensi. L'azienda vuole che la capacità di calcolo del database scali automaticamente con incrementi granulari. Quale soluzione è la PIÙ conveniente pur gestendo i picchi?","options":["Un cluster Aurora provisioned dimensionato per il carico di picco e coperto da Reserved Instances","Amazon RDS for MySQL con lo storage autoscaling abilitato sull'istanza DB","Amazon DynamoDB in modalità di capacità on-demand con lo schema denormalizzato","Amazon Aurora Serverless v2 con capacità minima e massima configurate"],"explanation":"Aurora Serverless v2 regola la capacità di calcolo a piccoli incrementi quasi istantaneamente al variare del carico, quindi l'azienda paga poco quando il database è inattivo e assorbe comunque i picchi improvvisi, con piena compatibilità MySQL. Un cluster provisioned dimensionato per il picco gestirebbe i picchi, ma pagherebbe la capacità di picco durante le molte ore di inattività.","optionExplanations":["La capacità provisioned dimensionata per il picco resta per lo più inutilizzata, quindi anche con le Reserved Instances non è l'opzione più conveniente.","Lo storage autoscaling aumenta solo lo spazio su disco; la capacità di calcolo resta fissa e non può assorbire i picchi.","DynamoDB non è un database relazionale compatibile con MySQL, quindi l'applicazione andrebbe riprogettata.","Corretto — Serverless v2 scala il calcolo con incrementi granulari in base al carico imprevedibile."]},
  "1105": {"h":"23c05316","question":"Un sito di notizie usa un cluster Amazon Aurora MySQL. Il traffico in lettura è 20 volte superiore a quello in scrittura e ha picchi imprevedibili quando le notizie diventano virali, sovraccaricando l'Aurora Replica esistente. L'applicazione invia già tutte le letture a un unico hostname del database. Quale soluzione gestirà i picchi di lettura con il MINOR overhead operativo?","options":["Abilitare Aurora Auto Scaling per le repliche e leggere tramite il reader endpoint.","Scalare l'istanza writer alla classe più grande e inviare le letture al writer.","Creare Aurora Replica cross-Region e aggiornare i record DNS all'inizio dei picchi.","Esportare le tabelle in Amazon S3 ogni ora e servire le letture con query Amazon Athena."],"explanation":"Aurora Auto Scaling aggiunge e rimuove Aurora Replica in base a metriche come CPU o connessioni, e il reader endpoint bilancia le connessioni su tutte le repliche disponibili, così l'applicazione continua a usare un solo hostname. Scalare il writer ha dei limiti e spreca capacità al di fuori dei picchi.","optionExplanations":["Corretto — Aurora Auto Scaling adegua il numero di repliche alla domanda e il reader endpoint distribuisce automaticamente le letture tra di esse.","Un writer più grande ha un tetto fisso, costa di più sempre e mescola i picchi di lettura con il workload di scrittura.","Le repliche cross-Region aggiungono replication lag e richiedono modifiche DNS manuali durante i picchi: un elevato overhead operativo per un problema di letture in una sola Region.","Athena su esportazioni orarie non può servire letture a bassa latenza per un sito web e i dati sarebbero vecchi fino a un'ora."]},
  "1106": {"h":"2897da9a","question":"Un'azienda sta realizzando due nuovi workload. Il primo è un catalogo prodotti i cui item hanno attributi JSON flessibili e il cui team applicativo usa già i driver MongoDB. Il secondo è un servizio di rilevamento frodi che deve attraversare in tempo reale le relazioni tra account, dispositivi e transazioni. Quale combinazione di servizi di database dovrebbe consigliare un solutions architect? (Seleziona DUE)","options":["Amazon Neptune per i documenti del catalogo prodotti","Amazon DocumentDB per i documenti del catalogo prodotti","Amazon Keyspaces per le query sulle relazioni del rilevamento frodi","Amazon Neptune per le query sulle relazioni del rilevamento frodi","Amazon Redshift per servire il catalogo prodotti al sito web"],"explanation":"Amazon DocumentDB (with MongoDB compatibility) è un database documentale gestito adatto a item JSON con attributi flessibili e funziona con i driver MongoDB esistenti. Amazon Neptune è un database a grafo progettato per attraversare in tempo reale dati altamente connessi, come le reti di frode. Ogni workload dovrebbe usare il motore specifico per il proprio pattern di accesso.","optionExplanations":["Neptune è un database a grafo; non è progettato per memorizzare e servire item di catalogo in stile documento accessibili tramite driver MongoDB.","Corretto — DocumentDB memorizza documenti JSON flessibili ed è compatibile con i driver MongoDB, in linea con i requisiti del catalogo.","Amazon Keyspaces è uno store wide-column compatibile con Cassandra; non offre un attraversamento efficiente delle relazioni su più livelli.","Corretto — Neptune è progettato appositamente per query a grafo che attraversano le relazioni tra account, dispositivi e transazioni.","Redshift è un data warehouse per l'analisi; non è pensato per servire ricerche nel catalogo a bassa latenza per un sito web."]},
  "1107": {"h":"2f04c3d0","question":"Un'azienda esegue cluster Apache Cassandra autogestiti su Amazon EC2. Patching, scalabilità e riparazione dei cluster richiedono un notevole impegno del team. L'azienda vuole un servizio gestito e serverless che funzioni con il codice applicativo CQL esistente. Quale soluzione soddisfa questi requisiti?","options":["Migrare i dati su Amazon Keyspaces (for Apache Cassandra).","Migrare su Amazon DynamoDB e riscrivere l'accesso con l'SDK di DynamoDB.","Migrare su Amazon DocumentDB e convertire le tabelle in collection.","Migrare su Amazon Aurora PostgreSQL e riprogettare uno schema relazionale."],"explanation":"Amazon Keyspaces è un database serverless compatibile con Cassandra che supporta CQL e i driver Cassandra esistenti, quindi le applicazioni migrano con modifiche minime e senza cluster da gestire. Anche DynamoDB è serverless e scala bene, ma passarvi richiede di riscrivere il livello di accesso ai dati.","optionExplanations":["Corretto — Keyspaces è serverless e compatibile con CQL e con i driver Cassandra.","DynamoDB usa un'API diversa, quindi tutto il codice di accesso ai dati in CQL andrebbe riscritto.","DocumentDB è compatibile con MongoDB e non supporta CQL, richiedendo modifiche al modello dati e al codice.","Una riprogettazione relazionale richiede grandi modifiche allo schema e al codice, contrariamente al requisito."]},
  "1108": {"h":"8cc88a5a","question":"Un sito di catalogo prodotti usa Amazon CloudFront con un Application Load Balancer come origin. Il cache hit ratio è basso e l'origin è molto carico. La cache policy include nella cache key tutte le query string, gli header e i cookie, sebbene le pagine varino solo in base alla query string lang. Cosa dovrebbe fare un solutions architect per migliorare le prestazioni?","options":["Aggiungere altre istanze EC2 dietro l'ALB per gestire il carico aggiuntivo sull'origin.","Abilitare CloudFront Origin Shield e mantenere la cache policy attuale.","Limitare la cache key della cache policy alla sola query string lang.","Ridurre il TTL predefinito in modo che le edge location aggiornino gli oggetti più spesso."],"explanation":"Includere header, cookie e query string non necessari frammenta la cache in molte varianti, quindi la maggior parte delle richieste genera un miss e arriva all'origin. Limitare la cache key al parametro lang permette di condividere pagine identiche tra gli utenti e aumenta l'hit ratio. Origin Shield aggiunge un livello di caching centrale, ma con la stessa cache key frammentata la maggior parte delle richieste resterebbe un miss.","optionExplanations":["Scalare l'origin cura il sintomo e aggiunge costi senza migliorare l'efficienza della cache sull'edge.","Origin Shield riduce alcune richieste all'origin, ma la cache key troppo specifica mantiene basso l'hit ratio.","Corretto — Una cache key minima permette a CloudFront di riutilizzare le pagine in cache, aumentando l'hit ratio e alleggerendo l'origin.","Un TTL più basso fa scadere prima gli oggetti, abbassando ulteriormente l'hit ratio."]},
  "1109": {"h":"9418513e","question":"Un'azienda di giochi multiplayer esegue game server basati su UDP su Amazon EC2 dietro Network Load Balancer in due Region AWS. I giocatori in tutto il mondo hanno bisogno di latenza e jitter più bassi, di un insieme fisso di indirizzi IP statici da inserire nelle allow list dei firewall e di un failover rapido tra Region. Quale soluzione soddisfa questi requisiti?","options":["Creare una distribuzione Amazon CloudFront con gli NLB come custom origin.","Configurare il routing basato sulla latenza di Amazon Route 53 verso i nomi DNS degli NLB.","Distribuire game server aggiuntivi in AWS Local Zones vicino alle basi di giocatori più grandi.","Creare un AWS Global Accelerator con un endpoint group per l'NLB di ciascuna Region."],"explanation":"Global Accelerator fornisce due indirizzi IP anycast statici, instrada il traffico TCP e UDP dalla edge location più vicina attraverso la rete backbone AWS ed esegue il failover tra endpoint regionali in pochi secondi senza dipendere dal caching DNS. Anche CloudFront usa le edge location, ma distribuisce contenuti HTTP e HTTPS e non può trasportare il traffico di gioco UDP.","optionExplanations":["CloudFront gestisce traffico HTTP e HTTPS e non fa da proxy per sessioni di gioco UDP.","Il routing basato su DNS espone IP regionali che cambiano e il failover dipende dal caching DNS, quindi è più lento e non fornisce un unico insieme di IP statici.","Le Local Zones possono ridurre la latenza per alcuni giocatori ma non forniscono IP globali statici né failover automatico tra Region.","Corretto — Global Accelerator offre IP anycast statici, supporto UDP, routing sulla backbone e failover rapido tra Region."]},
  "1110": {"h":"75164d77","question":"Un'azienda memorizza i dati di vendita in Amazon Redshift. Migliaia di utenti business in tutta l'azienda hanno bisogno di dashboard interattive con filtri e drill-down, e l'utilizzo varia molto da un giorno all'altro. L'azienda non vuole effettuare il provisioning né gestire alcun server BI. Quale soluzione soddisfa questi requisiti?","options":["Eseguire uno strumento BI su un Auto Scaling group di istanze EC2 connesso a Redshift.","Usare dashboard Amazon QuickSight connesse al cluster Redshift come origine dati.","Pianificare query Amazon Athena che scrivono report CSV in un bucket S3 per gli utenti.","Pubblicare i risultati delle query Redshift in Amazon OpenSearch Service e condividere l'indice."],"explanation":"Amazon QuickSight è un servizio BI serverless che si connette a Redshift e scala fino a migliaia di utenti con dashboard interattive, e può essere fatturato a sessione per i lettori occasionali. Eseguire uno strumento BI su EC2 soddisfa il requisito funzionale ma aggiunge la gestione dei server.","optionExplanations":["Uno strumento BI autogestito su EC2 funziona, ma l'azienda dovrebbe effettuare provisioning, patching e scalabilità dei server, cosa che vuole evitare.","Corretto — QuickSight è completamente gestito, si connette nativamente a Redshift e scala automaticamente per molti utenti delle dashboard.","Report CSV statici non sono dashboard interattive con filtri e drill-down.","OpenSearch Service è un motore di ricerca e di analisi dei log; non sostituisce un livello di dashboard BI su Redshift per gli utenti business."]},
  "1111": {"h":"92bde1a8","question":"Un'azienda ha decine di VPC in diversi account AWS in una sola Region e si connette al proprio data center con AWS Direct Connect. La full mesh di connessioni VPC peering è diventata difficile da gestire e ogni mese vengono aggiunti nuovi VPC. L'azienda ha bisogno di una rete hub-and-spoke che scali con il MINOR overhead operativo. Quale soluzione soddisfa questi requisiti?","options":["Distribuire AWS Transit Gateway e collegarvi i VPC e un Direct Connect gateway.","Mantenere il VPC peering e automatizzare le nuove route di peering con funzioni AWS Lambda.","Realizzare un transit VPC con appliance router di terze parti in esecuzione su EC2.","Creare endpoint service AWS PrivateLink tra ogni coppia di VPC."],"explanation":"Transit Gateway funge da hub regionale gestito: ogni VPC e il Direct Connect gateway si collegano una sola volta e le route table controllano il traffico tra di essi, quindi aggiungere un VPC richiede un solo attachment invece di molte connessioni di peering. Un transit VPC con appliance router realizza un routing hub-and-spoke, ma l'azienda deve gestire, scalare e rendere altamente disponibili le appliance in autonomia.","optionExplanations":["Corretto — Transit Gateway è un hub gestito che scala a molti VPC e connessioni on-premises.","Il peering non è transitivo e il numero di connessioni cresce in modo quadratico, quindi anche con l'automazione resta una mesh complessa.","Le appliance router autogestite aggiungono lavoro di licensing, patching e disponibilità rispetto a un hub gestito.","PrivateLink espone singoli servizi, non un routing di rete completo, e gli endpoint a coppie non scalerebbero."]},
  "1112": {"h":"20489379","question":"Un'azienda riceve file giornalieri da centinaia di partner commerciali che possono inviare dati solo tramite SFTP. Attualmente l'azienda gestisce e aggiorna i propri server SFTP su Amazon EC2, che spesso vanno in sovraccarico. I file devono arrivare in Amazon S3 per l'elaborazione a valle. Quale soluzione soddisferà questi requisiti con il MINOR overhead operativo?","options":["Usare AWS Transfer Family con un endpoint SFTP basato su Amazon S3.","Spostare i server SFTP in un Auto Scaling group dietro un Network Load Balancer.","Chiedere ai partner di caricare i dati con agent AWS DataSync installati nei loro data center.","Distribuire un S3 File Gateway e dare ai partner accesso alle sue condivisioni file via SMB."],"explanation":"AWS Transfer Family fornisce un endpoint SFTP (e FTPS/FTP/AS2) completamente gestito e con scalabilità automatica che scrive direttamente in Amazon S3, quindi l'azienda non deve più gestire né aggiornare server. Scalare la flotta SFTP basata su EC2 aiuterebbe con la capacità ma manterrebbe tutto il lavoro operativo.","optionExplanations":["Corretto — Transfer Family è un servizio SFTP gestito basato su Amazon S3; scala automaticamente ed elimina la gestione dei server.","Un Auto Scaling group con un NLB migliora la capacità, ma l'azienda dovrebbe comunque realizzare, aggiornare e gestire i server SFTP.","DataSync richiede agent e accesso ad AWS lato partner; i partner possono usare solo SFTP, quindi questa opzione non soddisfa il requisito.","S3 File Gateway espone condivisioni NFS/SMB per applicazioni on-premises; non è un endpoint SFTP per partner esterni."]},
  "1113": {"h":"89a21ece","question":"Un'azienda esegue un'applicazione di analisi in memoria distribuita su istanze Amazon EC2 in una sola Availability Zone. I nodi si scambiano grandi volumi di dati e richiedono il massimo throughput di rete possibile e la latenza più bassa tra di loro. Quale combinazione di azioni dovrebbe intraprendere un solutions architect? (Seleziona DUE)","options":["Avviare le istanze in un placement group spread su rack distinti.","Collegare a ogni istanza elastic network interface aggiuntive per aumentare la banda.","Usare tipi di istanza di generazione attuale con enhanced networking tramite ENA.","Assegnare indirizzi Elastic IP e comunicare tramite gli indirizzi IP pubblici.","Avviare le istanze in un cluster placement group nella Availability Zone."],"explanation":"L'enhanced networking con Elastic Network Adapter offre banda più elevata, packet rate maggiori e latenza più bassa grazie a SR-IOV, e un cluster placement group colloca le istanze vicine tra loro per ottenere la latenza più bassa e il throughput più alto tra i nodi. I placement group spread ottimizzano l'isolamento dai guasti anziché le prestazioni, e interfacce di rete aggiuntive non aumentano il limite di banda di un'istanza.","optionExplanations":["Il placement spread separa deliberatamente le istanze su rack diversi, aumentando la latenza tra i nodi.","La banda di un'istanza è determinata dal tipo di istanza, quindi interfacce aggiuntive non aggiungono throughput.","Corretto — L'enhanced networking basato su ENA aumenta banda e packet rate riducendo la latenza.","Instradare il traffico interno tramite indirizzi IP pubblici aggiunge hop e costi di trasferimento dati senza migliorare le prestazioni.","Corretto — Un cluster placement group fornisce una rete a bassa latenza e alto throughput tra le istanze."]},
  "1114": {"h":"e21f41d2","question":"Un sito web globale viene servito tramite Amazon CloudFront. A ogni viewer request, l'azienda deve riscrivere gli URL e reindirizzare gli utenti in base a un header di richiesta che indica il tipo di dispositivo. La logica è semplice, non effettua chiamate di rete e deve essere eseguita con latenza minima, con volumi di richieste molto elevati e al costo più basso. Quale soluzione soddisfa questi requisiti?","options":["Funzioni Lambda@Edge associate agli eventi origin request e origin response","La stessa logica implementata nell'applicazione di origin dietro il load balancer","Una web ACL AWS WAF associata alla distribuzione per riscrivere e reindirizzare","CloudFront Functions associate all'evento viewer request"],"explanation":"Le CloudFront Functions eseguono JavaScript leggero nelle edge location sugli eventi viewer con un avvio inferiore al millisecondo e sono progettate per attività ad alto volume come riscritture di URL, redirect e manipolazione degli header, a un costo inferiore rispetto a Lambda@Edge. Lambda@Edge può svolgere lo stesso lavoro, ma ha latenza e costi più elevati, e gli eventi origin non vengono eseguiti per le richieste servite dalla cache.","optionExplanations":["Lambda@Edge è più pesante e costoso, e gli eventi lato origin vengono eseguiti solo sui cache miss, non su ogni viewer request.","La logica sull'origin aggiunge un round trip verso l'origin per ogni richiesta e non viene eseguita per le risposte in cache.","AWS WAF ispeziona e filtra le richieste per la sicurezza; non è progettato per riscrivere URL o eseguire redirect in base al dispositivo.","Corretto — Le CloudFront Functions offrono un'esecuzione a latenza e costo molto bassi su ogni viewer request."]},
  "1115": {"h":"4d5f14b7","question":"Un'azienda raccoglie eventi di clickstream dai propri web server. Gli eventi devono essere consegnati in Amazon S3 quasi in tempo reale e convertiti in Apache Parquet, così che gli analisti possano interrogarli con Amazon Athena. L'azienda non vuole scrivere né gestire codice consumer personalizzato. Quale soluzione soddisfa questi requisiti con il MINOR overhead operativo?","options":["Usare Kinesis Data Streams con un consumer KCL su EC2 che scrive Parquet in S3.","Usare Amazon Data Firehose con la conversione del formato dei record in Parquet verso S3.","Usare una coda Amazon SQS con una funzione Lambda che raggruppa gli eventi in S3.","Usare Amazon MSK con un cluster Kafka Connect autogestito che scrive in S3."],"explanation":"Amazon Data Firehose è un servizio di consegna completamente gestito che bufferizza i record in streaming, li converte in Parquet usando uno schema dell'AWS Glue Data Catalog e li scrive in S3 senza alcun codice consumer. Kinesis Data Streams è adatto all'elaborazione personalizzata in tempo reale, ma richiede di realizzare e gestire applicazioni consumer per portare i dati in S3.","optionExplanations":["Un consumer KCL è codice personalizzato in esecuzione su server che l'azienda deve realizzare, scalare e mantenere.","Corretto — Firehose fornisce buffering gestito, conversione in Parquet e consegna in S3 senza codice.","La funzione Lambda è codice personalizzato che deve gestire da sé il batching e la conversione in Parquet.","Kafka Connect autogestito aggiunge la gestione di un cluster, e MSK stesso è più di quanto richieda questa attività di consegna."]},
  "1116": {"h":"e48fe713","question":"Un'azienda esegue Apache Kafka nel proprio data center e decine di applicazioni producer e consumer usano le API di Kafka. L'azienda vuole spostare la propria piattaforma di streaming su AWS senza riscrivere le applicazioni e vuole smettere di gestire l'infrastruttura dei broker. Quale soluzione soddisfa questi requisiti?","options":["Creare un cluster Amazon MSK e puntare le applicazioni ai suoi bootstrap broker.","Usare Amazon Kinesis Data Streams e rifattorizzare i producer per usare la KPL.","Sostituire ogni topic Kafka con una coda Amazon SQS FIFO per i consumer.","Eseguire Kafka su istanze EC2 in un Auto Scaling group su più Availability Zone."],"explanation":"Amazon MSK è un servizio completamente gestito e compatibile con Apache Kafka, quindi producer e consumer esistenti continuano a usare le API di Kafka e AWS gestisce i broker. Anche Kinesis Data Streams è un servizio di streaming gestito, ma usa un'API diversa, quindi ogni applicazione andrebbe modificata.","optionExplanations":["Corretto — MSK è compatibile con Kafka, quindi le applicazioni cambiano solo gli endpoint dei broker.","Kinesis usa una propria API, che richiede modifiche al codice di producer e consumer.","SQS ha semantica e API diverse da Kafka, quindi tutte le applicazioni andrebbero riscritte.","Kafka autogestito su EC2 mantiene l'onere di gestione dei broker che l'azienda vuole eliminare."]},
  "1117": {"h":"4591cd8e","question":"Un'azienda conserva anni di log applicativi in Amazon S3 come file CSV compressi con gzip sotto un unico prefisso. Le query Amazon Athena di solito filtrano su un intervallo di date e leggono solo poche colonne, ma scansionano l'intero dataset e sono lente e costose. Quale combinazione di azioni migliorerà le prestazioni delle query e ridurrà i costi? (Seleziona DUE)","options":["Convertire i dati in un formato colonnare come Apache Parquet.","Spostare i dati in S3 Standard-IA per abbassare il costo di ogni scansione.","Memorizzare i file non compressi così che Athena possa saltare la decompressione.","Partizionare i dati per data e registrare le partizioni nel Data Catalog.","Eseguire le query da un'istanza EC2 nella Availability Zone del bucket."],"explanation":"I formati colonnari come Parquet permettono ad Athena di leggere solo le colonne referenziate da una query e di saltare dati usando le statistiche, e il partizionamento per data permette ad Athena di escludere tutte le partizioni al di fuori dell'intervallo richiesto. Entrambi riducono drasticamente i byte scansionati, che determinano sia il tempo delle query sia il costo di Athena. Rimuovere la compressione o cambiare storage class aumenta la quantità di dati letti o aggiunge costi di recupero.","optionExplanations":["Corretto — Parquet consente il pruning delle colonne e la compressione, riducendo i byte scansionati.","Standard-IA aggiunge costi di recupero per GB e non riduce i dati scansionati da Athena.","I file non compressi aumentano i byte scansionati, rendendo le query più lente e costose.","Corretto — Le partizioni per data permettono ad Athena di saltare i dati al di fuori dell'intervallo di date interrogato.","Athena è un servizio serverless; il punto da cui viene inviata la query non cambia la quantità di dati scansionati."]},
  "1118": {"h":"a6b24f5a","question":"Il data warehouse Amazon Redshift di un'azienda contiene i dati di vendita degli ultimi due anni. I dati storici più vecchi, pari a diversi petabyte, sono memorizzati in Amazon S3 in formato Parquet e vengono interrogati raramente. Gli analisti devono unire dati attuali e storici nelle query SQL senza caricare i dati storici nel cluster. Quale soluzione è la PIÙ conveniente?","options":["Caricare i dati storici nel cluster e aggiungere nodi RA3 per la capacità.","Interrogare i dati storici con Athena ed esportare i risultati in Redshift ogni notte.","Creare tabelle esterne Redshift Spectrum sui dati in S3 ed eseguire le join.","Spostare i dati storici in Amazon DynamoDB e usare le federated query di Redshift."],"explanation":"Redshift Spectrum interroga i dati direttamente in S3 tramite tabelle esterne, così gli analisti possono unirli alle tabelle Redshift locali in un'unica istruzione SQL e pagare solo per i dati scansionati nelle rare occasioni in cui vengono interrogati. Caricare petabyte nel cluster funzionerebbe, ma aggiungerebbe elevati costi di storage e calcolo per dati usati raramente.","optionExplanations":["Caricare petabyte raramente interrogati nel managed storage di Redshift aggiunge costi che il pattern di accesso non giustifica.","Esportare ogni notte i risultati di Athena aggiunge una pipeline e non permette join ad hoc con i dati attuali in un'unica query.","Corretto — Spectrum unisce i dati di S3 alle tabelle del warehouse sul posto, senza caricarli.","DynamoDB non è progettato per scansioni analitiche e le federated query non hanno DynamoDB come destinazione, quindi questa opzione aggiunge costi e complessità."]},
  "1119": {"h":"8b3417ef","question":"Un'azienda deve migrare 600 TB di dati file da un NAS on-premises ad Amazon S3 entro poche settimane. La connessione Internet ha banda limitata ed è già molto utilizzata. Dopo il trasferimento massivo, i file che cambiano on-premises devono essere sincronizzati in S3 in modo incrementale fino al cutover finale. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Usare S3 Transfer Acceleration per caricare i dati massivi via Internet.","Usare dispositivi AWS Snowball Edge per spostare offline i dati massivi iniziali.","Usare AWS Transfer Family con SFTP per caricare i dati massivi dal NAS.","Usare un AWS Storage Gateway Volume Gateway in modalità cached per i file.","Usare AWS DataSync per sincronizzare le modifiche incrementali in S3 fino al cutover."],"explanation":"I dispositivi Snowball Edge spostano offline centinaia di terabyte, evitando il collegamento Internet limitato per la copia massiva. DataSync trasferisce poi solo i file modificati secondo una pianificazione, con verifica dell'integrità, fino al cutover. Qualsiasi metodo online per i dati massivi sarebbe comunque limitato dalla connessione congestionata e a bassa banda.","optionExplanations":["Transfer Acceleration invia comunque tutti i dati sul collegamento Internet limitato, quindi 600 TB non verrebbero trasferiti in poche settimane.","Corretto — Snowball Edge trasferisce i dati massivi offline senza consumare banda di rete.","Transfer Family fornisce endpoint SFTP gestiti per i partner, ma i dati massivi passerebbero comunque sul collegamento limitato.","Volume Gateway presenta volumi di storage a blocchi, non file come oggetti S3, quindi non è adatto a una migrazione di file da NAS a S3.","Corretto — DataSync copia in modo efficiente solo i file modificati e li verifica durante il periodo di sincronizzazione."]},
  "1120": {"h":"6690c093","question":"Un'azienda riceve ogni giorno in Amazon S3 file JSON da più sorgenti. Deve individuare automaticamente gli schemi, rendere i dati interrogabili con Amazon Athena, pulire i dati e convertirli in Parquet. L'azienda vuole usare servizi serverless con il MINOR overhead operativo. Quale soluzione soddisfa questi requisiti?","options":["Eseguire un cluster Amazon EMR persistente con Hive per catalogare e trasformare i dati.","Scrivere funzioni Lambda che deducono gli schemi e creano manualmente le tabelle Athena.","Caricare i file in un cluster Redshift provisioned e trasformarli con stored procedure.","Usare crawler AWS Glue per popolare il Data Catalog e job Glue ETL per convertire i dati."],"explanation":"I crawler AWS Glue deducono gli schemi e creano nel Glue Data Catalog tabelle che Athena usa direttamente, e i job Glue ETL serverless puliscono e convertono i dati in Parquet senza alcuna infrastruttura da gestire. EMR può eseguire le stesse trasformazioni, ma un cluster persistente deve essere dimensionato, aggiornato e pagato anche quando è inattivo.","optionExplanations":["Un cluster EMR persistente non è serverless e richiede una gestione continua del cluster.","Il codice personalizzato di deduzione degli schemi è fragile e va mantenuto al variare delle sorgenti.","Un cluster Redshift provisioned non è serverless e sposta i dati fuori dal data lake S3 interrogato da Athena.","Corretto — Crawler Glue, Data Catalog e Glue ETL forniscono individuazione e trasformazione serverless."]},
  "1121": {"h":"860c63fe","question":"Un'azienda del settore media memorizza milioni di oggetti in Amazon S3 Standard. Alcuni oggetti vengono letti spesso per mesi, mentre altri non vengono più letti dopo il caricamento, e il pattern di accesso non è prevedibile per nessun singolo oggetto. L'azienda vuole ridurre i costi di storage senza pagare costi di recupero e senza realizzare autonomamente analisi o automazioni. Quale soluzione soddisferà questi requisiti?","options":["Creare una lifecycle rule che sposti tutti gli oggetti in S3 Standard-IA dopo 30 giorni.","Usare S3 Storage Lens per trovare i prefissi freddi e spostarli in S3 One Zone-IA ogni mese.","Spostare gli oggetti in S3 Intelligent-Tiering così che passino automaticamente tra i livelli di accesso.","Creare una lifecycle rule che sposti tutti gli oggetti in S3 Glacier Instant Retrieval dopo 90 giorni."],"explanation":"S3 Intelligent-Tiering monitora l'accesso a ogni oggetto e sposta automaticamente gli oggetti tra i livelli di accesso frequente e infrequente, senza costi di recupero, il che si adatta a pattern di accesso sconosciuti o variabili. Una transizione generalizzata tramite lifecycle verso Standard-IA o Glacier Instant Retrieval comporterebbe costi di recupero sugli oggetti che continuano a essere letti spesso.","optionExplanations":["Gli oggetti che restano acceduti di frequente sosterrebbero i costi di recupero di Standard-IA, che possono annullare il risparmio sullo storage quando l'accesso è imprevedibile.","Richiede analisi e spostamenti manuali ricorrenti, e One Zone-IA aggiunge costi di recupero e memorizza i dati in una sola Availability Zone.","Corretto — Intelligent-Tiering ottimizza automaticamente il livello di ogni oggetto in base all'accesso, senza costi di recupero né automazioni personalizzate.","Glacier Instant Retrieval ha costi di recupero più alti di Standard-IA, quindi gli oggetti letti spesso diventerebbero più costosi."]},
  "1122": {"h":"3bf19eb2","question":"Un'azienda memorizza i log di audit applicativi in Amazon S3. I log vengono letti spesso nei primi 30 giorni, occasionalmente (con necessità di accesso immediato) fino a 1 anno di età e quasi mai in seguito, quando è accettabile un tempo di recupero fino a 48 ore. Le normative richiedono di conservare i log per 7 anni e poi eliminarli. Quale soluzione è la PIÙ conveniente?","options":["Transizione a S3 Standard-IA a 30 giorni e a S3 Glacier Deep Archive a 1 anno, poi scadenza a 7 anni.","Transizione a S3 Glacier Flexible Retrieval a 30 giorni, poi scadenza degli oggetti a 7 anni.","Transizione a S3 One Zone-IA a 30 giorni e a S3 Glacier Deep Archive a 1 anno, senza scadenza.","Memorizzare i log in S3 Intelligent-Tiering con i livelli di archivio abilitati ed eliminarli manualmente a 7 anni."],"explanation":"Il pattern di accesso è noto in anticipo, quindi le lifecycle rule possono spostare i log in Standard-IA finché serve ancora un accesso occasionale immediato, poi in Glacier Deep Archive (la classe più economica, con recuperi entro 48 ore) e infine farli scadere a 7 anni. Intelligent-Tiering aggiunge un costo di monitoraggio per oggetto che non porta alcun beneficio con un pattern prevedibile e richiederebbe l'eliminazione manuale.","optionExplanations":["Corretto — Le regole associano a ogni fase di accesso la classe adatta più economica ed eliminano automaticamente i log al termine della conservazione.","Glacier Flexible Retrieval non fornisce l'accesso immediato per le letture occasionali richieste durante il primo anno.","One Zone-IA è meno resiliente per i dati di audit e, senza scadenza, l'azienda continua a pagare per log che deve eliminare dopo 7 anni.","Intelligent-Tiering addebita costi di monitoraggio per un pattern prevedibile, e l'eliminazione manuale aggiunge overhead operativo e rischi."]},
  "1123": {"h":"21b0639e","question":"Un ospedale memorizza immagini mediche in Amazon S3. Dopo 60 giorni un'immagine viene in genere consultata circa una volta a trimestre, ma quando un medico la richiede deve essere restituita in pochi millisecondi. Le immagini devono essere conservate per 10 anni. Quale strategia di storage per le immagini più vecchie di 60 giorni è la PIÙ conveniente?","options":["Usare S3 Glacier Flexible Retrieval e richiedere recuperi expedited quando serve un'immagine.","Mantenere le immagini in S3 Standard-IA per l'intero periodo di conservazione.","Usare S3 Glacier Deep Archive e pianificare recuperi bulk prima degli appuntamenti dei pazienti.","Usare S3 Glacier Instant Retrieval per tutte le immagini più vecchie di 60 giorni."],"explanation":"S3 Glacier Instant Retrieval è progettato per dati di lunga durata acceduti circa una volta a trimestre che richiedono comunque un recupero in millisecondi, e ha un costo di storage inferiore a Standard-IA. I recuperi expedited di Glacier Flexible Retrieval richiedono minuti, non millisecondi.","optionExplanations":["I recuperi expedited si completano in genere in alcuni minuti, il che non soddisfa il requisito di accesso in millisecondi.","Standard-IA soddisfa il requisito di latenza ma ha un costo di storage più alto di Glacier Instant Retrieval per dati letti solo trimestralmente.","I recuperi da Deep Archive richiedono ore, e non tutte le richieste possono essere anticipate pianificandole in base agli appuntamenti.","Corretto — Glacier Instant Retrieval offre accesso in millisecondi a un prezzo di storage inferiore per dati acceduti circa una volta a trimestre."]},
  "1124": {"h":"d1ddc4e1","question":"Un'azienda esegue centinaia di istanze Amazon EC2 con volumi Amazon EBS gp2. Molti volumi sono stati resi più grandi del necessario solo per ottenere più IOPS. L'azienda conserva inoltre snapshot EBS mensili per 5 anni per conformità, e gli snapshot più vecchi di 90 giorni non vengono quasi mai ripristinati. Quale combinazione di azioni ridurrà MAGGIORMENTE i costi di storage? (Seleziona DUE)","options":["Migrare i volumi a gp3 ed effettuare il provisioning degli IOPS necessari indipendentemente dalla dimensione.","Migrare i volumi a io2 Block Express per ottenere IOPS elevati e costanti a qualsiasi dimensione.","Copiare gli snapshot in una seconda Region AWS ed eliminare gli originali nella Region primaria.","Spostare gli snapshot più vecchi di 90 giorni nel livello Amazon EBS Snapshots Archive.","Convertire i volumi in volumi st1 Throughput Optimized HDD per abbassare il prezzo per GB."],"explanation":"gp3 ha un prezzo per GB inferiore a gp2 e svincola IOPS e throughput dalla dimensione, quindi i volumi non devono più essere sovradimensionati per le prestazioni. EBS Snapshots Archive è un livello a basso costo per snapshot conservati a lungo termine e ripristinati raramente, a fronte di un tempo di ripristino più lungo. io2 aumenterebbe i costi, e st1 non può essere usato come volume di boot e offre prestazioni scarse per l'I/O casuale.","optionExplanations":["Corretto — gp3 costa meno per GB di gp2 e permette all'azienda di effettuare il provisioning degli IOPS senza pagare capacità non necessaria.","io2 Block Express è un tipo di volume premium e aumenterebbe i costi per workload che gp3 può gestire.","Copiare gli snapshot in un'altra Region aggiunge trasferimento cross-Region e non abbassa il prezzo dello storage.","Corretto — Il livello di archivio riduce sensibilmente il costo degli snapshot ripristinati raramente e conservati per conformità.","st1 non può essere usato come volume di boot e non è adatto agli IOPS casuali di cui questi workload hanno bisogno."]},
  "1125": {"h":"679fc8bf","question":"Un'azienda ha un bucket S3 con il versioning abilitato. Le applicazioni sovrascrivono spesso gli oggetti e molti grandi multipart upload falliscono a metà. La quantità di dati correnti è stabile, ma la bolletta di storage S3 continua a crescere. L'azienda deve mantenere il versioning per le modifiche recenti. Quale soluzione ridurrà i costi con il MINOR overhead operativo?","options":["Sospendere il versioning sul bucket ed eseguire uno script settimanale che elimina le vecchie versioni degli oggetti.","Aggiungere lifecycle rule per far scadere le vecchie versioni non correnti e interrompere i multipart upload incompleti.","Abilitare S3 Intelligent-Tiering così che versioni non correnti e parti di upload orfane passino a livelli più economici.","Abilitare S3 Object Lock in governance mode per impedire la creazione di versioni degli oggetti non necessarie."],"explanation":"Le versioni non correnti e le parti dei multipart upload incompleti vengono entrambe fatturate come storage, e le lifecycle rule possono far scadere automaticamente le versioni non correnti dopo un periodo scelto e interrompere gli upload incompleti. Intelligent-Tiering non elimina nulla e non si applica alle parti dei multipart upload incompleti, quindi la crescita continuerebbe.","optionExplanations":["Sospendere il versioning elimina la protezione che l'azienda deve mantenere, e uno script personalizzato aggiunge overhead operativo.","Corretto — Le lifecycle rule rimuovono automaticamente lo storage nascosto mantenendo il versioning per le modifiche recenti.","Il tiering può abbassare il prezzo delle vecchie versioni ma le conserva per sempre, e non gestisce le parti degli upload incompleti.","Object Lock impedisce l'eliminazione delle versioni, quindi peggiorerebbe la crescita dello storage invece di ridurla."]},
  "1126": {"h":"beef5ea5","question":"Un'azienda usa un file system Amazon EFS montato da istanze EC2 in più Availability Zone. I file vengono acceduti intensamente per alcuni giorni dopo la creazione e poi raramente, ma l'applicazione deve continuare a leggere ogni file dallo stesso percorso del file system quando necessario. Il file system deve restare altamente disponibile. Quale soluzione è la PIÙ conveniente?","options":["Eseguire uno script pianificato che copia in Amazon S3 i file più vecchi di 30 giorni e li elimina da EFS.","Ricreare il file system usando lo storage EFS One Zone per abbassare il prezzo di ogni file.","Configurare una lifecycle policy EFS che sposti in EFS Infrequent Access i file non acceduti da 30 giorni.","Passare il file system alla modalità Provisioned Throughput per ridurre il costo dei burst credit."],"explanation":"La lifecycle management di EFS sposta in modo trasparente i file non acceduti per un periodo stabilito nella storage class Infrequent Access, più economica, mentre restano allo stesso percorso nello stesso file system. EFS One Zone è più economico ma memorizza i dati in una sola Availability Zone, in conflitto con il requisito di alta disponibilità.","optionExplanations":["Spostare i file in S3 ne cambia la posizione, quindi l'applicazione non potrebbe più leggerli dallo stesso percorso, e lo script aggiunge overhead.","Lo storage One Zone mantiene i dati in una sola Availability Zone e non soddisfa il requisito di alta disponibilità.","Corretto — La lifecycle management riduce automaticamente il costo di storage e mantiene i file accessibili allo stesso percorso.","Provisioned Throughput aggiunge un costo per il throughput e non riduce in alcun modo il costo di memorizzazione dei file acceduti raramente."]},
  "1127": {"h":"238d60a6","question":"I file server on-premises di un'azienda sono quasi pieni e i dati crescono ogni mese. Gli utenti hanno bisogno di un accesso a bassa latenza ai file usati di recente tramite SMB, mentre i file più vecchi vengono aperti raramente. L'acquisto di un nuovo storage array richiederebbe una grossa spesa in conto capitale. Quale soluzione soddisferà questi requisiti nel modo PIÙ conveniente?","options":["Distribuire Amazon S3 File Gateway on-premises così che le condivisioni file siano memorizzate in S3 e in cache localmente.","Acquistare capacità NAS on-premises aggiuntiva ed eseguirne il backup in S3 Glacier Deep Archive.","Usare AWS DataSync per copiare tutti i file in Amazon EFS e montare EFS dall'ufficio via Internet.","Ordinare ogni mese dispositivi AWS Snowball Edge per scaricare i file più vecchi in Amazon S3."],"explanation":"S3 File Gateway presenta condivisioni SMB on-premises, mantiene i dati usati di recente in una cache locale per una bassa latenza e memorizza tutti i dati in modo durevole in S3, con prezzi a consumo e opzioni di lifecycle. Espandere il NAS richiede comunque la spesa in conto capitale che l'azienda vuole evitare.","optionExplanations":["Corretto — Il gateway elimina la necessità di nuova capacità locale mantenendo veloci i file più usati grazie alla cache locale.","Capacità NAS aggiuntiva è proprio la spesa in conto capitale che l'azienda vuole evitare; i backup non liberano lo storage primario.","EFS è un servizio NFS pensato per l'accesso dall'interno di AWS o tramite connettività privata, e l'accesso dall'ufficio sarebbe lento senza una cache locale.","Spedizioni ricorrenti di Snowball aggiungono impegno operativo e rendono i file scaricati non disponibili tramite le condivisioni esistenti."]},
  "1128": {"h":"0248b3c3","question":"Un istituto di ricerca pubblica grandi dataset genomici in un bucket Amazon S3. Le organizzazioni partner, ciascuna con il proprio account AWS, scaricano spesso i dati, e i costi di trasferimento dati e di richiesta dell'istituto sono diventati significativi. L'istituto vuole che i partner paghino i propri download. Quale soluzione soddisferà questo requisito?","options":["Distribuire i dataset tramite Amazon CloudFront ed emettere signed URL per ogni organizzazione partner.","Replicare il bucket nell'account di ogni partner usando S3 Cross-Region Replication.","Abilitare S3 Transfer Acceleration e usare cost allocation tag per addebitare i download a ogni partner.","Abilitare Requester Pays e far accedere i partner al bucket con le proprie credenziali AWS."],"explanation":"Con Requester Pays, l'account AWS del richiedente paga i costi di richiesta e di trasferimento dati, mentre il proprietario del bucket paga solo lo storage. CloudFront con signed URL controlla l'accesso ma lascia all'istituto il costo di tutta la distribuzione.","optionExplanations":["CloudFront distribuisce i dati, ma l'istituto paga comunque tutto il trasferimento dati e le richieste.","L'istituto pagherebbe le richieste e il trasferimento della replica, e il problema dei costi si sposterebbe semplicemente altrove.","Transfer Acceleration aggiunge costi, e i cost allocation tag organizzano solo la bolletta dell'istituto; non possono addebitare costi a un altro account.","Corretto — Requester Pays sposta i costi di download e di richiesta sugli account AWS dei partner."]},
  "1129": {"h":"9f66caff","question":"Un'azienda esegue ogni notte il rendering di fotogrammi video su una flotta di istanze EC2 On-Demand. Il software di rendering salva checkpoint dei propri progressi, quindi qualsiasi job interrotto può riprendere su un'altra istanza, e i job devono solo terminare entro una finestra di 8 ore. Durante il giorno le istanze sono inattive. Quale soluzione è la PIÙ conveniente?","options":["Acquistare Standard Reserved Instances per i tipi di istanza usati dai job notturni.","Eseguire i job su Spot Instances con diversi tipi di istanza e Availability Zone.","Eseguire i job su Dedicated Hosts così che la capacità sia riservata all'azienda ogni notte.","Creare On-Demand Capacity Reservations per garantire la capacità necessaria ogni notte."],"explanation":"I job batch flessibili e tolleranti ai guasti che salvano checkpoint del proprio lavoro sono ideali per le Spot Instances, che offrono lo sconto maggiore; diversificare tipi di istanza e Availability Zone riduce l'impatto delle interruzioni. Le Reserved Instances vengono fatturate per ogni ora del periodo, quindi sprecano denaro su istanze inattive durante il giorno.","optionExplanations":["Le Reserved Instances vengono addebitate 24 ore al giorno, quindi lo sconto viene sprecato mentre la flotta è inattiva durante il giorno.","Corretto — Le Spot Instances offrono lo sconto più elevato e i checkpoint rendono accettabili le interruzioni.","I Dedicated Hosts servono per esigenze di licensing o conformità e costano più delle istanze in tenancy condivisa.","Le Capacity Reservations garantiscono capacità a prezzi On-Demand e da sole non offrono alcuno sconto."]},
  "1130": {"h":"18aa1fef","question":"Un'azienda esegue un'applicazione web stateless in un EC2 Auto Scaling group. Servono dieci istanze 24 ore su 24, tutti i giorni, e vengono aggiunte istanze durante picchi diurni imprevedibili. L'applicazione tollera la perdita di singole istanze. L'azienda prevede che questo workload resterà in esecuzione per diversi anni. Quale combinazione di azioni è la PIÙ conveniente? (Seleziona DUE)","options":["Coprire l'utilizzo di base costante con un Compute Savings Plan.","Eseguire la capacità di base su Dedicated Instances per l'isolamento.","Usare una mixed instances policy che avvia Spot Instances oltre la base.","Acquistare Reserved Instances che coprano sia la capacità di picco sia la base.","Sostituire le scaling policy con una dimensione fissa del gruppo pari al picco."],"explanation":"Un impegno Savings Plan dimensionato sulla base sempre attiva offre uno sconto su un utilizzo costante, e una mixed instances policy può coprire la capacità variabile dei picchi con Spot Instances perché l'applicazione stateless tollera le interruzioni. Riservare capacità per i picchi significherebbe pagare capacità inutilizzata per la maggior parte del tempo.","optionExplanations":["Corretto — La base è in esecuzione continua per anni, quindi uno sconto basato su un impegno ripaga pienamente.","Le Dedicated Instances costano di più e l'isolamento non è un requisito indicato.","Corretto — Le Spot Instances riducono il costo della capacità di picco, che tollera le interruzioni.","La capacità di picco viene usata solo per parte della giornata, quindi le relative prenotazioni sarebbero in parte sprecate.","Un gruppo fisso dimensionato sul picco paga istanze inattive al di fuori dei periodi di picco."]},
  "1131": {"h":"215dad6e","question":"Un'azienda ha una spesa oraria di calcolo stabile per la quale è disposta a impegnarsi per 3 anni. In questo periodo prevede di cambiare famiglie di istanze EC2, spostare alcuni workload in un'altra Region AWS e migrare diversi servizi su AWS Fargate e AWS Lambda. Quale opzione di acquisto fornirà uno sconto supportando questi cambiamenti?","options":["Compute Savings Plans","EC2 Instance Savings Plans","Standard Reserved Instances con ambito regionale","Convertible Reserved Instances"],"explanation":"I Compute Savings Plans si applicano automaticamente all'utilizzo EC2 indipendentemente da famiglia, dimensione, Region o sistema operativo dell'istanza, e anche all'utilizzo di Fargate e Lambda. Le Convertible Reserved Instances possono essere scambiate con altre configurazioni EC2, ma non coprono mai Fargate o Lambda.","optionExplanations":["Corretto — I Compute Savings Plans seguono la spesa tra famiglie di istanze, Region, Fargate e Lambda.","Gli EC2 Instance Savings Plans sono legati a una famiglia di istanze in una Region e non coprono Fargate o Lambda.","Le Standard Reserved Instances si applicano solo a una specifica configurazione EC2 e non possono coprire Fargate o Lambda.","Le Convertible Reserved Instances possono essere scambiate tra configurazioni EC2, ma non si applicano a Fargate o Lambda."]},
  "1132": {"h":"b4be9773","question":"Un'azienda esegue centinaia di istanze EC2 in molti account di AWS Organizations. Il reparto finanziario sospetta che molte istanze, volumi EBS e funzioni Lambda siano sovradimensionati. L'azienda vuole raccomandazioni di dimensionamento basate sui dati di utilizzo effettivo con il MINOR sforzo operativo. Quale soluzione soddisferà questi requisiti?","options":["Installare ovunque il CloudWatch agent e creare dashboard per confrontare manualmente l'utilizzo.","Usare i controlli sulle service quota di AWS Trusted Advisor per trovare le risorse ridimensionabili.","Usare AWS Cost Explorer per elencare le risorse con la spesa mensile più alta in ogni account.","Abilitare AWS Compute Optimizer per l'organizzazione ed esaminarne le raccomandazioni di rightsizing."],"explanation":"AWS Compute Optimizer analizza le metriche di utilizzo e consiglia configurazioni ottimali per istanze EC2, Auto Scaling group, volumi EBS, funzioni Lambda e altro, e può essere abilitato per tutti gli account di un'organizzazione. Creare dashboard e confrontare manualmente l'utilizzo funzionerebbe, ma richiede molto più impegno.","optionExplanations":["L'analisi manuale su centinaia di risorse è laboriosa e più lenta di un servizio di raccomandazioni gestito.","I controlli sulle service quota indicano quanto l'utilizzo sia vicino ai limiti dell'account; non producono raccomandazioni di dimensionamento.","La spesa più alta non indica un sovradimensionamento, e questa vista non raccomanda nuove dimensioni per volumi o funzioni.","Corretto — Compute Optimizer fornisce raccomandazioni di rightsizing basate sull'utilizzo per tutta l'organizzazione, senza strumenti personalizzati."]},
  "1133": {"h":"4f9e2d2b","question":"Un'azienda esegue microservizi Java containerizzati su Amazon ECS usando istanze EC2 basate su x86. I servizi girano sulla JVM e non hanno dipendenze native x86, e il carico è sostenuto per tutto il giorno. L'azienda vuole un miglior rapporto prezzo/prestazioni per questo calcolo con modifiche minime all'applicazione. Quale soluzione soddisferà questi requisiti?","options":["Spostare i servizi su istanze x86 burstable in modalità di credito unlimited.","Spostare i servizi su meno istanze x86 più grandi per aumentare la densità dei task.","Ricompilare le immagini per arm64 ed eseguire i servizi su istanze basate su AWS Graviton.","Spostare i servizi sulla famiglia di istanze x86 più recente con instance storage NVMe locale."],"explanation":"Le istanze basate su AWS Graviton offrono un miglior rapporto prezzo/prestazioni rispetto a istanze x86 comparabili, e i workload JVM senza dipendenze native di solito richiedono solo di ricompilare le immagini dei container per arm64. Le istanze burstable non sono adatte a un carico sostenuto, poiché la modalità unlimited addebita i crediti CPU in eccedenza.","optionExplanations":["Un utilizzo sostenuto della CPU su istanze burstable in modalità unlimited comporta costi aggiuntivi per i crediti, annullando il risparmio.","Istanze più grandi della stessa famiglia mantengono lo stesso prezzo per vCPU e non migliorano il rapporto prezzo/prestazioni.","Corretto — Graviton offre un miglior rapporto prezzo/prestazioni e il codice JVM portabile richiede modifiche minime.","Lo storage NVMe locale non è richiesto dai servizi e aggiunge costi senza migliorare il rapporto prezzo/prestazioni del calcolo."]},
  "1134": {"h":"91c5db67","question":"Un'API interna riceve qualche centinaio di richieste al giorno a raffiche imprevedibili, e ogni richiesta si completa in meno di 2 secondi. L'API è attualmente eseguita su due istanze EC2 dietro un Application Load Balancer, 24 ore su 24. L'azienda vuole minimizzare i costi mantenendo l'API altamente disponibile. Quale soluzione soddisferà questi requisiti?","options":["Sostituire le due istanze con una sola Reserved Instance più grande dietro il load balancer.","Riscrivere l'API come funzioni AWS Lambda invocate tramite Amazon API Gateway.","Spostare l'API su Amazon ECS su AWS Fargate con due task in esecuzione continua.","Mantenere le istanze e aggiungere un Auto Scaling group con dimensione minima pari a due."],"explanation":"Lambda dietro API Gateway addebita solo per richiesta e tempo di esecuzione, quindi qualche centinaio di brevi richieste al giorno costa pochissimo, ed entrambi i servizi sono altamente disponibili su più Availability Zone per impostazione predefinita. Qualsiasi opzione che mantenga capacità in esecuzione 24 ore su 24 paga risorse per lo più inattive.","optionExplanations":["Una sola istanza elimina l'alta disponibilità, e resta comunque in esecuzione e a pagamento 24 ore su 24.","Corretto — Lambda a consumo si adatta a un volume di richieste basso e a raffiche ed è altamente disponibile senza gestire server.","Due task Fargate in esecuzione continua sono comunque capacità sempre attiva, inattiva per gran parte della giornata.","Un Auto Scaling group con minimo due mantiene lo stesso costo sempre attivo di oggi."]},
  "1135": {"h":"97ff93e0","question":"Un'azienda esegue worker di elaborazione immagini come task Amazon ECS su AWS Fargate. I worker interrogano una coda Amazon SQS, l'elaborazione è idempotente e, se un task viene arrestato, il messaggio torna visibile e viene elaborato da un altro task. L'azienda vuole ridurre i costi di calcolo con il MINOR overhead operativo. Quale soluzione soddisferà questi requisiti?","options":["Usare una capacity provider strategy che esegua i task worker su Fargate Spot.","Spostare i worker su un cluster ECS basato su Spot Instances EC2 autogestite.","Acquistare un EC2 Instance Savings Plan per coprire i task worker su Fargate.","Aumentare CPU e memoria di ogni task così che i messaggi vengano elaborati più velocemente."],"explanation":"Fargate Spot esegue task tolleranti alle interruzioni su capacità inutilizzata a prezzo scontato, e l'architettura basata su SQS gestisce già i task interrotti; il passaggio richiede solo una capacity provider strategy. Passare a Spot Instances EC2 autogestite potrebbe anch'esso far risparmiare, ma aggiunge overhead di gestione delle istanze.","optionExplanations":["Corretto — Fargate Spot offre un forte sconto senza server da gestire, e la coda tollera le interruzioni.","Le istanze EC2 autogestite aggiungono overhead di patching, scalabilità e gestione della capacità.","Gli EC2 Instance Savings Plans si applicano solo all'utilizzo EC2 e non coprono Fargate.","Task più grandi costano di più all'ora e non riducono necessariamente il costo totale dell'elaborazione."]},
  "1136": {"h":"6547fbcf","question":"Le istanze EC2 di sviluppo e test di un'azienda vengono usate solo dalle 8 alle 18 nei giorni feriali, ma restano in esecuzione continuamente. Tutte le istanze hanno un tag con il proprio ambiente. L'azienda vuole ridurne il costo con il MINOR overhead operativo. Quale soluzione soddisferà questi requisiti?","options":["Acquistare Reserved Instances per le istanze di sviluppo e test per abbassarne la tariffa oraria.","Chiedere agli sviluppatori di arrestare manualmente le proprie istanze alla fine di ogni giornata lavorativa.","Convertire le istanze di sviluppo e test in Spot Instances che terminano quando non vengono usate.","Usare Instance Scheduler on AWS per arrestare e avviare le istanze con tag secondo una pianificazione."],"explanation":"Arrestare le istanze fuori dall'orario lavorativo elimina la maggior parte dei loro costi di calcolo, e Instance Scheduler on AWS automatizza le azioni di arresto e avvio per le istanze con tag secondo pianificazioni definite. Le Reserved Instances abbassano la tariffa oraria ma vengono fatturate per ogni ora, comprese le molte ore in cui le istanze non servono.","optionExplanations":["Le Reserved Instances si pagano 24 ore al giorno, quindi non catturano il risparmio derivante dallo spegnimento delle istanze di notte e nei fine settimana.","L'arresto manuale è inaffidabile e dipende dal fatto che ogni sviluppatore se ne ricordi.","Le Spot Instances possono essere interrotte in qualsiasi momento, e le istanze terminate perdono configurazione e dati.","Corretto — L'automazione pianificata di arresto e avvio basata sui tag elimina le ore di inattività senza sforzo manuale."]},
  "1137": {"h":"c4a12e06","question":"Un'applicazione interna di reportistica usa un cluster Amazon Aurora compatibile con MySQL. Il database è molto utilizzato per poche ore a fine mese ed è quasi inattivo per il resto del mese, ma l'istanza DB è dimensionata per il picco di fine mese. L'azienda vuole ridurre i costi con un'amministrazione minima. Quale soluzione soddisferà questi requisiti?","options":["Acquistare una Reserved Instance per l'attuale classe di istanza DB Aurora.","Aggiungere Aurora Replica prima di ogni fine mese e rimuoverle manualmente in seguito.","Migrare il cluster ad Aurora Serverless v2 con limiti di capacità adeguati.","Spostare il database su Amazon RDS for MySQL con una grande classe di istanza DB burstable."],"explanation":"Aurora Serverless v2 aumenta e riduce automaticamente la capacità con incrementi granulari, quindi l'azienda paga un'elevata capacità solo a fine mese e una capacità ridotta per il resto del tempo. Una Reserved Instance abbassa la tariffa ma paga comunque per tutto il mese una capacità dimensionata sul picco.","optionExplanations":["Lo sconto si applica comunque a un'istanza dimensionata per un picco che si verifica solo poche ore al mese.","Aggiungere e rimuovere manualmente repliche ogni mese aggiunge amministrazione, e il writer resta dimensionato sul picco.","Corretto — Serverless v2 adegua automaticamente la capacità al carico intermittente.","Un'istanza burstable può esaurire i crediti CPU durante il picco sostenuto di fine mese e resta comunque capacità provisioned."]},
  "1138": {"h":"ac178fa1","question":"Una tabella Amazon DynamoDB usa la modalità di capacità on-demand da quando l'applicazione è stata lanciata 2 anni fa. Il traffico è ora costante e prevedibile, con un ciclo giornaliero graduale e senza picchi improvvisi. I costi di throughput rappresentano la maggior parte del costo della tabella. Quale modifica ridurrà MAGGIORMENTE il costo di questa tabella?","options":["Mantenere la modalità on-demand e aggiungere un cluster DynamoDB Accelerator (DAX) davanti alla tabella.","Passare la tabella alla modalità di capacità provisioned con auto scaling.","Cambiare la table class in DynamoDB Standard-Infrequent Access.","Esportare la tabella in Amazon S3 ogni giorno e servire le letture dall'esportazione."],"explanation":"Per un traffico costante e prevedibile, la capacità provisioned con un auto scaling che segue il ciclo giornaliero è in genere molto più economica dei prezzi on-demand. La table class Standard-IA abbassa il costo di storage ma aumenta quello di throughput, il compromesso sbagliato quando è il throughput a dominare la bolletta.","optionExplanations":["DAX aggiunge il costo del cluster, aiuta solo le letture e non cambia il prezzo per richiesta delle scritture.","Corretto — La capacità provisioned con auto scaling è adatta a un traffico prevedibile e costa meno dell'on-demand.","Standard-IA riduce il prezzo dello storage ma aumenta i costi di lettura e scrittura, quindi è sbagliata quando domina il throughput.","Servire le letture da esportazioni giornaliere restituisce dati non aggiornati e aggiunge complessità senza intervenire sui costi di scrittura."]},
  "1139": {"h":"ce8809ea","question":"Un'azienda esegue un database PostgreSQL di produzione su un'istanza DB Amazon RDS Multi-AZ. Il carico è costante 24 ore su 24 e l'azienda manterrà la stessa famiglia di istanze e la stessa Region per almeno altri 3 anni. L'alta disponibilità deve essere mantenuta. Quale soluzione è la PIÙ conveniente?","options":["Acquistare RDS Reserved Instances per l'istanza DB Multi-AZ con un periodo di 3 anni.","Acquistare un Compute Savings Plan dimensionato per coprire ogni ora l'utilizzo dell'istanza DB RDS.","Convertire il deployment in Single-AZ ed eseguire snapshot automatici frequenti.","Migrare il database ad Aurora Serverless v2 per pagare solo la capacità utilizzata."],"explanation":"Un workload RDS costante e di lunga durata con famiglia di istanze e Region fisse è adatto alle RDS Reserved Instances, che riducono sensibilmente il costo rispetto ai prezzi On-Demand. I Compute Savings Plans si applicano a EC2, Fargate e Lambda, non alle istanze DB RDS.","optionExplanations":["Corretto — Le Reserved Instances offrono un forte sconto per un workload RDS costante e pluriennale mantenendo il Multi-AZ.","I Compute Savings Plans non si applicano all'utilizzo di Amazon RDS.","Il Single-AZ elimina lo standby e non soddisfa il requisito di alta disponibilità.","La capacità serverless è più adatta a un carico variabile; un workload costante 24 ore su 24 è in genere più economico su capacità provisioned riservata."]},
  "1140": {"h":"134f414a","question":"Un sito di e-commerce memorizza il proprio catalogo prodotti in Amazon RDS for MySQL. L'utilizzo della CPU dell'istanza DB è elevato perché le stesse query sui dettagli dei prodotti vengono eseguite migliaia di volte al minuto, e il team sta valutando di passare a una classe di istanza più grande. L'azienda vuole ridurre il carico e la latenza del database nel modo PIÙ conveniente. Quale soluzione soddisferà questi requisiti?","options":["Scalare l'istanza DB alla classe immediatamente superiore con più vCPU e memoria.","Abilitare il Multi-AZ così che l'istanza standby possa servire parte del traffico in lettura.","Cambiare lo storage del DB in Provisioned IOPS SSD per aumentare le prestazioni in lettura.","Aggiungere un cluster Amazon ElastiCache per mettere in cache i dettagli dei prodotti più richiesti."],"explanation":"Letture identiche ripetute sono un workload ideale per il caching: ElastiCache le serve dalla memoria con latenza nell'ordine dei microsecondi e alleggerisce il database, che può quindi restare alla dimensione attuale. Uno standby Multi-AZ non serve traffico in lettura, quindi aggiunge costi senza ridurre il carico.","optionExplanations":["Un'istanza più grande costa di più e rimanda soltanto il problema causato dalle letture ripetute.","Uno standby Multi-AZ serve per il failover e non gestisce letture.","Il collo di bottiglia è la CPU dovuta alle query ripetute, non gli IOPS dello storage, e Provisioned IOPS aggiunge costi.","Corretto — Mettere in cache le letture ripetute alleggerisce il database e riduce la latenza a un costo inferiore rispetto allo scale-up."]},
  "1141": {"h":"3fef8ef5","question":"Un'azienda conserva lo storico degli ordini in una grande tabella Amazon DynamoDB. Gli item vengono letti raramente e lo storage rappresenta ora la maggior parte del costo della tabella. I record devono restare disponibili tramite la stessa API DynamoDB con latenza di pochi millisecondi. Quale soluzione ridurrà i costi soddisfacendo questi requisiti?","options":["Aggiungere un cluster DynamoDB Accelerator (DAX) per ridurre le letture che raggiungono la tabella.","Passare la tabella dalla capacità on-demand a quella provisioned con auto scaling.","Cambiare la table class in DynamoDB Standard-Infrequent Access (Standard-IA).","Esportare la tabella in S3 Glacier Deep Archive ed eliminare la tabella DynamoDB."],"explanation":"La table class DynamoDB Standard-IA riduce il costo di storage per le tabelle in cui lo storage è la voce dominante, mantenendo la stessa API, le stesse prestazioni e la stessa durabilità. Cambiare la modalità di capacità incide sui costi di throughput, che qui non sono la voce principale.","optionExplanations":["DAX aggiunge costi e riduce il carico in lettura, ma le letture sono rare e lo storage è il costo principale.","La modalità di capacità incide sul prezzo del throughput, non sullo storage, che è il costo dominante.","Corretto — Standard-IA riduce il costo di storage senza modificare l'API né la latenza.","I recuperi da Deep Archive richiedono ore, quindi i record non sarebbero più disponibili con latenza in millisecondi."]},
  "1142": {"h":"10cbaa3f","question":"Un'azienda esegue un cluster Amazon Redshift provisioned 24 ore su 24. Pochi analisti lo usano per eseguire query SQL ad hoc alcune volte al mese su dati di log già esportati in Amazon S3 come file CSV. L'azienda vuole ridurre sensibilmente i costi mantenendo l'accesso SQL. Quale soluzione soddisferà questi requisiti?","options":["Interrogare i log in S3 con Amazon Athena dopo averli convertiti in Parquet.","Acquistare reserved node Redshift per il cluster esistente per abbassarne la tariffa oraria.","Caricare i log in un'istanza DB Amazon RDS for PostgreSQL più piccola per gli analisti.","Caricare i log in Amazon DynamoDB ed eseguire scansioni ad hoc dagli strumenti degli analisti."],"explanation":"Athena è serverless e addebita in base ai dati scansionati, quindi query poco frequenti costano poco e nulla resta in esecuzione tra una query e l'altra; i formati colonnari riducono ulteriormente i dati scansionati. I reserved node pagano comunque un cluster inattivo per quasi tutto il mese.","optionExplanations":["Corretto — Athena interroga i dati sul posto senza infrastruttura sempre attiva, e Parquet riduce i dati scansionati.","I reserved node abbassano la tariffa ma continuano a pagare un cluster inattivo per gran parte del mese.","Un'istanza RDS resta comunque in esecuzione 24 ore su 24 e deve essere caricata e mantenuta.","DynamoDB non è progettato per analisi SQL ad hoc, e le scansioni dell'intera tabella sono lente e costose."]},
  "1143": {"h":"c96032f9","question":"Un'azienda esegue 20 istanze DB Amazon RDS for MySQL per sviluppo e test. I database vengono usati solo durante l'orario lavorativo nei giorni feriali, hanno un carico leggero e usano le stesse classi di istanza x86 della produzione. Quale combinazione di azioni ridurrà MAGGIORMENTE il costo di questi database? (Seleziona DUE)","options":["Acquistare RDS Reserved Instances triennali per tutte le istanze DB di sviluppo.","Arrestare le istanze DB fuori dall'orario lavorativo secondo una pianificazione e avviarle ogni mattina.","Convertire le istanze DB in deployment Multi-AZ per migliorare la disponibilità.","Spostare lo storage del DB su volumi Provisioned IOPS SSD (io2).","Ridimensionare le istanze DB a classi di istanza più piccole basate su Graviton."],"explanation":"Arrestare le istanze di notte e nei fine settimana elimina i costi per ora di istanza per gran parte della settimana, e ridimensionare i database poco carichi a classi Graviton più piccole abbassa il costo delle ore rimanenti. Le Reserved Instances vengono fatturate che l'istanza sia in esecuzione o meno, quindi sono in conflitto con l'arresto dei database.","optionExplanations":["Le Reserved Instances vengono addebitate per ogni ora del periodo, quindi sprecano denaro su database arrestati per gran parte della settimana.","Corretto — Le istanze DB arrestate non generano costi per ora di istanza, ma solo per lo storage.","Il Multi-AZ raddoppia circa il costo dell'istanza e non è necessario per sviluppo e test.","I volumi io2 costano di più e il carico leggero non richiede IOPS provisioned.","Corretto — Classi più piccole basate su Graviton si adattano al carico leggero a un prezzo inferiore."]},
  "1144": {"h":"29d6d488","question":"Istanze EC2 in subnet private leggono grandi volumi di dati da Amazon S3 e scrivono i risultati in Amazon DynamoDB nella stessa Region. Tutto questo traffico passa attualmente attraverso NAT gateway, e i costi di elaborazione dati dei NAT gateway sono ora la voce più alta in bolletta. Quale combinazione di passaggi ridurrà questi costi nel modo PIÙ conveniente? (Seleziona DUE)","options":["Sostituire i NAT gateway con NAT instance autogestite su tipi di istanza EC2 più grandi.","Creare un gateway VPC endpoint per Amazon S3 e aggiungerlo alle route table delle subnet private.","Creare un interface VPC endpoint per Amazon DynamoDB in ogni Availability Zone.","Creare un gateway VPC endpoint per Amazon DynamoDB e aggiungerlo alle route table delle subnet private.","Spostare le istanze in subnet pubbliche e assegnare loro indirizzi Elastic IP."],"explanation":"I gateway VPC endpoint per S3 e DynamoDB instradano privatamente questo traffico senza NAT gateway e non hanno costi orari né di elaborazione dati. Anche gli interface endpoint evitano il NAT gateway, ma aggiungono costi orari e per GB, quindi sono meno convenienti dei gateway endpoint.","optionExplanations":["Le NAT instance aggiungono overhead di gestione e rischi di disponibilità, continuando a far passare il traffico per un percorso NAT.","Corretto — Un gateway endpoint per S3 sottrae il traffico S3 al NAT gateway senza costi aggiuntivi.","Un interface endpoint ha costi orari e per GB, mentre un gateway endpoint per DynamoDB non ne ha.","Corretto — Un gateway endpoint per DynamoDB sottrae il traffico DynamoDB al NAT gateway senza costi aggiuntivi.","Le subnet pubbliche espongono le istanze a Internet e aggiungono i costi degli indirizzi IPv4 pubblici."]},
  "1145": {"h":"2946c45e","question":"Un'azienda esegue un job di analisi notturno su un cluster di istanze EC2 che si scambiano quantità di dati molto grandi. L'Auto Scaling group distribuisce i nodi su tre Availability Zone, e i costi di trasferimento dati tra AZ sono diventati significativi. Se il job fallisce, può semplicemente essere rieseguito l'ora successiva. Quale soluzione è la PIÙ conveniente?","options":["Inserire un Network Load Balancer tra i nodi per distribuire uniformemente il loro traffico.","Instradare il traffico tra i nodi tramite un transit gateway per ottimizzare il percorso di rete.","Avviare tutti i nodi in una sola Availability Zone usando un cluster placement group.","Abilitare Elastic Fabric Adapter sui nodi mantenendoli distribuiti su tre AZ."],"explanation":"Il trasferimento dati tra istanze nella stessa Availability Zone tramite indirizzi IP privati è gratuito, e un cluster placement group offre anche bassa latenza e throughput elevato. Poiché il job può essere rieseguito, la minore disponibilità di una sola Availability Zone è un compromesso accettabile.","optionExplanations":["Un load balancer aggiunge i propri costi e non elimina il trasferimento dati tra AZ.","Un transit gateway aggiunge costi di elaborazione dati per GB al traffico esistente.","Corretto — Mantenere i nodi in una sola AZ elimina i costi di trasferimento tra AZ, e la riesecuzione copre il rischio di disponibilità.","Elastic Fabric Adapter migliora le prestazioni di rete ma non elimina i costi per il traffico tra Availability Zone."]},
  "1146": {"h":"2419768f","question":"Un'azienda di software distribuisce installer da un bucket Amazon S3 in una sola Region a clienti in tutto il mondo. Il trasferimento dati in uscita da S3 è ora una parte rilevante della bolletta, e i clienti lontani dalla Region segnalano download lenti. Quale soluzione ridurrà i costi e migliorerà la velocità di download?","options":["Abilitare S3 Transfer Acceleration sul bucket e usarne l'endpoint per i download.","Distribuire gli installer tramite una distribuzione Amazon CloudFront con origin access control.","Replicare il bucket in diverse altre Region con regole S3 Cross-Region Replication.","Ospitare gli installer su istanze EC2 dietro un Network Load Balancer nella Region."],"explanation":"CloudFront mette in cache gli installer nelle edge location vicine ai clienti, migliorando la velocità e riducendo le richieste all'origin; il trasferimento dati da S3 a CloudFront non viene addebitato, e la distribuzione tramite CloudFront è in genere più economica del trasferimento dati in uscita diretto da S3. Transfer Acceleration migliora i trasferimenti a lunga distanza ma aggiunge un costo per GB oltre ai normali costi di trasferimento.","optionExplanations":["Transfer Acceleration aggiunge costi oltre al trasferimento dati in uscita ed è usato principalmente per velocizzare gli upload.","Corretto — Il caching sull'edge riduce il trasferimento dall'origin e i costi, rendendo i download più veloci.","La replica aggiunge costi di storage e di trasferimento per la replica, e i clienti avrebbero comunque bisogno di un modo per raggiungere la copia più vicina.","Istanze e load balancer aggiungono costi di calcolo e pagano comunque il trasferimento dati in uscita regionale, senza caching sull'edge."]},
  "1147": {"h":"79a43946","question":"Un'azienda invia continuamente decine di terabyte di dati al mese dal proprio VPC al data center on-premises tramite una AWS Site-to-Site VPN su Internet. Il volume è costante e in crescita, la soluzione è a lungo termine e il throughput sulla VPN è incostante. L'azienda vuole costi di trasferimento dati più bassi e prestazioni di rete più costanti. Quale soluzione soddisferà questi requisiti?","options":["Aggiungere altri tunnel VPN e usare il routing equal-cost multipath per aggregarne la banda.","Mettere AWS Global Accelerator davanti al VPC per instradare il traffico verso il data center.","Spedire ogni mese i dati al data center su dispositivi AWS Snowball Edge.","Stabilire una connessione AWS Direct Connect tra il data center e AWS."],"explanation":"Direct Connect fornisce una connessione privata dedicata con prestazioni costanti, e i dati trasferiti in uscita da AWS tramite Direct Connect vengono addebitati a una tariffa inferiore rispetto al trasferimento via Internet, il che ripaga con volumi elevati e costanti. Tunnel VPN aggiuntivi possono aggiungere banda, ma continuano a passare su Internet con le tariffe di trasferimento Internet.","optionExplanations":["Più tunnel possono aumentare la banda, ma il traffico usa comunque Internet, con tariffe di trasferimento Internet e prestazioni variabili.","Global Accelerator serve a migliorare il traffico degli utenti verso gli endpoint AWS, non per trasferimenti massivi verso un data center, e aggiunge costi.","Le spedizioni mensili non sono adatte a un flusso di dati continuo e aggiungono lavoro di gestione e ritardi.","Corretto — Direct Connect riduce i costi di trasferimento per GB su larga scala e offre prestazioni di rete costanti."]},
  "1148": {"h":"e7b7267f","question":"Un VPC di sviluppo ha subnet private in tre Availability Zone, ciascuna con il proprio NAT gateway. Il traffico Internet in uscita dei workload IPv4 è leggero. Il team accetta di perdere l'accesso Internet in uscita dalle altre subnet se una Availability Zone dovesse guastarsi. L'azienda vuole ridurre i costi. Quale soluzione soddisferà questi requisiti?","options":["Mantenere un solo NAT gateway in una AZ e instradare attraverso di esso tutte le subnet private.","Collegare un internet gateway a ogni subnet privata al posto dei NAT gateway.","Sostituire ogni NAT gateway con un egress-only internet gateway.","Creare un gateway VPC endpoint per ogni servizio AWS chiamato dalle istanze."],"explanation":"Ogni NAT gateway ha un costo orario, quindi usare un unico NAT gateway condiviso elimina due di questi costi; il compromesso è la dipendenza da una sola Availability Zone più un po' di trasferimento tra AZ, accettabile per un traffico di sviluppo leggero. Gli egress-only internet gateway funzionano solo per il traffico IPv6.","optionExplanations":["Corretto — Un unico NAT gateway condiviso riduce i costi orari, e il team ha accettato la dipendenza da una sola AZ.","Gli internet gateway si collegano al VPC, non alle subnet, e instradare le subnet private verso uno di essi le renderebbe pubbliche.","Gli egress-only internet gateway supportano solo traffico IPv6, quindi i workload IPv4 perderebbero l'accesso a Internet.","I gateway endpoint esistono solo per S3 e DynamoDB e non possono sostituire l'accesso generale a Internet."]},
  "1149": {"h":"0082142e","question":"Un'azienda ha tre VPC nella stessa Region che si scambiano grandi volumi di dati. L'azienda non prevede di aggiungere altri VPC e non ha bisogno di routing transitivo né di connessioni a reti on-premises. L'azienda vuole la connettività privata più economica tra i VPC. Quale soluzione soddisferà questi requisiti?","options":["Collegare tutti e tre i VPC a un AWS Transit Gateway con un'unica route table condivisa.","Instradare il traffico tra i VPC tramite NAT gateway e la rete Internet pubblica.","Creare una full mesh di connessioni VPC peering tra i tre VPC.","Esporre i servizi di ogni VPC tramite interface endpoint AWS PrivateLink."],"explanation":"Il VPC peering non ha costi orari né di elaborazione dati, ma solo il normale trasferimento dati, e una full mesh di tre VPC richiede solo tre connessioni di peering. Transit Gateway semplifica grandi reti hub-and-spoke ma aggiunge costi orari per attachment e costi di elaborazione per GB, significativi con volumi elevati.","optionExplanations":["Transit Gateway aggiunge costi di attachment e di elaborazione dati non necessari per tre VPC.","Il routing via Internet aggiunge costi di elaborazione NAT e di trasferimento e non è connettività privata.","Corretto — Il peering è l'opzione privata più economica per un numero piccolo e fisso di VPC.","Gli endpoint PrivateLink aggiungono costi orari e per GB ed espongono singoli servizi invece di connettere le reti."]},
  "1150": {"h":"19e069a7","question":"Diversi team condividono un unico account AWS e tutte le risorse hanno un tag con il team proprietario. Il reparto finanziario vuole vedere i costi mensili di ogni team e vuole che ogni team lead riceva un'email quando la spesa mensile prevista del team supera il suo budget. Quale soluzione soddisferà questi requisiti con il MINOR overhead operativo?","options":["Esportare ogni giorno l'AWS Cost and Usage Report e scrivere una funzione Lambda che invia email ai team lead.","Attivare il tag del team per la cost allocation e creare AWS Budgets filtrati per tag con avvisi sulle previsioni.","Creare allarmi di fatturazione Amazon CloudWatch per ogni team basati sulla metrica dei costi stimati dell'account.","Configurare AWS Cost Anomaly Detection con un unico monitor che copre l'intero account."],"explanation":"Attivare il tag come cost allocation tag permette a Cost Explorer e AWS Budgets di raggruppare i costi per team, e un budget per ogni team può inviare avvisi via email quando la spesa prevista supera l'importo previsto a budget. Gli allarmi di fatturazione CloudWatch monitorano i costi stimati totali e non possono generare avvisi sulle previsioni per singolo team.","optionExplanations":["Una pipeline di reportistica personalizzata funziona, ma richiede di scrivere e mantenere codice.","Corretto — I cost allocation tag insieme a budget filtrati per tag offrono visibilità per team e avvisi sulle previsioni senza codice personalizzato.","La metrica dei costi stimati non è suddivisa per tag e non valuta le previsioni.","L'anomaly detection segnala pattern di spesa insoliti, non una spesa che supera il budget di un team, e un unico monitor per tutto l'account non è per team."]},
  "1151": {"h":"a8c41f40","question":"Un'azienda conserva un data lake in un unico bucket Amazon S3. Decine di team in diversi account AWS necessitano di autorizzazioni diverse su prefissi diversi, e alcuni team devono poter raggiungere i dati solo da uno specifico VPC. La bucket policy è diventata troppo grande per essere gestita in sicurezza. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Assegnare a ogni team un proprio S3 access point con relativa policy, con access point limitati al VPC dove serve.","Suddividere i dati in un bucket per team e mantenere sincronizzati gli oggetti condivisi con S3 Replication.","Concedere all'account di ciascun team l'accesso al proprio prefisso tramite ACL sugli oggetti caricati.","Affidarsi solo alle policy IAM basate sull'identità in ogni account dei team e rimuovere del tutto la bucket policy."],"explanation":"Gli S3 Access Points consentono a ogni team di avere un proprio endpoint con nome e una propria policy, e un access point può essere limitato a un'origine di rete VPC. In questo modo un'enorme bucket policy viene suddivisa in parti gestibili. Bucket separati con replica funzionerebbero comunque, ma duplicano i dati e aggiungono un onere operativo significativo.","optionExplanations":["Corretto — Gli access point danno a ogni team una policy separata e più piccola e un'origine di rete VPC opzionale, mentre la bucket policy si limita a delegare il controllo agli access point.","Duplica i dati e aggiunge la gestione della replica per ogni dataset condiviso, aumentando onere e costi.","Le ACL sono legacy, non possono esprimere condizioni a livello di prefisso o di VPC e andrebbero impostate su ogni oggetto.","L'accesso cross-account richiede che il proprietario del bucket conceda l'accesso in una resource policy; le sole policy basate sull'identità non bastano."]},
  "1152": {"h":"101fadd6","question":"Alcune aziende partner caricano file dai propri account AWS nel bucket Amazon S3 di un'azienda. L'azienda non riesce a leggere alcuni degli oggetti caricati perché sono di proprietà degli account che li hanno caricati. L'azienda vuole essere proprietaria di ogni oggetto nel bucket e smettere del tutto di usare le ACL. Quale soluzione soddisfa questi requisiti?","options":["Richiedere ai partner di caricare con la canned ACL bucket-owner-full-control in ogni richiesta.","Impostare S3 Object Ownership del bucket su bucket owner enforced.","Aggiungere una bucket policy che conceda all'account dell'azienda s3:GetObject su tutti gli oggetti.","Abilitare S3 Versioning e far copiare a una funzione Lambda ogni nuovo oggetto su se stesso."],"explanation":"Con Object Ownership impostato su bucket owner enforced, le ACL vengono disabilitate e il proprietario del bucket diventa automaticamente proprietario di tutti gli oggetti, quindi l'accesso è controllato solo dalle policy. Richiedere l'ACL bucket-owner-full-control è il vecchio workaround e mantiene il bucket dipendente dalle ACL.","optionExplanations":["Dipende ancora dalle ACL e dal fatto che ogni partner si ricordi l'header, in contrasto con l'obiettivo di smettere di usare le ACL.","Corretto — Bucket owner enforced disabilita le ACL e rende il proprietario del bucket proprietario di ogni oggetto, inclusi quelli caricati da altri account.","Finché le ACL sono attive, gli oggetti di proprietà di un altro account non sono governati dalla policy del proprietario del bucket, quindi questo non risolve l'accesso.","Aggiunge codice personalizzato e lo storage di versioni extra, e lascia comunque le ACL abilitate sul bucket."]},
  "1153": {"h":"0b9d6488","question":"Un'azienda conserva i record dei clienti come oggetti JSON in Amazon S3. Un'applicazione di fatturazione necessita dei record completi. Un'applicazione di analytics deve leggere gli stessi oggetti, ma senza i campi con dati personali. L'azienda non vuole archiviare né mantenere una seconda copia dei dati. Quale soluzione soddisfa questi requisiti?","options":["Fornire all'applicazione di analytics presigned URL di breve durata che puntano agli oggetti originali.","Eseguire ogni notte un job AWS Glue che scriva copie oscurate degli oggetti in un secondo bucket.","Usare un access point S3 Object Lambda che rimuova i campi personali nelle letture di analytics.","Abilitare Amazon Macie sul bucket per mascherare automaticamente i campi con dati personali negli oggetti."],"explanation":"S3 Object Lambda aggiunge una funzione Lambda al percorso delle richieste di un access point, così ogni chiamante può ricevere una vista trasformata dello stesso oggetto. I presigned URL concedono solo un accesso temporaneo e restituiscono il contenuto originale.","optionExplanations":["I presigned URL controllano l'accesso limitato nel tempo ma restituiscono l'oggetto completo, non oscurato.","Crea e mantiene una seconda copia dei dati, cosa che l'azienda vuole evitare, e la copia non è aggiornata tra un'esecuzione e l'altra.","Corretto — Object Lambda trasforma i dati al volo durante le richieste GET, quindi un'unica copia archiviata serve entrambe le applicazioni.","Macie individua e segnala i dati sensibili; non modifica né maschera il contenuto degli oggetti."]},
  "1154": {"h":"ae0be4df","question":"L'account A condivide uno snapshot Amazon EBS con l'account B. Lo snapshot è cifrato con una customer managed key AWS KMS nell'account A. Gli utenti dell'account B vedono lo snapshot condiviso ma ricevono errori quando creano volumi a partire da esso. Quale combinazione di passaggi risolverà il problema? (Seleziona DUE)","options":["Aggiornare la key policy della chiave KMS nell'account A per consentire all'account B di usare la chiave.","Ricifrare lo snapshot con la chiave AWS managed aws/ebs e condividerlo di nuovo.","Abilitare la cifratura EBS predefinita nell'account B con una nuova chiave KMS.","Associare nell'account B una policy IAM che consenta ai suoi utenti di usare la chiave KMS dell'account A.","Condividere la chiave KMS con l'account B creando una resource share AWS RAM."],"explanation":"L'uso cross-account di una customer managed key KMS richiede due autorizzazioni: la key policy nell'account proprietario deve consentire l'account esterno, e l'account esterno deve delegare tale autorizzazione ai propri principal con una policy IAM. Gli snapshot cifrati con chiavi AWS managed non possono essere condivisi affatto.","optionExplanations":["Corretto — Il proprietario della chiave deve consentire l'account esterno nella key policy prima che qualsiasi principal di quell'account possa usare la chiave.","Gli snapshot cifrati con una chiave AWS managed non possono essere condivisi con altri account perché la relativa key policy non può essere modificata.","La cifratura predefinita riguarda i nuovi volumi ma non concede l'autorizzazione a decifrare con la chiave di origine dello snapshot.","Corretto — L'uso cross-account della chiave richiede sia l'autorizzazione nella key policy sia una policy basata sull'identità nell'account esterno.","Le chiavi KMS non si condividono tramite AWS RAM; l'accesso cross-account viene concesso tramite la key policy."]},
  "1155": {"h":"fbaac50c","question":"Una piattaforma batch avvia job di breve durata. Ogni job necessita dell'autorizzazione a decifrare con una customer managed key AWS KMS solo mentre è in esecuzione, e l'autorizzazione deve essere rimossa al termine del job. Le autorizzazioni devono essere rilasciate in modo programmatico senza modificare la key policy per ogni job. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere alla key policy uno statement per il ruolo del job e rimuoverlo al termine del job.","Condividere la chiave KMS con il ruolo di ciascun job tramite una resource share AWS RAM.","Archiviare il materiale della chiave in chiaro in AWS Secrets Manager e lasciarlo leggere a ogni job.","Creare un grant KMS per il ruolo del job all'avvio e ritirarlo al termine del job."],"explanation":"I grant KMS sono pensati per la delega temporanea e programmatica delle autorizzazioni sulle chiavi e possono essere ritirati quando non servono più. Modificare la key policy per ogni job è tecnicamente possibile, ma è rischioso e non scala.","optionExplanations":["Modifiche continue alla key policy sono soggette a errori, rischiano di escludere gli amministratori e la policy ha un limite di dimensione.","AWS RAM non condivide chiavi KMS; l'accesso alle chiavi è controllato da key policy, policy IAM e grant.","Il materiale delle chiavi KMS non può essere esportato, e distribuire chiavi in chiaro vanificherebbe lo scopo di KMS.","Corretto — I grant delegano operazioni specifiche sulla chiave in modo programmatico e possono essere ritirati o revocati senza modificare la key policy."]},
  "1156": {"h":"d40c6842","question":"Un'applicazione deve cifrare file di diversi gigabyte con una chiave AWS KMS prima di inviarli a un archivio on-premises. Gli sviluppatori hanno scoperto che l'operazione encrypt di KMS rifiuta questi payload di grandi dimensioni. Quale soluzione dovrebbe raccomandare un solutions architect?","options":["Richiedere a KMS una data key, cifrare il file localmente e archiviare la data key cifrata insieme al file.","Suddividere ogni file in piccoli blocchi e cifrare ciascun blocco con una chiamata encrypt KMS separata.","Usare invece una chiave KMS asimmetrica, perché le chiavi asimmetriche accettano payload molto più grandi di quelle simmetriche.","Esportare il materiale della chiave KMS e usarlo nella libreria di cifratura dell'applicazione."],"explanation":"La envelope encryption è il pattern standard per grandi quantità di dati: KMS genera una data key, l'applicazione cifra localmente con la data key in chiaro e poi conserva solo la copia cifrata della data key accanto al testo cifrato. Suddividere i dati in molte chiamate KMS è lento, costoso e complesso.","optionExplanations":["Corretto — La envelope encryption usa una data key protetta da KMS per cifrare localmente grandi quantità di dati, aggirando il limite di payload di KMS.","Tecnicamente possibile, ma aggiunge latenza, molte richieste KMS e una logica di ricomposizione complessa.","Le chiavi KMS asimmetriche accettano payload ancora più piccoli e non sono adatte alla cifratura di dati in blocco.","Le chiavi KMS non lasciano mai KMS in chiaro, quindi il materiale della chiave non può essere esportato."]},
  "1157": {"h":"1be5bf23","question":"Un ente regolatore richiede che le chiavi di cifratura di un'azienda risiedano in hardware security module single-tenant controllati in modo esclusivo dall'azienda. L'azienda vuole comunque che Amazon S3 e Amazon EBS cifrino i dati tramite la loro integrazione nativa con AWS KMS. Quale soluzione soddisfa questi requisiti?","options":["Usare customer managed key KMS con materiale della chiave importato, generato nell'HSM dell'azienda.","Creare un custom key store KMS basato su un cluster AWS CloudHSM e creare le chiavi al suo interno.","Usare direttamente AWS CloudHSM e far chiamare il cluster a S3 ed EBS per ogni operazione di cifratura.","Usare customer managed key KMS con rotazione automatica abilitata e una key policy restrittiva."],"explanation":"Un custom key store KMS basato su CloudHSM mantiene il materiale delle chiavi in HSM dedicati al cliente, mentre i servizi AWS continuano a chiamare KMS come di consueto. Il materiale della chiave importato migliora il controllo sull'origine della chiave, ma le chiavi restano nella flotta di HSM condivisa di KMS.","optionExplanations":["Il materiale importato risiede comunque nella flotta di HSM multi-tenant di KMS, quindi non soddisfa il requisito single-tenant.","Corretto — Un custom key store basato su CloudHSM mantiene le chiavi in HSM single-tenant mentre i servizi le usano tramite KMS.","S3 ed EBS non possono usare direttamente CloudHSM; la loro cifratura lato server si integra solo con KMS.","Le chiavi KMS standard sono archiviate in HSM condivisi e gestiti da AWS, il che non soddisfa il controllo single-tenant."]},
  "1158": {"h":"d886f1e0","question":"Un secret in AWS Secrets Manager nell'account A è cifrato con la chiave predefinita aws/secretsmanager. Una funzione AWS Lambda nell'account B deve leggere il secret, e il suo execution role ha già una policy IAM che lo consente. Quale combinazione di passaggi completerà la configurazione? (Seleziona DUE)","options":["Replicare il secret nell'account B usando la replica dei secret di Secrets Manager.","Ricifrare il secret con una customer managed key KMS la cui key policy consenta al ruolo dell'account B di decifrare.","Modificare la key policy della chiave aws/secretsmanager per consentire il ruolo dell'account B.","Archiviare una copia del secret in Parameter Store nell'account B e aggiornarla a mano.","Associare al secret una resource-based policy che consenta al ruolo Lambda dell'account B di leggerlo."],"explanation":"L'accesso cross-account a un secret richiede una resource policy sul secret e una chiave KMS che l'account esterno possa usare. Poiché i secret cifrati con aws/secretsmanager non possono essere decifrati cross-account, il secret deve essere ricifrato con una customer managed key.","optionExplanations":["La replica dei secret copia i secret in altre Region dello stesso account, non in un altro account.","Corretto — La policy della chiave AWS managed non può essere modificata, quindi serve una customer managed key per la decifratura cross-account.","Le key policy delle chiavi AWS managed non possono essere modificate.","Crea un duplicato non gestito che si discosta dall'origine e interrompe la rotazione.","Corretto — La resource policy del secret deve concedere al principal esterno l'accesso al secret."]},
  "1159": {"h":"b9c70af7","question":"Un'azienda vuole che i dipendenti accedano ad Amazon WorkSpaces con le credenziali esistenti dell'Active Directory on-premises. L'azienda non vuole che alcun dato della directory venga archiviato o sincronizzato in AWS. Una Site-to-Site VPN collega già il data center al VPC. Quale soluzione soddisfa questi requisiti?","options":["Distribuire AWS Managed Microsoft AD nel VPC e creare un trust con il dominio on-premises.","Distribuire Simple AD e sincronizzarvi periodicamente gli utenti on-premises.","Distribuire AD Connector nel VPC per inoltrare le richieste di autenticazione all'AD on-premises.","Creare un user pool Amazon Cognito federato con l'AD on-premises tramite SAML."],"explanation":"AD Connector è un gateway di directory che inoltra l'autenticazione all'Active Directory on-premises, quindi nessun dato utente viene archiviato in AWS. Anche AWS Managed Microsoft AD funzionerebbe con un trust, ma crea una directory separata in AWS.","optionExplanations":["Managed Microsoft AD è una directory completa archiviata in AWS, cosa che l'azienda vuole evitare.","Simple AD non supporta trust né sincronizzazione con l'AD on-premises e archivia una propria directory in AWS.","Corretto — AD Connector è un proxy che reindirizza le richieste di accesso all'AD esistente senza memorizzare in cache né archiviare dati della directory.","WorkSpaces non usa Cognito per l'autenticazione degli utenti, e questo aggiunge un archivio utenti separato."]},
  "1160": {"h":"4992eed5","question":"Un'azienda sta spostando su Amazon EC2 applicazioni Windows che usano l'autenticazione Windows, come SQL Server. Le applicazioni necessitano di domain controller in AWS che continuino a funzionare se la connessione con il data center si interrompe, e gli utenti della foresta on-premises devono comunque potervi accedere. Quale soluzione soddisfa questi requisiti?","options":["Distribuire AD Connector e aggiungere tramite esso le istanze EC2 al dominio on-premises.","Distribuire Simple AD e ricreare a mano al suo interno gli utenti e i gruppi on-premises.","Usare IAM Identity Center con l'AD on-premises come identity source per le istanze.","Distribuire AWS Managed Microsoft AD e creare un forest trust con il dominio on-premises."],"explanation":"AWS Managed Microsoft AD fornisce domain controller ad alta disponibilità all'interno di AWS, quindi i workload aggiunti al dominio continuano ad autenticarsi durante un'interruzione del collegamento, e un forest trust consente l'accesso agli utenti on-premises. AD Connector fa solo da proxy verso i controller on-premises e quindi dipende dalla connessione.","optionExplanations":["AD Connector dipende dai domain controller on-premises, quindi l'autenticazione fallisce quando la connessione è interrotta.","Simple AD non supporta i trust, quindi gli utenti on-premises non potrebbero usare le loro identità esistenti.","IAM Identity Center fornisce l'accesso ad account e applicazioni AWS, non domain controller per l'autenticazione Windows.","Corretto — Managed Microsoft AD esegue veri domain controller in AWS e un trust consente agli utenti on-premises di accedere alle applicazioni."]},
  "1161": {"h":"f7d570df","question":"Un'app mobile autentica gli utenti con un user pool Amazon Cognito. Gli utenti devono caricare foto direttamente su Amazon S3, ciascuno in un prefisso accessibile solo a quell'utente, senza far passare i caricamenti da un backend. Nell'app non possono essere archiviate credenziali AWS a lungo termine. Quale soluzione soddisfa questi requisiti?","options":["Usare un identity pool Cognito per ottenere credenziali temporanee limitate dall'identity ID nella policy.","Incorporare nell'app le access key di un utente IAM e limitarle con una bucket policy per prefisso.","Configurare la bucket policy S3 affinché accetti direttamente i token del user pool Cognito come identità del chiamante.","Generare alla registrazione un presigned URL di lunga durata per utente e archiviarlo nell'app."],"explanation":"Gli identity pool Cognito forniscono credenziali AWS temporanee agli utenti autenticati, e la policy IAM può usare la variabile dell'identity ID Cognito per limitare ogni utente al proprio prefisso S3. I soli user pool emettono soltanto token; S3 non può autorizzare richieste con essi.","optionExplanations":["Corretto — Gli identity pool scambiano i token del user pool con credenziali AWS temporanee, e una variabile di policy limita ogni utente al proprio prefisso.","Incorporare chiavi a lungo termine in un'app mobile viola il requisito ed espone le chiavi al rischio di estrazione.","S3 non accetta JWT di Cognito per l'autorizzazione; le richieste devono essere firmate con credenziali AWS.","I presigned URL scadono dopo un tempo limitato e concedono l'accesso a una singola chiave di oggetto, non a un intero prefisso."]},
  "1162": {"h":"e57b2f4e","question":"Un'azienda espone una REST API tramite Amazon API Gateway. I client inviano bearer token opachi emessi da un sistema di identità interno legacy, e i token possono essere validati solo chiamando l'endpoint di introspection di tale sistema. Le richieste non valide devono essere rifiutate prima di raggiungere il backend e i risultati della validazione devono essere memorizzati in cache. Quale soluzione soddisfa questi requisiti?","options":["Configurare un authorizer basato su user pool Amazon Cognito per i metodi dell'API.","Usare un Lambda authorizer che chiami l'endpoint di introspection e memorizzi in cache i risultati.","Richiedere API key sui metodi e associarle a usage plan per ciascun client.","Abilitare l'autorizzazione IAM in modo che i client debbano firmare le richieste con Signature Version 4."],"explanation":"Un Lambda authorizer esegue codice personalizzato per validare qualsiasi formato di token e restituisce una policy IAM che API Gateway può memorizzare in cache per un TTL configurabile. Un authorizer Cognito comprende solo i token del proprio user pool.","optionExplanations":["Un authorizer Cognito valida solo i token emessi dal user pool Cognito, non token opachi provenienti da un altro sistema.","Corretto — Un Lambda authorizer può eseguire logica di validazione personalizzata verso qualsiasi sistema di identità, e API Gateway ne memorizza in cache il risultato.","Le API key identificano i client per throttling e quote ma non sono un meccanismo di autenticazione.","I client possiedono token del sistema legacy, non credenziali AWS, quindi non potrebbero firmare le richieste."]},
  "1163": {"h":"666eba4e","question":"Microservizi in diversi account AWS dell'organizzazione di un'azienda chiamano una REST API interna in Amazon API Gateway ospitata in un account centrale. Le chiamate devono essere autenticate con i ruoli IAM esistenti dei chiamanti, e l'azienda non vuole gestire token o secret condivisi. Quale soluzione soddisfa questi requisiti?","options":["Creare un Lambda authorizer che verifichi un header con un secret condiviso inviato da ogni microservizio.","Emettere API key per ciascun account e richiederle su ogni metodo dell'API.","Usare l'autorizzazione IAM con una resource policy che consenta i principal dell'organizzazione.","Usare un user pool Cognito con client credentials per ogni microservizio."],"explanation":"Con l'autorizzazione IAM, i chiamanti firmano le richieste con SigV4 usando le credenziali dei propri ruoli esistenti, e una resource policy dell'API può consentire principal di altri account, ad esempio in base all'ID dell'organizzazione. Le alternative richiedono tutte la gestione di secret, chiavi o token.","optionExplanations":["Richiede la distribuzione e la rotazione di secret condivisi, cosa che l'azienda vuole evitare.","Le API key non sono un meccanismo di autenticazione e devono essere distribuite e ruotate.","Corretto — I chiamanti firmano le richieste con le credenziali del proprio ruolo, e la resource policy concede l'accesso cross-account ai principal dell'organizzazione.","Richiede la gestione di app client, secret e recupero dei token invece di usare i ruoli IAM esistenti."]},
  "1164": {"h":"fefe3d7e","question":"Un'azienda ha una REST API interna in Amazon API Gateway. L'API deve essere raggiungibile solo dai VPC dell'azienda, e il traffico non deve attraversare la rete internet pubblica. Quale soluzione soddisfa questi requisiti?","options":["Usare un'API Regional con un IP set AWS WAF che consenta solo gli indirizzi dei NAT gateway dei VPC.","Usare un'API edge-optimized con restrizioni geografiche CloudFront limitate al paese dell'azienda.","Usare un'API Regional e associarle un security group che consenta solo i range CIDR dei VPC.","Distribuirla come private REST API accessibile tramite un interface VPC endpoint execute-api."],"explanation":"Un endpoint di API privata è accessibile solo tramite un interface endpoint execute-api, mantenendo il traffico sulla rete AWS, e la sua resource policy può consentire solo VPC o endpoint specifici. Una allow list di IP su un'API Regional espone comunque un endpoint pubblico.","optionExplanations":["Il traffico passa comunque sull'endpoint pubblico attraverso i NAT gateway, quindi attraversa internet.","La restrizione geografica non limita l'accesso ai VPC e l'API resta raggiungibile pubblicamente.","Gli endpoint pubblici di API Gateway non supportano i security group.","Corretto — Le API private sono raggiungibili solo tramite interface VPC endpoint, e la resource policy limita quali endpoint possono chiamarle."]},
  "1165": {"h":"51697f99","question":"Una piattaforma video trasmette contenuti HLS tramite Amazon CloudFront. Ogni video è composto da migliaia di file di segmento. Solo gli abbonati paganti che hanno effettuato l'accesso possono guardare, e l'azienda non vuole cambiare gli URL dei singoli file di segmento. Quale soluzione soddisfa questi requisiti?","options":["Emettere signed cookie CloudFront agli abbonati dopo l'accesso.","Generare un signed URL CloudFront per ogni file di segmento quando il player lo richiede.","Generare presigned URL Amazon S3 per i segmenti e bypassare CloudFront.","Configurare la origin access control tra CloudFront e il bucket S3."],"explanation":"I signed cookie CloudFront sono consigliati quando gli spettatori devono accedere a molti file, come tutti i segmenti di uno stream, senza cambiare gli URL. I signed URL sono adatti ai singoli file e sarebbero poco pratici per migliaia di segmenti.","optionExplanations":["Corretto — I signed cookie concedono l'accesso a molti file riservati contemporaneamente senza cambiarne gli URL.","Richiederebbe un signed URL univoco per ciascuno delle migliaia di segmenti, cambiando l'URL di ogni segmento.","Perde il caching di CloudFront e richiede comunque di cambiare l'URL di ogni segmento.","OAC limita l'origine S3 a CloudFront ma non autentica gli spettatori."]},
  "1166": {"h":"d591741f","question":"Un'azienda media distribuisce contenuti da Amazon S3 tramite Amazon CloudFront. Gli accordi di licenza vietano di servire i contenuti agli spettatori di determinati paesi. Quale soluzione soddisfa questo requisito con il MINOR onere operativo?","options":["Usare una funzione Lambda@Edge che confronti gli indirizzi IP degli spettatori con un database di geolocalizzazione di terze parti.","Abilitare le restrizioni geografiche di CloudFront con una block list dei paesi vietati.","Usare il routing di geolocalizzazione di Route 53 che non restituisca risposta alle query DNS da quei paesi.","Aggiungere una bucket policy S3 che neghi le richieste dai range IP dei paesi vietati."],"explanation":"La restrizione geografica integrata di CloudFront usa un database GeoIP per consentire o bloccare paesi senza codice personalizzato. Lambda@Edge potrebbe implementare lo stesso controllo, ma aggiunge codice e manutenzione dei dati.","optionExplanations":["Funziona ma richiede codice personalizzato e la manutenzione di un dataset di geolocalizzazione, aumentando l'onere.","Corretto — La restrizione geografica di CloudFront blocca nativamente gli spettatori per paese senza codice da mantenere.","La posizione DNS riflette il resolver, non lo spettatore, e gli spettatori possono aggirarla con altri resolver.","Le richieste raggiungono S3 da CloudFront, non dagli spettatori, quindi le condizioni sugli IP degli spettatori nel bucket sono inefficaci."]},
  "1167": {"h":"a5de42ef","question":"Un'applicazione web usa Amazon CloudFront davanti a un Application Load Balancer esposto su internet. Alcuni attaccanti aggirano CloudFront inviando richieste direttamente all'ALB. L'ALB deve accettare traffico solo da CloudFront, e gli indirizzi consentiti devono restare aggiornati automaticamente. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Usare voci di Network ACL con i range IP di CloudFront aggiornate da una funzione Lambda pianificata.","Sottoscrivere AWS Shield Advanced e aggiungere l'ALB come risorsa protetta.","Consentire il traffico in ingresso all'ALB solo dalla AWS managed prefix list dei server origin-facing di CloudFront.","Associare all'ALB una regola geo match AWS WAF che consenta solo i paesi con edge location CloudFront."],"explanation":"AWS pubblica una managed prefix list degli indirizzi origin-facing di CloudFront che può essere referenziata in un security group, così solo CloudFront può raggiungere l'ALB e AWS mantiene la lista aggiornata. Una NACL aggiornata da Lambda risolve lo stesso problema con un onere molto maggiore.","optionExplanations":["Richiede codice personalizzato, e i limiti sulle regole delle NACL rendono difficile mantenere l'ampia e mutevole lista di range di CloudFront.","Shield Advanced mitiga gli attacchi DDoS ma non limita quali client possono raggiungere l'ALB.","Corretto — La managed prefix list è mantenuta da AWS, quindi la regola del security group resta aggiornata senza lavoro personalizzato.","Gli attaccanti in quei paesi possono comunque raggiungere direttamente l'ALB, quindi l'aggiramento resta possibile."]},
  "1168": {"h":"996d5e7b","question":"Un'azienda deve ispezionare tutto il traffico in uscita dai propri VPC alla ricerca di firme di minacce note e deve consentire l'HTTPS in uscita solo verso un elenco approvato di nomi di dominio. Quale soluzione soddisfa questi requisiti?","options":["Configurare regole egress dei security group che consentano la porta 443 solo verso le destinazioni approvate.","Usare Route 53 Resolver DNS Firewall per consentire la risoluzione DNS solo per i domini approvati.","Aggiungere regole di Network ACL che neghino il traffico in uscita verso gli indirizzi IP di host malevoli noti.","Instradare il traffico in uscita tramite AWS Network Firewall con regole IPS e liste di domini."],"explanation":"AWS Network Firewall è un firewall stateful gestito con intrusion prevention e filtraggio basato sui domini, distribuito in subnet dedicate con un routing che vi fa passare il traffico in uscita. DNS Firewall controlla la risoluzione dei nomi ma non può ispezionare il traffico né bloccare connessioni effettuate direttamente verso indirizzi IP.","optionExplanations":["I security group filtrano per IP e porta, non possono riconoscere nomi di dominio e non ispezionano il traffico alla ricerca di minacce.","DNS Firewall filtra solo le query DNS; non ispeziona il traffico e può essere aggirato connettendosi direttamente agli indirizzi IP.","Le NACL sono filtri IP stateless che non possono riconoscere domini né ispezionare i pacchetti alla ricerca di firme.","Corretto — Network Firewall fornisce ispezione stateful, firme IPS compatibili con Suricata e allow list di domini per il traffico in uscita."]},
  "1169": {"h":"c6022bca","question":"Un team di sicurezza vuole impedire ai workload di molti VPC di risolvere nomi di dominio associati a malware e all'esfiltrazione di dati via DNS. Il team vuole usare liste di minacce mantenute da AWS anziché curarne di proprie. Quale soluzione soddisfa questi requisiti?","options":["Usare Route 53 Resolver DNS Firewall con le AWS managed domain list sui VPC.","Affidarsi ai finding DNS di Amazon GuardDuty per identificare le query verso domini malevoli.","Aggiungere regole di Network ACL che neghino il traffico verso gli indirizzi IP dei domini malevoli noti.","Creare hosted zone private Route 53 per ogni dominio malevolo che puntino a un sinkhole."],"explanation":"Route 53 Resolver DNS Firewall filtra le query DNS in uscita dai VPC, e le AWS managed domain list coprono malware e altre minacce note. GuardDuty è un servizio di rilevamento; segnala tali query ma non le impedisce.","optionExplanations":["Corretto — DNS Firewall blocca le query dai VPC verso i domini presenti nelle liste di minacce gestite da AWS.","GuardDuty rileva e segnala attività DNS sospette ma non blocca la risoluzione.","Gli indirizzi IP dei domini cambiano spesso, e il team dovrebbe mantenere le liste da solo.","Richiede di curare e creare manualmente le zone e non usa liste di minacce gestite da AWS."]},
  "1170": {"h":"097a82d3","question":"Un auditor richiede un registro di ogni tentativo di connessione in ingresso rifiutato verso le istanze Amazon EC2 di un VPC, inclusi indirizzo IP e porta di origine. I record devono essere archiviati in Amazon S3 per analisi successive. Quale soluzione soddisfa questi requisiti?","options":["Abilitare i data event di AWS CloudTrail per le istanze EC2 e consegnarli su S3.","Creare VPC Flow Logs che catturino il traffico rifiutato e pubblicarli in un bucket S3.","Configurare VPC Traffic Mirroring per tutte le istanze e archiviare i pacchetti catturati su S3.","Esportare i finding di Amazon GuardDuty su S3 tramite Amazon EventBridge."],"explanation":"I VPC Flow Logs catturano i metadati del traffico IP, inclusa l'azione REJECT, e possono essere filtrati sul traffico rifiutato e pubblicati su S3. Traffic Mirroring cattura il contenuto dei pacchetti, cosa non necessaria per questo requisito di audit.","optionExplanations":["CloudTrail registra le chiamate API, non i tentativi di connessione di rete verso le istanze.","Corretto — I flow log registrano indirizzi di origine e destinazione, porte e l'azione di accettazione o rifiuto, e possono essere consegnati su S3.","Cattura il payload completo dei pacchetti, il che comporta molti più dati e lavoro del necessario per registrare le connessioni rifiutate.","GuardDuty segnala minacce sospette, non un registro completo di ogni connessione rifiutata."]},
  "1171": {"h":"624b5aa8","question":"Un team di sicurezza usa un'appliance di intrusion detection di terze parti che deve analizzare il payload completo dei pacchetti provenienti dalle istanze Amazon EC2 di produzione. Il team non può installare agent sulle istanze. Quale soluzione soddisfa questi requisiti?","options":["Abilitare VPC Flow Logs sulle subnet e inviarli in streaming alle appliance.","Abilitare Amazon GuardDuty Runtime Monitoring e inoltrarne i finding alle appliance.","Usare VPC Traffic Mirroring per inviare il traffico delle istanze alle appliance dietro un NLB.","Attivare gli access log di Elastic Load Balancing e inviarli alle appliance."],"explanation":"VPC Traffic Mirroring copia i pacchetti dalle ENI verso una destinazione come un NLB posto davanti alle appliance di sicurezza, consentendo la deep packet inspection senza agent sugli host. I flow log sono utili per l'audit ma non contengono payload.","optionExplanations":["I flow log contengono solo i metadati delle connessioni, non il payload dei pacchetti.","Runtime Monitoring usa un agent e produce finding, non copie grezze dei pacchetti.","Corretto — Traffic Mirroring copia i pacchetti completi dalle elastic network interface verso una destinazione di monitoraggio senza agent.","Gli access log descrivono le richieste al load balancer e non includono i pacchetti completi delle istanze."]},
  "1172": {"h":"17891bcb","question":"Un'azienda con 30 account AWS in AWS Organizations vuole controlli continui e automatizzati rispetto al CIS AWS Foundations Benchmark e agli AWS Foundational Security Best Practices. I finding di tutti gli account devono essere aggregati in un account di sicurezza centrale. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Eseguire i controlli di AWS Trusted Advisor in ogni account ed esportare i risultati ogni settimana.","Scrivere regole personalizzate AWS Config per ogni controllo del benchmark e distribuirle con StackSets.","Attivare Amazon Inspector in ogni account e aggregare i finding nell'account di sicurezza.","Abilitare AWS Security Hub con entrambi gli standard tramite un delegated administrator."],"explanation":"Security Hub esegue controlli gestiti per il CIS benchmark e per gli AWS Foundational Security Best Practices, e un delegated administrator può abilitarlo per tutti gli account membri e aggregarne i finding. Scrivere regole Config personalizzate replicherebbe questa funzionalità con molto più lavoro.","optionExplanations":["Trusted Advisor non implementa questi standard e non offre un'aggregazione a livello di organizzazione dei finding di sicurezza.","Ricostruire controlli già esistenti come standard gestiti aggiunge un grande lavoro di sviluppo e manutenzione.","Inspector analizza i workload alla ricerca di vulnerabilità software, non la configurazione degli account rispetto a questi benchmark.","Corretto — Security Hub fornisce entrambi gli standard come controlli gestiti e aggrega i finding centralmente in tutta l'organizzazione."]},
  "1173": {"h":"b5a77a6a","question":"Un'azienda deve rilevare qualsiasi security group che consenta SSH da 0.0.0.0/0 e rimuovere automaticamente quella regola entro pochi minuti. Le altre modifiche ai security group devono restare consentite. Quale soluzione soddisfa questi requisiti?","options":["Usare una regola AWS Config con remediation automatica tramite un runbook SSM Automation.","Abilitare Amazon GuardDuty e rivedere ogni giorno i finding sui tentativi di brute force SSH.","Interrogare una volta al giorno i log di AWS CloudTrail con Amazon Athena per trovare le modifiche alle regole.","Associare a ogni utente IAM una policy IAM che neghi tutte le modifiche alle regole in ingresso dei security group."],"explanation":"AWS Config può valutare i security group a ogni modifica della configurazione e invocare un runbook SSM Automation per correggere automaticamente le risorse non conformi. Negare tutte le modifiche in ingresso eviterebbe il problema, ma bloccherebbe anche il lavoro legittimo.","optionExplanations":["Corretto — Config valuta le modifiche nel momento in cui avvengono e il runbook di remediation rimuove automaticamente la regola incriminata.","GuardDuty rileva attacchi, non regole configurate in modo errato, e una revisione manuale giornaliera non corregge entro pochi minuti.","Una query giornaliera non è né quasi in tempo reale né una remediation automatica.","Blocca ogni modifica legittima ai security group, che l'azienda deve invece continuare a consentire."]},
  "1174": {"h":"ffba2675","question":"Un'azienda deve garantire che ogni Application Load Balancer e distribuzione CloudFront in tutti gli account della propria organizzazione, inclusi gli account futuri, abbia una web ACL AWS WAF di base. I team applicativi devono comunque poter aggiungere regole proprie. Quale soluzione soddisfa questi requisiti?","options":["Distribuire la web ACL in ogni account con CloudFormation StackSets e chiedere ai team di associarla.","Creare una policy AWS WAF di AWS Firewall Manager per l'organizzazione con remediation automatica.","Associare una SCP che neghi la creazione di load balancer se non è associata una web ACL WAF.","Sottoscrivere AWS Shield Advanced per ogni account e abilitarlo per tutti gli ALB."],"explanation":"Firewall Manager applica centralmente le policy WAF in tutta l'organizzazione, proteggendo automaticamente nuovi account e risorse, e le sue policy supportano rule group iniziali e finali in modo che i team possano aggiungere le proprie regole nel mezzo. StackSets può distribuire la ACL ma non garantisce che venga associata.","optionExplanations":["Si affida ai team per associare manualmente la web ACL, quindi le nuove risorse potrebbero restare non protette.","Corretto — Firewall Manager applica i rule group di base alle risorse in ambito in tutti gli account, inclusi quelli nuovi, mentre i team aggiungono le proprie regole.","Le SCP non possono verificare se una web ACL è associata, né possono associarne una.","Shield Advanced fornisce protezione DDoS ma non distribuisce un set di regole WAF di base su ogni risorsa."]},
  "1175": {"h":"74842b26","question":"Amazon GuardDuty ha segnalato un'attività API insolita da parte di un ruolo IAM. Gli analisti di sicurezza devono indagare rapidamente sull'attività correlata del ruolo nelle ultime settimane e visualizzare con quali indirizzi IP e risorse ha interagito. Il team non vuole costruire pipeline di analisi dei log. Quale soluzione soddisfa questi requisiti?","options":["Interrogare i log di AWS CloudTrail in Amazon S3 con Amazon Athena e costruire dashboard.","Usare Amazon Macie per analizzare le risorse a cui ha avuto accesso il ruolo IAM.","Usare Amazon Detective per indagare sul finding con il suo behavior graph.","Usare AWS Security Hub per visualizzare il finding insieme ai finding correlati."],"explanation":"Amazon Detective acquisisce automaticamente i dati dei log e costruisce un behavior graph che aiuta gli analisti a ricostruire nel tempo l'attività di un'entità, i suoi indirizzi IP e i finding correlati. Athena su CloudTrail può rispondere alle stesse domande, ma richiede di costruire l'analisi da sé.","optionExplanations":["Possibile, ma richiede di costruire tabelle, query e visualizzazioni, cosa che il team vuole evitare.","Macie individua dati sensibili in S3; non indaga sul comportamento delle entità.","Corretto — Detective costruisce automaticamente un behavior graph a partire dai dati di CloudTrail, VPC Flow Logs e GuardDuty per le indagini.","Security Hub aggrega i finding ma non fornisce un'indagine interattiva sul comportamento."]},
  "1176": {"h":"aefb8bd3","question":"Un'azienda deve registrare ogni lettura di oggetti in un bucket Amazon S3 sensibile, incluso il principal IAM che ha effettuato ciascuna richiesta. Gli auditor devono poter eseguire query SQL su diversi anni di questo storico. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Creare un trail CloudTrail che registri solo i management event e interrogarlo con Athena.","Abilitare il server access logging di S3 e creare tabelle Amazon Athena sui file di log.","Abilitare Amazon Macie sul bucket ed esportarne i finding su Amazon S3.","Usare un event data store di CloudTrail Lake che raccolga i data event S3 del bucket."],"explanation":"Le letture di oggetti sono data event di CloudTrail, e CloudTrail Lake archivia gli eventi in un event data store gestito che può essere interrogato in SQL per anni. I server access log con Athena possono funzionare, ma richiedono più configurazione e offrono una consegna best-effort.","optionExplanations":["I management event non includono le letture a livello di oggetto come GetObject.","Funziona ma richiede di gestire il parsing dei log e le tabelle, e i server access log vengono consegnati in modalità best-effort.","Macie segnala finding sui dati sensibili, non un registro di ogni lettura di oggetti.","Corretto — CloudTrail Lake cattura i data event a livello di oggetto, li conserva a lungo termine e supporta nativamente le query SQL."]},
  "1177": {"h":"a324dd9a","question":"Un'azienda vuole che i dipendenti da remoto raggiungano applicazioni web interne ospitate in un VPC senza usare una VPN. Ogni richiesta deve essere valutata in base all'identità dell'utente in IAM Identity Center e alla security posture del dispositivo fornita da un provider di gestione dei dispositivi di terze parti. Quale soluzione soddisfa questi requisiti?","options":["Distribuire AWS Verified Access con trust provider di identità e di dispositivo.","Distribuire AWS Client VPN con autenticazione Active Directory per i dipendenti.","Collocare le applicazioni dietro un ALB pubblico che autentichi gli utenti con Amazon Cognito.","Configurare una AWS Site-to-Site VPN dal router domestico di ciascun dipendente al VPC."],"explanation":"AWS Verified Access fornisce un accesso zero-trust alle applicazioni valutando ogni richiesta rispetto a policy che usano trust provider di identità e di dispositivo, senza VPN. Cognito su un ALB copre solo l'identità, non la posture del dispositivo.","optionExplanations":["Corretto — Verified Access valuta ogni richiesta in base all'identità e alla posture del dispositivo senza VPN.","Client VPN è una VPN e non valuta la posture del dispositivo per ogni richiesta applicativa.","Autentica gli utenti ma non può valutare la posture del dispositivo fornita dal provider di gestione dei dispositivi.","Usa tunnel VPN, è poco pratica per i singoli dipendenti e non valuta né l'identità né la posture del dispositivo."]},
  "1178": {"h":"37bf8fac","question":"I server di un data center on-premises eseguono script che caricano file su Amazon S3 usando le access key di un utente IAM. L'azienda gestisce una certificate authority aziendale che emette certificati per questi server e vuole eliminare le credenziali AWS a lungo termine. Quale soluzione soddisfa questi requisiti?","options":["Archiviare le access key in AWS Secrets Manager e ruotarle ogni 30 giorni.","Usare IAM Roles Anywhere, con la CA aziendale come trust anchor.","Creare un utente IAM Identity Center per ogni server e usarne l'accesso negli script.","Configurare un identity pool Amazon Cognito con accesso non autenticato per gli script."],"explanation":"IAM Roles Anywhere consente ai workload esterni ad AWS di usare certificati emessi da una CA registrata per ottenere credenziali temporanee di un ruolo IAM, eliminando la necessità di access key. Ruotare le chiavi in Secrets Manager riduce il rischio ma mantiene credenziali a lungo termine.","optionExplanations":["Le chiavi restano credenziali a lungo termine di un utente IAM, che l'azienda vuole eliminare.","Corretto — Roles Anywhere scambia certificati X.509 emessi da una CA attendibile con credenziali temporanee del ruolo.","IAM Identity Center è pensato per l'accesso del personale umano, non per l'autenticazione di macchine.","Le identità non autenticate permetterebbero a chiunque di ottenere credenziali e non sono adatte ai workload server."]},
  "1179": {"h":"7d9c89fc","question":"Un topic Amazon SNS consegna messaggi a una coda Amazon SQS. Dopo che l'azienda ha abilitato la cifratura lato server sulla coda con una customer managed key AWS KMS, i messaggi hanno smesso di arrivare nella coda. Quale soluzione risolverà il problema?","options":["Passare la cifratura della coda alla chiave AWS managed per Amazon SQS.","Abilitare la cifratura lato server sul topic SNS con la stessa customer managed key.","Aggiornare la key policy KMS per consentire al service principal di SNS di usare la chiave.","Aggiungere alla access policy della coda uno statement sqs:SendMessage per il topic SNS."],"explanation":"Quando una coda SQS è cifrata con una customer managed key, il servizio che pubblica (qui SNS) deve essere autorizzato nella key policy a usare la chiave. La chiave AWS managed di SQS non può essere usata a questo scopo perché la sua policy non può essere modificata.","optionExplanations":["SNS non può usare la chiave AWS managed di SQS perché la sua key policy non può essere modificata per consentire il servizio SNS.","Cifrare il topic non concede a SNS l'autorizzazione a usare la chiave della coda quando invia i messaggi.","Corretto — SNS ha bisogno dell'autorizzazione a generare data key e a decifrare con la chiave della coda per inviare messaggi cifrati.","La consegna funzionava prima della cifratura, quindi la policy della coda consente già SNS; l'autorizzazione mancante riguarda la chiave."]},
  "1180": {"h":"6d5fc0d8","question":"Un gioco mobile archivia i dati dei giocatori in una tabella Amazon DynamoDB con l'ID del giocatore come partition key. I giocatori accedono direttamente alla tabella con credenziali temporanee ottenute da un identity pool Amazon Cognito. Ogni giocatore deve poter leggere e scrivere solo gli item che gli appartengono. Quale soluzione soddisfa questi requisiti?","options":["Creare una tabella DynamoDB separata per ogni giocatore e concederne l'accesso per nome.","Cifrare gli item di ciascun giocatore con una customer managed key KMS diversa.","Abilitare DynamoDB Streams e annullare le scritture effettuate sugli item di altri giocatori.","Limitare dynamodb:LeadingKeys all'identity ID del giocatore nella policy IAM."],"explanation":"Il fine-grained access control di DynamoDB usa condition key IAM come dynamodb:LeadingKeys con la variabile dell'identità Cognito, così ogni utente può accedere solo agli item con partition key corrispondente. Tabelle separate per utente funzionerebbero in linea di principio, ma sono ingestibili.","optionExplanations":["Non scala su molti giocatori e aggiunge un grande onere operativo.","La cifratura non impedisce ai giocatori di leggere o sovrascrivere gli item di altri giocatori.","Rileva le violazioni a posteriori invece di impedire letture e scritture non autorizzate.","Corretto — Il fine-grained access control con la condizione dynamodb:LeadingKeys limita ogni giocatore agli item con la propria partition key."]},
  "1181": {"h":"fcf9d18e","question":"Alcune istanze Amazon EC2 montano un file system Amazon EFS esistente creato senza cifratura. Una nuova policy richiede che i dati siano cifrati at rest e in transito. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Creare un nuovo file system EFS con cifratura at rest abilitata e migrare i dati con AWS DataSync.","Abilitare la cifratura at rest sul file system esistente dalle sue impostazioni.","Montare il file system sulle istanze usando l'EFS mount helper con l'opzione TLS.","Abilitare la cifratura sui volumi root EBS delle istanze che montano il file system.","Limitare il security group del mount target EFS al solo traffico NFS proveniente dalle istanze."],"explanation":"La cifratura at rest di EFS è un'impostazione definita alla creazione, quindi un file system non cifrato deve essere sostituito e i dati migrati, ad esempio con DataSync. La cifratura in transito si abilita per singolo mount usando l'EFS mount helper con TLS.","optionExplanations":["Corretto — La cifratura at rest può essere abilitata solo alla creazione di un file system EFS, quindi i dati devono essere spostati su uno nuovo.","La cifratura at rest di EFS non può essere abilitata su un file system esistente.","Corretto — Il mount helper con TLS cifra il traffico NFS tra le istanze ed EFS.","Cifrare i volumi EBS non cifra i dati archiviati in EFS né il traffico verso di esso.","Limita l'accesso di rete ma non cifra i dati né at rest né in transito."]},
  "1182": {"h":"8b1bfa15","question":"Un'applicazione su Amazon EC2 si connette a un database Amazon RDS for MySQL. Il team di sicurezza vuole eliminare tutte le password di database archiviate. L'applicazione deve autenticarsi al database con token di breve durata derivati dal suo instance role esistente. Quale soluzione soddisfa questi requisiti?","options":["Abilitare l'autenticazione IAM al database e lasciare che l'instance role generi i token di autenticazione.","Archiviare la password in AWS Secrets Manager e abilitare la rotazione automatica.","Archiviare la password come parametro SecureString in Systems Manager Parameter Store.","Richiedere connessioni SSL alla DB instance e mantenere la password nella configurazione dell'applicazione."],"explanation":"Con l'autenticazione IAM al database, l'applicazione usa il proprio ruolo IAM per generare un token di breve durata che sostituisce la password per MySQL e PostgreSQL. La rotazione di Secrets Manager migliora la gestione delle password ma usa comunque password archiviate.","optionExplanations":["Corretto — L'autenticazione IAM al database usa token di breve durata generati dalle credenziali IAM al posto delle password.","La password viene comunque archiviata e usata, anche se ruotata, quindi non soddisfa il requisito.","Si basa comunque su una password di database archiviata, solo cifrata.","Cifra le connessioni ma mantiene una password archiviata, che deve essere eliminata."]},
  "1183": {"h":"5a576b8d","question":"Un'applicazione su Amazon EC2 elabora dati di carte di pagamento. I dati devono essere decifrati ed elaborati in un ambiente isolato a cui non possano accedere nemmeno gli amministratori con accesso root all'istanza, e AWS KMS deve rilasciare la chiave solo a quell'ambiente verificato. Quale soluzione soddisfa questi requisiti?","options":["Eseguire l'applicazione su un EC2 Dedicated Host in modo che nessun altro cliente condivida l'hardware.","Elaborare i dati in un AWS Nitro Enclave e usare condizioni nella key policy KMS basate sull'attestazione dell'enclave.","Archiviare la chiave in AWS CloudHSM e decifrare i dati sull'istanza con il client HSM.","Spostare l'elaborazione su un'istanza separata in una subnet isolata con un security group restrittivo."],"explanation":"AWS Nitro Enclaves forniscono ambienti di calcolo isolati privi di accesso interattivo, anche per gli utenti root dell'istanza padre, e KMS supporta condizioni basate sull'attestazione in modo che solo un enclave verificato possa decifrare. Hardware dedicato o HSM non isolano i dati dagli amministratori dell'istanza stessa.","optionExplanations":["Isola l'hardware dagli altri clienti ma non dagli amministratori con accesso root all'istanza.","Corretto — I Nitro Enclaves sono isolati dall'istanza padre, e KMS può verificare l'attestazione prima di rilasciare le chiavi.","I dati decifrati restano accessibili sull'istanza agli utenti con accesso root.","L'isolamento di rete non impedisce agli amministratori con accesso root a quell'istanza di leggere i dati."]},
  "1184": {"h":"55dfe3fb","question":"Un account di networking centrale possiede i VPC, il transit gateway e l'uscita verso internet dell'azienda. Gli account applicativi devono distribuire i workload in subnet gestite centralmente, e i loro amministratori non devono poter creare VPC o internet gateway propri. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Creare connessioni VPC peering dai VPC di networking a un VPC in ciascun account applicativo.","Associare un IAM permissions boundary ai ruoli amministratore di ciascun account applicativo.","Condividere le subnet dall'account di networking con gli account applicativi usando AWS RAM.","Creare un transit gateway attachment per il VPC proprio di ciascun account applicativo.","Associare all'OU degli account applicativi una SCP che neghi la creazione di VPC e internet gateway."],"explanation":"La condivisione di VPC tramite AWS RAM consente agli account applicativi di distribuire risorse in subnet di proprietà dell'account di networking, e le SCP forniscono guardrail che gli amministratori degli account non possono aggirare. I permissions boundary sono gestiti all'interno dell'account e possono essere modificati dai suoi amministratori.","optionExplanations":["Richiede che ogni account applicativo possieda un VPC, in contrasto con la proprietà centralizzata della rete.","Gli amministratori dell'account potrebbero rimuovere o modificare il boundary, quindi non è un guardrail affidabile.","Corretto — La condivisione di VPC consente agli account partecipanti di avviare risorse in subnet di proprietà centrale.","Presuppone che ogni account crei un proprio VPC, cosa che l'azienda vuole impedire.","Corretto — Le SCP si applicano a tutti i principal degli account membri, inclusi gli amministratori."]},
  "1185": {"h":"602393df","question":"Un'azienda con molti account AWS vuole standardizzare la chiave di tag CostCenter, incluse le maiuscole/minuscole e i valori consentiti. Le operazioni di tagging non conformi su tipi di risorse selezionati devono essere impedite, e l'azienda vuole report di conformità per tutta l'organizzazione. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Usare la regola gestita required-tags di AWS Config in ogni account e rivederne i finding.","Scrivere una SCP che elenchi ogni valore consentito di CostCenter nelle condizioni sui tag della richiesta.","Creare una tag policy di AWS Organizations con l'enforcement abilitato per i tipi di risorse selezionati.","Far correggere i tag ogni mese agli amministratori usando il Tag Editor in ogni account."],"explanation":"Le tag policy di Organizations definiscono chiavi di tag standard, maiuscole/minuscole e valori consentiti, possono bloccare le operazioni di tagging non conformi per i tipi di risorse scelti e generano report di conformità tra gli account. Una SCP potrebbe limitare i valori, ma è più difficile da mantenere e non fornisce report di conformità.","optionExplanations":["Config rileva i tag mancanti ma non impedisce il tagging non conforme né standardizza le maiuscole/minuscole.","Possibile in alcuni casi, ma più difficile da mantenere e senza report di conformità a livello di organizzazione.","Corretto — Le tag policy standardizzano chiavi e valori, possono imporre la conformità per tipi di risorse specifici e forniscono report.","Un processo manuale e a posteriori che non impedisce i tag non conformi."]},
  "1186": {"h":"27cf54d4","question":"Un'azienda deve garantire che ogni account membro della propria organizzazione, inclusi gli account futuri, esegua il backup delle risorse con tag backup=daily secondo un unico piano definito centralmente. Gli amministratori degli account membri non devono poter modificare tale piano. Quale soluzione soddisfa questi requisiti?","options":["Distribuire il backup plan in ogni account con CloudFormation StackSets.","Eseguire in ogni account una funzione Lambda pianificata che crei snapshot delle risorse con il tag.","Usare policy di Amazon Data Lifecycle Manager in ogni account per le risorse con il tag.","Associare alle OU una backup policy di AWS Organizations che definisca il piano e la selezione basata sui tag."],"explanation":"Le backup policy di Organizations creano piani AWS Backup in ogni account delle OU di destinazione, inclusi i nuovi account, e i piani risultanti sono immutabili per gli account membri. StackSets può distribuire i piani ma non impedisce le modifiche locali.","optionExplanations":["Gli amministratori degli account membri possono modificare o eliminare le risorse create dallo stack, e il drift non viene impedito.","Codice personalizzato in ogni account aggiunge onere e può essere modificato dagli amministratori dell'account.","DLM gestisce solo snapshot EBS e AMI, e ogni account deve configurarlo separatamente.","Corretto — Le backup policy distribuiscono centralmente i piani AWS Backup a tutti gli account in ambito, e gli account membri non possono modificarli."]},
  "1187": {"h":"74531dcb","question":"Un ruolo IAM nell'account A ha una policy basata sull'identità che consente s3:GetObject su un bucket nell'account B. Le richieste del ruolo vengono negate. Il bucket usa la cifratura SSE-S3 e la sua bucket policy non menziona l'account A. Quale azione consentirà al ruolo di leggere gli oggetti?","options":["Consentire al ruolo dell'account A di leggere gli oggetti nella bucket policy dell'account B.","Associare al ruolo un permissions boundary che consenta s3:GetObject sul bucket.","Associare all'account A una SCP che consenta s3:GetObject sul bucket nell'account B.","Creare un gateway VPC endpoint S3 nell'account A e instradarvi le richieste."],"explanation":"Per le richieste cross-account, sia la policy basata sull'identità del chiamante sia la policy del proprietario della risorsa devono consentire l'azione. I permissions boundary e le SCP limitano soltanto le autorizzazioni e non possono mai concederle.","optionExplanations":["Corretto — L'accesso cross-account richiede che il proprietario della risorsa conceda l'accesso, oltre alla policy basata sull'identità del chiamante.","Un permissions boundary limita solo le autorizzazioni massime e non concede mai accesso da solo.","Le SCP non concedono autorizzazioni; definiscono solo le autorizzazioni massime disponibili.","Cambia il percorso di rete ma non fornisce l'autorizzazione mancante da parte dell'account B."]},
  "1188": {"h":"bf2e7c2e","question":"Il backend di un SaaS multi-tenant assume un unico ruolo IAM per accedere a un bucket Amazon S3 per conto dei tenant. Un bug software potrebbe permettere alla richiesta di un tenant di leggere il prefisso di un altro tenant. Senza creare un ruolo per tenant, le credenziali usate per ogni richiesta devono essere limitate al prefisso di quel tenant. Quale soluzione soddisfa questi requisiti?","options":["Creare un ruolo IAM per ogni tenant che consenta l'accesso solo al prefisso di quel tenant.","Passare una session policy limitata al prefisso del tenant quando si assume il ruolo per ogni richiesta.","Associare al ruolo condiviso un permissions boundary che consenta l'accesso a tutti i prefissi dei tenant.","Aggiungere uno statement alla bucket policy per ogni prefisso di tenant che limiti l'accesso per indirizzo IP di origine."],"explanation":"Le session policy passate quando si assume un ruolo limitano la sessione risultante all'intersezione tra le policy del ruolo e la session policy, così ogni richiesta del tenant ottiene credenziali limitate al proprio prefisso. Un permissions boundary statico si applica allo stesso modo a ogni sessione.","optionExplanations":["Raggiunge l'obiettivo di isolamento ma crea un ruolo per tenant, cosa che l'azienda vuole evitare.","Corretto — Le session policy restringono ulteriormente le autorizzazioni del ruolo solo per quella sessione, fornendo credenziali per singolo tenant.","Un boundary è statico e uguale per ogni sessione, quindi non può isolare i tenant tra loro.","Le richieste provengono dallo stesso backend, quindi l'IP di origine non può distinguere i tenant."]},
  "1189": {"h":"d9ace03e","question":"Un team di sicurezza ha creato una customer managed key AWS KMS la cui key policy concede autorizzazioni solo a un ruolo KeyAdmin e non ha alcuno statement per l'account stesso. Un ruolo applicativo ha una policy IAM che consente kms:Decrypt sulla chiave, ma le sue richieste vengono negate. Quale soluzione risolverà il problema?","options":["Associare al ruolo applicativo una policy IAM AWS managed con ampie autorizzazioni KMS.","Creare un alias per la chiave e referenziare l'alias nella policy IAM del ruolo applicativo.","Aggiornare la key policy per consentire al ruolo applicativo di usare la chiave per la decifratura.","Abilitare la rotazione automatica della chiave in modo che KMS rigeneri la key policy per l'account."],"explanation":"Le key policy KMS sono la resource policy principale di una chiave: se la key policy non consente l'account (abilitando le policy IAM) o il ruolo specifico, le sole policy basate sull'identità non possono concedere l'accesso. Aggiungere autorizzazioni IAM più ampie quindi non serve.","optionExplanations":["Le policy IAM non hanno effetto su una chiave KMS a meno che la key policy non le abiliti o non nomini il ruolo.","Gli alias non modificano l'autorizzazione, e la key policy continua a non consentire il ruolo.","Corretto — La key policy è il controllo di accesso principale per le chiavi KMS; il ruolo deve essere consentito lì oppure devono essere abilitate le policy IAM.","La rotazione cambia solo il materiale della chiave e non modifica mai la key policy."]},
  "1190": {"h":"eb7b4232","question":"Gli utenti caricano file in un bucket Amazon S3 tramite un'applicazione web, e una pipeline di elaborazione li consuma. L'azienda deve analizzare automaticamente ogni oggetto appena caricato alla ricerca di malware prima dell'elaborazione e applicare un tag agli oggetti infetti. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Usare Amazon Macie per analizzare i nuovi oggetti e mettere in quarantena quelli classificati come sensibili.","Usare Amazon Inspector per analizzare il bucket alla ricerca di vulnerabilità software.","Eseguire un motore antivirus open source in una funzione Lambda attivata dagli eventi S3.","Abilitare Amazon GuardDuty Malware Protection for S3 sul bucket e agire in base ai tag del risultato della scansione."],"explanation":"GuardDuty Malware Protection for S3 è una funzionalità gestita che analizza gli oggetti appena caricati e può aggiungere tag con il risultato della scansione, che la pipeline può usare per saltare i file infetti. Una funzione Lambda antivirus autogestita aggiunge manutenzione continua.","optionExplanations":["Macie individua dati sensibili come le PII; non rileva malware.","Inspector analizza EC2, immagini ECR e funzioni Lambda, non gli oggetti S3 alla ricerca di malware.","Funziona ma richiede di mantenere il motore, gli aggiornamenti delle firme e la logica di scalabilità.","Corretto — GuardDuty Malware Protection for S3 analizza automaticamente i nuovi oggetti e può applicare loro un tag con il risultato."]},
  "1191": {"h":"45bdede2","question":"Un'applicazione necessita di decine di valori di configurazione, incluse alcune password di database modificate manualmente una volta all'anno. I valori devono essere cifrati at rest e l'accesso deve essere controllato con IAM. La rotazione automatica non è necessaria. Quale soluzione soddisfa questi requisiti nel modo PIÙ conveniente?","options":["Archiviare i valori come parametri SecureString in Systems Manager Parameter Store.","Archiviare ogni valore come secret separato in AWS Secrets Manager.","Archiviare i valori negli user data dell'istanza nel launch template.","Archiviare i valori nelle variabili d'ambiente Lambda di una funzione di supporto."],"explanation":"I parametri SecureString di Parameter Store forniscono cifratura KMS e controllo degli accessi IAM, e i parametri standard non comportano costi di storage. Secrets Manager è la scelta migliore quando servono la rotazione automatica o la condivisione cross-account dei secret, cosa che qui non accade.","optionExplanations":["Corretto — I parametri SecureString standard sono cifrati con KMS, controllati da IAM e non hanno costi di storage.","Secrets Manager si paga per secret e il suo vantaggio principale, la rotazione automatica, qui non serve.","Gli user data non sono cifrati per i secret e sono leggibili da chiunque possa visualizzare gli attributi dell'istanza.","Lega la configurazione a una funzione, è difficile da condividere e offre un controllo degli accessi più debole per l'applicazione."]},
  "1192": {"h":"05aeb317","question":"Microservizi eseguiti su Amazon ECS devono autenticarsi a vicenda con mutual TLS. I certificati devono provenire da una certificate authority privata gestita da AWS, non devono essere attendibili pubblicamente e devono essere emessi automaticamente. Quale soluzione soddisfa questi requisiti?","options":["Richiedere certificati ACM pubblici per il nome DNS interno di ciascun servizio.","Usare AWS Private CA per emettere certificati privati per i servizi.","Generare certificati self-signed in ogni container al suo avvio.","Caricare in IAM certificati di una CA commerciale come server certificate."],"explanation":"AWS Private CA è una certificate authority privata gestita che emette certificati attendibili solo all'interno dell'organizzazione, adatti al mutual TLS tra servizi. I certificati ACM pubblici sono attendibili pubblicamente e richiedono la validazione del dominio.","optionExplanations":["I certificati pubblici richiedono la validazione pubblica del dominio e sono attendibili pubblicamente, cosa che l'azienda non vuole.","Corretto — AWS Private CA fornisce una gerarchia di CA privata gestita per emettere certificati interni, anche per mTLS.","Nessun trust anchor comune né gestione centralizzata, quindi i servizi non possono verificarsi a vicenda in modo affidabile.","Usa certificati attendibili pubblicamente e caricamenti manuali invece di un'emissione privata automatizzata."]},
  "1193": {"h":"62b072c5","question":"Un'azienda espone una REST API pubblica in Amazon API Gateway a tre partner. Ogni partner chiama l'API da un insieme fisso di range IP. Le richieste da qualsiasi altro indirizzo IP devono essere rifiutate, e ogni partner deve essere soggetto a throttling in base al proprio tasso di richieste contrattuale. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Associare all'API un security group che consenta solo i range IP dei partner.","Aggiungere una resource policy dell'API che consenta l'invocazione solo dai range IP di origine dei partner.","Impostare il throttling a livello di stage al più basso dei tassi contrattuali dei partner.","Creare un usage plan per ogni partner con il relativo rate limit e associarvi l'API key del partner.","Impostare la reserved concurrency sulla funzione Lambda di backend per ogni partner."],"explanation":"Le resource policy di API Gateway possono limitare l'invocazione a specifici range IP di origine, e gli usage plan con API key applicano throttling e quote separati a ciascun partner. Il throttling a livello di stage non può distinguere tra i chiamanti.","optionExplanations":["Gli endpoint pubblici di API Gateway non supportano i security group.","Corretto — Le resource policy possono consentire o negare l'invocazione in base alla condizione aws:SourceIp.","Applica un unico limite a tutti i chiamanti invece di un tasso separato per ogni partner.","Corretto — Gli usage plan applicano throttling e quote per singolo client, identificato tramite API key.","La reserved concurrency si applica per funzione, non per chiamante, e non limita i singoli partner."]},
  "1194": {"h":"2d42f5ee","question":"Un replication group Amazon ElastiCache (Redis OSS) archivia token di sessione degli utenti. Una revisione di sicurezza richiede che i dati siano cifrati tra i client e la cache e che i client si autentichino prima di poter eseguire comandi. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Abilitare la cifratura in transito (TLS) sul replication group.","Abilitare la cifratura at rest sul replication group.","Limitare il security group della cache al traffico in ingresso dal security group dell'applicazione.","Collocare il replication group in subnet private senza una route verso internet.","Configurare Redis AUTH o il role-based access control e far autenticare i client alla connessione."],"explanation":"La cifratura in transito di ElastiCache fornisce TLS tra client e nodi, e AUTH o RBAC richiedono ai client di autenticarsi prima di eseguire comandi. Security group e subnet private sono controlli di rete utili, ma non costituiscono autenticazione.","optionExplanations":["Corretto — TLS cifra il traffico tra i client e i nodi della cache ed è necessario per le funzionalità di autenticazione.","Protegge i dati archiviati e i backup ma non cifra il traffico dei client né li autentica.","Limita l'accesso di rete ma non autentica i client prima che eseguano comandi.","Il posizionamento di rete non fornisce cifratura in transito né autenticazione dei client.","Corretto — I token AUTH o gli utenti RBAC richiedono ai client di autenticarsi prima che i comandi vengano accettati."]},
  "1195": {"h":"9d945121","question":"Amazon GuardDuty segnala che le credenziali temporanee del ruolo di un'istanza Amazon EC2 vengono usate da un indirizzo IP esterno. Il team di sicurezza deve invalidare immediatamente tutte le credenziali già emesse per il ruolo e contenere l'istanza preservandola per l'analisi forense. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Terminare immediatamente l'istanza e avviarne una sostitutiva dall'AMI.","Scollegare l'instance profile dall'istanza.","Revocare le sessioni attive del ruolo in modo che le credenziali emesse prima di questo momento vengano negate.","Sostituire i security group dell'istanza con un gruppo di isolamento privo di regole in ingresso e in uscita.","Ruotare le access key di tutti gli utenti IAM dell'account."],"explanation":"La revoca delle sessioni attive del ruolo associa una policy che nega qualsiasi credenziale emessa prima del momento della revoca, invalidando le credenziali temporanee rubate. Isolare l'istanza con un security group restrittivo la contiene preservando le prove; terminarla distruggerebbe tali prove.","optionExplanations":["Distrugge le prove presenti sull'istanza, che devono essere preservate per l'analisi forense.","Impedisce la consegna di nuove credenziali ma non invalida quelle già emesse.","Corretto — La revoca delle sessioni aggiunge un deny per i token emessi prima del momento attuale, invalidando le credenziali rubate.","Corretto — Un security group di isolamento contiene l'istanza mantenendola disponibile per l'indagine.","Le credenziali compromesse appartengono a un ruolo, non a utenti IAM, quindi ruotare le chiavi degli utenti non serve."]},
  "1196": {"h":"278d718c","question":"Un'azienda esegue una flotta di worker EC2 che effettuano polling su una coda Amazon SQS standard. I messaggi arrivano sporadicamente, e il monitoraggio mostra che la maggior parte delle chiamate ReceiveMessage non restituisce messaggi, il che aumenta i costi delle API e aggiunge carico di CPU sui worker. L'azienda vuole ridurre le risposte vuote senza ritardare i messaggi una volta arrivati. Cosa dovrebbe fare un solutions architect?","options":["Configurare un delivery delay sulla coda in modo che i messaggi vengano raggruppati prima che i worker li ricevano.","Abilitare il long polling impostando sulla coda un receive message wait time maggiore di zero.","Aumentare il visibility timeout in modo che i worker mantengano i messaggi nascosti più a lungo tra un polling e l'altro.","Sostituire la coda standard con una coda FIFO in modo che i worker ricevano i messaggi in gruppi più grandi."],"explanation":"Il long polling fa sì che SQS attenda l'arrivo dei messaggi (fino al wait time configurato) prima di rispondere, e interroga tutti i server, riducendo drasticamente le risposte vuote e il relativo costo, restituendo i messaggi non appena sono disponibili. Un delivery delay tratterrebbe ogni messaggio, aggiungendo latenza invece di ridurre le ricezioni vuote.","optionExplanations":["Un delivery delay rende ogni nuovo messaggio invisibile per un certo periodo, il che aggiunge latenza e non fa nulla per evitare le risposte ReceiveMessage vuote.","Corretto — Il long polling attende i messaggi prima di rispondere, eliminando la maggior parte delle risposte vuote e riducendo i costi delle richieste senza aggiungere ritardo.","Il visibility timeout si applica solo ai messaggi già ricevuti; non influisce sulla frequenza con cui i polling restituiscono risposte vuote.","Una coda FIFO cambia la semantica di ordinamento e deduplicazione ma non riduce le risposte vuote dello short polling."]},
  "1197": {"h":"e0d88bd1","question":"Un rivenditore online consente ai clienti di annullare gratuitamente un ordine entro due minuti dall'invio. I messaggi degli ordini vengono inviati a una coda Amazon SQS, e un servizio di evasione non deve iniziare a elaborare alcun ordine prima che siano trascorsi due minuti dal suo invio. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Impostare il visibility timeout della coda a due minuti in modo che il servizio di evasione veda ogni ordine più tardi.","Avviare per ogni ordine un workflow AWS Step Functions che attenda due minuti prima di invocare l'evasione.","Configurare la coda come delay queue con un delivery delay di due minuti per tutti i nuovi messaggi.","Creare per ogni ordine una schedule una tantum di Amazon EventBridge Scheduler che lo invii due minuti dopo."],"explanation":"Una delay queue nasconde ogni nuovo messaggio ai consumer per il delivery delay configurato, quindi gli ordini diventano visibili al servizio di evasione solo dopo due minuti senza componenti aggiuntivi. Il visibility timeout è una tentazione, ma inizia solo dopo che un consumer ha ricevuto un messaggio, quindi non può posticipare la prima consegna.","optionExplanations":["Il visibility timeout inizia solo dopo la ricezione di un messaggio, quindi il servizio riceverebbe comunque ogni ordine immediatamente.","Uno stato wait di Step Functions funziona, ma aggiunge un workflow per ogni ordine, con un onere operativo maggiore rispetto a un'impostazione della coda.","Corretto — Un delivery delay sulla coda posticipa di due minuti la prima visibilità di ogni messaggio con una sola modifica di configurazione.","Creare una schedule per ogni ordine è tecnicamente possibile, ma aggiunge molte risorse e logica personalizzata rispetto a un ritardo a livello di coda."]},
  "1198": {"h":"9157c101","question":"Un'azienda invia aggiornamenti dell'inventario a una coda Amazon SQS che usa le impostazioni predefinite. Il mese prossimo il sistema consumer sarà offline fino a 10 giorni durante una migrazione pianificata, ma i producer continueranno a inviare aggiornamenti. Nessun aggiornamento può andare perso, e l'azienda vuole evitare di scrivere codice personalizzato. Cosa dovrebbe fare un solutions architect?","options":["Aumentare il periodo di conservazione dei messaggi della coda al valore massimo prima dell'inizio della migrazione.","Associare una dead-letter queue in modo che i messaggi non consumati vi vengano spostati dopo il periodo di conservazione.","Aumentare il visibility timeout in modo che i messaggi restino nascosti fino al ritorno del sistema consumer.","Aggiungere una funzione Lambda che copi ogni messaggio su Amazon S3 e li riproduca dopo la migrazione."],"explanation":"SQS conserva i messaggi per quattro giorni per impostazione predefinita e può essere configurato per conservarli fino a 14 giorni, il che copre un'interruzione di 10 giorni con una semplice modifica di configurazione. La dead-letter queue è il distrattore allettante, ma riceve solo i messaggi che superano il numero massimo di ricezioni, non quelli che scadono senza essere letti.","optionExplanations":["Corretto — Portare il periodo di conservazione al massimo consente ai messaggi di sopravvivere all'interruzione di 10 giorni senza codice personalizzato.","Una dead-letter queue riceve i messaggi dopo ripetute ricezioni fallite; i messaggi mai ricevuti semplicemente scadono e vengono eliminati.","Il visibility timeout si applica solo dopo la ricezione di un messaggio e non estende la durata di conservazione di un messaggio non letto.","Copiare i messaggi su S3 e riprodurli funzionerebbe, ma richiede codice personalizzato, che l'azienda vuole evitare."]},
  "1199": {"h":"647b4dd7","question":"Un servizio ordini pubblica tutti gli eventi degli ordini su un unico topic Amazon SNS. Diverse code Amazon SQS sono sottoscritte al topic, ma la coda del team antifrode dovrebbe ricevere solo gli ordini con tipo di pagamento carta di credito, e la coda wholesale solo gli ordini di clienti business. Oggi ogni consumer scarta nel codice i messaggi irrilevanti. Quale soluzione ridurrà l'elaborazione superflua con il MINOR onere operativo?","options":["Creare un topic SNS separato per ogni consumer e modificare il servizio ordini affinché pubblichi sui topic corretti.","Inserire tra il topic e ciascuna coda una funzione Lambda che inoltri solo gli eventi degli ordini pertinenti.","Usare una coda SQS FIFO per ogni consumer e usare i message group ID per separare gli ordini pertinenti.","Applicare a ogni sottoscrizione delle code una subscription filter policy SNS che corrisponda agli attributi pertinenti."],"explanation":"Le subscription filter policy di SNS consentono a ogni sottoscrittore di ricevere solo i messaggi i cui attributi o il cui body corrispondono alla sua policy, quindi il filtraggio avviene in SNS senza codice. Creare topic separati funzionerebbe comunque, ma costringe il producer a conoscere le esigenze di ogni consumer, aumentando accoppiamento e manutenzione.","optionExplanations":["Topic per singolo consumer accoppiano il producer ai consumer e richiedono modifiche al codice ogni volta che serve un nuovo filtro.","Un inoltro tramite Lambda aggiunge funzioni da costruire, monitorare e scalare, quando SNS può filtrare nativamente.","I message group ID controllano l'ordinamento all'interno di una coda FIFO; non filtrano quali messaggi raggiungono la coda.","Corretto — Le subscription filter policy consegnano a ogni coda solo i messaggi corrispondenti, eliminando l'elaborazione superflua senza codice personalizzato."]},
  "1200": {"h":"8d148f02","question":"Un'azienda instrada gli eventi applicativi attraverso un event bus Amazon EventBridge personalizzato verso diversi target Lambda. Un bug in una delle funzioni target le ha fatto elaborare in modo errato due giorni di eventi. Dopo aver distribuito una correzione, l'azienda deve rielaborare esattamente quegli eventi e vuole che questa capacità sia disponibile anche per incidenti futuri. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Aggiungere una regola che invii tutti gli eventi ad Amazon S3 e scrivere uno script che li ripubblichi sul bus quando serve.","Creare un archivio sull'event bus e fare il replay degli eventi archiviati della finestra temporale interessata verso la regola.","Abilitare una dead-letter queue sul target e fare il redrive degli eventi in coda una volta corretta la funzione.","Aggiungere una coda Amazon SQS come target aggiuntivo e conservarne i messaggi finché il team non decide di rielaborarli."],"explanation":"Gli archivi EventBridge conservano gli eventi che corrispondono a un pattern, e un replay rimanda sul bus gli eventi di una finestra temporale scelta, in modo che le regole e i target corretti possano elaborarli di nuovo. Una dead-letter queue del target cattura solo gli eventi la cui consegna è fallita, mentre questi eventi sono stati consegnati correttamente ma elaborati in modo errato.","optionExplanations":["Archiviare su S3 e ripubblicare con uno script funziona, ma richiede codice personalizzato per qualcosa che EventBridge fornisce nativamente.","Corretto — Archive e replay di EventBridge rinviano sul bus gli eventi di un intervallo temporale specifico senza strumenti personalizzati.","Una dead-letter queue contiene solo gli eventi che EventBridge non è riuscito a consegnare; gli eventi elaborati in modo errato sono stati consegnati correttamente.","Una coda SQS conserva i messaggi per un tempo limitato e richiede codice personalizzato per far ripassare gli eventi attraverso le regole."]},
  "1201": {"h":"0144d997","question":"Un'azienda ha decine di account AWS in AWS Organizations. Il team di sicurezza vuole che eventi specifici, come le modifiche ai security group, provenienti da ogni account vengano elaborati da un unico insieme di funzioni Lambda in un account di sicurezza centrale. Nuovi account vengono aggiunti regolarmente. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Distribuire le funzioni Lambda in ogni account e fare in modo che ciascuna scriva i risultati in un bucket Amazon S3 condiviso.","Configurare in ogni account un trail AWS CloudTrail che consegna i log a un bucket che le funzioni centrali analizzano ogni ora.","Creare in ogni account regole che inviano gli eventi corrispondenti a un event bus centrale la cui policy consente l'organizzazione.","Creare un topic Amazon SNS in ogni account e sottoscrivere le funzioni Lambda centrali a ciascun topic singolarmente."],"explanation":"EventBridge supporta l'invio di eventi da regole in un account a un event bus in un altro account; una policy basata sulle risorse sul bus centrale può consentire l'intera organizzazione e le regole possono essere distribuite ai nuovi account con StackSets. Distribuire le funzioni in ogni account duplica codice e attività operative su decine di account.","optionExplanations":["Distribuire le funzioni in ogni account moltiplica il codice, i permessi e il monitoraggio da mantenere.","Analizzare i log di CloudTrail ogni ora introduce ritardi e un parsing personalizzato invece di reagire agli eventi nel momento in cui si verificano.","Corretto — La consegna di eventi cross-account a un bus centrale centralizza l'elaborazione, e una policy del bus valida per tutta l'organizzazione copre i nuovi account.","I topic SNS per singolo account richiedono una sottoscrizione separata per ogni account e non filtrano nativamente in base al contenuto gli eventi provenienti dai servizi AWS."]},
  "1202": {"h":"430a8ffe","question":"Un workflow AWS Step Functions chiama l'API di inventario di un partner tramite una funzione Lambda. L'API restituisce occasionalmente errori temporanei di throttling che vanno a buon fine se la chiamata viene ripetuta qualche secondo dopo. Se la chiamata fallisce ancora dopo diversi tentativi, il workflow deve rilasciare la merce riservata e avvisare il team operativo invece di fallire semplicemente. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Aggiungere una regola Retry con backoff esponenziale per l'errore di throttling e una regola Catch che instrada verso passaggi di compensazione.","Scrivere la logica di retry e di compensazione nella funzione Lambda e restituire un codice di stato che il workflow esamina.","Configurare una dead-letter queue sulla funzione Lambda ed elaborare le invocazioni fallite con una funzione separata.","Usare un workflow Express in modo che le esecuzioni fallite vengano ritentate automaticamente da Step Functions finché non riescono."],"explanation":"I campi Retry di Step Functions forniscono retry dichiarativi con backoff esponenziale per errori specifici, e i campi Catch inviano l'esecuzione a stati di fallback, come il rilascio della merce e l'invio di una notifica, una volta esauriti i tentativi. Inserire questa logica nella funzione Lambda funziona, ma aggiunge codice personalizzato e può prolungare l'esecuzione della funzione durante le attese.","optionExplanations":["Corretto — Retry con backoff gestisce gli errori transitori, e Catch instrada i fallimenti persistenti verso stati di compensazione e notifica.","Il codice personalizzato di retry e compensazione nella funzione duplica funzionalità integrate del workflow ed è più difficile da mantenere.","Una dead-letter queue di Lambda si applica alle invocazioni asincrone; Step Functions invoca il task in modo sincrono, quindi non catturerebbe questi fallimenti.","I workflow Express non ritentano intere esecuzioni fino al successo; la gestione degli errori deve comunque essere definita con Retry e Catch."]},
  "1203": {"h":"f28f81e0","question":"Un'azienda di ricerca deve eseguire ogni settimana la stessa logica di validazione su diversi milioni di oggetti archiviati in un bucket Amazon S3. Ogni oggetto può essere elaborato in modo indipendente in pochi secondi. Il processo deve essere eseguito con un elevato parallelismo, tollerare i fallimenti dei singoli elementi e riportare quali elementi sono falliti. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Avviare un'istanza EC2 di grandi dimensioni che elenca il bucket ed elabora gli oggetti con molti thread in parallelo.","Usare uno stato Map inline in un workflow Step Functions Standard per iterare su un elenco di chiavi degli oggetti.","Inviare ogni chiave di oggetto a una coda SQS ed elaborarla con un Auto Scaling group di istanze EC2.","Usare uno stato Distributed Map di Step Functions che legge gli oggetti S3 ed esegue workflow figli in parallelo."],"explanation":"Uno stato Distributed Map può iterare direttamente sugli oggetti di un bucket S3, eseguire in parallelo un gran numero di esecuzioni di workflow figli, tollerare una soglia di fallimenti configurabile e scrivere i risultati, compresi i fallimenti, in S3. Uno stato Map inline viene eseguito all'interno di una singola esecuzione con concorrenza e cronologia limitate, quindi non è adatto a milioni di elementi.","optionExplanations":["Una singola istanza è un single point of failure, limita il parallelismo e richiede codice personalizzato per tracciare i fallimenti.","Un Map inline viene eseguito all'interno di una sola esecuzione con concorrenza e cronologia di esecuzione limitate, e non scala a milioni di elementi.","SQS con worker EC2 può scalare, ma richiede la gestione delle istanze e una reportistica personalizzata dei fallimenti, che aggiunge carico.","Corretto — Distributed Map itera sugli oggetti S3 con un parallelismo massivo, con tolleranza ai fallimenti e reportistica dei risultati integrate."]},
  "1204": {"h":"b7f43eb1","question":"Le notifiche di eventi di Amazon S3 invocano in modo asincrono una funzione Lambda per ogni file caricato. Alcune invocazioni falliscono ripetutamente a causa di formati di file inattesi e, dopo i retry automatici, questi eventi vengono scartati. Il team ha bisogno che ogni evento fallito, insieme ai dettagli dell'errore, venga inviato a una coda Amazon SQS per l'analisi, senza modificare il codice della funzione. Cosa dovrebbe fare un solutions architect?","options":["Aggiungere una destinazione on-failure per le invocazioni asincrone della funzione che punti alla coda.","Modificare le notifiche di eventi S3 in modo che puntino direttamente alla coda SQS e smettere di invocare la funzione.","Aumentare il timeout e la memoria della funzione in modo che possa completare l'elaborazione dei formati di file inattesi.","Impostare a zero la reserved concurrency della funzione quando si verificano errori, così che gli eventi attendano nella coda."],"explanation":"Le destinazioni Lambda per le invocazioni asincrone inviano un record di ogni invocazione fallita, che include l'evento originale e i dettagli dell'errore, a una destinazione come una coda SQS una volta esauriti i retry. Inviare gli eventi solo a SQS interromperebbe l'elaborazione dei file validi, che hanno comunque bisogno della funzione.","optionExplanations":["Corretto — Una destinazione on-failure cattura l'evento e i dettagli del risultato dell'invocazione una volta esauriti i retry, senza modifiche al codice.","Puntare solo alla coda rimuove la funzione dal flusso, quindi i file validi non verrebbero più elaborati.","Più tempo o più memoria non risolvono gli errori di formato; le invocazioni continuerebbero a fallire e a essere scartate.","Impostare a zero la reserved concurrency limita tutte le invocazioni e non cattura gli eventi falliti con i dettagli dell'errore."]},
  "1205": {"h":"288aed32","question":"Un'azienda esegue molte funzioni Lambda in un unico account. Una funzione di checkout rivolta ai clienti subisce occasionalmente throttling quando le funzioni di elaborazione batch nello stesso account scalano e consumano gran parte della concorrenza disponibile. L'azienda deve garantire che la funzione di checkout possa sempre scalare fino a un livello definito. Cosa dovrebbe fare un solutions architect?","options":["Configurare la provisioned concurrency sulle funzioni di elaborazione batch in modo che la loro capacità sia fissa.","Aumentare la memoria allocata alla funzione di checkout in modo che ogni invocazione si completi più rapidamente.","Configurare la reserved concurrency sulla funzione di checkout al livello di cui deve sempre disporre.","Distribuire la funzione di checkout in una seconda Region e instradarvi le richieste quando si verifica il throttling."],"explanation":"La reserved concurrency riserva una parte della concorrenza dell'account esclusivamente a una funzione, così che le altre funzioni non possano consumarla, e al tempo stesso limita quella funzione allo stesso livello. La provisioned concurrency sulle funzioni batch pre-inizializza gli ambienti, ma non impedisce loro di scalare oltre quella quantità.","optionExplanations":["La provisioned concurrency pre-riscalda gli ambienti; non pone un limite alle funzioni batch, che possono quindi ancora esaurire la concorrenza dell'account.","Invocazioni più rapide possono ridurre leggermente la concorrenza, ma non garantiscono capacità quando le altre funzioni hanno dei picchi.","Corretto — La reserved concurrency garantisce alla funzione di checkout la sua quota di concorrenza dell'account indipendentemente dalle altre funzioni.","Una seconda Region aggiunge complessità di deployment e di routing e non offre comunque alcuna garanzia nella Region principale."]},
  "1206": {"h":"a4c7c430","question":"Un'API basata su funzioni Lambda legge e scrive dati in un'istanza database Amazon RDS for PostgreSQL Multi-AZ. Durante i picchi di traffico, migliaia di invocazioni concorrenti aprono nuove connessioni, il database esaurisce le connessioni e le richieste falliscono. Inoltre i failover richiedono più tempo di quanto l'azienda desideri. Quale soluzione migliorerà la resilienza con il MINOR numero di modifiche all'applicazione?","options":["Aggiungere read replica RDS e distribuire le connessioni delle funzioni Lambda tra gli endpoint delle replica.","Inserire una coda Amazon SQS davanti al database e far applicare tutte le letture e scritture a un singolo worker.","Scalare l'istanza database a una classe più grande in modo che supporti un numero massimo di connessioni più elevato.","Inserire Amazon RDS Proxy tra le funzioni e il database per raggruppare e riutilizzare le connessioni al database."],"explanation":"RDS Proxy mantiene un pool di connessioni al database condiviso da molte invocazioni Lambda, evitando l'esaurimento delle connessioni, e riduce i tempi di failover mantenendo aperte le connessioni dei client mentre instrada verso la nuova istanza primaria. Le read replica non aiutano con le scritture e richiederebbero la separazione tra letture e scritture nell'applicazione.","optionExplanations":["Le read replica servono solo le letture, quindi le connessioni in scrittura esaurirebbero comunque l'istanza primaria e l'applicazione richiederebbe una logica di separazione.","Un singolo worker della coda serializzerebbe tutte le letture e le scritture, compromettendo le letture sincrone dell'API e creando un collo di bottiglia.","Un'istanza più grande alza il limite, ma i picchi possono comunque esaurirlo, e non fa nulla per abbreviare i failover.","Corretto — RDS Proxy raggruppa e riutilizza le connessioni per il traffico Lambda a raffica e riduce l'interruzione durante il failover con il solo cambio di endpoint."]},
  "1207": {"h":"ab043fbf","question":"Un'azienda di ride-sharing acquisisce aggiornamenti di posizione dai veicoli. Gli aggiornamenti di ciascun veicolo devono essere elaborati in ordine. Un servizio di tracciamento in tempo reale e un servizio di analytics separato devono leggere ciascuno tutti gli aggiornamenti in modo indipendente, e il team di analytics deve poter rielaborare i dati delle ultime 24 ore dopo una modifica al codice. Quale servizio dovrebbe usare un solutions architect per acquisire gli aggiornamenti?","options":["Una coda Amazon SQS FIFO con l'ID del veicolo come message group ID e due applicazioni consumer.","Un topic Amazon SNS standard con una sottoscrizione per ciascun servizio e un filtro dei messaggi per veicolo.","Amazon Data Firehose che consegna gli aggiornamenti ad Amazon S3, da cui entrambi i servizi leggono i nuovi file in arrivo.","Amazon Kinesis Data Streams con l'ID del veicolo come partition key e un'applicazione per ciascun servizio."],"explanation":"Kinesis Data Streams mantiene i record ordinati per partition key, consente a più consumer di leggere lo stesso stream in modo indipendente e conserva i dati in modo che i consumer possano ripartire da una posizione precedente. Una coda SQS FIFO preserva l'ordine, ma ogni messaggio viene consumato ed eliminato una sola volta, quindi due servizi non possono leggere entrambi ogni messaggio né rielaborarlo.","optionExplanations":["Con SQS un messaggio viene eliminato dopo che un consumer lo ha elaborato, quindi due servizi non possono leggere ciascuno ogni aggiornamento né rielaborare i dati passati.","I topic SNS standard non garantiscono l'ordinamento e non possono rielaborare i messaggi già consegnati.","Firehose accumula i dati in file S3, aggiungendo un ritardo non adatto al tracciamento in tempo reale e senza fornire ai consumer un ordinamento per veicolo.","Corretto — Kinesis fornisce ordinamento per chiave, più consumer indipendenti e la rielaborazione entro il periodo di retention dello stream."]},
  "1208": {"h":"8ab2821e","question":"Un'azienda espone un'API REST a decine di partner tramite Amazon API Gateway. Di recente l'integrazione mal configurata di un partner ha inviato un'ondata di richieste che ha causato il throttling dell'intera API e degradato il servizio per tutti gli altri partner. L'azienda vuole limitare la frequenza delle richieste di ciascun partner singolarmente. Quale soluzione soddisferà questi requisiti?","options":["Abbassare i limiti di throttling a livello di stage dell'API in modo che la frequenza totale delle richieste resti entro la capacità del backend.","Creare usage plan con limiti di throttling e associare la API key di ciascun partner a un piano appropriato.","Abilitare l'API caching sullo stage in modo che le richieste ripetute di qualsiasi partner non raggiungano il backend.","Inserire una distribuzione Amazon CloudFront davanti all'API e abilitare la protezione AWS Shield Standard."],"explanation":"Gli usage plan di API Gateway applicano limiti di throttling e quote per API key, quindi un partner che supera il proprio limite riceve errori di throttling mentre gli altri partner non ne risentono. Abbassare i limiti a livello di stage limita il totale, ma consente comunque a un singolo partner di consumare la capacità condivisa.","optionExplanations":["I limiti a livello di stage si applicano a tutti i chiamanti insieme, quindi un singolo partner rumoroso può comunque esaurire il limite condiviso.","Corretto — Gli usage plan con throttling per chiave isolano ogni partner, così un singolo client non può degradare l'API per gli altri.","Il caching aiuta solo con richieste identiche memorizzabili in cache e non limita quante richieste può inviare un singolo partner.","Shield Standard protegge dagli attacchi DDoS a livello di rete, non da un client legittimo che supera una frequenza di richieste equa."]},
  "1209": {"h":"096e85f2","question":"Un'applicazione di elaborazione file è eseguita su istanze EC2 in un Auto Scaling group dietro un Application Load Balancer. Alcuni upload richiedono fino a due minuti. Quando il gruppo esegue lo scale-in, gli utenti con upload in corso sull'istanza in fase di terminazione ricevono errori. Quale soluzione risolverà il problema con il MINOR sforzo?","options":["Impostare il deregistration delay del target group su un valore superiore alla durata dell'upload più lungo.","Abilitare le sticky session sul target group in modo che ogni utente resti sulla stessa istanza fino al termine.","Allungare l'health check grace period dell'Auto Scaling group per mantenere le istanze in servizio.","Disabilitare lo scale-in dell'Auto Scaling group e ridurre la capacità manualmente nei periodi di calma."],"explanation":"Con un deregistration delay (connection draining), il load balancer smette di inviare nuove richieste a un target in fase di deregistrazione ma lascia completare le richieste in corso, e Auto Scaling attende il completamento della deregistrazione prima di terminare l'istanza. Le sticky session mantengono un utente su un'istanza, ma non proteggono le richieste in corso su un'istanza in fase di terminazione.","optionExplanations":["Corretto — Un deregistration delay più lungo dell'upload più lento consente alle richieste in corso di completarsi prima che l'istanza venga terminata.","La stickiness instrada gli utenti verso lo stesso target, ma non fa nulla per mantenere attiva un'istanza in terminazione mentre le richieste si completano.","L'health check grace period riguarda solo le istanze appena avviate e non ritarda la terminazione durante lo scale-in.","Lo scale-in manuale elimina l'elasticità e aggiunge lavoro operativo invece di correggere la gestione delle richieste in corso."]},
  "1210": {"h":"d5482611","question":"Un'applicazione web su istanze EC2 dietro un Application Load Balancer costruisce una grande cache in memoria durante i primi minuti dopo l'avvio. Quando l'Auto Scaling group aggiunge un'istanza, il load balancer le invia immediatamente una quota piena di traffico, i tempi di risposta aumentano bruscamente e a volte l'istanza non supera gli health check. Come può un solutions architect correggere questo comportamento?","options":["Cambiare l'algoritmo di routing del target group in least outstanding requests per tutti i suoi target.","Abilitare la modalità slow start sul target group in modo che i nuovi target ricevano traffico gradualmente.","Aumentare il cooldown predefinito dell'Auto Scaling group in modo che le nuove istanze vengano aggiunte meno spesso.","Sostituire l'Application Load Balancer con un Network Load Balancer con il cross-zone load balancing."],"explanation":"La modalità slow start assegna a un target appena registrato una quota di richieste che cresce linearmente per un periodo configurato, consentendogli di riscaldare la cache prima di ricevere una quota piena. Least outstanding requests favorirebbe invece la nuova istanza inattiva e potrebbe inviarle una raffica di traffico.","optionExplanations":["Least outstanding requests tende a inviare più richieste a un nuovo target inattivo, il che può peggiorare il problema del riscaldamento.","Corretto — Slow start aumenta gradualmente il traffico verso i nuovi target, così possono riscaldarsi prima di gestire una quota piena di carico.","Un cooldown più lungo cambia la frequenza dello scaling, ma non la quantità di traffico che una nuova istanza riceve una volta registrata.","Un Network Load Balancer non dispone della funzionalità slow start e invierebbe comunque ai nuovi target una quota piena di connessioni."]},
  "1211": {"h":"b195b1ce","question":"Un'azienda usa un Network Load Balancer con nodi in due Availability Zone. Dopo un evento di Auto Scaling, una zona ha due istanze registrate e l'altra sei, e le due istanze della prima zona sono sovraccariche mentre le altre sono sottoutilizzate. L'azienda vuole che il traffico sia distribuito uniformemente tra tutte le istanze registrate. Cosa dovrebbe fare un solutions architect?","options":["Aggiungere un secondo Network Load Balancer nella zona con meno istanze e bilanciare il traffico con Route 53.","Abilitare le sticky session sul target group in modo che i client continuino a usare le istanze raggiunte inizialmente.","Abilitare il cross-zone load balancing in modo che ogni nodo del load balancer distribuisca il traffico a tutti i target.","Cambiare il tipo di target da istanza a indirizzo IP in modo che il load balancer distribuisca le connessioni uniformemente."],"explanation":"Il cross-zone load balancing è disattivato per impostazione predefinita sui Network Load Balancer, quindi ogni nodo suddivide il proprio traffico solo tra i target della propria zona; abilitandolo, ogni nodo distribuisce il traffico tra i target di tutte le zone abilitate. Cambiare il tipo di target non modifica il modo in cui i nodi di ciascuna zona scelgono i target.","optionExplanations":["Un altro load balancer aggiunge costi e complessità, mentre ogni nodo continuerebbe a privilegiare i target della propria zona.","La stickiness mantiene i client sugli stessi target e conserverebbe lo squilibrio invece di correggerlo.","Corretto — Con il cross-zone load balancing, ogni nodo distribuisce il traffico su tutti i target registrati indipendentemente dalla zona.","Il tipo di target influisce sul modo in cui i target vengono registrati, non sul fatto che i nodi distribuiscano il traffico tra le zone."]},
  "1212": {"h":"3922fce5","question":"I server applicativi di un Auto Scaling group scrivono file di log importanti sul proprio instance store locale. Quando le istanze vengono terminate durante lo scale-in, i log più recenti vanno persi prima che venga eseguito il job di upload orario. L'azienda deve copiare i log residui di ogni istanza in Amazon S3 prima che l'istanza venga terminata. Quale soluzione soddisferà questo requisito?","options":["Aggiungere un lifecycle hook di terminazione che mette in pausa l'istanza mentre uno script carica i suoi log in S3.","Abilitare la termination protection sulle istanze in modo che lo scale-in non possa rimuoverle finché i log non sono copiati.","Impostare per l'Auto Scaling group una termination policy che rimuove per prime le istanze più vecchie.","Creare uno snapshot EBS di ogni istanza tramite una regola EventBridge quando si verifica un evento di terminazione."],"explanation":"Un lifecycle hook di terminazione mette l'istanza in uno stato di attesa prima della terminazione, dando a uno script il tempo di caricare i log residui e poi completare la lifecycle action. Gli snapshot creati dopo un evento di terminazione arrivano troppo tardi, e in ogni caso gli snapshot EBS non includono i dati dell'instance store.","optionExplanations":["Corretto — Un lifecycle hook di terminazione mantiene l'istanza in uno stato di attesa così che i log possano essere copiati prima della terminazione.","La termination protection delle istanze non blocca lo scale-in di Auto Scaling, e bloccare la terminazione non caricherebbe comunque i log.","Una termination policy sceglie solo quale istanza rimuovere; i log non ancora inviati di quell'istanza andrebbero comunque persi.","Gli snapshot EBS non includono i volumi instance store, e uno snapshot attivato dall'evento di terminazione potrebbe non essere eseguito in tempo."]},
  "1213": {"h":"a4cf06ea","question":"Un'applicazione in un Auto Scaling group ha bisogno di circa 10 minuti dopo l'avvio per installare le dipendenze e caricare i dati di riferimento prima di poter servire le richieste. I picchi di traffico arrivano senza preavviso, quindi le nuove istanze sono pronte troppo tardi. L'azienda vuole ridurre i tempi di scale-out senza mantenere sempre in esecuzione istanze aggiuntive. Cosa dovrebbe consigliare un solutions architect?","options":["Aumentare la capacità minima del gruppo in modo che ci siano sempre abbastanza istanze in esecuzione per qualsiasi picco.","Aggiungere una policy di predictive scaling in modo che la capacità venga avviata prima degli aumenti di domanda previsti.","Creare una scheduled action che aumenta la capacità desiderata ogni mattina prima dell'inizio dell'orario lavorativo.","Aggiungere un warm pool di istanze arrestate e pre-inizializzate che il gruppo può mettere rapidamente in servizio."],"explanation":"Un warm pool mantiene in stato arrestato (o ibernato) istanze che hanno già completato l'inizializzazione, quindi lo scale-out deve solo avviarle, evitando di pagare per capacità in esecuzione. Il predictive scaling e lo scaling pianificato dipendono da pattern ricorrenti, che questi picchi imprevedibili non hanno.","optionExplanations":["Un minimo più alto mantiene sempre in esecuzione istanze aggiuntive, cosa che l'azienda vuole evitare.","Il predictive scaling si basa su pattern di carico ricorrenti, quindi non può anticipare picchi che arrivano senza preavviso.","Una scheduled action aiuta solo in orari noti e mantiene comunque in esecuzione istanze aggiuntive, che si verifichi o meno un picco.","Corretto — Le istanze arrestate e pre-inizializzate in un warm pool possono entrare rapidamente in servizio senza il costo di capacità di riserva in esecuzione."]},
  "1214": {"h":"e531fe04","question":"Una piattaforma di pagamenti esegue un deployment active-passive in due Region AWS. Durante un incidente, gli operatori devono poter spostare in modo affidabile tutto il traffico sulla Region di standby, anche se alcune operazioni del control plane AWS nella Region principale sono compromesse, e dei controlli di sicurezza devono impedire che entrambe le Region vengano disattivate contemporaneamente. Quale soluzione soddisferà questi requisiti?","options":["Usare record di failover Route 53 e far aggiornare i record agli operatori tramite la console durante un incidente.","Usare i routing control di Amazon Route 53 Application Recovery Controller con safety rule per cambiare Region.","Usare record weighted di Route 53 e far modificare agli operatori i pesi di ciascuna Region durante un incidente.","Usare l'origin failover di CloudFront tra i load balancer di entrambe le Region per spostare il traffico automaticamente."],"explanation":"I routing control di Route 53 Application Recovery Controller funzionano come interruttori on/off ad alta disponibilità, supportati da un data plane distribuito su più Region, e le safety rule possono imporre che almeno una Region resti attiva. Modificare i record DNS durante un incidente si basa sul control plane di Route 53, ed è proprio da questo che l'azienda vuole evitare di dipendere.","optionExplanations":["Modificare i record durante un incidente dipende dal control plane di Route 53 e non offre safety rule contro gli errori.","Corretto — I routing control di ARC forniscono uno spostamento del traffico affidabile basato sul data plane, e le safety rule impediscono stati non sicuri.","Anche cambiare i pesi è un'operazione di control plane e non offre alcuna protezione contro l'invio del traffico verso nessuna destinazione.","L'origin failover di CloudFront reagisce agli errori richiesta per richiesta e non offre agli operatori un failover regionale controllato con controlli di sicurezza."]},
  "1215": {"h":"baa63c50","question":"Uno sviluppatore ha eseguito per errore, 15 minuti fa, un'istruzione DELETE senza clausola WHERE su un DB cluster Amazon Aurora MySQL di produzione. L'azienda vuole riportare il cluster esistente allo stato immediatamente precedente all'errore il più rapidamente possibile, senza creare un nuovo cluster né modificare gli endpoint dell'applicazione. Il Backtrack è stato abilitato alla creazione del cluster. Cosa dovrebbe fare un solutions architect?","options":["Ripristinare il cluster a un point in time appena precedente al DELETE e puntare l'applicazione al nuovo cluster.","Promuovere una delle Aurora Replica del cluster a writer in modo che serva i dati originali.","Ripristinare lo snapshot automatico più recente in un nuovo cluster e ricopiare in produzione le righe eliminate.","Eseguire il Backtrack del DB cluster esistente a un momento appena precedente all'esecuzione dell'istruzione DELETE."],"explanation":"Il Backtrack di Aurora MySQL riavvolge sul posto il cluster esistente a un point in time precedente, di solito in pochi minuti, senza nuovo cluster né cambio di endpoint. Il point-in-time recovery è un metodo di ripristino valido, ma crea sempre un nuovo cluster, il che richiede di modificare gli endpoint dell'applicazione e richiede più tempo.","optionExplanations":["Il point-in-time recovery crea un nuovo cluster, quindi gli endpoint dell'applicazione devono cambiare e il ripristino richiede più tempo.","Le Aurora Replica condividono lo stesso volume del cluster, quindi le righe eliminate non esistono più nemmeno su nessuna replica.","Ripristinare uno snapshot e ricopiare le righe è lento, soggetto a errori e perde le modifiche apportate dopo lo snapshot.","Corretto — Il Backtrack riavvolge sul posto lo stesso cluster fino a poco prima dell'errore, rapidamente e senza cambi di endpoint."]},
  "1216": {"h":"ab7c2415","question":"Un'azienda esegue un'istanza database Amazon RDS for MySQL Multi-AZ in una Region. Per il disaster recovery, ha bisogno di un RPO di pochi minuti nel caso in cui l'intera Region diventi indisponibile e vuole poter attivare rapidamente un database scrivibile in una seconda Region. Quale soluzione soddisferà questi requisiti nel modo PIÙ conveniente?","options":["Creare una read replica cross-Region e promuoverla a istanza autonoma in caso di disastro.","Copiare ogni giorno gli snapshot automatici nella seconda Region e ripristinare l'ultimo snapshot durante un disastro.","Aggiungere un secondo standby Multi-AZ in un'altra Availability Zone della Region principale per una protezione aggiuntiva.","Migrare il database su Amazon Aurora e aggiungere un cluster secondario Aurora global database nella seconda Region."],"explanation":"Una read replica cross-Region usa la replica asincrona, mantenendo in genere l'RPO nell'ordine dei minuti, e può essere promossa a istanza autonoma scrivibile durante un disastro regionale. Le copie giornaliere degli snapshot costano meno, ma danno un RPO fino a un giorno, che non soddisfa il requisito.","optionExplanations":["Corretto — Una replica cross-Region replicata in modo asincrono offre un RPO di minuti e può essere promossa per diventare scrivibile.","Le copie giornaliere degli snapshot danno un RPO fino a 24 ore e un ripristino più lento, che non soddisfa l'obiettivo.","Qualsiasi standby aggiuntivo nella stessa Region non protegge dalla perdita dell'intera Region.","Un Aurora global database soddisfa l'RPO, ma richiede una migrazione e costa più del necessario per un RPO nell'ordine dei minuti."]},
  "1217": {"h":"eb1b674a","question":"Un deployment difettoso ha corrotto alcuni item di una tabella Amazon DynamoDB in un momento sconosciuto negli ultimi tre giorni. Dai log applicativi il team può identificare il momento esatto in cui la release difettosa ha iniziato a scrivere dati e deve ripristinare la tabella allo stato di quel secondo. Quale funzionalità avrebbe dovuto abilitare l'azienda per soddisfare questo requisito?","options":["Backup on-demand della tabella creati da un piano AWS Backup giornaliero.","DynamoDB Streams con una funzione Lambda che copia le modifiche in Amazon S3.","Il point-in-time recovery, ripristinando la tabella in una nuova tabella a quel secondo.","Una replica DynamoDB global table in una seconda Region che contiene i dati precedenti."],"explanation":"Il point-in-time recovery esegue il backup continuo della tabella e può ripristinarla a qualsiasi secondo all'interno della finestra di ripristino, creando una nuova tabella in quello stato. I backup on-demand giornalieri catturano solo momenti fissi, quindi i dati scritti tra il backup e la release difettosa andrebbero persi.","optionExplanations":["I backup giornalieri catturano solo i momenti in cui vengono eseguiti, quindi non possono ripristinare al secondo esatto prima della corruzione.","Copiare i record dello stream in S3 richiederebbe codice personalizzato per ricostruire la tabella e conserva solo una cronologia limitata.","Corretto — Il PITR ripristina la tabella a qualsiasi secondo entro il periodo di retention, corrispondendo al momento esatto richiesto.","Le repliche delle global table replicano le scritture, comprese quelle corrotte, entro circa un secondo, quindi non offrono una copia storica."]},
  "1218": {"h":"5924b80b","question":"Un'azienda archivia gli ordini dei clienti in una tabella Amazon DynamoDB. Ogni volta che viene inserito un nuovo ordine, l'azienda deve inviare un'email di conferma e aggiornare un servizio di punti fedeltà. L'applicazione degli ordini non deve essere modificata per chiamare questi servizi, e i guasti del sistema email non devono influire sulla scrittura degli ordini. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Pianificare ogni minuto una funzione Lambda che esegue lo scan della tabella alla ricerca di nuovi ordini e chiama entrambi i servizi.","Abilitare DynamoDB Streams sulla tabella e usare una funzione Lambda attivata dai record dei nuovi item.","Esportare la tabella in Amazon S3 ogni ora ed elaborare l'export con un job AWS Glue per individuare i nuovi ordini.","Aggiungere un cluster DynamoDB Accelerator (DAX) e fargli notificare entrambi i servizi quando vengono scritti item."],"explanation":"DynamoDB Streams cattura in ordine le modifiche a livello di item, e un event source mapping Lambda elabora i record dei nuovi item in modo asincrono rispetto al percorso di scrittura, quindi la scrittura degli ordini non risente dei guasti a valle. Eseguire lo scan della tabella ogni minuto è inefficiente, consuma capacità di lettura e rende inaffidabile il rilevamento dei nuovi item.","optionExplanations":["Gli scan ripetuti consumano capacità di lettura, aggiungono ritardo e richiedono logica personalizzata per tracciare quali ordini sono nuovi.","Corretto — Streams più un trigger Lambda reagisce a ogni inserimento senza modificare l'applicazione e tiene i guasti a valle fuori dal percorso di scrittura.","Gli export orari aggiungono lunghi ritardi e usano strumenti batch per quella che dovrebbe essere una reazione quasi in tempo reale.","DAX è una cache di lettura in memoria e non ha alcuna capacità di notificare altri servizi delle scritture."]},
  "1219": {"h":"bde02af3","question":"Un'azienda finanziaria replica le conferme di negoziazione da un bucket Amazon S3 in una Region a un bucket in un'altra Region. Una nuova normativa impone all'azienda di dimostrare che la replica si completa entro un tempo prevedibile e garantito contrattualmente, e di ricevere un avviso quando la replica degli oggetti richiede più tempo del previsto. Quale soluzione soddisferà questi requisiti?","options":["Usare S3 Batch Replication in modo pianificato per copiare gli oggetti che non sono stati replicati in tempo.","Configurare S3 Event Notifications per ogni upload e confrontare i timestamp in una funzione Lambda.","Eseguire task AWS DataSync ogni pochi minuti per copiare i nuovi oggetti nel bucket della seconda Region.","Abilitare S3 Replication Time Control sulla regola di replica e usarne le metriche e gli eventi di replica."],"explanation":"S3 Replication Time Control replica la maggior parte degli oggetti entro un tempo definito, garantito da un service level agreement, e fornisce metriche ed eventi di replica per gli oggetti che superano la soglia. Batch Replication è pensata per recuperare oggetti esistenti o falliti, non per garantire il tempo di replica dei nuovi upload.","optionExplanations":["Batch Replication recupera su richiesta oggetti esistenti o falliti e non offre garanzie di tempo né avvisi per i nuovi upload.","Un confronto personalizzato dei timestamp aggiunge codice da mantenere e non offre comunque alcuna garanzia contrattuale sul tempo di replica.","I task DataSync pianificati sostituiscono la replica nativa con copie batch e non offrono un tempo di replica garantito da SLA.","Corretto — Replication Time Control fornisce un tempo di replica garantito da SLA, oltre a metriche e notifiche per gli oggetti in ritardo."]},
  "1220": {"h":"e96c9375","question":"Un'applicazione archivia file di progettazione in un bucket Amazon S3. Di recente un bug ha sovrascritto centinaia di file con contenuto vuoto e l'azienda non è riuscita a recuperarli. L'azienda vuole poter ripristinare qualsiasi oggetto a uno stato precedente per 30 giorni dopo che è stato sovrascritto o eliminato, mantenendo sotto controllo i costi di storage. Quale soluzione soddisferà questi requisiti?","options":["Configurare la Cross-Region Replication verso un altro bucket in modo che esista una seconda copia di ogni oggetto.","Abilitare S3 Object Lock in modalità compliance con un periodo di retention di 30 giorni su ogni oggetto.","Abilitare S3 Versioning e aggiungere una regola di lifecycle che fa scadere le versioni non correnti dopo 30 giorni.","Creare un piano AWS Backup giornaliero per il bucket con backup conservati per 30 giorni."],"explanation":"S3 Versioning conserva le versioni precedenti quando gli oggetti vengono sovrascritti o eliminati, quindi è possibile ripristinare qualsiasi stato precedente, e una regola di lifecycle sulle versioni non correnti limita per quanto tempo le vecchie versioni generano costi di storage. La sola replica copierebbe nella destinazione anche le sovrascritture vuote.","optionExplanations":["La replica copia le nuove scritture, comprese le sovrascritture errate, quindi il secondo bucket conterrebbe gli stessi file vuoti.","Object Lock in modalità compliance impedisce di eliminare le versioni bloccate, il che è più rigido del necessario e blocca le pulizie legittime.","Corretto — Il Versioning conserva le versioni precedenti per il ripristino, e far scadere le versioni non correnti dopo 30 giorni controlla i costi.","I backup giornalieri non possono recuperare le modifiche apportate tra un backup e l'altro, quindi i file modificati e sovrascritti nello stesso giorno andrebbero persi."]},
  "1221": {"h":"8edf0b4d","question":"Un'azienda esegue un sistema di content management su istanze EC2 che condividono un file system Amazon EFS. Per il disaster recovery, l'azienda ha bisogno di una copia in sola lettura del file system in una seconda Region, mantenuta aggiornata con un RPO di minuti e che possa essere resa rapidamente scrivibile durante un'interruzione regionale. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Configurare la replica EFS per creare un file system replica nella seconda Region ed eseguire il failover su di esso.","Creare un piano AWS Backup che copia ogni ora i backup EFS nella seconda Region.","Pianificare task AWS DataSync che copiano i file modificati in un file system nella seconda Region.","Eseguire su un'istanza EC2 un job rsync che sincronizza i file nella seconda Region ogni pochi minuti."],"explanation":"La replica EFS mantiene continuamente un file system replica in sola lettura in un'altra Region, con la maggior parte delle modifiche replicate entro pochi minuti, e la replica può essere resa scrivibile eliminando la configurazione di replica durante il failover. Le copie orarie di AWS Backup non possono raggiungere un RPO di minuti.","optionExplanations":["Corretto — La replica nativa di EFS mantiene una replica cross-Region con un RPO di minuti e un failover semplice.","Le copie di backup orarie danno un RPO fino a un'ora e richiedono un ripristino prima che i dati possano essere usati.","I task DataSync pianificati funzionano, ma aggiungono pianificazione e monitoraggio dei task che la replica nativa evita.","Un job rsync autogestito su un'istanza aggiunge un single point of failure e una manutenzione continua."]},
  "1222": {"h":"0b8c136b","question":"Un'azienda sta spostando su AWS le condivisioni file dipartimentali basate su Windows. Gli utenti vi accedono tramite SMB con permessi di Active Directory. Le condivisioni file devono restare disponibili automaticamente in caso di guasto di una Availability Zone, e l'azienda non vuole gestire server Windows. Quale soluzione soddisferà questi requisiti?","options":["Distribuire Amazon FSx for Windows File Server come file system Single-AZ con backup automatici giornalieri.","Usare un file system Amazon EFS con storage regionale montato in rete dai client Windows.","Eseguire file server Windows su istanze EC2 in due Availability Zone con DFS Replication tra di essi.","Distribuire Amazon FSx for Windows File Server come file system Multi-AZ aggiunto ad Active Directory."],"explanation":"Un file system FSx for Windows File Server Multi-AZ esegue un file server preferito e uno di standby in Availability Zone diverse ed esegue il failover automaticamente, integrandosi con Active Directory tramite SMB. Un deployment Single-AZ con backup richiederebbe un ripristino dopo il guasto di una Availability Zone.","optionExplanations":["Un file system Single-AZ diventa indisponibile se la sua zona si guasta, e il ripristino da backup è un recupero manuale e lento.","Amazon EFS usa il protocollo NFS e non è supportato per client Windows SMB con permessi di Active Directory.","I server Windows autogestiti con DFS Replication funzionano, ma richiedono la gestione dei server che l'azienda vuole evitare.","Corretto — FSx for Windows Multi-AZ fornisce condivisioni SMB gestite con integrazione AD e failover automatico tra le zone."]},
  "1223": {"h":"ee56cd46","question":"Un'azienda usa AWS Backup per proteggere database Amazon RDS e volumi Amazon EBS. Gli auditor hanno chiesto prove periodiche che i backup possano effettivamente essere ripristinati e che i tempi di ripristino rispettino l'RTO documentato. L'azienda vuole ridurre al minimo l'impegno manuale. Quale soluzione soddisferà questi requisiti?","options":["Attivare i report di AWS Backup Audit Manager che mostrano se ogni risorsa è coperta da un piano di backup.","Creare piani di restore testing di AWS Backup che ripristinano periodicamente i recovery point e registrano i risultati.","Chiedere agli operatori di ripristinare ogni trimestre un backup a caso e documentare il tempo impiegato in un runbook.","Abilitare la copia cross-Region in ogni piano di backup in modo che sia sempre disponibile una seconda copia di ogni backup."],"explanation":"Il restore testing di AWS Backup ripristina automaticamente e in modo pianificato i recovery point selezionati, può eseguire una validazione, registra le durate e i risultati dei ripristini e poi elimina le risorse di test. I report di Audit Manager dimostrano che i backup esistono e rispettano le policy, ma non che possano essere ripristinati.","optionExplanations":["I report di Audit Manager mostrano la copertura dei backup e la conformità, ma non eseguono né cronometrano alcun ripristino.","Corretto — I piani di restore testing automatizzano i ripristini periodici, registrano tempi ed esiti dei ripristini e poi rimuovono le risorse di test.","I ripristini manuali trimestrali aggiungono impegno operativo e forniscono prove solo saltuarie.","Una seconda copia migliora la durabilità, ma non fornisce alcuna prova che i backup possano essere ripristinati entro l'RTO."]},
  "1224": {"h":"0d6db503","question":"Un'azienda esegue un'applicazione web su AWS Elastic Beanstalk con il database in un'istanza Amazon RDS separata. A volte le release falliscono in modi che vengono notati solo dopo il deployment. Il team vuole testare ogni nuova versione in un ambiente completo simile alla produzione prima che riceva traffico, e poter eseguire il rollback quasi istantaneamente. Quale approccio di deployment soddisferà questi requisiti?","options":["Usare un deployment rolling che aggiorna uno alla volta gruppi di istanze nell'ambiente esistente.","Usare un deployment all-at-once e, se necessario, ridistribuire la versione precedente dalle application version.","Distribuire su un ambiente clonato e scambiare gli URL degli ambienti, scambiandoli di nuovo se emerge un problema.","Usare un deployment immutable che avvia nuove istanze in un Auto Scaling group temporaneo all'interno dell'ambiente."],"explanation":"Un deployment blue/green su Elastic Beanstalk distribuisce la nuova versione in un ambiente separato che può essere testato sul proprio URL, poi scambia i CNAME per spostare il traffico, e il rollback è un altro scambio di URL. I deployment immutable sono sicuri, ma avvengono all'interno dello stesso ambiente e non consentono di testare la nuova versione prima che serva traffico di produzione.","optionExplanations":["I deployment rolling mescolano le versioni in produzione e richiedono di ridistribuire la vecchia versione per il rollback.","I deployment all-at-once causano downtime e un rollback lento, perché la vecchia versione deve essere distribuita di nuovo.","Corretto — Il blue/green con scambio di URL consente al team di testare prima il nuovo ambiente e di eseguire il rollback con un nuovo scambio.","I deployment immutable aggiungono nuove istanze all'ambiente attivo, quindi la nuova versione non viene prima testata separatamente e il rollback è più lento."]},
  "1225": {"h":"e6efd85b","question":"Un'azienda deve distribuire le stesse risorse di base, inclusi ruoli IAM, allarmi Amazon CloudWatch e regole AWS Config, in ogni account della propria organizzazione in tre Region. Quando un nuovo account entra in una specifica unità organizzativa, la baseline deve essere distribuita automaticamente. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Eseguire una pipeline CI/CD che scorre ogni account e Region e distribuisce uno stack CloudFormation.","Usare CloudFormation StackSets con permessi service-managed e deployment automatico sull'OU.","Condividere il template CloudFormation tramite AWS Resource Access Manager in modo che ogni account lo distribuisca.","Scrivere una funzione Lambda attivata da EventBridge che distribuisce le risorse quando viene creato un account."],"explanation":"CloudFormation StackSets con permessi service-managed distribuisce un singolo template su molti account e Region in AWS Organizations, e il deployment automatico aggiunge lo stack agli account che entrano nell'OU di destinazione. Una pipeline o una funzione Lambda personalizzate potrebbero farlo, ma richiedono di costruire e mantenere una logica di deployment cross-account.","optionExplanations":["Una pipeline personalizzata deve gestire da sé credenziali, retry e nuovi account, il che aggiunge manutenzione.","Corretto — StackSets distribuisce su più account e Region a partire da un unico template e copre automaticamente i nuovi account nell'OU.","AWS RAM non condivide template CloudFormation, e ogni account dovrebbe comunque distribuire lo stack da sé.","Un sistema di deployment personalizzato basato su Lambda aggiunge codice da mantenere e duplica ciò che StackSets offre nativamente."]},
  "1226": {"h":"247c72ee","question":"Un'azienda esegue un'applicazione di trading basata su TCP dietro Network Load Balancer in due Region. I client si connettono tramite indirizzo IP e molti memorizzano in cache i risultati DNS per lunghi periodi, quindi il failover basato su DNS si è rivelato troppo lento. L'azienda ha bisogno che il traffico si sposti sulla Region integra entro pochi secondi in caso di guasto di una Region. Quale soluzione soddisferà questi requisiti?","options":["Usare AWS Global Accelerator con un endpoint group per Region e i suoi indirizzi IP anycast statici.","Ridurre il TTL dei record di failover Route 53 in modo che i client aggiornino più spesso le risposte DNS.","Usare Amazon CloudFront con un origin group che contiene i Network Load Balancer di entrambe le Region.","Assegnare un indirizzo Elastic IP al load balancer principale e riassegnarlo alla seconda Region durante il failover."],"explanation":"Global Accelerator fornisce indirizzi IP anycast statici che i client usano direttamente, esegue gli health check degli endpoint in ciascuna Region e sposta il traffico sugli endpoint group integri in pochi secondi senza dipendere dalla cache DNS. Abbassare i TTL non aiuta i client che ignorano i TTL e memorizzano in cache i risultati DNS.","optionExplanations":["Corretto — Gli IP statici e il routing basato sullo stato di salute di Global Accelerator spostano rapidamente il traffico tra le Region senza dipendere dal DNS.","I client che memorizzano in cache i risultati DNS per lunghi periodi ignorano i TTL bassi, quindi per loro il failover resterebbe lento.","CloudFront è pensato per la distribuzione di contenuti HTTP e HTTPS, non per connessioni TCP arbitrarie verso un'applicazione di trading.","Gli indirizzi Elastic IP sono risorse regionali e non possono essere spostati su un load balancer in un'altra Region."]},
  "1227": {"h":"8e993a82","question":"Un'azienda ha progettato un'applicazione multi-AZ con Auto Scaling, Aurora Replica e health check, ma non ha mai verificato come si comporta il sistema quando le istanze vengono terminate o una Availability Zone subisce un degrado. L'azienda vuole eseguire esperimenti controllati che si interrompano automaticamente se i tassi di errore visibili ai clienti salgono troppo. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Scrivere script che terminano istanze casuali in modo pianificato e far osservare le dashboard agli operatori.","Usare esperimenti AWS Fault Injection Service con allarmi CloudWatch configurati come stop condition.","Usare AWS Resilience Hub per calcolare l'RTO e l'RPO stimati dell'applicazione a partire dalla sua progettazione.","Eseguire load test con uno strumento di terze parti da istanze EC2 per verificare che il gruppo scali correttamente."],"explanation":"AWS Fault Injection Service esegue esperimenti gestiti di fault injection, come la terminazione di istanze o l'interruzione di una Availability Zone, e li interrompe automaticamente quando un allarme CloudWatch usato come stop condition entra in stato di allarme. Resilience Hub valuta e monitora la resilienza rispetto agli obiettivi, ma non inietta di per sé i guasti reali descritti.","optionExplanations":["Gli script di terminazione personalizzati non hanno controlli di sicurezza integrati e dipendono dagli operatori per interrompere manualmente gli esperimenti.","Corretto — FIS fornisce fault injection gestita con stop condition basate su allarmi per proteggere i clienti durante gli esperimenti.","Resilience Hub stima la resilienza a partire dalla configurazione dell'applicazione, ma non esegue gli esperimenti di guasto controllati richiesti.","I load test verificano lo scaling sotto traffico, ma non simulano guasti di istanze o di Availability Zone."]},
  "1228": {"h":"e8e47ade","question":"Un'azienda collega il proprio data center al VPC con una singola connessione AWS Direct Connect. Un recente taglio della fibra ha causato un'interruzione completa del traffico ibrido. L'azienda ha bisogno che la connettività prosegua automaticamente in caso di guasto della connessione Direct Connect; durante un guasto sono accettabili una banda ridotta e una latenza maggiore. Quale soluzione soddisferà questi requisiti nel modo PIÙ conveniente?","options":["Ordinare una seconda connessione Direct Connect in una diversa Direct Connect location come percorso di standby.","Aggiungere una seconda virtual interface sulla connessione Direct Connect esistente per un routing ridondante.","Configurare una connessione AWS Site-to-Site VPN su internet come backup del collegamento Direct Connect.","Usare attachment AWS Transit Gateway Connect per creare tunnel ridondanti sulla stessa connessione."],"explanation":"Una Site-to-Site VPN su internet è un percorso di backup a basso costo; con BGP il traffico privilegia Direct Connect ed esegue automaticamente il failover sulla VPN quando la connessione cade. Una seconda connessione Direct Connect in un'altra location offre la massima resilienza, ma costa molto più del necessario quando una banda ridotta è accettabile.","optionExplanations":["Una seconda connessione Direct Connect è più resiliente, ma notevolmente più costosa di quanto giustifichino i requisiti.","Le virtual interface aggiuntive si basano comunque sulla stessa connessione fisica, quindi un taglio della fibra le farebbe cadere tutte.","Corretto — Una VPN di backup fornisce un failover automatico su internet a basso costo, accettando prestazioni ridotte durante le interruzioni.","Gli attachment Connect che passano sulla stessa connessione Direct Connect ne condividono il punto di guasto fisico."]},
  "1229": {"h":"3914fb5a","question":"Una funzione Lambda elabora i record di un data stream Amazon Kinesis. Occasionalmente un singolo record malformato fa fallire la funzione. Lambda ritenta allora ripetutamente l'intero batch, l'elaborazione di quello shard si ferma finché il record non scade e i dati a valle accumulano un forte ritardo. L'azienda vuole che i record validi continuino a fluire e che i record falliti vengano conservati per l'analisi. Quale combinazione di passaggi soddisferà questi requisiti? (Seleziona DUE)","options":["Aumentare il numero di shard dello stream in modo che il record malformato coinvolga meno dati.","Configurare l'event source mapping per dividere in due un batch che fallisce e ritentare ciascuna metà separatamente.","Aumentare il timeout della funzione in modo che abbia più tempo per elaborare il record malformato.","Impostare un numero massimo di retry sull'event source mapping e aggiungere una destinazione on-failure come SQS.","Collegare una dead-letter queue Amazon SQS direttamente al data stream Kinesis per i record falliti."],"explanation":"Dividere in due un batch che fallisce isola il record difettoso, così i record validi che lo circondano vengono elaborati, e limitare i retry con una destinazione on-failure consente allo shard di proseguire inviando i dettagli dei record falliti a SQS o SNS. I data stream Kinesis non hanno dead-letter queue proprie; la gestione dei fallimenti si configura sull'event source mapping di Lambda.","optionExplanations":["Più shard distribuiscono i dati, ma un record malformato continua a bloccare il proprio shard a tempo indeterminato.","Corretto — Dividere il batch in caso di errore isola il record difettoso, così i record validi dello stesso batch vengono elaborati.","Il record fallisce a causa del suo contenuto, non per mancanza di tempo, quindi un timeout più lungo rallenta solo i retry.","Corretto — Limitare i retry e inviare i dettagli dei record falliti a una destinazione on-failure sblocca lo shard e conserva i fallimenti.","I data stream Kinesis non hanno un'impostazione di dead-letter queue; i record falliti sono gestiti dalla destinazione dell'event source mapping."]},
  "1230": {"h":"303b37f6","question":"Dopo un incidente ransomware presso un'azienda dello stesso settore, un'azienda vuole assicurarsi che i propri recovery point di AWS Backup non possano essere eliminati né subire una riduzione della retention, nemmeno da parte di un amministratore le cui credenziali nell'account di produzione siano compromesse. Quale combinazione di passaggi soddisferà questi requisiti? (Seleziona DUE)","options":["Applicare AWS Backup Vault Lock in modalità compliance ai vault che archiviano i recovery point.","Abilitare S3 Versioning sui backup vault in modo che i recovery point eliminati possano essere recuperati.","Copiare i recovery point in un backup vault in un account separato dell'organizzazione dedicato ai backup.","Aumentare il periodo di retention di ogni regola di backup in modo che i recovery point vengano conservati più a lungo.","Crittografare i recovery point con una AWS managed key in modo che solo AWS Backup possa leggerli."],"explanation":"Vault Lock in modalità compliance rende immutabili le impostazioni di retention del vault e impedisce a chiunque, inclusi gli amministratori e l'utente root, di eliminare anticipatamente i recovery point. Copiare i backup in un vault di un account separato e strettamente controllato li isola dalle credenziali compromesse nell'account di produzione.","optionExplanations":["Corretto — Vault Lock in modalità compliance impedisce a qualsiasi utente di eliminare i recovery point o di ridurne la retention.","I backup vault non sono bucket S3, quindi su di essi non è possibile abilitare S3 Versioning.","Corretto — Una copia in un account di backup separato è isolata dalle credenziali compromesse nell'account di produzione.","Una retention più lunga non impedisce a un amministratore compromesso di eliminare i recovery point o di modificare le regole.","La crittografia con una AWS managed key non impedisce l'eliminazione e complica la copia dei backup in un altro account."]},
  "1231": {"h":"96f9c8d8","question":"Un'azienda esegue una flotta di elaborazione batch stateless su Spot Instances in un Auto Scaling group che usa un solo tipo di istanza in una sola Availability Zone. Quando la capacità Spot per quel tipo viene recuperata, molte istanze vengono interrotte contemporaneamente e il lavoro si blocca finché la capacità non torna disponibile. Quale combinazione di passaggi migliorerà la resilienza della flotta mantenendo il risparmio delle Spot? (Seleziona DUE)","options":["Usare una mixed instances policy con diversi tipi di istanza distribuiti su più Availability Zone.","Passare al tipo di istanza più grande disponibile in modo che servano complessivamente meno istanze.","Allungare l'health check grace period in modo che le istanze interrotte restino in servizio più a lungo.","Aggiungere una scheduled action che aumenta la capacità desiderata nelle ore in cui si verificano le interruzioni.","Abilitare il Capacity Rebalancing in modo che le Spot Instances a rischio vengano sostituite proattivamente prima dell'interruzione."],"explanation":"Diversificare su molti tipi di istanza e Availability Zone con un'allocazione price-capacity-optimized attinge a più capacity pool Spot, quindi un recupero in un pool coinvolge solo una parte della flotta. Il Capacity Rebalancing avvia istanze sostitutive quando le Spot Instances ricevono una rebalance recommendation, prima che vengano interrotte.","optionExplanations":["Corretto — Diversificare tipi di istanza e zone distribuisce la flotta su molti capacity pool Spot e riduce le interruzioni simultanee.","Un unico tipo di istanza più grande attinge comunque a pochi capacity pool, quindi le interruzioni restano concentrate.","Le Spot Instances interrotte vengono recuperate da AWS indipendentemente dalle impostazioni degli health check.","Gli aumenti di capacità pianificati dallo stesso pool verranno interrotti allo stesso modo e non risolvono la causa principale.","Corretto — Il Capacity Rebalancing sostituisce proattivamente le Spot Instances a rischio elevato di interruzione."]},
  "1232": {"h":"f66a4536","question":"Una funzione Lambda elabora batch di messaggi da una coda Amazon SQS standard. Quando un messaggio di un batch fallisce, l'intero batch torna nella coda, quindi anche i messaggi elaborati con successo vengono rielaborati e nel database compaiono record duplicati. L'azienda vuole mantenere l'attuale dimensione del batch per il throughput. Quale combinazione di passaggi soddisferà questi requisiti? (Seleziona DUE)","options":["Ridurre la dimensione del batch a un solo messaggio in modo che ogni fallimento riguardi un unico messaggio.","Abilitare le partial batch response in modo che la funzione segnali per il retry solo i messaggi falliti.","Aumentare il visibility timeout della coda in modo che i batch falliti vengano ritentati meno spesso.","Rendere idempotente la logica di elaborazione in modo che un messaggio elaborato due volte non abbia effetti aggiuntivi.","Passare a una coda FIFO in modo che i messaggi vengano sempre consegnati alla funzione una sola volta."],"explanation":"Segnalare i fallimenti dei singoli elementi del batch consente a Lambda di eliminare i messaggi elaborati con successo e di restituire alla coda solo quelli falliti, eliminando gran parte della rielaborazione, e l'elaborazione idempotente protegge dai duplicati che la consegna at-least-once può comunque causare. Una dimensione del batch pari a uno eviterebbe anch'essa la rielaborazione del batch, ma sacrificherebbe il throughput che l'azienda vuole mantenere.","optionExplanations":["Una dimensione del batch pari a uno evita i retry del batch, ma riduce notevolmente il throughput, che l'azienda vuole mantenere.","Corretto — Le partial batch response restituiscono alla coda solo i messaggi falliti, quindi quelli elaborati con successo non vengono rielaborati.","Un visibility timeout più lungo ritarda solo i retry; l'intero batch verrebbe comunque rielaborato.","Corretto — L'elaborazione idempotente garantisce che eventuali consegne duplicate residue non creino record duplicati.","La deduplicazione FIFO si applica agli invii dei producer; un batch fallito verrebbe comunque riconsegnato e rielaborato."]},
  "1233": {"h":"291bcc53","question":"Un'azienda esegue un servizio Amazon ECS su un cluster basato su EC2. L'Auto Scaling group del cluster avvia istanze in una sola subnet e il servizio usa una placement strategy binpack. Un'interruzione di una Availability Zone ha recentemente fermato tutti i task del servizio. Quale combinazione di modifiche renderà il servizio resiliente alla perdita di una Availability Zone? (Seleziona DUE)","options":["Cambiare la placement strategy del servizio per distribuire (spread) i task uniformemente tra le Availability Zone.","Usare tipi di istanza più grandi in modo che ogni container instance possa eseguire più task del servizio.","Aggiungere un placement constraint in modo che ogni task venga eseguito su una container instance distinta del cluster.","Aumentare il numero desiderato di task in modo che più copie del servizio vengano eseguite nella subnet esistente.","Usare un capacity provider il cui Auto Scaling group si estende su subnet in più Availability Zone."],"explanation":"Il cluster ha bisogno di container instance in più Availability Zone, fornite da un capacity provider basato su un Auto Scaling group che si estende su più subnet con managed scaling, e il servizio deve distribuire i task tra quelle zone invece di concentrarli. Un constraint distinct-instance distribuisce i task tra gli host, ma non serve se tutti gli host si trovano nella stessa zona.","optionExplanations":["Corretto — Una placement strategy spread per AZ distribuisce i task tra le zone, così il guasto di una zona lascia in esecuzione gli altri task.","Istanze più grandi concentrano ancora più task su meno host nella stessa zona, aumentando l'impatto di un guasto.","Le istanze distinte distribuiscono i task tra gli host, ma tutti gli host restano nella stessa Availability Zone.","Più task nella stessa subnet condividono comunque un'unica Availability Zone e fallirebbero tutti insieme.","Corretto — Un capacity provider basato su un Auto Scaling group multi-AZ fornisce al cluster capacità in più zone."]},
  "1234": {"h":"0ff2359a","question":"Un'azienda esegue un job di riconciliazione notturno tramite cron su una singola istanza EC2. Il job è pacchettizzato come container e viene eseguito per circa due ore. Se all'orario pianificato l'istanza non è integra, il job non viene eseguito, e il team deve anche applicare le patch all'istanza. L'azienda vuole una soluzione resiliente con il MINOR carico operativo. Quale combinazione di passaggi soddisferà questi requisiti? (Seleziona DUE)","options":["Eseguire cron su due istanze EC2 in Availability Zone diverse, in modo che una possa eseguire il job se l'altra si guasta.","Creare una pianificazione Amazon EventBridge Scheduler che avvia il job all'orario richiesto ogni notte.","Eseguire il job containerizzato come task Amazon ECS su AWS Fargate avviato dalla pianificazione.","Pacchettizzare il job come funzione Lambda e invocarla dalla pianificazione per eliminare tutti i server.","Abilitare l'EC2 automatic recovery sull'istanza in modo che venga ripristinata se l'host ha un problema."],"explanation":"EventBridge Scheduler è uno scheduler gestito e ad alta disponibilità che può avviare direttamente un task ECS, ed eseguire il container esistente su Fargate elimina l'istanza da aggiornare e il single point of failure. Lambda non è adatta perché un job di due ore supera il tempo massimo di esecuzione di Lambda.","optionExplanations":["Due istanze con cron eseguirebbero entrambe il job, a meno di costruire un coordinamento personalizzato, ed entrambe richiederebbero comunque patch.","Corretto — EventBridge Scheduler è un servizio gestito e ad alta disponibilità che avvia il job secondo la pianificazione.","Corretto — Un task Fargate esegue il container esistente senza server da aggiornare e senza un singolo host che possa guastarsi.","Un job di due ore supera la durata massima di esecuzione di Lambda, quindi non può essere eseguito come singola invocazione di una funzione.","L'automatic recovery aiuta con alcuni guasti dell'host, ma mantiene una singola istanza che richiede comunque patch e può saltare delle esecuzioni."]},
  "1235": {"h":"df460df6","question":"Un team di machine learning addestra modelli su una flotta di istanze Amazon EC2 in una singola Availability Zone. Ogni epoca di addestramento esegue milioni di piccole richieste di lettura su un dataset in Amazon S3, e la latenza delle richieste in S3 Standard è diventata il collo di bottiglia principale. In caso di perdita, i dati possono essere ricreati da un sistema sorgente. Quale soluzione fornirà la latenza delle richieste PIÙ BASSA?","options":["Archiviare i dati in una directory bucket S3 Express One Zone nella Availability Zone delle istanze.","Abilitare S3 Transfer Acceleration sul bucket esistente e leggere tramite l'endpoint accelerato.","Spostare i dati in S3 Standard-Infrequent Access e leggerli in parallelo con byte-range fetch.","Inserire una distribuzione Amazon CloudFront davanti al bucket e leggere gli oggetti attraverso di essa."],"explanation":"S3 Express One Zone è una storage class ad alte prestazioni nelle directory bucket che offre una latenza delle richieste costante nell'ordine di pochi millisecondi, e collocarla nella stessa Availability Zone del compute riduce ulteriormente la latenza. La sua durabilità su una singola AZ è accettabile perché i dati possono essere ricreati. Transfer Acceleration ottimizza i trasferimenti a lunga distanza su internet, non la latenza delle richieste da compute nella stessa Region.","optionExplanations":["Corretto — S3 Express One Zone è progettato per workload sensibili alla latenza e con molte richieste, collocati insieme al compute in una sola AZ.","Transfer Acceleration instrada upload e download attraverso le edge location per client distanti; non riduce la latenza per richiesta delle istanze nella stessa Region.","S3 Standard-IA ha la stessa latenza delle richieste di S3 Standard più i costi di recupero, e i byte-range fetch non aiutano con milioni di piccoli oggetti.","CloudFront memorizza in cache i contenuti per gli utenti internet nelle edge location; aggiunge un passaggio per le istanze EC2 all'interno della Region e non è pensato per questo pattern di accesso."]},
  "1236": {"h":"fa634d15","question":"Un'azienda di streaming distribuisce segmenti video in tutto il mondo tramite Amazon CloudFront da un'origin personalizzata in esecuzione in una singola Region AWS. Durante gli eventi live più seguiti, molte regional edge cache richiedono gli stessi segmenti all'origin contemporaneamente, sovraccaricandola. L'azienda vuole ridurre il carico sull'origin e migliorare il cache hit ratio senza modificare l'applicazione. Cosa dovrebbe fare un solutions architect?","options":["Creare distribuzioni CloudFront aggiuntive per ogni continente che puntano agli stessi server di origin.","Abilitare CloudFront Origin Shield nella Region AWS più vicina all'origin.","Aumentare il TTL minimo e inoltrare all'origin tutti gli header di ogni richiesta.","Sostituire l'origin personalizzata con un bucket S3 con S3 Transfer Acceleration attivato."],"explanation":"Origin Shield aggiunge un livello di caching centralizzato davanti all'origin, così le richieste di tutte le regional edge cache vengono consolidate e una sola richiesta per oggetto raggiunge l'origin. Questo aumenta il cache hit ratio e protegge l'origin durante i picchi di traffico. Distribuzioni aggiuntive moltiplicherebbero, anziché ridurre, il numero di cache che richiedono contenuti all'origin.","optionExplanations":["Più distribuzioni creano più cache indipendenti che recuperano ciascuna i contenuti dall'origin, aumentando il carico sull'origin.","Corretto — Origin Shield accorpa le richieste delle regional edge cache in un unico livello di caching davanti all'origin.","Inoltrare tutti gli header frammenta la cache key e abbassa il hit ratio, aumentando il carico sull'origin.","Transfer Acceleration accelera i trasferimenti dal client a S3; non consolida i cache miss di CloudFront e richiede di riprogettare un'origin live."]},
  "1237": {"h":"0180b0c9","question":"Un'applicazione di elaborazione dati è eseguita su una singola istanza Amazon EC2 con quattro volumi EBS gp3 collegati. Il monitoraggio mostra che il throughput combinato dei volumi smette di crescere a un livello ben al di sotto della somma del throughput provisionato su ciascun volume, e nessun volume raggiunge il proprio limite. Quale azione aumenterà PIÙ probabilmente il throughput dello storage?","options":["Convertire i quattro volumi gp3 in volumi io2 Block Express con IOPS provisionati più elevati.","Unire i quattro volumi in striping in un array RAID 0 a livello di sistema operativo.","Passare a un tipo di istanza che offre una banda Amazon EBS dedicata più elevata.","Collegare quattro volumi gp3 aggiuntivi in modo che l'I/O sia distribuito su più dispositivi."],"explanation":"Ogni tipo di istanza EC2 ha una banda EBS massima, e quando il throughput aggregato dei volumi si stabilizza al di sotto di quanto provisionato per i volumi, il collo di bottiglia è l'istanza. Passare a un tipo di istanza EBS-optimized con una banda EBS più elevata elimina quel limite. Volumi più veloci, RAID 0 o più volumi passano comunque tutti attraverso lo stesso limite a livello di istanza.","optionExplanations":["I volumi non sono al loro limite, quindi volumi più veloci non aiutano finché il vincolo è la banda EBS dell'istanza.","RAID 0 aggrega le prestazioni dei volumi, ma il totale resta limitato dalla banda EBS dell'istanza.","Corretto — il collo di bottiglia è il limite di banda EBS a livello di istanza, quindi un tipo di istanza più grande o EBS-optimized alza il tetto.","Più volumi aggiungono throughput provisionato che l'istanza non può usare perché la sua banda EBS è già satura."]},
  "1238": {"h":"42621eed","question":"Un'azienda sta spostando su AWS applicazioni di ingegneria basate su Windows. Le applicazioni leggono e scrivono file condivisi tramite il protocollo SMB, si basano su permessi NTFS legati agli utenti di Active Directory e richiedono prestazioni SSD costanti e a bassa latenza. L'azienda non ha requisiti specifici di NetApp. Quale servizio di storage dovrebbe consigliare un solutions architect?","options":["Amazon EFS con la modalità di prestazioni General Purpose e throughput Elastic","Amazon S3 montato su ogni server tramite Mountpoint for Amazon S3","Amazon FSx for Lustre con un tipo di deployment persistent su SSD","Amazon FSx for Windows File Server con storage SSD aggiunto al dominio"],"explanation":"FSx for Windows File Server fornisce condivisioni file SMB native completamente gestite con ACL NTFS, integrazione con Active Directory e storage SSD per un accesso a bassa latenza. Amazon EFS è la scelta che può sembrare allettante per i file condivisi, ma supporta solo NFS e non è supportato per le istanze Windows.","optionExplanations":["Amazon EFS usa NFS e non è supportato sulle istanze Windows, quindi non può fornire condivisioni SMB con permessi NTFS.","Mountpoint for Amazon S3 è un client Linux per letture di oggetti ad alto throughput; non fornisce la semantica SMB o NTFS.","FSx for Lustre è un file system parallelo Linux per HPC e non offre accesso SMB né permessi NTFS basati su Active Directory.","Corretto — FSx for Windows File Server offre SMB nativo, ACL NTFS, integrazione con Active Directory e storage SSD."]},
  "1239": {"h":"2fa7f787","question":"Un'azienda acquisisce telemetria in uno stream Amazon Kinesis Data Streams che usa capacità provisioned. Il traffico è imprevedibile e durante i picchi i producer ricevono spesso errori di throughput superato. Cinque applicazioni consumer indipendenti leggono lo stesso stream, e la loro latenza di lettura aumenta man mano che si aggiungono consumer, perché competono per il throughput di lettura di ciascuno shard. Quale combinazione di azioni risolverà questi problemi con il MINOR carico operativo? (Seleziona DUE)","options":["Passare lo stream alla modalità di capacità on-demand in modo che scali automaticamente la capacità di scrittura.","Aumentare il periodo di retention dei dati dello stream in modo che i consumer abbiano più tempo per recuperare il ritardo.","Registrare i consumer per l'uso di enhanced fan-out in modo che ciascuno riceva un proprio throughput di lettura dedicato.","Sostituire lo stream con una coda Amazon SQS standard che tutti e cinque i consumer interrogano contemporaneamente.","Aggiungere una funzione Lambda pianificata che divide a metà ogni shard ogni mattina prima dell'orario lavorativo."],"explanation":"La modalità on-demand si adatta automaticamente a un throughput di scrittura imprevedibile senza dover gestire il numero di shard, eliminando il throttling dei producer. L'enhanced fan-out fornisce a ogni consumer registrato un throughput di lettura dedicato per shard, consegnato in modalità push, quindi l'aggiunta di consumer non rallenta più gli altri. Il resharding pianificato aggiunge carico operativo e non segue i picchi imprevedibili.","optionExplanations":["Corretto — la modalità di capacità on-demand scala automaticamente lo stream per un traffico di scrittura imprevedibile.","Una retention più lunga mantiene i dati disponibili più a lungo, ma non aggiunge capacità di scrittura né throughput di lettura.","Corretto — l'enhanced fan-out fornisce un throughput di lettura dedicato per consumer e per shard, con bassa latenza.","Con SQS ogni messaggio viene consumato da un solo consumer, quindi cinque applicazioni indipendenti non potrebbero elaborare ciascuna ogni record.","Un job di resharding pianificato è lavoro operativo personalizzato e non reagisce ai picchi che si verificano in momenti imprevedibili."]},
  "1240": {"h":"bd71a3d7","question":"Una piattaforma IoT scrive le letture dei sensori in una tabella Amazon DynamoDB che usa la data corrente come partition key e l'ID del sensore con un timestamp come sort key. Sebbene la tabella abbia un'ampia capacità di scrittura complessiva, le scritture subiscono throttling perché quasi tutto il traffico punta alla stessa chiave. Quale modifica distribuirà in modo PIÙ efficace il carico di scrittura?","options":["Aggiungere un suffisso casuale o calcolato alla partition key della data per distribuire le scritture su molti valori di chiave.","Aumentare la capacità di scrittura provisionata della tabella a un valore pari a diverse volte il picco attuale di scrittura.","Creare un global secondary index che usa l'ID del sensore come partition key per tutte le query.","Abilitare DynamoDB Accelerator (DAX) davanti alla tabella per assorbire il traffico di scrittura in ingresso."],"explanation":"Usare la data come partition key concentra tutte le scritture della giornata su un'unica chiave, creando una hot partition che subisce throttling indipendentemente dalla capacità della tabella. Il write sharding, aggiungendo un suffisso alla chiave, distribuisce le scritture su molte partizioni. Aggiungere capacità non risolve il problema, perché un singolo valore di partition key ha un proprio limite di throughput.","optionExplanations":["Corretto — il write sharding con un suffisso della chiave distribuisce le scritture di una hot key su molte partizioni.","Capacità aggiuntiva della tabella non alza il limite di throughput per partizione raggiunto da un singolo valore di hot key.","Un GSI aiuta le query su un altro attributo, ma le scritture sulla tabella base restano concentrate sulla hot key della data e il GSI non le alleggerisce.","DAX è una cache di lettura write-through; le scritture vanno comunque su DynamoDB e colpiscono comunque la stessa hot partition."]},
  "1241": {"h":"47d18030","question":"Un'applicazione di assistenza clienti archivia i ticket in una tabella Amazon DynamoDB con ticketId come partition key. Una nuova funzionalità deve elencare tutti i ticket associati a un determinato indirizzo email del cliente, e l'implementazione attuale esegue lo scan dell'intera tabella, che è lento e consuma grandi quantità di capacità di lettura. Quale soluzione migliorerà MAGGIORMENTE le prestazioni?","options":["Usare scan paralleli con più thread worker per leggere più rapidamente i segmenti della tabella.","Creare un global secondary index con l'email del cliente come partition key ed eseguire query su di esso.","Aggiungere un local secondary index con l'email del cliente come sort key della tabella esistente.","Esportare la tabella in Amazon S3 ogni ora ed eseguire invece le ricerche con Amazon Athena."],"explanation":"Un global secondary index con chiave sull'attributo email consente all'applicazione di eseguire una Query efficiente che legge solo gli item corrispondenti invece di eseguire lo scan dell'intera tabella. Un local secondary index può sembrare allettante, ma condivide la partition key della tabella base e può essere creato solo alla creazione della tabella, quindi non può cercare i ticket per email su tutti i ticketId.","optionExplanations":["Gli scan paralleli terminano prima, ma leggono comunque ogni item e consumano ancora più capacità di lettura tutta insieme.","Corretto — un GSI sull'attributo email trasforma lo scan in una Query mirata.","Un LSI mantiene ticketId come partition key, quindi non può eseguire query per email su tutti i ticket, e può essere definito solo alla creazione della tabella.","Gli export orari aggiungono latenza e risultati non aggiornati, e le query Athena sono più lente di una Query DynamoDB per le ricerche interattive."]},
  "1242": {"h":"f8b6d2f0","question":"Un'azienda esegue un cluster Amazon Aurora PostgreSQL con diverse Aurora Replica. L'applicazione web invia le sue brevi query di lettura al reader endpoint. Un team di data science ora deve eseguire lunghe query analitiche, e l'azienda vuole che tali query vengano eseguite solo su due replica più grandi, in modo da non rallentare il traffico web. Quale soluzione soddisfa questi requisiti?","options":["Indirizzare il team di data science al cluster endpoint in modo che le sue query vengano eseguite sull'istanza writer.","Fornire al team di data science il reader endpoint e aumentare le dimensioni di ogni replica del cluster.","Creare un custom endpoint Aurora che include solo le due replica più grandi per il team di analytics.","Creare read replica cross-Region e lasciare che il team di data science si connetta a quella più vicina."],"explanation":"Un custom endpoint Aurora bilancia le connessioni su un sottoinsieme scelto di istanze, quindi il workload analitico può essere isolato sulle due replica più grandi mentre l'applicazione web continua a usare le altre replica. Il reader endpoint distribuisce le connessioni su tutte le replica, quindi le query analitiche competerebbero comunque con il traffico web.","optionExplanations":["Eseguire lunghe analisi sul writer degraderebbe le prestazioni di scrittura per l'intera applicazione.","Il reader endpoint distribuisce le connessioni su tutte le replica, quindi le query analitiche finirebbero comunque sulle replica che servono l'applicazione web.","Corretto — un custom endpoint instrada le connessioni di analytics solo verso le replica più grandi designate.","Le replica cross-Region aggiungono ritardo di replica e costi e non forniscono un gruppo di istanze controllato e isolato per l'analytics."]},
  "1243": {"h":"2f2b6ae2","question":"Un'azienda usa già AWS Batch per eseguire job containerizzati. Ora deve applicare lo stesso container di elaborazione immagini a 50.000 file di input indipendenti in Amazon S3, e ogni job deve solo sapere quale file elaborare. Il team vuole il modo più semplice per inviare e monitorare questo lavoro, lasciando che AWS Batch esegua in parallelo tutti i job consentiti dalla capacità. Cosa dovrebbe consigliare un solutions architect?","options":["Scrivere uno script che scorre i file e invia 50.000 job separati alla job queue.","Eseguire un unico job di grandi dimensioni sul tipo di istanza più grande che elabora tutti i file in sequenza in un ciclo.","Creare un workflow AWS Step Functions Standard con uno stato per ogni file che chiama il container.","Inviare un singolo array job AWS Batch in cui ogni job figlio usa il proprio indice dell'array per scegliere un file."],"explanation":"Un array job invia molti job figli con una sola richiesta, e ogni figlio riceve un indice che può usare per selezionare il proprio file di input; AWS Batch pianifica i figli in parallelo e possono essere monitorati come gruppo. Inviare decine di migliaia di job singoli funziona, ma aggiunge carico di invio e di monitoraggio, e un singolo job sequenziale elimina del tutto il parallelismo.","optionExplanations":["Gli invii singoli sono più difficili da gestire e monitorare rispetto a un unico array job e aggiungono script personalizzati.","Elaborare in sequenza su una sola istanza spreca il parallelismo offerto da AWS Batch e richiede molto più tempo.","Definire uno stato per ogni file non è praticabile a questa scala e aggiunge un secondo servizio di orchestrazione senza alcun beneficio.","Corretto — gli array job distribuiscono molti job figli paralleli a partire da un unico invio, ciascuno identificato dal proprio indice."]},
  "1244": {"h":"22a67d25","question":"Un'azienda esegue un cluster Amazon Redshift su nodi dense compute (DC2). I dati archiviati crescono molto più rapidamente del carico di query, quindi l'azienda continua ad aggiungere nodi solo per ottenere storage, anche se l'utilizzo della CPU resta basso. Quale soluzione consentirà all'azienda di scalare storage e compute in modo indipendente?","options":["Migrare il cluster su nodi RA3, che usano Redshift Managed Storage basato su Amazon S3.","Abilitare il concurrency scaling in modo che vengano aggiunti cluster aggiuntivi nei periodi di carico elevato.","Attivare l'automatic table optimization in modo che Redshift scelga sort key e distribution key migliori.","Scaricare i dati più vecchi in Amazon S3 Glacier Flexible Retrieval e ripristinarli ogni volta che servono agli analisti."],"explanation":"I nodi RA3 separano il compute dallo storage usando Redshift Managed Storage, quindi l'azienda può dimensionare il compute in base al carico di query e pagare lo storage separatamente man mano che i dati crescono. Il concurrency scaling aggiunge capacità di query per i picchi di query concorrenti, il che non risolve la crescita dello storage.","optionExplanations":["Corretto — RA3 con managed storage svincola la capacità di storage dal numero e dalle dimensioni dei nodi di compute.","Il concurrency scaling aiuta con i picchi di query concorrenti, non con la capacità di storage del cluster principale.","Sort key e distribution key migliori migliorano le prestazioni delle query, ma non cambiano il modo in cui lo storage scala con i nodi.","Glacier Flexible Retrieval richiede un ripristino prima che i dati possano essere interrogati, il che rende i dati di fatto non disponibili per l'analisi."]},
  "1245": {"h":"5d5d95e6","question":"Un'azienda retail usa un cluster Amazon Redshift provisioned per dashboard di BI. A fine mese, centinaia di utenti aprono le dashboard contemporaneamente e le query restano a lungo in coda. La maggior parte delle dashboard esegue ripetutamente le stesse join e aggregazioni onerose sulle tabelle delle vendite. Quale combinazione di azioni migliorerà le prestazioni delle dashboard? (Seleziona DUE)","options":["Abilitare il concurrency scaling per la coda di workload management usata dalle dashboard.","Creare materialized view per le aggregazioni comuni e lasciare che Redshift le aggiorni automaticamente.","Ridimensionare il cluster a un unico nodo più grande in modo che tutte le query condividano un solo nodo di compute.","Spostare le tabelle delle vendite in Amazon S3 e interrogarle tramite tabelle esterne Redshift Spectrum.","Configurare le dashboard per esportare ogni notte i risultati delle query in file CSV che gli utenti possono scaricare."],"explanation":"Il concurrency scaling aggiunge automaticamente capacità temporanea al cluster quando le query si accodano, gestendo il picco di utenti concorrenti di fine mese. Le materialized view precalcolano le join e le aggregazioni ripetute, così le query delle dashboard leggono risultati memorizzati invece di ricalcolarli. Spostare le tabelle più usate su Spectrum rallenterebbe in genere queste query frequenti invece di velocizzarle.","optionExplanations":["Corretto — il concurrency scaling aggiunge capacità per i picchi di query di lettura concorrenti, così non restano in coda.","Corretto — le materialized view memorizzano i risultati precalcolati delle query onerose ripetute.","Un singolo nodo riduce parallelismo e capacità, il che peggiora l'accodamento.","Spectrum è adatto a dati in S3 interrogati di rado; le tabelle delle dashboard interrogate spesso offrono prestazioni migliori nello storage locale del cluster.","Gli export CSV notturni tolgono alle dashboard interattività e aggiornamento dei dati."]},
  "1246": {"h":"310b4c91","question":"Un marketplace online archivia milioni di annunci di prodotti in Amazon RDS for MySQL. La casella di ricerca usa query SQL LIKE, che sono lente, non possono ordinare i risultati per rilevanza e non tollerano gli errori di ortografia. L'azienda vuole una ricerca full-text veloce con punteggio di rilevanza e fuzzy matching. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere altre read replica RDS e instradare tutte le query di ricerca verso le read replica.","Indicizzare gli annunci in Amazon OpenSearch Service e inviare a esso le query di ricerca.","Spostare gli annunci in Amazon DynamoDB e usare operazioni Scan con filter expression.","Memorizzare in cache in Amazon ElastiCache i risultati delle ricerche più comuni con un TTL breve."],"explanation":"Amazon OpenSearch Service è progettato per la ricerca full-text con indici invertiti, punteggio di rilevanza e fuzzy matching, mentre RDS resta il system of record. Le read replica distribuiscono solo le stesse inefficienti query LIKE su più istanze e continuano a non poter ordinare i risultati né gestire gli errori di ortografia.","optionExplanations":["Le read replica aggiungono capacità, ma le query LIKE restano lente e continuano a mancare di ordinamento per rilevanza e fuzzy matching.","Corretto — OpenSearch fornisce indicizzazione full-text, punteggio di rilevanza e query fuzzy a bassa latenza.","Gli Scan di DynamoDB leggono l'intera tabella e le filter expression non offrono né ordinamento per rilevanza né fuzzy matching.","Il caching aiuta solo con ricerche identiche ripetute e non aggiunge punteggio di rilevanza né tolleranza agli errori di battitura."]},
  "1247": {"h":"bfa2a5db","question":"Un'azienda esegue una funzione AWS Lambda basata su Java dietro Amazon API Gateway. La funzione usa un framework di grandi dimensioni e la sua inizializzazione richiede diversi secondi, quindi le invocazioni che avviano un nuovo ambiente di esecuzione sono lente. Il traffico è imprevedibile e l'azienda vuole ridurre la latenza di avvio senza pagare per capacità inutilizzata. Quale soluzione soddisfa questi requisiti?","options":["Configurare la provisioned concurrency per il numero massimo previsto di richieste concorrenti.","Aumentare il timeout della funzione in modo che le inizializzazioni lente non falliscano più durante l'avvio.","Abilitare Lambda SnapStart su una versione pubblicata della funzione e invocare quella versione.","Pianificare una regola Amazon EventBridge che invoca la funzione ogni minuto per mantenerla calda."],"explanation":"Lambda SnapStart per Java crea uno snapshot dell'ambiente di esecuzione inizializzato quando viene pubblicata una versione e riprende i nuovi ambienti da quello snapshot, riducendo notevolmente la latenza di avvio. Anche la provisioned concurrency elimina i cold start, ma mantiene gli ambienti inizializzati e fatturati di continuo, il che è in conflitto con il requisito di non pagare per capacità inutilizzata con un traffico imprevedibile.","optionExplanations":["La provisioned concurrency viene fatturata finché è configurata, anche quando è inutilizzata, cosa che l'azienda vuole evitare.","Un timeout più lungo evita i fallimenti, ma non rende l'inizializzazione più rapida.","Corretto — SnapStart riprende gli ambienti da uno snapshot pre-inizializzato, riducendo la latenza dei cold start per le funzioni Java.","Un ping keep-warm mantiene caldi solo uno o pochi ambienti e non aiuta quando i picchi di traffico richiedono nuovi ambienti."]},
  "1248": {"h":"e9d15d35","question":"Un'azienda esegue centinaia di funzioni AWS Lambda in Python che eseguono trasformazioni di dati. Le funzioni non hanno dipendenze native specifiche per x86. L'azienda vuole un miglior rapporto prezzo/prestazioni per queste funzioni con modifiche minime e senza riprogettazione. Cosa dovrebbe consigliare un solutions architect?","options":["Riscrivere le funzioni come container ed eseguirle come task Amazon ECS con il launch type Fargate.","Ridurre al minimo l'impostazione di memoria di ogni funzione per abbassare il costo di ciascuna invocazione.","Pacchettizzare le funzioni come immagini container invece che come archivi .zip per migliorarne le prestazioni.","Cambiare l'architettura del set di istruzioni delle funzioni in arm64 per eseguirle su AWS Graviton."],"explanation":"Le funzioni Lambda configurate per l'architettura arm64 vengono eseguite su processori AWS Graviton, che per molti workload offrono un miglior rapporto prezzo/prestazioni rispetto a x86, e il codice Python puro di solito funziona senza modifiche. Ridurre la memoria riduce anche la CPU, il che può rendere le funzioni più lente e non più economiche nel complesso.","optionExplanations":["Passare a ECS su Fargate è una riprogettazione e aggiunge lavoro operativo che l'azienda vuole evitare.","Lambda alloca la CPU in proporzione alla memoria, quindi la memoria minima può allungare l'esecuzione e annullare qualsiasi risparmio.","Il formato di pacchettizzazione non cambia il processore che esegue il codice né il suo rapporto prezzo/prestazioni.","Corretto — passare ad arm64 esegue le funzioni su Graviton con un miglior rapporto prezzo/prestazioni e modifiche minime al codice."]},
  "1249": {"h":"5810c9fc","question":"Diverse funzioni AWS Lambda eseguono inferenza con modelli di machine learning e dataset di riferimento che occupano complessivamente molti gigabyte. I modelli vengono aggiornati più volte al giorno indipendentemente dal codice delle funzioni, e tutte le funzioni devono leggere a runtime gli stessi file più recenti. Quale soluzione soddisfa questi requisiti con il MINOR sforzo?","options":["Montare un file system Amazon EFS condiviso sulle funzioni e archiviarvi i modelli.","Includere i modelli nel pacchetto di deployment di ogni funzione e ridistribuirlo ogni volta che cambiano.","Scaricare i modelli da Amazon S3 in /tmp all'inizio di ogni invocazione di ciascuna funzione.","Archiviare i modelli come Lambda layer e pubblicare una nuova versione del layer per ogni aggiornamento del modello."],"explanation":"Le funzioni Lambda possono montare un file system Amazon EFS, che offre a tutte le funzioni un accesso condiviso e a bassa latenza a file di grandi dimensioni aggiornabili indipendentemente dal codice. Layer e pacchetti di deployment legano i modelli alle versioni delle funzioni e hanno limiti di dimensione, quindi ogni aggiornamento del modello richiederebbe una nuova pubblicazione e un nuovo deployment.","optionExplanations":["Corretto — EFS offre a tutte le funzioni un accesso condiviso a runtime a file di grandi dimensioni aggiornati in modo indipendente.","Pacchettizzare modelli di grandi dimensioni con il codice impone nuovi deployment a ogni modifica del modello e si scontra con i limiti di dimensione del pacchetto.","Scaricare molti gigabyte a ogni invocazione aggiunge una latenza elevata e un forte carico di trasferimento.","I layer hanno limiti di dimensione e ogni aggiornamento richiede una nuova versione del layer e l'aggiornamento delle funzioni per usarla."]},
  "1250": {"h":"a66a5811","question":"Un'azienda sta spostando su Amazon EC2 un cluster di database in memoria autogestito. Il database mantiene l'intero working set in RAM e richiede un elevato rapporto tra memoria e vCPU, mentre l'utilizzo della CPU è moderato. Quale famiglia di istanze EC2 è la PIÙ adatta?","options":["Istanze compute optimized come la famiglia C","Istanze memory optimized come la famiglia R","Istanze storage optimized come la famiglia I","Istanze accelerated computing come la famiglia G"],"explanation":"Le istanze memory optimized come la famiglia R offrono un elevato rapporto tra memoria e vCPU, adatto ai database in memoria il cui working set deve stare nella RAM. Le istanze compute optimized offrono più CPU per GiB di memoria, che è l'opposto di ciò di cui ha bisogno questo workload.","optionExplanations":["Le istanze C hanno un basso rapporto tra memoria e vCPU e sono progettate per workload vincolati dalla CPU.","Corretto — le istanze R sono progettate per workload ad alto uso di memoria come i database in memoria.","Le istanze I sono ottimizzate per un elevato I/O sullo storage locale, non per un ampio working set in memoria.","Le istanze G aggiungono GPU per la grafica e l'inferenza ML, che questo workload non usa."]},
  "1251": {"h":"3faf5a7b","question":"Un sito di e-commerce memorizza nella cache di Amazon ElastiCache i dettagli dei prodotti provenienti da un database Amazon RDS, usando il lazy loading. Quando i prezzi vengono aggiornati nel database, i clienti continuano a vedere i prezzi vecchi finché le voci della cache non scadono. Inoltre la cache si riempie di voci relative a prodotti visualizzati raramente. Quale combinazione di modifiche risolverà entrambi i problemi? (Seleziona DUE)","options":["Aggiornare la voce della cache nello stesso momento in cui l'applicazione scrive una modifica nel database.","Eliminare la cache e inviare ogni lettura dei prodotti direttamente al database RDS.","Aggiungere un time to live (TTL) alle voci della cache, in modo che quelle non utilizzate scadano.","Abilitare Multi-AZ con failover automatico sul replication group di ElastiCache.","Aggiungere delle Read Replica RDS e indirizzare verso di esse i cache miss del lazy loading."],"explanation":"Una strategia write-through aggiorna la cache ogni volta che i dati vengono scritti nel database, così chi legge vede sempre i prezzi aggiornati. Aggiungere un TTL fa scadere le voci non utilizzate, evitando che i prodotti visualizzati raramente riempiano la cache. Multi-AZ migliora la disponibilità della cache ma non cambia l'aggiornamento dei dati né il contenuto della cache.","optionExplanations":["Corretto — il write-through mantiene i prezzi in cache sincronizzati con il database al momento della scrittura.","Eliminare la cache risolve i dati obsoleti rinunciando al vantaggio prestazionale e aumentando il carico sul database.","Corretto — un TTL fa scadere le voci inutilizzate e limita per quanto tempo una voce obsoleta può restare in cache.","Multi-AZ protegge dal guasto di un nodo; non risolve i dati obsoleti né lo spazio di cache sprecato.","Le Read Replica riducono il carico sul primario ma non fanno nulla per le voci obsolete o il ricambio della cache."]},
  "1252": {"h":"294fadf9","question":"Una società di ingegneria esegue su Amazon EC2 un'applicazione di fluidodinamica computazionale. L'applicazione usa MPI e i suoi nodi si scambiano messaggi continuamente durante ogni esecuzione, per cui la latenza tra i nodi ne limita la scalabilità oltre qualche decina di istanze. La società vuole che l'applicazione scali fino a centinaia di istanze. Quale soluzione offrirà le MIGLIORI prestazioni di comunicazione tra i nodi?","options":["Distribuire le istanze su più Availability Zone e usare il VPC peering tra le subnet.","Usare istanze con enhanced networking tramite ENA in uno spread placement group.","Usare istanze che supportano Elastic Fabric Adapter (EFA) in un cluster placement group.","Inserire un Network Load Balancer interno tra i nodi per distribuire il traffico MPI."],"explanation":"Elastic Fabric Adapter fornisce un'interfaccia con OS bypass che consente alle applicazioni MPI di comunicare con una latenza più bassa e costante rispetto al networking basato su TCP, ed è ciò che serve all'HPC strettamente accoppiato per scalare. Un cluster placement group mantiene i nodi fisicamente vicini per la latenza minima. ENA da solo migliora la larghezza di banda ma non offre l'OS bypass, e uno spread placement group aumenta la distanza tra i nodi.","optionExplanations":["Distribuire i nodi su più AZ aumenta la latenza tra di essi, penalizzando i workload MPI strettamente accoppiati.","ENA non fornisce comunicazione con OS bypass e uno spread placement group separa deliberatamente le istanze.","Corretto — EFA con OS bypass in un cluster placement group offre la messaggistica tra nodi a latenza più bassa per MPI.","I nodi MPI comunicano direttamente tra loro; un load balancer aggiunge latenza e non si adatta a questo tipo di traffico."]},
  "1253": {"h":"c3c85a5f","question":"Un'azienda elabora eventi provenienti da milioni di dispositivi IoT. Ogni evento avvia un breve workflow di tre funzioni AWS Lambda che si completa in pochi secondi, e il volume raggiunge decine di migliaia di esecuzioni di workflow al secondo. I workflow sono idempotenti e l'azienda non ha bisogno di una cronologia visuale a lungo termine di ogni esecuzione. Quale opzione di orchestrazione è la PIÙ adatta?","options":["AWS Step Functions Standard Workflows avviati da una regola EventBridge per ogni evento","Un ambiente Amazon MWAA che esegue un DAG per ogni evento in arrivo dai dispositivi","Code Amazon SQS FIFO che concatenano in sequenza le tre funzioni Lambda","AWS Step Functions Express Workflows per le esecuzioni ad alto volume e di breve durata"],"explanation":"Gli Express Workflows sono progettati per l'elaborazione di eventi ad alto volume e di breve durata, supportano frequenze di avvio delle esecuzioni molto elevate e sono tariffati in base a esecuzioni e durata. Gli Standard Workflows sono pensati per workflow di lunga durata e verificabili, con esecuzione exactly-once, hanno frequenze di avvio più basse e una tariffazione per transizione, il che non si adatta a decine di migliaia di brevi esecuzioni al secondo.","optionExplanations":["Gli Standard Workflows sono adatti a processi di lunga durata e verificabili e non gestiscono in modo efficiente questo volume di brevi esecuzioni.","Apache Airflow è progettato per la schedulazione orientata ai batch e non può eseguire un DAG per evento a questa frequenza.","Le code FIFO limitano il throughput per message group e richiedono codice personalizzato per concatenare i passaggi.","Corretto — gli Express Workflows gestiscono a basso costo frequenze molto elevate di esecuzioni brevi e idempotenti."]},
  "1254": {"h":"0a6e3de9","question":"Un servizio di acquisizione ordini invia messaggi a una coda Amazon SQS standard un messaggio per chiamata API, e i consumer su Amazon EC2 ricevono un messaggio per chiamata. Con l'aumentare del volume, sia i producer sia i consumer passano la maggior parte del tempo in round trip di rete e il throughput non riesce a tenere il passo. Quale modifica migliorerà il throughput con il MINOR sforzo?","options":["Inviare e ricevere i messaggi in batch, in modo che ogni chiamata API gestisca più messaggi.","Convertire la coda in una coda SQS FIFO, in modo che i messaggi vengano consegnati in ordine rigoroso.","Aumentare il visibility timeout, in modo che i consumer abbiano più tempo per elaborare ogni messaggio.","Sostituire la coda con Amazon SNS e sottoscrivere ogni istanza consumer con un endpoint HTTP."],"explanation":"Il batching invia e riceve più messaggi per chiamata API, riducendo il numero di round trip e aumentando il throughput di ciascun producer e consumer. Le code FIFO aggiungono garanzie di ordinamento ma hanno un throughput inferiore rispetto alle code standard, quindi non aiuterebbero in questo caso.","optionExplanations":["Corretto — il batching ripartisce ogni round trip di rete su più messaggi.","FIFO aggiunge garanzie di ordinamento non richieste e ha un throughput inferiore rispetto a una coda standard.","Il visibility timeout controlla la riconsegna, non quanti messaggi vengono trasferiti per chiamata.","SNS invia ogni messaggio a ogni sottoscrittore, cambiando la semantica ed eliminando il livellamento del carico basato sulla coda."]},
  "1255": {"h":"2f0d3cca","question":"Un'azienda di viaggi espone una REST API Amazon API Gateway basata su AWS Lambda e Amazon DynamoDB. La maggior parte del traffico è costituita da richieste GET per i dettagli delle destinazioni, che cambiano solo poche volte al giorno, e le stesse richieste si ripetono migliaia di volte al minuto. L'azienda vuole ridurre la latenza delle risposte e il carico sul backend con il MINOR sforzo di sviluppo. Che cosa dovrebbe fare un solutions architect?","options":["Aggiungere DynamoDB Accelerator (DAX) e riscrivere le funzioni Lambda per usare il client DAX.","Abilitare il caching di API Gateway sullo stage con un TTL coerente con la frequenza di modifica dei dati.","Aumentare la memoria delle funzioni Lambda in modo che ogni richiesta termini più rapidamente.","Passare la tabella DynamoDB alla modalità di capacità on-demand per gestire le letture ripetute."],"explanation":"Il caching dello stage di API Gateway restituisce risposte memorizzate per le richieste ripetute senza invocare Lambda o DynamoDB, riducendo sia la latenza sia il carico sul backend con una semplice modifica di configurazione. DAX velocizzerebbe le letture da DynamoDB, ma invocherebbe comunque Lambda a ogni richiesta e richiederebbe modifiche al codice.","optionExplanations":["DAX richiede modifiche al codice e comporta comunque un'invocazione Lambda per ogni richiesta ripetuta.","Corretto — il caching dello stage risponde alle richieste GET ripetute dalla cache di API Gateway per il TTL configurato.","Più memoria può accorciare ogni invocazione, ma ogni richiesta raggiunge comunque Lambda e DynamoDB.","La modalità on-demand cambia la gestione della capacità ma non riduce il numero di chiamate al backend né la loro latenza."]},
  "1256": {"h":"26d37f87","question":"Un'azienda sportiva sta sviluppando un'app mobile che mostra risultati e commenti delle partite in diretta. I client usano GraphQL per recuperare esattamente i campi di cui hanno bisogno e devono ricevere gli aggiornamenti in tempo reale non appena i dati cambiano, senza polling. L'azienda vuole una soluzione completamente gestita. Quale servizio dovrebbe usare un solutions architect?","options":["Una REST API Amazon API Gateway con i client che verificano le modifiche tramite polling ogni pochi secondi","Notifiche push mobili di Amazon SNS che inviano a ogni dispositivo i dati completi della partita","AWS AppSync con subscription GraphQL che inviano le modifiche dei dati ai client connessi","Un Application Load Balancer con istanze EC2 che eseguono un server GraphQL autogestito"],"explanation":"AWS AppSync è un servizio GraphQL gestito le cui subscription inviano aggiornamenti in tempo reale ai client connessi tramite WebSocket. Una REST API con polling aggiunge latenza e richieste inutili, e un server GraphQL autogestito su EC2 non soddisfa il requisito di soluzione completamente gestita.","optionExplanations":["Il polling non è in tempo reale, spreca richieste e non fornisce GraphQL.","Le notifiche push servono per gli avvisi e non forniscono query GraphQL né un flusso di dati in tempo reale nell'app.","Corretto — AppSync fornisce GraphQL gestito con subscription in tempo reale.","Eseguire un server GraphQL su EC2 aggiunge onere operativo e non è completamente gestito."]},
  "1257": {"h":"8011e9aa","question":"Un'azienda esegue in us-east-1 un'applicazione web con molte letture e un database Amazon Aurora MySQL. Un numero crescente di utenti in Europa riscontra caricamenti lenti delle pagine perché ogni richiesta viaggia fino a us-east-1, e la maggior parte dei caricamenti comporta diverse letture dal database. Le scritture sono rare e possono tollerare una latenza aggiuntiva. Quale combinazione di passaggi migliorerà MAGGIORMENTE le prestazioni per gli utenti europei? (Seleziona DUE)","options":["Convertire il cluster in un Aurora global database con un cluster secondario in una Region europea.","Abilitare Multi-AZ sul cluster Aurora e inviare le letture allo standby in un'altra Availability Zone.","Distribuire il livello applicativo nella Region europea e usare il routing basato sulla latenza di Route 53.","Copiare ogni ora gli snapshot automatici di Aurora nella Region europea per avere accesso locale in lettura.","Abilitare S3 Transfer Acceleration per il bucket degli asset statici dell'applicazione in us-east-1."],"explanation":"Un Aurora global database replica i dati in una Region secondaria con un ritardo minimo, così uno stack applicativo in Europa può servire le letture localmente, mentre le scritture possono continuare ad andare alla Region primaria. Il routing basato sulla latenza di Route 53 indirizza gli utenti europei verso lo stack più vicino. Le repliche Aurora in altre AZ di us-east-1 non riducono la latenza transatlantica e gli snapshot non sono un database attivo e leggibile.","optionExplanations":["Corretto — il cluster secondario di un global database fornisce letture locali a bassa latenza in Europa.","Le AZ aggiuntive restano in us-east-1, quindi le richieste europee attraversano comunque l'Atlantico.","Corretto — un livello applicativo locale con routing basato sulla latenza serve gli utenti europei dalla Region vicina.","Gli snapshot devono essere ripristinati per essere usati e sarebbero vecchi fino a un'ora; non sono una replica attiva.","Transfer Acceleration velocizza i trasferimenti verso S3 ma non fa nulla per le pagine dinamiche e le letture dal database."]},
  "1258": {"h":"133a521d","question":"Un gioco multiplayer usa un servizio di matchmaking che assegna ogni partita a uno specifico processo di game server su una specifica istanza Amazon EC2 e porta. I giocatori di tutto il mondo devono connettersi tramite la rete globale AWS esattamente a quell'istanza e porta, e l'azienda vuole evitare di esporre indirizzi IP pubblici sulle istanze. Quale soluzione soddisfa questi requisiti?","options":["Un AWS Global Accelerator standard che instrada i giocatori verso l'endpoint più integro nella Region più vicina","Amazon CloudFront con le istanze EC2 configurate come origini personalizzate per il traffico di gioco","Un Network Load Balancer in ogni Region con record Route 53 basati sulla latenza per i load balancer","Un acceleratore AWS Global Accelerator con custom routing che mappa le porte del listener sulle porte delle istanze"],"explanation":"Un acceleratore con custom routing mappa in modo deterministico le porte dell'acceleratore su specifici indirizzi IP privati e porte di istanze EC2 nelle subnet del VPC, così il matchmaker può indirizzare ogni giocatore a un game server preciso attraverso la rete globale AWS. Un acceleratore standard sceglie l'endpoint in base a stato di salute e vicinanza e non può indirizzare un giocatore a un determinato processo server.","optionExplanations":["Un acceleratore standard sceglie gli endpoint automaticamente e non può vincolare un giocatore a un'istanza e porta specifiche.","CloudFront è progettato per la distribuzione di contenuti HTTP, non per instradare sessioni di gioco in tempo reale verso una porta server specifica.","Un NLB distribuisce le connessioni tra i target e non può garantire un'istanza e una porta specifiche per ogni giocatore.","Corretto — il custom routing mappa ogni giocatore su un'istanza e porta specifiche senza IP pubblici sulle istanze."]},
  "1259": {"h":"6f205bf4","question":"Un'azienda ospita un'applicazione web personalizzata dietro un Application Load Balancer in una sola Region AWS. Le risposte sono diverse per ogni utente e non possono essere memorizzate in cache, ma gli utenti di altri continenti segnalano una latenza elevata, causata soprattutto dagli handshake TCP e TLS su lunghe distanze. L'azienda vuole migliorare la latenza con modifiche minime all'applicazione. Quale soluzione soddisfa questi requisiti?","options":["Posizionare Amazon CloudFront davanti all'ALB con il caching disabilitato per i percorsi dinamici.","Distribuire una copia del database e dell'applicazione in ogni Region in cui si trovano gli utenti.","Spostare l'applicazione su tipi di istanza EC2 più grandi per ridurre il tempo di elaborazione lato server.","Usare il routing di geolocalizzazione di Route 53 per inviare tutti gli utenti all'unico ALB da record DNS regionali."],"explanation":"Anche per contenuti non memorizzabili in cache, CloudFront termina TCP e TLS presso Edge Location vicine e inoltra le richieste all'origine tramite connessioni persistenti sul backbone AWS, riducendo la latenza per gli utenti lontani. Distribuire stack completi in ogni Region ridurrebbe anch'esso la latenza, ma richiede modifiche significative all'applicazione e ai dati.","optionExplanations":["Corretto — CloudFront accelera i contenuti dinamici terminando le connessioni all'edge e usando connessioni persistenti verso l'origine.","Un deployment multi-Region con replica dei dati è un cambiamento architetturale importante, non minimo.","Server più veloci non riducono i round trip di rete che causano la maggior parte della latenza.","Il routing DNS verso lo stesso unico ALB non cambia il percorso di rete né la latenza degli handshake."]},
  "1260": {"h":"3fd1b114","question":"Un database Amazon RDS for PostgreSQL contiene dati applicativi la cui crescita è difficile da prevedere. Due volte nell'ultimo anno il database ha esaurito lo storage e l'applicazione ha smesso di accettare scritture finché un amministratore non ha aumentato lo storage allocato. L'azienda vuole evitare che accada di nuovo con il MINOR onere operativo. Che cosa dovrebbe fare un solutions architect?","options":["Creare un allarme CloudWatch sullo spazio di storage libero che invii un'email all'amministratore per ridimensionare il volume.","Abilitare lo storage autoscaling di RDS con una soglia massima di storage per l'istanza DB.","Allocare fin da ora uno storage pari a diverse volte quello attuale, in modo che il database non si riempia.","Pianificare una funzione Lambda che controlli lo spazio libero ogni notte e aumenti lo storage allocato."],"explanation":"Lo storage autoscaling di RDS aumenta automaticamente lo storage allocato quando lo spazio libero si esaurisce, fino a una soglia massima, senza downtime e senza interventi manuali. Un allarme dipende comunque dalla reazione tempestiva di un amministratore, ed è proprio ciò che non ha funzionato in passato.","optionExplanations":["Un allarme si limita a notificare; il rischio di interruzione resta se l'amministratore non interviene rapidamente.","Corretto — lo storage autoscaling fa crescere automaticamente lo storage quando si esaurisce, fino al massimo configurato.","Un sovradimensionamento massiccio spreca denaro e non garantisce comunque che una crescita imprevedibile ci stia.","Una funzione pianificata personalizzata aggiunge codice da mantenere e può non intercettare la crescita che avviene tra un'esecuzione e l'altra."]},
  "1261": {"h":"c573c800","question":"Un fornitore di dati finanziari trasmette dati di mercato ai clienti tramite connessioni TCP di lunga durata usando un protocollo proprietario. Il servizio deve gestire milioni di richieste al secondo con latenza bassissima, preservare gli indirizzi IP di origine dei client e fornire un indirizzo IP statico per Availability Zone da inserire nelle allow list dei clienti. Quale soluzione di bilanciamento del carico dovrebbe essere usata?","options":["Un Application Load Balancer con sticky session e cross-zone load balancing","Un Gateway Load Balancer che inoltra il traffico ai server tramite GENEVE","Un Network Load Balancer con listener TCP e un indirizzo Elastic IP in ogni subnet","Un Classic Load Balancer con listener TCP e Proxy Protocol abilitato per i client"],"explanation":"Un Network Load Balancer opera al livello 4, gestisce milioni di richieste al secondo con latenza bassissima, supporta un indirizzo Elastic IP per Availability Zone e può preservare gli IP di origine dei client. Un ALB lavora al livello 7 per HTTP e HTTPS e non fornisce indirizzi IP statici, quindi non è adatto a un protocollo TCP proprietario.","optionExplanations":["Un ALB gestisce solo HTTP e HTTPS e non offre indirizzi IP statici per AZ.","Gateway Load Balancer serve a inserire virtual appliance di terze parti come i firewall, non a servire il traffico dei client.","Corretto — un NLB offre prestazioni di livello 4, Elastic IP statici per AZ e preservazione dell'IP di origine.","Classic Load Balancer è di generazione precedente e non ha le prestazioni e gli IP statici di un NLB."]},
  "1262": {"h":"f1ed3ff5","question":"Un'azienda sta realizzando un servizio di sessioni e carrello che richiede latenza di lettura nell'ordine dei microsecondi e deve usare l'API compatibile con Redis OSS. I dati devono essere la copia primaria e durevole, senza un database di appoggio separato, e devono sopravvivere alla perdita di una Availability Zone senza perdita di dati. Quale soluzione soddisfa questi requisiti?","options":["Amazon ElastiCache (Redis OSS) con un singolo nodo e backup giornalieri su Amazon S3","Amazon DynamoDB con DynamoDB Accelerator (DAX) e il codice client Redis esistente","Amazon ElastiCache (Redis OSS) con repliche Multi-AZ come cache davanti ad Amazon RDS","Amazon MemoryDB con un cluster Multi-AZ come database primario durevole del servizio"],"explanation":"Amazon MemoryDB è un database in memoria compatibile con Redis OSS che archivia i dati in modo durevole in un log transazionale Multi-AZ, quindi può fungere da database primario con letture nell'ordine dei microsecondi. ElastiCache è progettato come cache; con la replica asincrona, le scritture recenti possono andare perse durante un failover, quindi non è pensato per essere l'unica copia durevole.","optionExplanations":["Un singolo nodo con backup giornalieri può perdere un giorno di dati e non sopravvive al guasto di una AZ.","DAX usa l'API di DynamoDB, non Redis, quindi l'applicazione andrebbe riscritta.","Questa architettura richiede un database di appoggio separato, escluso dai requisiti.","Corretto — MemoryDB fornisce storage durevole, Multi-AZ e compatibile con Redis OSS con letture nell'ordine dei microsecondi."]},
  "1263": {"h":"562b74ac","question":"Un gioco mobile globale archivia lo stato dei giocatori in una tabella Amazon DynamoDB in us-west-2. I giocatori in Europa e in Asia riscontrano una latenza elevata sia in lettura sia in scrittura. Il gioco deve consentire ai giocatori di leggere e scrivere nella Region più vicina e le modifiche devono essere replicate automaticamente tra le Region. Quale soluzione soddisfa questi requisiti?","options":["Convertire la tabella in una DynamoDB global table con repliche nelle Region di Europa e Asia.","Aggiungere cluster DynamoDB Accelerator (DAX) in Europa e Asia che puntano alla tabella in us-west-2.","Usare DynamoDB Streams e AWS Lambda per copiare le modifiche in tabelle separate in altre Region.","Posizionare Amazon CloudFront davanti all'endpoint DynamoDB per memorizzare in cache lo stato dei giocatori vicino agli utenti."],"explanation":"Le DynamoDB global table forniscono una replica multi-Region e multi-active, così i giocatori possono leggere e scrivere su una replica locale mentre le modifiche vengono replicate automaticamente. I cluster DAX devono trovarsi nella stessa Region della tabella e memorizzano in cache solo le letture, quindi non possono fornire scritture locali.","optionExplanations":["Corretto — le global table forniscono letture e scritture locali in ogni Region con replica automatica.","DAX è una cache di lettura regionale per una tabella nella stessa Region e non accetta scritture locali in altre Region.","Una replica personalizzata basata sugli stream aggiunge codice e gestione dei conflitti che le global table forniscono già.","CloudFront non memorizza in cache dati di database personalizzati e scritti frequentemente, e le scritture viaggerebbero comunque verso us-west-2."]},
  "1264": {"h":"524c9cd0","question":"Un'azienda esegue il proprio sistema di elaborazione ordini su Amazon Aurora MySQL. Gli analisti eseguono query di reportistica pesanti direttamente sul database, rallentando le transazioni. Gli analisti hanno bisogno dei dati degli ordini in Amazon Redshift entro pochi secondi da ogni modifica e l'azienda non vuole realizzare né gestire pipeline ETL. Quale soluzione soddisfa questi requisiti?","options":["Pianificare ogni notte un job AWS Glue che copi le tabelle degli ordini da Aurora a Redshift.","Configurare un'integrazione zero-ETL di Aurora con Amazon Redshift ed eseguire i report in Redshift.","Aggiungere una Aurora Replica e far eseguire agli analisti i report sulla replica.","Esportare ogni ora gli snapshot di Aurora su Amazon S3 e interrogarli con Redshift Spectrum."],"explanation":"L'integrazione zero-ETL di Aurora con Amazon Redshift replica i dati transazionali in Redshift quasi in tempo reale senza dover realizzare pipeline, spostando le analisi fuori dal database OLTP. Un job Glue notturno aggiunge una pipeline da gestire e non rende disponibili i dati entro pochi secondi.","optionExplanations":["Un job batch notturno aggiunge un processo ETL da mantenere e lascia dati vecchi fino a un giorno.","Corretto — l'integrazione zero-ETL rende disponibili i dati di Aurora in Redshift entro pochi secondi senza gestire pipeline.","Una replica scarica le query dall'istanza di scrittura, ma gli analisti hanno bisogno dei dati in Redshift, cosa che una replica non fornisce.","Le esportazioni orarie degli snapshot aggiungono ritardo e gestione del processo e non soddisfano il requisito dei pochi secondi."]},
  "1265": {"h":"0028dfd0","question":"Un'azienda serve un modello di deep learning per l'inferenza in tempo reale con un volume di richieste molto elevato su istanze Amazon EC2 basate su GPU. Il modello è supportato dall'AWS Neuron SDK. L'azienda vuole mantenere throughput elevato e bassa latenza ottenendo il costo per inferenza più basso. Quale famiglia di istanze dovrebbe usare l'azienda?","options":["Istanze P con GPU di fascia alta progettate per l'addestramento di modelli su larga scala","Istanze C con processori x86 ad alta frequenza di ultima generazione","Istanze Inf2 basate su acceleratori AWS Inferentia2","Istanze X con una quantità molto elevata di memoria per vCPU"],"explanation":"Le istanze Inf2 usano chip AWS Inferentia2, progettati appositamente per l'inferenza di deep learning, e offrono throughput elevato e bassa latenza con un costo per inferenza inferiore per i modelli supportati dal Neuron SDK. Le istanze P sono ottimizzate per l'addestramento e sono costose da usare per l'inferenza su larga scala.","optionExplanations":["Le istanze P sono pensate per l'addestramento su larga scala e costano di più per inferenza rispetto agli acceleratori dedicati all'inferenza.","Le istanze solo CPU offrono di solito un throughput di inferenza di deep learning molto inferiore rispetto agli acceleratori.","Corretto — Inferentia2 è progettato appositamente per un'inferenza ad alto throughput e a basso costo con il Neuron SDK.","Le istanze X ottimizzate per la memoria non accelerano l'inferenza delle reti neurali."]},
  "1266": {"h":"9c1efc92","question":"Un'applicazione web viene eseguita in un Auto Scaling group Amazon EC2 con target tracking sull'utilizzo della CPU. Ogni giorno feriale il traffico aumenta bruscamente alle 8:00 e le nuove istanze impiegano diversi minuti per essere pronte, quindi l'applicazione è lenta nella prima parte di ogni mattina. Durante il giorno si verificano anche picchi non pianificati. Quale combinazione di azioni migliorerà le prestazioni evitando costi inutili? (Seleziona DUE)","options":["Impostare la capacità minima del gruppo sul numero di istanze di picco per l'intera giornata.","Abilitare il predictive scaling in modo che la capacità venga avviata prima dell'aumento ricorrente del mattino.","Sostituire il target tracking con policy di simple scaling che usano lunghi periodi di cooldown.","Mantenere la policy di target tracking in modo che il gruppo continui a reagire ai picchi non pianificati durante il giorno.","Passare a un unico tipo di istanza più grande, così che il gruppo non debba più fare scale out."],"explanation":"Il predictive scaling prevede l'andamento giornaliero ricorrente a partire dallo storico e avvia le istanze prima del picco del mattino, così sono pronte quando arriva il traffico. Mantenere insieme il target tracking consente al gruppo di rispondere dinamicamente ai picchi imprevisti. Mantenere la capacità di picco tutto il giorno risolverebbe il problema del mattino, ma sprecherebbe denaro per la maggior parte della giornata.","optionExplanations":["Mantenere la capacità di picco tutto il giorno significa pagare istanze inattive al di fuori del periodo di punta.","Corretto — il predictive scaling avvia la capacità in anticipo rispetto al traffico ricorrente del mattino.","Il simple scaling con lunghi cooldown reagisce più lentamente del target tracking, peggiorando i ritardi.","Corretto — il target tracking continua a gestire i picchi non pianificati che una previsione non può anticipare.","Un'unica istanza elimina elasticità e tolleranza ai guasti e non riesce comunque ad assorbire picchi più grandi."]},
  "1267": {"h":"c1d3b949","question":"Uno studio di design vuole che i propri artisti 3D lavorino da thin client su applicazioni di modellazione e rendering con grafica intensiva. Le applicazioni richiedono l'accelerazione GPU per la visualizzazione interattiva e lo studio trasmetterà i desktop tramite un protocollo di visualizzazione remota. Quale famiglia di istanze EC2 è la PIÙ adatta per queste workstation?","options":["Istanze C ottimizzate per il calcolo con frequenze di clock elevate","Istanze R ottimizzate per la memoria con grande capacità di RAM","Istanze T a prestazioni burstable che accumulano crediti CPU","Istanze G per il calcolo accelerato con GPU grafiche"],"explanation":"Le istanze G forniscono GPU NVIDIA o AMD progettate per applicazioni con grafica intensiva come workstation remote, visualizzazione 3D e rendering. Le altre famiglie non dispongono di GPU, quindi non possono accelerare la grafica 3D interattiva di cui queste applicazioni hanno bisogno.","optionExplanations":["Le istanze C offrono ottime prestazioni CPU ma nessuna GPU per la grafica 3D interattiva.","Le istanze R aggiungono memoria ma nessuna accelerazione GPU per la visualizzazione.","Le istanze T burstable non sostengono workload pesanti e non hanno GPU.","Corretto — le istanze G sono progettate per workstation grafiche e visualizzazione accelerata da GPU."]},
  "1268": {"h":"39735f03","question":"Un'azienda ha decine di microservizi gestiti da team diversi in molti VPC e account AWS. Diversi VPC hanno intervalli CIDR sovrapposti. I servizi devono chiamarsi a vicenda tramite HTTP e gRPC con routing e policy di accesso a livello di richiesta, e l'azienda non vuole gestire peering, proxy o sidecar. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Amazon VPC Lattice con una service network associata ai servizi e ai VPC","Una mesh completa di connessioni VPC peering con route aggiunte tra tutti i VPC dei servizi","AWS Transit Gateway con una route table per account e proxy NGINX in ogni VPC","Application Load Balancer esposti su internet per ogni servizio con regole dei Security Group"],"explanation":"Amazon VPC Lattice fornisce connettività gestita tra servizi a livello applicativo attraverso VPC e account diversi, supporta intervalli IP sovrapposti e offre routing e auth policy a livello di richiesta senza sidecar. Peering e Transit Gateway non possono instradare tra CIDR sovrapposti e aggiungono onere di gestione della rete.","optionExplanations":["Corretto — VPC Lattice gestisce la connettività tra servizi su VPC e account diversi con routing e auth policy, anche con CIDR sovrapposti.","Il VPC peering non funziona tra CIDR sovrapposti e una mesh completa è difficile da gestire a questa scala.","Transit Gateway non può instradare CIDR sovrapposti e i proxy autogestiti aggiungono lavoro operativo.","Esporre servizi interni su internet indebolisce la sicurezza e aggiunge latenza e la gestione di molti load balancer."]},
  "1269": {"h":"a81acfc5","question":"Un database su Amazon EC2 usa un volume EBS gp2 da 200 GiB. Il database ha bisogno di più IOPS di quelli forniti dal volume, ma non di maggiore capacità di storage. L'azienda vuole aumentare gli IOPS senza pagare per storage inutilizzato. Quale soluzione è la PIÙ conveniente?","options":["Aumentare la dimensione del volume gp2 finché gli IOPS di base non raggiungono il livello richiesto.","Modificare il volume in gp3 ed effettuare il provisioning degli IOPS richiesti indipendentemente dalla dimensione.","Cambiare il volume in io2 Block Express ed effettuare il provisioning del massimo degli IOPS disponibili.","Convertire il volume in st1 Throughput Optimized HDD per ottenere più I/O per gigabyte."],"explanation":"I volumi gp3 consentono di effettuare il provisioning di IOPS e throughput indipendentemente dalla dimensione dello storage, così l'azienda può aumentare gli IOPS senza acquistare capacità aggiuntiva, e la modifica può essere fatta con Elastic Volumes senza downtime. Con gp2 gli IOPS crescono con la dimensione, quindi più IOPS significano pagare storage non necessario.","optionExplanations":["Gli IOPS di gp2 sono legati alla dimensione del volume, quindi si paga storage di cui il database non ha bisogno.","Corretto — gp3 svincola gli IOPS dalla dimensione ed è il modo più economico per aggiungere IOPS.","io2 Block Express è progettato per i workload più esigenti e costa più del necessario in questo caso.","st1 è ottimizzato per il throughput sequenziale e offre prestazioni scarse per gli IOPS casuali di un database."]},
  "1270": {"h":"e1e0a2a0","question":"Un sito web multimediale servito tramite Amazon CloudFront deve convalidare un token di autorizzazione su ogni richiesta del viewer chiamando in rete un servizio di entitlement esterno prima di restituire il contenuto. La logica richiede qualche centinaio di millisecondi di tempo di esecuzione e l'accesso al corpo della richiesta. Quale soluzione soddisfa questi requisiti?","options":["CloudFront Functions associate all'evento viewer request della distribuzione","Regole rate-based di AWS WAF collegate alla distribuzione CloudFront","Funzioni Lambda@Edge associate all'evento viewer request","Un origin access control di CloudFront tra la distribuzione e la sua origine"],"explanation":"Le funzioni Lambda@Edge possono effettuare chiamate di rete, essere eseguite più a lungo delle CloudFront Functions e accedere al corpo della richiesta, quindi possono chiamare il servizio di entitlement esterno all'edge. Le CloudFront Functions sono più economiche e veloci per la logica leggera, ma non hanno accesso alla rete e non possono leggere il corpo della richiesta.","optionExplanations":["Le CloudFront Functions non possono effettuare chiamate di rete né leggere il corpo della richiesta e hanno un tempo massimo di esecuzione molto breve.","Le regole rate-based limitano la frequenza delle richieste e non possono convalidare token tramite un servizio esterno.","Corretto — Lambda@Edge supporta chiamate di rete, esecuzioni più lunghe e l'accesso al corpo della richiesta all'edge.","L'origin access control limita chi può raggiungere l'origine; non convalida i token dei viewer."]},
  "1271": {"h":"0911e7e5","question":"Un'azienda ha più di 400 bucket Amazon S3 distribuiti su 60 account in AWS Organizations. I costi di storage S3 sono cresciuti costantemente e il reparto finanziario non riesce a capire quali bucket o prefissi ne siano responsabili, né se vi contribuiscano le versioni non correnti e i multipart upload incompleti. L'azienda vuole visibilità a livello di organizzazione su questi fattori di costo con il MINOR onere operativo. Quale soluzione soddisfa questi requisiti?","options":["Abilitare S3 Storage Lens per l'organizzazione ed esaminarne le metriche di efficienza dei costi.","Abilitare il server access logging di S3 su ogni bucket e analizzare i file di log con Amazon Athena.","Scrivere in ogni account una funzione AWS Lambda che elenchi ogni giorno tutti i bucket e sommi le dimensioni degli oggetti.","Abilitare i data event di AWS CloudTrail per tutti i bucket e creare dashboard in Amazon CloudWatch."],"explanation":"S3 Storage Lens aggrega le metriche di utilizzo dello storage e di attività su tutti gli account e i bucket di un'organizzazione, comprese metriche come i byte delle versioni non correnti e dei multipart upload incompleti, senza codice da mantenere. I server access log registrano le richieste, non la composizione dello storage, e richiederebbero di realizzare ed eseguire una pipeline di analisi in ogni account.","optionExplanations":["Corretto — Storage Lens fornisce una dashboard a livello di organizzazione con metriche per bucket e prefisso che evidenziano problemi di efficienza dei costi come le versioni non correnti e gli upload incompleti.","Gli access log descrivono le richieste fatte ai bucket; non mostrano quanto storage è occupato da versioni non correnti o upload incompleti e aggiungono un proprio costo di storage.","Funzioni di elencazione personalizzate in 60 account sono onerose da realizzare e gestire, comportano costi per le richieste LIST e comunque non evidenzierebbero facilmente i multipart upload incompleti.","I data event di CloudTrail registrano le chiamate API e aggiungono costi significativi a questa scala; non riportano la composizione dello storage per bucket."]},
  "1272": {"h":"79d01c0e","question":"Un'azienda IoT scrive ogni giorno milioni di letture di sensori su Amazon S3, ciascuna archiviata come oggetto separato di pochi kilobyte. Le letture devono essere conservate per 10 anni e non vengono quasi mai lette dopo la prima settimana. Un ingegnere propone una regola di lifecycle che trasferisca ogni oggetto in S3 Glacier Deep Archive dopo 7 giorni. Quale approccio è il PIÙ conveniente?","options":["Applicare la regola di lifecycle proposta, così ogni lettura passa a S3 Glacier Deep Archive dopo 7 giorni.","Trasferire ogni lettura in S3 Intelligent-Tiering con i livelli di accesso archive attivati.","Raggruppare le letture di ogni giorno in file di grandi dimensioni e poi archiviare tali file in Deep Archive.","Mantenere le letture in S3 Standard ed eliminarle dopo 10 anni con una regola di scadenza."],"explanation":"Le transizioni di lifecycle sono addebitate per oggetto e ogni oggetto archiviato nelle classi di storage Glacier comporta un overhead aggiuntivo di metadati per oggetto, quindi per miliardi di oggetti minuscoli questi costi superano il risparmio sullo storage. Combinare prima le letture in oggetti di grandi dimensioni rende l'archiviazione efficiente. Trasferire gli oggetti singolarmente, come proposto, moltiplica i costi di richiesta e di overhead.","optionExplanations":["Le richieste di transizione per oggetto e l'overhead dei metadati di archivio per milioni di oggetti minuscoli al giorno ridurrebbero o supererebbero il risparmio sullo storage.","Intelligent-Tiering addebita una tariffa di monitoraggio per oggetto e non sposta automaticamente tra i livelli gli oggetti molto piccoli, quindi le letture minuscole ne traggono poco vantaggio e comportano comunque costi per oggetto.","Corretto — raggruppare le letture in un piccolo numero di oggetti di grandi dimensioni elimina i costi di transizione e di overhead per oggetto, sfruttando appieno il basso prezzo di storage di Deep Archive.","S3 Standard è il modo più costoso per conservare per 10 anni dati letti raramente; evita i costi di transizione ma paga molto di più per lo storage."]},
  "1273": {"h":"bcca4fff","question":"Una pipeline di dati scrive file intermedi su Amazon S3. Ogni file viene letto una o due volte dai job a valle entro poche ore e viene eliminato dalla pipeline dopo 10 giorni. Un membro del team suggerisce di archiviare i file in S3 Standard-IA per risparmiare, dato che vengono letti raramente dopo il primo giorno. Quale approccio di storage è il PIÙ conveniente?","options":["Scrivere i file direttamente in S3 Standard-IA mantenendo l'eliminazione dopo 10 giorni.","Archiviare i file in S3 Standard con una regola di scadenza a 10 giorni.","Scrivere i file in S3 One Zone-IA perché i dati possono essere rigenerati.","Scrivere i file in S3 Glacier Instant Retrieval e farli scadere dopo 10 giorni."],"explanation":"S3 Standard-IA, One Zone-IA e Glacier Instant Retrieval prevedono tutti un addebito per durata minima di storage (30 giorni o più) e tariffe di recupero per GB, quindi gli oggetti eliminati dopo 10 giorni vengono fatturati come se fossero stati conservati per l'intero periodo minimo. S3 Standard non ha durata minima né tariffe di recupero ed è quindi il più economico per i dati di breve durata. One Zone-IA è allettante perché i dati possono essere rigenerati, ma anche per esso si applica la durata minima.","optionExplanations":["Standard-IA fattura una durata minima di storage di 30 giorni e addebita i recuperi, quindi i file eliminati dopo 10 giorni costano più che in S3 Standard.","Corretto — S3 Standard non ha durata minima di storage né costi di recupero, il che si adatta a dati che vivono solo 10 giorni e vengono letti poco dopo la creazione.","Anche One Zone-IA ha un addebito minimo di storage di 30 giorni e tariffe di recupero, quindi gli oggetti di breve durata vengono fatturati per un tempo in cui non esistono.","Glacier Instant Retrieval ha una durata minima di storage di 90 giorni e tariffe di recupero più alte, risultando la scelta peggiore per oggetti da 10 giorni."]},
  "1274": {"h":"a633f0d6","question":"Un'azienda conserva 40 TB di immagini satellitari storiche in S3 Glacier Flexible Retrieval. Un team di ricerca ha bisogno che l'intero dataset venga ripristinato per un progetto di rielaborazione che inizierà la mattina successiva, tra circa 15 ore. Ricevere i dati prima non porta alcun vantaggio. Quale opzione di recupero rispetta la scadenza nel modo PIÙ conveniente?","options":["Recuperi Expedited con capacità di recupero provisioned acquistata in anticipo","Recuperi Standard per tutti gli oggetti","Recuperi Bulk per tutti gli oggetti","Copiare gli oggetti in S3 Glacier Instant Retrieval con S3 Batch Operations"],"explanation":"I recuperi Bulk da S3 Glacier Flexible Retrieval si completano tipicamente entro 5-12 ore e sono l'opzione di recupero più economica, compatibile con una scadenza di 15 ore. I recuperi Standard terminano più rapidamente (tipicamente 3-5 ore) ma costano di più, il che qui non porta alcun vantaggio.","optionExplanations":["I recuperi Expedited restituiscono i dati in pochi minuti al prezzo più alto e la capacità provisioned aggiunge un ulteriore costo per una velocità di cui il team non ha bisogno.","I recuperi Standard rispettano la scadenza ma costano più dei recuperi Bulk senza offrire alcun vantaggio utile in questo scenario.","Corretto — Bulk è il livello di recupero più economico e si completa tipicamente entro 5-12 ore, ben prima dell'inizio del progetto.","Gli oggetti archiviati devono essere ripristinati prima di poter essere copiati, quindi serve comunque un recupero e si aggiungono i costi di storage di Instant Retrieval."]},
  "1275": {"h":"be6e7b47","question":"Un'azienda sta chiudendo un data center e deve spostare 120 TB di file archiviati su Amazon S3 entro 3 settimane. La sede dispone di una connessione internet da 200 Mbps già molto utilizzata durante l'orario lavorativo. Dopo la migrazione non verranno trasferiti altri dati da questa sede. Quale soluzione è la PIÙ conveniente?","options":["Ordinare una connessione AWS Direct Connect da 1 Gbps e copiare i file con AWS DataSync.","Usare AWS DataSync sulla connessione internet esistente al di fuori dell'orario lavorativo.","Caricare i file con S3 Transfer Acceleration sulla connessione internet esistente.","Copiare i file su dispositivi AWS Snowball Edge Storage Optimized e spedirli ad AWS."],"explanation":"A 200 Mbps, anche sfruttando l'intera banda, il trasferimento di 120 TB richiederebbe molto più di 3 settimane, quindi qualsiasi opzione basata sulla rete tramite il collegamento esistente non rispetta la scadenza. I dispositivi Snowball Edge spostano i dati offline con un basso costo una tantum. Direct Connect è un investimento di connettività a lungo termine che può richiedere settimane per il provisioning e non è giustificato per un trasferimento una tantum.","optionExplanations":["Direct Connect comporta tempi di provisioning e costi ricorrenti delle porte, risultando costoso e forse troppo lento da attivare per una migrazione una tantum.","Anche funzionando di continuo, un collegamento da 200 Mbps non può spostare 120 TB in 3 settimane, e limitarlo alle ore non lavorative lo rende ancora più lento.","Transfer Acceleration migliora il throughput sulle lunghe distanze ma non può superare la banda di 200 Mbps della sede e aggiunge costi per GB.","Corretto — Snowball Edge spedisce fisicamente i dati, evitando il collo di bottiglia della banda con un costo una tantum prevedibile, adatto a una migrazione una tantum."]},
  "1276": {"h":"5c4a98cb","question":"Un'azienda crea snapshot Amazon EBS dei propri volumi di produzione con uno script notturno eseguito su un'istanza EC2. Lo script non elimina gli snapshot vecchi, quindi se ne sono accumulate migliaia e la fattura per lo storage degli snapshot continua a crescere. L'azienda ha bisogno di snapshot giornalieri conservati per 14 giorni e di snapshot settimanali conservati per 3 mesi. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Estendere lo script per eliminare gli snapshot più vecchi dei periodi di conservazione e mantenerlo sull'istanza.","Usare policy di Amazon Data Lifecycle Manager con pianificazioni giornaliere e settimanali e regole di conservazione.","Usare AWS Backup per copiare ogni snapshot in una seconda Region ed eliminare gli originali dopo 14 giorni.","Spostare tutti gli snapshot esistenti nel livello EBS Snapshots Archive e lasciare invariato lo script notturno."],"explanation":"Amazon Data Lifecycle Manager crea nativamente snapshot EBS secondo pianificazioni e li elimina automaticamente in base alle regole di conservazione, eliminando lo script e la relativa istanza. Estendere lo script funzionerebbe, ma lascerebbe codice personalizzato e un'istanza da mantenere.","optionExplanations":["Questo risolve la conservazione ma lascia codice personalizzato e un'istanza EC2 in esecuzione da aggiornare e monitorare, con un onere maggiore rispetto a una policy gestita.","Corretto — le policy di Data Lifecycle Manager selezionano i volumi tramite tag, creano snapshot con pianificazioni giornaliere e settimanali e li eliminano automaticamente alla scadenza della conservazione.","Le copie tra Region aggiungono costi di storage e di trasferimento dati e non implementano lo schema di conservazione giornaliero e settimanale richiesto.","L'archiviazione riduce il prezzo degli snapshot vecchi, ma questi continuano ad accumularsi indefinitamente, e l'archivio prevede una conservazione minima e costi di ripristino."]},
  "1277": {"h":"06f83b4a","question":"Una revisione dei costi di un account di sviluppo individua decine di volumi Amazon EBS non collegati a nessuna istanza da mesi e molti indirizzi Elastic IP non associati ad alcuna istanza in esecuzione. I dati sui volumi potrebbero servire di nuovo in rari casi. Quale combinazione di azioni ridurrà MAGGIORMENTE i costi? (Seleziona DUE)","options":["Creare uno snapshot di ogni volume non collegato e poi eliminare il volume.","Cambiare ogni volume non collegato nel tipo gp3 e mantenerlo.","Collegare i volumi non collegati a un'istanza EC2 arrestata per evitare gli addebiti.","Rilasciare gli indirizzi Elastic IP non associati a istanze in esecuzione.","Associare gli indirizzi Elastic IP inutilizzati a un NAT Gateway dell'account."],"explanation":"I volumi EBS non collegati vengono fatturati per l'intera dimensione allocata, quindi crearne uno snapshot (che archivia solo i blocchi usati a un prezzo inferiore) ed eliminarli preserva i dati a un costo molto più basso. Gli indirizzi Elastic IP inutilizzati comportano addebiti orari per gli IPv4 pubblici, quindi rilasciarli elimina quel costo. Collegare i volumi a istanze arrestate non interrompe gli addebiti per lo storage EBS.","optionExplanations":["Corretto — uno snapshot mantiene i dati recuperabili a un prezzo di storage inferiore ed eliminare il volume interrompe gli addebiti per la capacità allocata.","gp3 può costare meno di gp2, ma i volumi continuerebbero a essere fatturati per l'intera capacità allocata senza fornire alcun valore.","I volumi EBS vengono fatturati indipendentemente dal fatto che l'istanza a cui sono collegati sia in esecuzione, quindi non si risparmia nulla.","Corretto — gli indirizzi IPv4 pubblici inutilizzati vengono addebitati su base oraria; rilasciare quelli che non servono alcun workload in esecuzione elimina l'addebito.","Un NAT Gateway ha propri costi orari e di elaborazione dati, e associarvi gli indirizzi aggiunge costi anziché eliminarli."]},
  "1278": {"h":"c2aa43bd","question":"Un'azienda esegue un workload batch tollerante ai guasti su un EC2 Fleet di Spot Instances con 12 tipi di istanza e 3 Availability Zone. Il fleet usa la strategia di allocazione lowest-price e le frequenti interruzioni fanno ripartire molti job, che terminano in ritardo. L'azienda vuole mantenere bassi i costi riducendo le interruzioni con il MINOR sforzo. Quale soluzione soddisfa questi requisiti?","options":["Cambiare la strategia di allocazione in diversified, così le istanze vengono distribuite uniformemente su tutti i pool Spot.","Sostituire le Spot Instances con istanze On-Demand coperte da un Compute Savings Plan.","Limitare il fleet all'unico tipo di istanza con il prezzo Spot storico più basso.","Cambiare la strategia di allocazione in price-capacity-optimized."],"explanation":"La strategia price-capacity-optimized avvia capacità Spot dai pool con maggiore capacità disponibile e, tra questi, con i prezzi più bassi, riducendo le interruzioni e mantenendo bassi i costi; AWS la raccomanda per la maggior parte dei workload Spot. La strategia lowest-price ignora la profondità della capacità, ed è per questo che le interruzioni sono frequenti.","optionExplanations":["Diversified distribuisce le istanze tra i pool indipendentemente dalla loro capacità disponibile, quindi può comunque collocare capacità in pool soggetti a interruzioni.","Passare a On-Demand elimina le interruzioni ma rinuncia alla maggior parte del risparmio Spot, in contrasto con l'obiettivo di costo.","Usare un unico tipo di istanza riduce i pool di capacità disponibili e aumenta la probabilità e l'impatto delle interruzioni.","Corretto — price-capacity-optimized privilegia i pool con molta capacità e poi i prezzi bassi, bilanciando rischio di interruzione e costo con una semplice modifica di configurazione."]},
  "1279": {"h":"f0712a5d","question":"Un fleet di istanze worker interroga continuamente in un ciclo serrato una coda Amazon SQS standard. I messaggi arrivano a raffiche irregolari e la maggior parte delle chiamate di ricezione non restituisce alcun messaggio. I costi delle richieste SQS sono diventati evidenti in fattura. Quale modifica ridurrà questi costi con il MINOR sforzo?","options":["Abilitare il long polling impostando il tempo di attesa di ricezione dei messaggi sulla coda.","Convertire la coda in una coda FIFO in modo che i messaggi vengano consegnati in batch.","Aumentare il visibility timeout in modo che i messaggi vengano ricevuti meno volte.","Aggiungere un topic Amazon SNS che invii ogni nuovo messaggio ai worker tramite HTTPS."],"explanation":"Il long polling fa sì che una chiamata di ricezione attenda l'arrivo dei messaggi prima di rispondere, eliminando la maggior parte delle risposte vuote e quindi la maggior parte delle richieste fatturabili. Aumentare il visibility timeout influisce su quanto a lungo un messaggio in elaborazione resta nascosto, non sul numero di polling vuoti.","optionExplanations":["Corretto — con il long polling ogni richiesta di ricezione attende i messaggi, riducendo drasticamente il numero di risposte vuote fatturabili.","Le code FIFO forniscono ordinamento e deduplicazione; la conversione non riduce le ricezioni vuote e richiede modifiche all'applicazione.","Il visibility timeout controlla la riconsegna dei messaggi in elaborazione e non ha alcun effetto sulle richieste di polling vuote.","L'invio verso endpoint HTTP richiede che i worker espongano endpoint e gestiscano i tentativi, una riprogettazione significativa rispetto a un'impostazione della coda."]},
  "1280": {"h":"f63acdfd","question":"Un'azienda esegue milioni di volte al giorno una funzione AWS Lambda a uso intensivo di CPU. La funzione è configurata con l'impostazione di memoria minima, usa solo una piccola quantità di memoria e ogni invocazione dura diversi secondi. L'azienda vuole trovare la configurazione con il costo per invocazione più basso sulla base di misurazioni reali. Quale soluzione soddisfa questi requisiti?","options":["Mantenere l'impostazione di memoria minima, perché i costi di Lambda sono proporzionali alla memoria configurata.","Usare AWS Lambda Power Tuning per confrontare costo e durata con diverse impostazioni di memoria.","Configurare la provisioned concurrency per la funzione per ottenere un prezzo per invocazione inferiore.","Spostare la funzione su Amazon EC2 Spot Instances per eliminare i costi per invocazione."],"explanation":"Lambda assegna la CPU in proporzione alla memoria configurata, quindi una funzione CPU-bound può essere eseguita molto più velocemente con più memoria, riducendo talvolta i GB-secondi totali e quindi il costo. AWS Lambda Power Tuning esegue la funzione con diverse impostazioni di memoria e riporta costo e durata per ciascuna. Mantenere la memoria minima è allettante perché il prezzo per millisecondo è il più basso, ma la durata maggiore può renderla complessivamente più costosa.","optionExplanations":["Lambda fattura la memoria moltiplicata per la durata; con più memoria una funzione CPU-bound ottiene più CPU e può terminare abbastanza in fretta da costare meno.","Corretto — Power Tuning misura durata e costo con diverse impostazioni di memoria usando invocazioni reali, individuando la configurazione più economica.","La provisioned concurrency riguarda la latenza dei cold start e aggiunge un costo per gli ambienti allocati; non è un metodo di tuning basato su misurazioni.","Migrare su EC2 Spot aggiunge gestione dell'infrastruttura e delle interruzioni e non risponde alla domanda su quale configurazione sia la più economica."]},
  "1281": {"h":"15ec75bf","question":"Un'azienda elabora un flusso continuo di transazioni con funzioni AWS Lambda. Il traffico è costante 24 ore su 24, centinaia di istanze della funzione sono sempre occupate e ogni invocazione dura diversi minuti con CPU elevata. Il team operativo ha esperienza nell'esecuzione di container su istanze EC2 e il workload continuerà per anni. Quale soluzione sarà la PIÙ conveniente?","options":["Aumentare la memoria delle funzioni Lambda in modo che ogni invocazione termini più rapidamente.","Orchestrare le funzioni con AWS Step Functions Express Workflows per ridurre i costi di overhead per invocazione.","Eseguire l'elaborazione come container di lunga durata su Amazon ECS su istanze EC2 coperte da un Savings Plan.","Posizionare Amazon API Gateway con caching davanti alle funzioni per ridurre le invocazioni ripetute."],"explanation":"Lambda è più conveniente per workload a picchi o con basso ciclo di utilizzo; per un'elaborazione costante ad alto utilizzo attiva 24 ore su 24, i container di lunga durata su istanze EC2 con un impegno Savings Plan costano molto meno per unità di lavoro. Il team ha già le competenze per gestire container basati su EC2. Più memoria potrebbe accorciare ogni invocazione, ma non cambia un modello di prezzo sfavorevole per un carico sostenuto.","optionExplanations":["Regolare la memoria può ridurre leggermente il costo, ma un'elaborazione sostenuta a tempo pieno resta più costosa su Lambda che su capacità EC2 con impegno.","Step Functions aggiunge costi di orchestrazione e non riduce il costo di calcolo delle invocazioni Lambda di lunga durata.","Corretto — un'elaborazione sempre attiva e pienamente utilizzata costa meno su capacità EC2 con un impegno a lungo termine, e il team è in grado di gestire il cluster ECS.","Ogni transazione è un dato univoco dello stream, quindi il caching delle risposte non evita le invocazioni e aggiunge costi di API Gateway."]},
  "1282": {"h":"850f522f","question":"Un'azienda ha acquistato dei Compute Savings Plans un anno fa. Da allora sono stati avviati diversi nuovi workload su Amazon EC2, AWS Fargate e AWS Lambda. Il reparto finanziario vuole sapere quanta parte della spesa di calcolo idonea viene ancora fatturata a tariffe On-Demand per decidere se acquistare un impegno aggiuntivo. Quale strumento fornisce questa informazione nel modo PIÙ diretto?","options":["Il report di utilizzo dei Savings Plans in AWS Cost Explorer","Il report di copertura dei Savings Plans in AWS Cost Explorer","I controlli di AWS Trusted Advisor per le istanze EC2 sottoutilizzate","Le raccomandazioni sulle istanze di AWS Compute Optimizer"],"explanation":"Il report di copertura dei Savings Plans mostra quale parte della spesa idonea è coperta dai Savings Plans e quanta resta a tariffe On-Demand, esattamente ciò che serve per dimensionare un impegno aggiuntivo. Il report di utilizzo è il distrattore allettante, ma mostra quanto dell'impegno esistente viene usato, non quanta spesa resta scoperta.","optionExplanations":["L'utilizzo misura quanto viene sfruttato l'impegno esistente; non mostra la spesa On-Demand residua che potrebbe essere coperta.","Corretto — la copertura riporta la quota della spesa idonea per EC2, Fargate e Lambda coperta dai Savings Plans rispetto a quella fatturata On-Demand.","Trusted Advisor segnala le istanze poco utilizzate per il rightsizing; non riporta la copertura dei Savings Plans sulla spesa di calcolo.","Compute Optimizer raccomanda dimensioni delle risorse in base all'utilizzo; non misura la copertura degli impegni."]},
  "1283": {"h":"2373808b","question":"Un'azienda usa AWS Organizations con la fatturazione consolidata. L'account di networking ha acquistato diverse EC2 Reserved Instances per un progetto concluso e le prenotazioni ora sono inutilizzate. Istanze corrispondenti sono in esecuzione On-Demand in altri account membri, ma questi account non ricevono alcuno sconto RI perché la condivisione degli sconti è stata disattivata per tutti gli account anni fa. Quale soluzione ridurrà i costi con il MINOR sforzo?","options":["Attivare la condivisione degli sconti di Reserved Instances e Savings Plans nelle preferenze di fatturazione dell'account di gestione.","Vendere le Reserved Instances inutilizzate sul Reserved Instance Marketplace e acquistarne di nuove negli altri account.","Spostare i workload On-Demand dagli account membri all'account di networking che possiede le prenotazioni.","Modificare le Reserved Instances in una diversa famiglia di istanze ancora usata dall'account di networking."],"explanation":"Con la fatturazione consolidata, gli sconti di RI e Savings Plans possono essere condivisi tra tutti gli account dell'organizzazione; riattivare la condivisione consente di applicare le prenotazioni inutilizzate all'utilizzo corrispondente in altri account con un'unica impostazione. Vendere e riacquistare le prenotazioni o migrare i workload tra account otterrebbe un risultato simile con uno sforzo molto maggiore.","optionExplanations":["Corretto — riattivare la condivisione degli sconti consente di applicare automaticamente le prenotazioni inutilizzate all'utilizzo On-Demand corrispondente in altre parti dell'organizzazione.","Le vendite sul Marketplace richiedono tempo, potrebbero non recuperare l'intero valore e il riacquisto crea un nuovo impegno quando quelli esistenti potrebbero semplicemente essere condivisi.","Migrare i workload tra account è un progetto impegnativo che stravolge i confini degli account solo per ottenere uno sconto in fattura.","Modificare gli attributi della prenotazione non aiuta se l'account di networking non esegue più alcun utilizzo corrispondente di qualsiasi famiglia."]},
  "1284": {"h":"54eb661c","question":"Un'azienda esegue un'applicazione OLTP con molte scritture su un cluster Amazon Aurora compatibile con PostgreSQL con la configurazione di storage Aurora Standard. L'analisi dei costi mostra che gli addebiti per le richieste di I/O costituiscono una quota ampia e imprevedibile della fattura mensile del cluster, mentre il dimensionamento delle istanze è appropriato. Quale soluzione ridurrà i costi e li renderà più prevedibili con il MINOR sforzo?","options":["Aggiungere delle Aurora Replica in modo che il traffico di lettura non generi più costi di I/O sull'istanza di scrittura.","Migrare il database su Amazon RDS for PostgreSQL con storage Provisioned IOPS SSD.","Cambiare la configurazione di storage del cluster in Aurora I/O-Optimized.","Abilitare Aurora Serverless v2 per l'istanza di scrittura per ridurre le richieste di I/O."],"explanation":"Aurora I/O-Optimized elimina gli addebiti per le operazioni di I/O in lettura e scrittura in cambio di prezzi più alti per istanze e storage, riducendo il costo totale e rendendolo prevedibile per i cluster a uso intensivo di I/O; la modifica è un cambio di configurazione senza migrazione. Migrare su RDS con Provisioned IOPS richiede una migrazione del database e fa perdere le funzionalità di Aurora.","optionExplanations":["Le Aurora Replica condividono lo stesso storage del cluster e con Aurora Standard le letture dalle repliche sono comunque fatturate come I/O, mentre le repliche aggiungono costi di istanza.","Una migrazione a RDS richiede uno sforzo significativo e cambia l'architettura, quando un'impostazione della configurazione di storage risolve direttamente il problema dei costi.","Corretto — I/O-Optimized elimina gli addebiti di I/O per richiesta, adatto ai cluster in cui l'I/O è una quota ampia della spesa, e si abilita senza migrare.","Serverless v2 cambia il modo in cui scala la capacità di calcolo; non riduce le richieste di I/O generate da un workload con molte scritture."]},
  "1285": {"h":"3018413f","question":"Un'azienda ha una tabella Amazon DynamoDB in modalità di capacità provisioned con auto scaling. La tabella usa costantemente un livello minimo stabile di capacità di lettura e scrittura in ogni ora del giorno e l'applicazione resterà in produzione per almeno altri 3 anni senza modifiche importanti. Quale soluzione ridurrà MAGGIORMENTE il costo di questa tabella?","options":["Passare la tabella alla modalità di capacità on-demand per pagare solo le richieste effettuate.","Acquistare DynamoDB reserved capacity per la base stabile di capacità di lettura e scrittura.","Cambiare la classe della tabella in DynamoDB Standard-Infrequent Access.","Aggiungere un cluster DynamoDB Accelerator (DAX) davanti alla tabella per tutte le letture."],"explanation":"La DynamoDB reserved capacity offre uno sconto significativo sulla capacità di lettura e scrittura provisioned in cambio di un impegno di 1 o 3 anni, adatto a una base stabile e di lunga durata. La modalità on-demand costa di più per richiesta rispetto a una capacità provisioned ben utilizzata con traffico costante.","optionExplanations":["On-demand è pensata per il traffico imprevedibile ed è più costosa per richiesta rispetto a una capacità provisioned utilizzata in modo costante.","Corretto — impegnarsi sulla base stabile con la reserved capacity riduce il prezzo del throughput, mentre l'auto scaling continua a gestire le variazioni al di sopra.","Standard-IA riduce i prezzi dello storage ma aumenta quelli del throughput; è adatta a tabelle dominate dallo storage, non dal throughput.","DAX aggiunge costi per i nodi e aiuta solo con accessi a prevalenza di letture e adatti al caching; non sconta la capacità di scrittura e lettura esistente."]},
  "1286": {"h":"68aabf8d","question":"Un'azienda usa un cluster Amazon ElastiCache for Redis OSS come session store. Il cluster è in esecuzione da 2 anni con lo stesso tipo e numero di nodi, l'utilizzo della memoria è stabile e non sono previste modifiche per i prossimi 3 anni. Un membro del team suggerisce di migrare a ElastiCache Serverless per risparmiare. Quale soluzione è la PIÙ conveniente?","options":["Migrare a ElastiCache Serverless così l'azienda paga solo per i dati archiviati e le richieste effettuate.","Sostituire il cluster con una tabella Amazon DynamoDB in modalità di capacità on-demand.","Eseguire Redis su Amazon EC2 Spot Instances autogestite per ottenere il prezzo di calcolo più basso.","Acquistare ElastiCache reserved node per il tipo di nodo esistente con una durata di 3 anni."],"explanation":"Per una cache con capacità stabile e prevedibile, i reserved node offrono uno sconto sostanziale rispetto al prezzo On-Demand dei nodi senza alcuna modifica architetturale. ElastiCache Serverless è ottimizzato per workload variabili o imprevedibili; con un utilizzo costante è generalmente più costoso dei reserved node.","optionExplanations":["Il prezzo Serverless è adatto a una domanda a picchi o sconosciuta; per un utilizzo costante e a lungo termine di solito costa più dei reserved node scontati.","Sostituire la cache con DynamoDB è una riprogettazione e il prezzo on-demand non è ottimizzato per un traffico di sessione costante.","Le interruzioni Spot farebbero perdere i dati di sessione e l'autogestione aggiunge onere operativo, il che è inaccettabile per un session store.","Corretto — i reserved node scontano la capacità prevedibile e invariata senza alcuna migrazione o modifica operativa."]},
  "1287": {"h":"216e1b90","question":"Un'azienda ha un cluster Amazon Redshift provisioned in esecuzione continua. Gli analisti eseguono poche query in momenti imprevedibili del giorno e della notte e il cluster resta inattivo per più del 90% del tempo. Le query devono partire senza attendere che il data warehouse venga avviato manualmente. Quale soluzione è la PIÙ conveniente?","options":["Migrare il data warehouse su Amazon Redshift Serverless.","Pianificare la sospensione del cluster provisioned di notte e la ripresa ogni mattina.","Acquistare Redshift reserved node per il cluster esistente.","Usare l'elastic resize per ridurre il cluster al numero minimo di nodi."],"explanation":"Redshift Serverless effettua automaticamente il provisioning della capacità quando arrivano le query e fattura solo il calcolo usato durante la loro esecuzione, il che si adatta a un utilizzo sporadico in momenti imprevedibili. Una pianificazione di sospensione e ripresa è allettante, ma le query possono arrivare di notte, quando il cluster sarebbe sospeso.","optionExplanations":["Corretto — Serverless addebita solo durante l'esecuzione delle query e si avvia automaticamente, quindi un data warehouse inattivo costa solo lo storage.","Una pianificazione fissa non può adattarsi a orari delle query imprevedibili; le query che arrivano mentre il cluster è sospeso fallirebbero finché qualcuno non lo riprende.","I reserved node scontano un cluster sempre in esecuzione, ma l'azienda continuerebbe a pagare per una capacità inattiva per la maggior parte del tempo.","Un cluster più piccolo viene comunque fatturato ogni ora anche quando è inattivo e potrebbe avere difficoltà nelle prestazioni delle query."]},
  "1288": {"h":"9429688d","question":"Un'azienda archivia diversi anni di dati di clickstream su Amazon S3 come file JSON non compressi in un unico prefisso. Gli analisti interrogano i dati con Amazon Athena e quasi ogni query filtra su un intervallo di date di pochi giorni, eppure ogni query scansiona l'intero dataset. Quale combinazione di azioni ridurrà MAGGIORMENTE i costi di Athena? (Seleziona DUE)","options":["Convertire i dati in un formato colonnare compresso come Apache Parquet.","Spostare i file JSON nella classe di storage S3 Standard-IA.","Organizzare i dati in partizioni basate sulla data e usare la partition projection nella definizione della tabella.","Creare un workgroup Athena separato per ogni team di analisti.","Acquistare capacità provisioned di Athena per le query degli analisti."],"explanation":"Athena addebita in base alla quantità di dati scansionati. I formati colonnari compressi consentono ad Athena di leggere solo le colonne referenziate di file molto più piccoli, e le partizioni per data permettono alle query di saltare tutti i dati al di fuori dell'intervallo richiesto; la partition projection evita di gestire i metadati delle partizioni. Spostare i file in Standard-IA aumenterebbe i costi, perché le letture di Athena comportano tariffe di recupero IA.","optionExplanations":["Corretto — Parquet con compressione riduce i byte archiviati e consente ad Athena di leggere solo le colonne necessarie a una query.","Standard-IA aggiunge addebiti di recupero per GB ogni volta che Athena scansiona i file, aumentando i costi per dati interrogati di frequente.","Corretto — il partizionamento per data consente alle query di escludere i dati al di fuori dell'intervallo filtrato, così vengono scansionati solo pochi giorni di dati.","I workgroup aiutano a separare e limitare l'utilizzo, ma non riducono i dati scansionati da ciascuna query.","La capacità provisioned fattura in modo continuo le unità di elaborazione riservate e non riduce la quantità di dati scansionati da tabelle mal organizzate."]},
  "1289": {"h":"73e176fa","question":"Un sito di notizie regionale usa una distribuzione Amazon CloudFront con le impostazioni predefinite. Le analisi mostrano che quasi tutti i lettori si trovano in Nord America ed Europa e il piccolo numero di lettori altrove può tollerare una latenza maggiore. L'azienda vuole ridurre i costi di CloudFront. Quale soluzione soddisfa questi requisiti?","options":["Disabilitare la distribuzione CloudFront e servire i contenuti direttamente dall'origine.","Usare le restrizioni geografiche di CloudFront per bloccare tutti i paesi al di fuori di Nord America ed Europa.","Impostare la price class della distribuzione in modo da includere solo le Edge Location delle aree meno costose.","Abilitare CloudFront Origin Shield in una Region vicina al Nord America."],"explanation":"Le price class di CloudFront limitano quali Edge Location servono le richieste; una price class che copre solo Nord America ed Europa evita le Edge Location più costose, mentre gli utenti altrove continuano a essere serviti, con una latenza maggiore. Le restrizioni geografiche bloccherebbero completamente quegli utenti, cosa che i requisiti non consentono.","optionExplanations":["Servire direttamente dall'origine aumenta il carico sull'origine e i costi di trasferimento dati ed elimina i vantaggi del caching.","Le restrizioni geografiche negano l'accesso ai lettori al di fuori dei paesi consentiti, ma anche quei lettori devono essere serviti.","Corretto — una price class ristretta serve le richieste solo da Edge Location meno costose, riducendo i costi mentre tutti gli utenti continuano a ricevere i contenuti.","Origin Shield aggiunge un livello di caching per ridurre il carico sull'origine e ha costi propri; non riduce i prezzi di distribuzione dall'edge."]},
  "1290": {"h":"cdcb563d","question":"Le applicazioni in subnet private inviano un volume molto elevato di messaggi ad Amazon SQS e di record ad Amazon Kinesis Data Streams nella stessa Region. Attualmente tutto questo traffico esce attraverso NAT Gateway e i costi di elaborazione dati dei NAT Gateway sono diventati una voce di spesa importante. Quale soluzione ridurrà questi costi nel modo PIÙ conveniente?","options":["Sostituire i NAT Gateway con NAT instance su tipi di istanza EC2 burstable.","Creare gateway VPC endpoint per Amazon SQS e Kinesis Data Streams.","Spostare le applicazioni in subnet pubbliche e assegnare loro indirizzi IPv4 pubblici.","Creare interface VPC endpoint per Amazon SQS e Kinesis Data Streams nel VPC."],"explanation":"Gli interface VPC endpoint (AWS PrivateLink) consentono alle applicazioni di raggiungere SQS e Kinesis in modo privato e il loro costo di elaborazione per GB è inferiore a quello dei NAT Gateway per questo tipo di traffico ad alto volume. I gateway endpoint sono l'opzione gratuita, ma esistono solo per Amazon S3 e DynamoDB.","optionExplanations":["Le NAT instance aggiungono onere di gestione, hanno un throughput limitato sui tipi burstable e diventano un rischio per scalabilità e disponibilità.","I gateway endpoint sono disponibili solo per Amazon S3 e Amazon DynamoDB, non per SQS o Kinesis.","Le subnet pubbliche indeboliscono la sicurezza e aggiungono costi per gli indirizzi IPv4 pubblici; non sono una soluzione adeguata a un problema di costi.","Corretto — gli interface endpoint mantengono il traffico sulla rete AWS ed evitano i costi di elaborazione dati dei NAT Gateway con una tariffa per GB inferiore."]},
  "1291": {"h":"1dab04ad","question":"Un application server e un database server autogestito sono in esecuzione su istanze EC2 nella stessa Availability Zone e si scambiano grandi quantità di dati. L'applicazione si connette al database usando l'indirizzo Elastic IP dell'istanza database e la fattura mostra costi significativi di trasferimento dati tra le due. Quale modifica ridurrà questi costi?","options":["Configurare l'applicazione per connettersi al database usando il suo indirizzo IP privato.","Spostare l'istanza database in una subnet diversa nella stessa Availability Zone.","Collocare entrambe le istanze in uno spread placement group all'interno della Availability Zone.","Abilitare l'enhanced networking su entrambe le istanze per comprimere il traffico."],"explanation":"Il traffico tra istanze EC2 nella stessa Availability Zone è gratuito quando usa indirizzi IP privati, ma il traffico inviato a un indirizzo pubblico o Elastic IP viene fatturato come trasferimento dati anche all'interno della stessa AZ. Cambiare subnet o posizionamento non conta finché si usa l'indirizzo pubblico.","optionExplanations":["Corretto — usare gli indirizzi IP privati rende il traffico nella stessa AZ esente da costi di trasferimento dati.","La subnet non cambia la fatturazione; l'addebito deriva dal raggiungere l'istanza tramite il suo Elastic IP pubblico.","I placement group influiscono sul posizionamento fisico, non su come viene fatturato il traffico indirizzato a un IP pubblico.","L'enhanced networking aumenta le prestazioni a livello di pacchetti; non comprime il traffico né cambia il prezzo del trasferimento dati."]},
  "1292": {"h":"0e42f265","question":"Un'azienda invia ad Amazon CloudWatch Logs i log applicativi di centinaia di servizi. Tutti i log group usano l'impostazione predefinita di nessuna scadenza e lo storage dei log è ora una delle voci più grandi della fattura. Gli ingegneri consultano solo gli ultimi 30 giorni di log, ma i revisori richiedono una conservazione di 7 anni, con un recupero entro un giorno accettabile per i log più vecchi. Quale soluzione è la PIÙ conveniente?","options":["Mantenere i log in CloudWatch Logs a tempo indeterminato e creare metric filter per supportare le query dei revisori.","Impostare una conservazione di 30 giorni e usare Data Firehose per inviare i log a S3, archiviati in Deep Archive.","Impostare una conservazione di 7 anni su tutti i log group e passarli alla log class CloudWatch Logs Infrequent Access.","Installare il CloudWatch agent per scrivere i log su volumi Amazon EBS collegati a ogni istanza per 7 anni."],"explanation":"Una conservazione breve in CloudWatch Logs mantiene consultabili i log solo per il periodo usato dagli ingegneri, e inviarne una copia a S3 con transizione a Glacier Deep Archive conserva la copia di audit per 7 anni al prezzo di storage più basso, con recupero entro poche ore. La log class Infrequent Access riduce il costo di acquisizione, ma conservare 7 anni di log in CloudWatch Logs resta molto più costoso dello storage di archiviazione su S3.","optionExplanations":["I log group senza scadenza sono la causa della fattura in crescita e i metric filter non riducono il volume dei log archiviati.","Corretto — la conservazione di 30 giorni limita lo storage di CloudWatch, mentre la copia su S3 archiviata in Deep Archive soddisfa il requisito dei 7 anni a costo minimo.","Conservare 7 anni di log in CloudWatch Logs costa molto più dello storage di archiviazione, anche con la classe Infrequent Access.","Archiviare i log su volumi EBS è costoso, fragile, difficile da consultare e non fornisce una conservazione di audit durevole e centralizzata."]},
  "1293": {"h":"67fbfc56","question":"Un'azienda assegna a ogni team di sviluppo un proprio account AWS. Un team ha più volte lasciato in esecuzione istanze EC2 di grandi dimensioni, superando il budget mensile. La direzione vuole che le istanze di sviluppo con tag del team vengano arrestate automaticamente quando la spesa effettiva supera il budget, senza scrivere codice personalizzato. Quale soluzione soddisfa questi requisiti?","options":["Creare una regola Amazon EventBridge che arresti le istanze quando un allarme di fatturazione CloudWatch cambia stato.","Creare un'azione AWS Budgets che arresti le istanze EC2 specificate quando il budget viene superato.","Abilitare AWS Cost Anomaly Detection e iscrivere il responsabile del team agli avvisi di anomalia via email.","Applicare una service control policy che neghi sempre tutte le azioni EC2 nell'account del team."],"explanation":"Le azioni di AWS Budgets possono essere eseguite automaticamente quando viene superata una soglia di budget, ad esempio arrestando specifiche istanze EC2 o RDS o applicando policy IAM o SCP, senza codice personalizzato. Un allarme di fatturazione CloudWatch con EventBridge richiederebbe una funzione Lambda o un target simile per arrestare effettivamente le istanze.","optionExplanations":["I cambi di stato dell'allarme di fatturazione richiederebbero comunque un'automazione personalizzata, come una funzione Lambda, per individuare e arrestare le istanze.","Corretto — un'azione di Budgets arresta automaticamente le istanze selezionate quando la spesa supera la soglia, senza codice personalizzato.","Anomaly Detection segnala andamenti di spesa insoliti ma non esegue alcuna azione automatica per arrestare le risorse.","Un divieto permanente sulle azioni EC2 impedirebbe al team qualsiasi attività di sviluppo, andando ben oltre il requisito."]},
  "1294": {"h":"ef955e4e","question":"Un'azienda sta pianificando la migrazione su AWS di un'applicazione on-premises. Prima di approvare il progetto, la direzione vuole una stima del costo mensile dell'architettura proposta, che include istanze EC2, un Application Load Balancer, Amazon RDS, Amazon S3 e il trasferimento dati. Su AWS non è ancora stato distribuito nulla. Quale soluzione fornirà questa stima?","options":["Usare le previsioni di AWS Cost Explorer per proiettare i costi della nuova architettura.","Usare AWS Compute Optimizer per ottenere raccomandazioni sui tipi di istanza e i relativi prezzi mensili.","Modellare l'architettura in AWS Pricing Calculator e condividere la stima salvata.","Creare un budget AWS Budgets ed esaminarne la spesa prevista per il primo mese."],"explanation":"AWS Pricing Calculator stima il costo dei servizi e delle configurazioni AWS pianificati prima che venga distribuito qualsiasi cosa, e la stima può essere salvata e condivisa. Le previsioni di Cost Explorer si basano sull'utilizzo storico, che per questo account non esiste ancora.","optionExplanations":["Le previsioni di Cost Explorer derivano dall'utilizzo passato, quindi non possono proiettare i costi di un'architettura mai eseguita.","Compute Optimizer analizza le metriche di risorse in esecuzione; senza nulla di distribuito non ha dati per produrre raccomandazioni.","Corretto — Pricing Calculator consente al team di modellare ogni servizio pianificato e produrre una stima mensile condivisibile prima del deployment.","Budgets monitora e prevede la spesa effettiva; non stima il costo di un'architettura non ancora distribuita."]},
  "1295": {"h":"9662a7e9","question":"Un'azienda ha 80 account in AWS Organizations. I costi devono essere riportati per business unit, ma una business unit è definita da una combinazione di appartenenza agli account e tag delle risorse, e i costi di un account di networking condiviso devono essere ripartiti proporzionalmente tra le business unit. L'azienda vuole questa reportistica negli strumenti di fatturazione AWS con il MINOR onere operativo. Quale soluzione soddisfa questi requisiti?","options":["Creare AWS Cost Categories con regole basate su account e tag e usare regole di split charge per i costi condivisi.","Esportare il Cost and Usage Report su Amazon S3 e realizzare un processo di ripartizione personalizzato in Amazon Athena.","Spostare tutte le risorse di ogni business unit in un account dedicato, così che i report a livello di account siano sufficienti.","Creare un budget AWS Budgets per ogni business unit filtrato per tag e aggiungere manualmente i costi di networking."],"explanation":"Le AWS Cost Categories raggruppano i costi in categorie definite dal business tramite regole basate su account, tag e altre dimensioni, e le regole di split charge ripartiscono i costi condivisi tra le categorie in modo proporzionale o per importi fissi; le categorie compaiono poi in Cost Explorer, Budgets e nel Cost and Usage Report. Un processo personalizzato in Athena potrebbe produrre lo stesso risultato, ma richiede di realizzare e mantenere la logica di ripartizione.","optionExplanations":["Corretto — le Cost Categories combinano nativamente regole su account e tag e le regole di split charge ripartiscono automaticamente i costi di networking condivisi.","Una pipeline personalizzata con CUR e Athena funziona, ma richiede sviluppo e manutenzione continui della logica di ripartizione.","Ristrutturare tutti gli account è un'operazione di migrazione impegnativa e comunque non gestisce i costi di networking condivisi.","Budgets monitora la spesa rispetto a dei limiti; ripartire manualmente ogni mese i costi di networking è soggetto a errori e aggiunge lavoro."]},
  "1296": {"h":"32c80ee2","question":"Un'azienda archivia le foto dei prodotti in un bucket S3. Il team ritiene che le foto diventino ad accesso poco frequente alcune settimane dopo il caricamento, ma non sa quando, e vuole basare una transizione di lifecycle verso S3 Standard-IA su dati di accesso osservati anziché su un'ipotesi. Si prevede che l'andamento degli accessi sia simile per tutte le foto. Quale soluzione soddisfa questi requisiti con il MINOR sforzo?","options":["Abilitare i server access log di S3 e calcolare l'età di accesso degli oggetti con uno script personalizzato.","Configurare S3 Storage Class Analysis e usarne i risultati per impostare l'età di transizione.","Abilitare i report di S3 Inventory e confrontare le date di creazione degli oggetti con la loro classe di storage.","Usare AWS Trusted Advisor per trovare l'età di transizione raccomandata per il bucket."],"explanation":"S3 Storage Class Analysis osserva gli andamenti di accesso su un bucket, un prefisso o un tag e indica quando i dati diventano ad accesso poco frequente, informazione utilizzabile per impostare l'età di una transizione di lifecycle verso Standard-IA. S3 Inventory elenca gli oggetti e i relativi metadati, ma non mostra con quale frequenza vengono letti.","optionExplanations":["Analizzare gli access log potrebbe rivelare l'andamento, ma richiede di realizzare ed eseguire un'analisi personalizzata.","Corretto — Storage Class Analysis misura gli accessi effettivi in base all'età degli oggetti e aiuta a scegliere l'età di transizione corretta per Standard-IA.","I report di Inventory mostrano metadati degli oggetti come dimensione e classe di storage, non la frequenza di accesso, quindi non possono rivelare quando gli accessi diminuiscono.","Trusted Advisor non analizza gli andamenti di accesso dei singoli bucket per raccomandare età di transizione del lifecycle."]},
  "1297": {"h":"71ba30ee","question":"Un'applicazione di elaborazione log su EC2 scrive e legge in modo sequenziale file di log da diversi terabyte in blocchi di grandi dimensioni. Il workload richiede un throughput elevato ma pochissimi IOPS casuali e il volume dati non è il volume di avvio. Attualmente usa volumi gp3 di grandi dimensioni. Quale tipo di volume EBS soddisfa questi requisiti nel modo PIÙ conveniente?","options":["Volumi Provisioned IOPS SSD (io2)","Volumi Throughput Optimized HDD (st1)","Volumi Cold HDD (sc1)","Volumi General Purpose SSD (gp2)"],"explanation":"Throughput Optimized HDD (st1) è progettato per workload sequenziali ad accesso frequente e a uso intensivo di throughput, come l'elaborazione di log e i big data, con un prezzo per GB inferiore rispetto ai volumi SSD. Cold HDD (sc1) è ancora più economico, ma è pensato per dati ad accesso poco frequente e offre un throughput inferiore, non adatto a un workload ad alto throughput.","optionExplanations":["I volumi io2 hanno prezzi pensati per IOPS casuali elevati e bassa latenza, di cui questo workload sequenziale non ha bisogno.","Corretto — st1 offre un throughput sequenziale elevato a basso costo per GB, adatto all'elaborazione sequenziale di grandi log su volumi non di avvio.","sc1 ha il prezzo più basso ma un throughput inferiore ed è pensato per dati freddi ad accesso poco frequente.","Lo storage SSD gp2 costa più per GB di st1 e le sue prestazioni sono legate alla dimensione del volume, senza alcun vantaggio per il throughput sequenziale."]},
  "1298": {"h":"6772ea4f","question":"Un'azienda esegue un cluster Amazon EMR di lunga durata con nodi primary, core e task On-Demand. Il cluster archivia i dati di input in HDFS ed esegue job Spark per circa 4 ore ogni notte, poi resta inattivo per il resto della giornata. I job possono tollerare la perdita di singoli nodi task. Quale combinazione di azioni ridurrà MAGGIORMENTE i costi? (Seleziona DUE)","options":["Archiviare i dati su Amazon S3 e avviare un cluster transitorio per ogni esecuzione notturna che termini al completamento dei job.","Eseguire i nodi core su Spot Instances in modo che la capacità HDFS costi meno.","Eseguire i nodi task su Spot Instances mantenendo On-Demand i nodi primary e core.","Acquistare Reserved Instances per ogni nodo dell'attuale cluster di lunga durata.","Eseguire il nodo primary su una Spot Instance e i nodi core e task On-Demand."],"explanation":"Mantenere i dati su Amazon S3 separa lo storage dal calcolo, così il cluster può essere eseguito solo durante la finestra notturna e terminare subito dopo, invece di restare inattivo per 20 ore. I nodi task non contengono dati HDFS, quindi eseguirli su Spot Instances riduce il costo di calcolo con un rischio minimo. Spot per i nodi core o primary rischia perdite di dati HDFS o il fallimento del cluster, e le RI vincolerebbero il pagamento di una capacità inattiva per la maggior parte della giornata.","optionExplanations":["Corretto — i cluster transitori con i dati su S3 pagano il calcolo solo durante l'esecuzione dei job, eliminando il costo del cluster inattivo.","I nodi core archiviano dati HDFS; le interruzioni Spot potrebbero causare perdita di dati e fallimento dei job.","Corretto — i nodi task forniscono solo capacità di calcolo, quindi le interruzioni Spot sono tollerabili e il loro costo si riduce in modo significativo.","Le Reserved Instances scontano le istanze, ma l'azienda continuerebbe a pagare un cluster inattivo per la maggior parte della giornata.","Perdere il nodo primary per un'interruzione Spot termina l'intero cluster, il che non è accettabile."]},
  "1299": {"h":"880e9c22","question":"Un'azienda serve una REST API pubblica da istanze EC2 dietro un Application Load Balancer in una sola Region. Le risposte sono documenti JSON di grandi dimensioni, molte richieste GET restituiscono lo stesso contenuto per diversi minuti e il trasferimento dati in uscita verso internet è ora la voce più grande della fattura. Quale combinazione di azioni ridurrà MAGGIORMENTE i costi? (Seleziona DUE)","options":["Posizionare una distribuzione Amazon CloudFront davanti all'ALB e memorizzare in cache le risposte GET con un TTL breve.","Posizionare AWS Global Accelerator davanti all'ALB per instradare gli utenti sulla rete AWS.","Abilitare S3 Transfer Acceleration per l'endpoint dell'API.","Attivare la compressione automatica in CloudFront in modo che le risposte vengano restituite in formato compresso.","Sostituire l'ALB con un Network Load Balancer per ridurre i costi di elaborazione per richiesta."],"explanation":"CloudFront serve le risposte GET ripetute dalle cache all'edge, riducendo carico e richieste sull'origine; il trasferimento dati dalle origini AWS a CloudFront non viene addebitato, mentre il prezzo di distribuzione di CloudFront è tipicamente inferiore al traffico in uscita diretto verso internet. Comprimere all'edge le risposte JSON di grandi dimensioni riduce ulteriormente i byte trasferiti. Global Accelerator migliora le prestazioni ma aggiunge costi propri e non memorizza i contenuti in cache.","optionExplanations":["Corretto — memorizzare in cache all'edge le risposte ripetute riduce il traffico verso l'origine e la distribuzione tramite CloudFront è generalmente più economica del trasferimento dati diretto in uscita.","Global Accelerator aggiunge costi orari e costi premium per il trasferimento dati e non offre caching, quindi aumenta i costi.","Transfer Acceleration si applica solo ai bucket Amazon S3, non a un'API basata su ALB.","Corretto — il JSON compresso è molto più piccolo, quindi vengono fatturati meno byte per la distribuzione agli utenti.","Il tipo di load balancer non influisce sui costi di trasferimento dati in uscita, che qui sono la voce dominante."]},
  "1300": {"h":"00ce194d","question":"Un'azienda esegue un job di riconciliazione containerizzato una volta per notte. Il job dura circa 40 minuti e attualmente viene eseguito su un'istanza EC2 dedicata che resta attiva 24 ore al giorno solo per ospitare la pianificazione cron. L'azienda vuole ridurre al minimo i costi ed evitare di gestire server. Quale soluzione soddisfa questi requisiti?","options":["Impacchettare il job come funzione AWS Lambda attivata ogni notte da una pianificazione Amazon EventBridge.","Mantenere l'istanza EC2 e acquistare per essa una Reserved Instance di 3 anni.","Eseguire il job su una EC2 Spot Instance avviata da un cron job su un'altra istanza.","Usare EventBridge Scheduler per eseguire ogni notte il container come task ECS su AWS Fargate."],"explanation":"EventBridge Scheduler può avviare un task ECS su Fargate secondo una pianificazione, così l'azienda paga solo per i circa 40 minuti di esecuzione del container e non gestisce alcun server. Lambda è allettante per i job pianificati, ma il suo tempo massimo di esecuzione di 15 minuti è troppo breve per un job di 40 minuti.","optionExplanations":["Le funzioni Lambda non possono essere eseguite per più di 15 minuti, quindi un job di 40 minuti verrebbe interrotto.","Una Reserved Instance sconta l'istanza ma si continua a pagare 24 ore di capacità per eseguire un job di 40 minuti, e restano server da gestire.","Serve comunque un'istanza sempre attiva per ospitare la pianificazione cron e le interruzioni Spot potrebbero arrestare il job.","Corretto — un task Fargate pianificato viene eseguito solo per la durata del job senza server da gestire, eliminando il costo dell'istanza inattiva."]},
  "1301": {"h":"df28e454","question":"Un'azienda esegue AWS CodePipeline in un account centrale di strumenti e distribuisce stack AWS CloudFormation in un account di produzione separato. Gli artifact della pipeline sono archiviati in un bucket Amazon S3 nell'account degli strumenti e devono essere crittografati at rest. La fase di deploy fallisce con errori di accesso negato quando viene eseguita nell'account di produzione. Quale combinazione di passaggi consentirà il deployment rispettando il principio del privilegio minimo? (Seleziona DUE)","options":["Crittografare il bucket degli artifact con una chiave KMS gestita dal cliente la cui key policy consenta al ruolo di deployment di produzione di decrittografare.","Mantenere la chiave aws/s3 gestita da AWS e aggiungere l'account di produzione alla sua key policy come principal autorizzato.","Creare un ruolo IAM nell'account di produzione che consideri attendibile il ruolo della pipeline nell'account degli strumenti e abbia solo i permessi di deployment.","Creare un utente IAM nell'account di produzione e memorizzarne le access key come variabili d'ambiente della pipeline.","Replicare il bucket degli artifact nell'account di produzione con S3 Cross-Region Replication prima di ogni deployment."],"explanation":"Le pipeline cross-account richiedono due cose: un ruolo nell'account di destinazione che la pipeline possa assumere e artifact che il ruolo di destinazione possa decrittografare. Poiché le chiavi gestite da AWS come aws/s3 non possono essere condivise tra account, l'archivio degli artifact deve usare una chiave KMS gestita dal cliente la cui key policy conceda al ruolo di produzione l'accesso in decrittografia. Utenti IAM con chiavi memorizzate funzionerebbero, ma violano la best practice del privilegio minimo e dell'assenza di credenziali a lungo termine.","optionExplanations":["Corretto — la key policy predefinita della chiave aws/s3 non può essere modificata per concedere accesso a un altro account, quindi serve una chiave gestita dal cliente che autorizzi esplicitamente il ruolo di produzione a leggere gli artifact crittografati.","Le key policy delle chiavi gestite da AWS non possono essere modificate, quindi non possono mai essere usate tra account diversi.","Corretto — la pipeline assume questo ruolo cross-account per l'azione di deploy, ricevendo credenziali temporanee limitate a ciò che serve al deployment.","Access key a lungo termine nella pipeline violano le best practice e aggiungono l'onere della rotazione, quando un ruolo cross-account è sufficiente.","La replica aggiunge latenza e costi e comunque non fornisce al deployment di produzione un modo per essere invocato dalla pipeline."]},
  "1302": {"h":"5ed0cb33","question":"Un'azienda esegue i deploy su AWS da GitHub Actions usando access key di un utente IAM memorizzate come secret del repository. Il team di sicurezza vuole eliminare le credenziali a lungo termine e garantire che solo i workflow eseguiti sul branch main di uno specifico repository possano effettuare il deploy. Quale soluzione soddisfa questi requisiti?","options":["Ruotare ogni giorno le access key dell'utente IAM con una funzione AWS Lambda pianificata che aggiorni automaticamente i secret del repository GitHub.","Creare un identity provider IAM OIDC per GitHub e un ruolo la cui trust policy verifichi i claim del repository e del branch.","Usare un account di un user pool Cognito per il workflow e scambiarne i token con credenziali AWS tramite un identity pool.","Memorizzare le access key in AWS Secrets Manager e lasciare che il workflow le recuperi con una chiave separata di sola lettura."],"explanation":"Federare GitHub Actions tramite un identity provider IAM OIDC fornisce a ogni esecuzione del workflow credenziali temporanee, e le condizioni sul claim subject del token limitano l'assunzione del ruolo al branch main del repository indicato. Ruotare o spostare le access key lascia comunque credenziali a lungo termine utilizzabili da qualsiasi workflow che possieda il secret.","optionExplanations":["La rotazione riduce l'esposizione ma si basa ancora su chiavi a lungo termine, e qualsiasi branch o workflow con il secret può fare il deploy.","Corretto — GitHub emette un token OIDC firmato per ogni esecuzione del workflow; la trust policy del ruolo può richiedere che il subject del token corrisponda al repository e al branch main, e STS restituisce credenziali di breve durata.","Questo memorizza una password utente in GitHub e aggiunge componenti Cognito senza legare l'accesso a un repository e a un branch specifici.","Il workflow ha comunque bisogno di una chiave a lungo termine per raggiungere Secrets Manager, quindi il problema viene solo spostato, non eliminato."]},
  "1303": {"h":"6429876b","question":"La policy di rete di un'azienda richiede che ogni funzione AWS Lambda nella sua AWS organization sia collegata a VPC approvati, in modo che il traffico in uscita passi attraverso un firewall di ispezione centrale. Il controllo deve impedire che funzioni non conformi vengano create o aggiornate in qualsiasi account, anche da parte degli amministratori degli account. Quale soluzione soddisfa questi requisiti?","options":["Distribuire in ogni account una regola AWS Config che segnali le funzioni non collegate a un VPC approvato.","Associare a ogni funzione una resource-based policy che consenta l'invocazione solo dai VPC approvati.","Associare una SCP che neghi la creazione o l'aggiornamento di funzioni a meno che la condizione lambda:VpcIds corrisponda ai VPC approvati.","Associare a ogni ruolo sviluppatore in ciascun account un permissions boundary che neghi le funzioni al di fuori dei VPC approvati."],"explanation":"Lambda supporta condition key come lambda:VpcIds e lambda:SubnetIds, quindi una SCP può negare le chiamate CreateFunction e UpdateFunctionConfiguration che non usano VPC approvati in tutta l'organizzazione, amministratori inclusi. Una regola Config rileva il problema solo a posteriori, e i permissions boundary possono essere modificati dagli amministratori degli account.","optionExplanations":["Config è un controllo di rilevamento: le funzioni non conformi verrebbero prima create e solo successivamente segnalate.","Una resource-based policy controlla chi può invocare la funzione, non a quale VPC è collegata la funzione stessa.","Corretto — Lambda espone condition key relative al VPC, e una SCP che le usa blocca le chiamate di creazione e aggiornamento non conformi in ogni account, anche per gli amministratori.","Gli amministratori degli account potrebbero rimuovere o aggirare il boundary, quindi non soddisfa il requisito di vincolare anche gli amministratori."]},
  "1304": {"h":"30ebaf5f","question":"Migliaia di sensori industriali sono registrati in AWS IoT Core, ciascuno con il proprio certificato X.509 creato da AWS IoT. Ora i sensori devono caricare file diagnostici direttamente in un bucket Amazon S3. Sui dispositivi non possono essere memorizzate credenziali AWS a lungo termine, e il team desidera il MINOR carico operativo. Quale soluzione soddisfa questi requisiti?","options":["Usare il credential provider di AWS IoT Core e un role alias per scambiare i certificati dei dispositivi con credenziali temporanee.","Memorizzare una access key univoca di un utente IAM nel secure element di ogni dispositivo e ruotare le chiavi una volta all'anno.","Abilitare le identità non autenticate in un identity pool Amazon Cognito e lasciare che ogni sensore richieda credenziali AWS guest.","Creare per ogni dispositivo un account in un user pool Cognito con password ed eseguire l'accesso prima di ogni caricamento."],"explanation":"Il credential provider di AWS IoT Core consente a un dispositivo che si autentica già con un certificato X.509 di ottenere credenziali AWS temporanee tramite un role alias, senza bisogno di un nuovo sistema di identità. Le chiavi IAM per dispositivo sono credenziali a lungo termine, e le identità Cognito non autenticate permetterebbero a chiunque di ottenere l'accesso.","optionExplanations":["Corretto — il credential provider autentica il dispositivo con il suo certificato X.509 esistente e restituisce credenziali temporanee per il ruolo IAM a cui fa riferimento il role alias.","Si tratta di credenziali a lungo termine sui dispositivi, vietate dal requisito, e ruotare migliaia di chiavi è un lavoro gravoso.","Chiunque potrebbe ottenere credenziali guest, quindi i dispositivi non sarebbero affatto autenticati.","I dispositivi memorizzerebbero password e il team dovrebbe gestire migliaia di account utente, con maggiore carico e rischio."]},
  "1305": {"h":"56944e83","question":"Un fornitore SaaS archivia i file dei clienti in Amazon S3 nel proprio account AWS. I clienti enterprise richiedono che i loro file siano crittografati con una chiave nell'account AWS del cliente stesso, che ogni utilizzo della chiave compaia nei log AWS CloudTrail del cliente e di poter revocare in qualsiasi momento l'accesso del fornitore. Quale soluzione soddisfa questi requisiti?","options":["Crittografare i file di ogni cliente con SSE-C usando una chiave che il cliente invia al fornitore.","Importare il key material di ogni cliente in una chiave KMS nell'account del fornitore e crittografare con SSE-KMS.","Usare SSE-KMS con una chiave nell'account di ciascun cliente la cui key policy consenta al ruolo del fornitore di usarla.","Archiviare i file di ogni cliente in un bucket dedicato che usa SSE-S3 e concedere al cliente l'accesso in lettura."],"explanation":"Quando la chiave KMS risiede nell'account del cliente e la sua key policy concede al ruolo del fornitore l'uso crittografico, ogni chiamata di crittografia e decrittografia viene registrata nel CloudTrail del proprietario della chiave, e il cliente può revocare l'accesso modificando la policy o disabilitando la chiave. Importare il key material nell'account del fornitore lascia controllo e log al fornitore.","optionExplanations":["Con SSE-C il fornitore deve memorizzare e inviare la chiave, l'uso della chiave non viene registrato nel CloudTrail del cliente e la revoca dipende dal fornitore.","La chiave risiederebbe nell'account del fornitore, quindi il cliente non può controllarla né vederne gli eventi di utilizzo nel proprio CloudTrail.","Corretto — l'uso cross-account di KMS viene registrato nel CloudTrail del proprietario della chiave, e il cliente può disabilitare la chiave o modificarne la policy per revocare immediatamente l'accesso.","Le chiavi SSE-S3 sono gestite interamente da Amazon S3, quindi i clienti non possiedono la chiave né possono revocare l'accesso tramite essa."]},
  "1306": {"h":"5477dd6f","question":"Un'azienda usa account AWS separati per sviluppo, test e produzione, ma tutti gli ambienti crittografano i dati con un'unica chiave AWS KMS gestita dal cliente in un account condiviso. Il team di sicurezza richiede che nessun principal di sviluppo o test possa mai decrittografare i dati di produzione e che gli amministratori che gestiscono le chiavi non possano usarle per decrittografare dati. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Sostituire la chiave condivisa con un'unica chiave multi-Region e crearne una replica per ogni ambiente.","Usare in ogni account di ambiente le chiavi gestite da AWS di ciascun servizio invece delle chiavi gestite dal cliente.","Concedere agli amministratori delle chiavi permessi KMS completi, così da poter recuperare i dati se un ruolo del workload va perso.","Creare in ogni account di ambiente una chiave gestita dal cliente separata, utilizzabile solo dai ruoli di quell'ambiente.","In ogni key policy, concedere agli amministratori solo le azioni di gestione della chiave e ai ruoli dei workload solo le azioni crittografiche."],"explanation":"Una chiave per ambiente, ciascuna con la propria key policy, garantisce che i principal di sviluppo e test non possano mai decrittografare i dati di produzione. Separare in ogni key policy i permessi di amministrazione della chiave da quelli di uso crittografico soddisfa il requisito di separazione dei compiti. Le repliche multi-Region condividono il key material all'interno di un unico account e non forniscono isolamento tra ambienti.","optionExplanations":["Le repliche multi-Region condividono lo stesso key material e vengono create in altre Region dello stesso account, quindi non separano gli ambienti.","Le key policy delle chiavi gestite da AWS non possono essere modificate, quindi il team non può separare amministrazione e utilizzo né controllare l'accesso cross-account.","Concedere agli amministratori delle chiavi diritti di decrittografia viola direttamente il requisito secondo cui gli amministratori non possono usare le chiavi.","Corretto — chiavi separate con key policy separate creano un confine crittografico netto: i dati di produzione non possono essere decrittografati con credenziali di sviluppo o test.","Corretto — separare nella key policy l'amministrazione della chiave dal suo utilizzo impone la separazione dei compiti, così gli amministratori non possono decrittografare i dati."]},
  "1307": {"h":"89881748","question":"Un'azienda ospita una single-page application in un bucket Amazon S3 e la sua REST API in Amazon API Gateway. Entrambe devono essere servite sotto un unico dominio personalizzato in HTTPS, protette dalle stesse regole AWS WAF, e il bucket deve rimanere privato. L'azienda vuole inoltre evitare di configurare CORS. Quale soluzione soddisfa questi requisiti?","options":["Abilitare l'hosting di siti web statici S3 con una bucket policy pubblica e puntare una distribuzione CloudFront al website endpoint.","Creare una distribuzione per il sito e un'altra per l'API, ciascuna con il proprio sottodominio e la propria web ACL.","Usare un dominio personalizzato API edge-optimized e servire il sito dallo stesso hostname tramite l'hosting di siti web S3.","Usare un'unica distribuzione CloudFront con un'origine S3 protetta da OAC, un behavior /api/* per API Gateway e una web ACL."],"explanation":"Un'unica distribuzione CloudFront può instradare il percorso predefinito verso l'origine S3 privata tramite origin access control e il percorso /api/* verso API Gateway, così il browser vede una sola origine e non serve alcuna configurazione CORS. Una sola web ACL sulla distribuzione protegge entrambi. Usare il website endpoint di S3 richiederebbe di rendere pubblico il bucket.","optionExplanations":["Il website endpoint richiede un bucket pubblico, il che viola il requisito che il bucket rimanga privato.","Due domini diversi fanno sì che il browser tratti le chiamate API come cross-origin, quindi CORS sarebbe comunque necessario.","Lo stesso hostname non può puntare sia a un dominio personalizzato API Gateway sia a un website endpoint S3, e il bucket sarebbe pubblico.","Corretto — una sola distribuzione serve entrambi sotto un unico dominio, quindi CORS non serve, l'origin access control mantiene privato il bucket e una sola web ACL protegge tutto."]},
  "1308": {"h":"9de9da10","question":"Le applicazioni in 25 account AWS scrivono log in Amazon CloudWatch Logs. Il team di sicurezza ha bisogno di una copia di questi log in un account centrale di archivio log quasi in tempo reale. Le copie devono essere immutabili per un anno, e il team desidera il MINOR carico operativo. Quale soluzione soddisfa questi requisiti?","options":["Pianificare in ogni account una funzione AWS Lambda che esporti ogni notte i log group nel bucket centrale.","Abilitare la CloudWatch cross-account observability in modo che l'account centrale possa visualizzare i log group.","Usare subscription filter verso una destinazione di log centrale che consegni tramite Firehose a un bucket S3 con Object Lock.","Creare un organization trail in AWS CloudTrail che consegni gli eventi a un bucket S3 con Object Lock nell'account di archivio log."],"explanation":"I subscription filter di CloudWatch Logs possono inviare gli eventi di log a una destinazione cross-account basata su Amazon Data Firehose, che li consegna quasi in tempo reale a un bucket S3 in cui Object Lock garantisce l'immutabilità. La cross-account observability consente all'account centrale solo di visualizzare i log, e CloudTrail non acquisisce i log applicativi.","optionExplanations":["Le esportazioni notturne non sono quasi in tempo reale e richiedono codice e pianificazioni in ogni account.","La cross-account observability fornisce solo accesso in visualizzazione; i log restano negli account di origine e non vengono copiati né protetti dalla cancellazione.","Corretto — i subscription filter cross-account consegnano i log in modo continuo a una destinazione nell'account di archivio, e Object Lock in compliance mode mantiene immutabili gli oggetti consegnati.","CloudTrail registra l'attività delle API, non i log applicativi scritti in CloudWatch Logs."]},
  "1309": {"h":"3d906696","question":"Un'azienda collega il proprio data center a un VPC con AWS Direct Connect. I server on-premises devono risolvere i record di una private hosted zone Route 53 per aws.example.internal, e le istanze Amazon EC2 devono risolvere corp.example.internal, ospitato sui server DNS on-premises. Le query DNS non devono attraversare internet, e l'azienda preferisce i servizi gestiti. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Creare un inbound endpoint di Route 53 Resolver e configurare il DNS on-premises per inoltrare aws.example.internal ai suoi indirizzi IP.","Convertire la private hosted zone in una public hosted zone in modo che i server on-premises possano risolverne i record.","Eseguire forwarder BIND su istanze Amazon EC2 nel VPC e far puntare a essi le DHCP options del VPC.","Abilitare DNS hostnames e DNS resolution sul VPC in modo che il dominio on-premises diventi risolvibile.","Creare un outbound endpoint di Resolver e una regola di inoltro per corp.example.internal che punti ai server DNS on-premises."],"explanation":"Gli inbound endpoint di Route 53 Resolver accettano query da on-premises per le private hosted zone, e gli outbound endpoint con regole di inoltro inviano le query per i domini on-premises ai server DNS aziendali, il tutto sulla connessione privata. Anche BIND su EC2 funzionerebbe, ma aggiunge un carico di gestione che gli endpoint gestiti evitano.","optionExplanations":["Corretto — l'inbound endpoint fornisce ai resolver on-premises indirizzi IP privati nel VPC a cui inoltrare le query per la private hosted zone.","Questo espone i record interni su internet e invia le query al di fuori della connessione privata.","I server DNS autogestiti funzionano ma aggiungono carico per patching, scalabilità e disponibilità che gli endpoint gestiti di Resolver evitano.","Queste impostazioni controllano il resolver fornito da Amazon solo per i nomi AWS; non inoltrano le query al DNS on-premises.","Corretto — l'outbound endpoint e la regola di inoltro consentono al resolver del VPC di inviare le query per il dominio aziendale tramite Direct Connect ai server DNS on-premises."]},
  "1310": {"h":"f398e216","question":"Una task definition Amazon ECS su AWS Fargate inietta una password di database da AWS Secrets Manager in una variabile d'ambiente del container facendo riferimento al secret nella task definition. I task vengono eseguiti in subnet con un NAT gateway, e il task role consente già di leggere il secret. I task non si avviano e restituiscono un errore secondo cui il secret non può essere recuperato. Quale soluzione risolverà il problema?","options":["Concedere al task execution role il permesso di leggere il secret e di decrittografarlo con la relativa chiave KMS.","Aggiungere al secret una resource-based policy che consenta al service principal ecs-tasks.amazonaws.com di leggerlo.","Creare un interface VPC endpoint per Secrets Manager nelle subnet in cui vengono eseguiti i task.","Spostare la password in un parametro di Systems Manager Parameter Store e fare riferimento a quello."],"explanation":"I secret referenziati in una task definition ECS vengono recuperati dall'agent con il task execution role prima dell'avvio del container; il task role viene usato solo dal codice applicativo in fase di esecuzione. Concedere all'execution role l'accesso in lettura al secret (e la decrittografia KMS nel caso di una chiave gestita dal cliente) risolve il problema di avvio. La connettività non è il problema, perché le subnet hanno un NAT gateway.","optionExplanations":["Corretto — l'agent ECS recupera i secret referenziati nella task definition usando il task execution role prima dell'avvio del container.","L'iniezione dei secret viene eseguita con le credenziali del task execution role, non con un service principal, quindi questa policy non aiuta.","Le subnet raggiungono già Secrets Manager tramite il NAT gateway, quindi la connettività non è la causa.","Anche i riferimenti a Parameter Store vengono risolti dall'execution role, quindi si verificherebbe lo stesso errore di permessi."]},
  "1311": {"h":"3039d706","question":"Diverse applicazioni sono eseguite su un cluster Amazon EKS condiviso. Attualmente tutti i pod usano l'instance role dei nodi, che ha i permessi combinati di tutte le applicazioni. Il team di sicurezza richiede che i pod di ciascuna applicazione ricevano solo i propri permessi AWS, con il MINOR carico operativo. Quale soluzione soddisfa questi requisiti?","options":["Creare un managed node group separato per ogni applicazione, ciascuno con il proprio instance role EC2 dedicato.","Memorizzare access key IAM per ciascuna applicazione in Kubernetes Secrets e montarle nei pod.","Usare EKS Pod Identity per associare il service account Kubernetes di ogni applicazione al proprio ruolo IAM.","Definire ruoli Kubernetes RBAC che limitino i servizi AWS che ogni namespace può chiamare."],"explanation":"EKS Pod Identity (o gli IAM roles for service accounts) associa un service account Kubernetes a un ruolo IAM, così i pod di ciascuna applicazione ottengono credenziali temporanee limitate a quel ruolo, indipendentemente dal ruolo del nodo. Node group separati aggiungono costi e i pod su un nodo condividono comunque i permessi, mentre RBAC non governa le chiamate alle API AWS.","optionExplanations":["Questo moltiplica i node group e i costi, e i pod pianificati su un nodo condividono comunque il ruolo di quel nodo.","Questo introduce credenziali a lungo termine che devono essere ruotate e protette, una soluzione meno sicura delle credenziali temporanee di un ruolo.","Corretto — ogni pod riceve credenziali temporanee solo per il ruolo associato al suo service account, quindi le applicazioni sono isolate senza infrastruttura aggiuntiva.","Kubernetes RBAC controlla l'accesso all'API Kubernetes, non ai servizi AWS."]},
  "1312": {"h":"7a3c28b8","question":"Una banca deve mantenere tutti i dati dei clienti e il key material che li protegge all'interno di eu-central-1. Una SCP limita già la maggior parte delle azioni a quella Region. Il team di compliance teme che uno sviluppatore possa creare chiavi AWS KMS il cui key material venga replicato in altre Region. Il controllo deve applicarsi a ogni account, inclusi gli amministratori dei member account. Quale soluzione soddisfa questi requisiti con il MINOR carico operativo?","options":["Aggiungere un'istruzione SCP che neghi la creazione di chiavi KMS multi-Region e neghi la replica delle chiavi.","Chiedere a ogni proprietario di chiave di aggiungere alla key policy un'istruzione che neghi la replica della chiave.","Distribuire una regola AWS Config che segnali le chiavi multi-Region al team di sicurezza per l'eliminazione manuale.","Associare a ogni ruolo sviluppatore in ciascun account un permissions boundary che neghi la replica KMS."],"explanation":"Una SCP che nega kms:CreateKey quando kms:MultiRegion è true, insieme a kms:ReplicateKey, impedisce centralmente le chiavi multi-Region in tutti i member account, amministratori inclusi. Key policy e permissions boundary possono essere modificati dagli amministratori degli account, e una regola Config rileva la replica solo dopo che è avvenuta.","optionExplanations":["Corretto — negare la creazione di chiavi quando la condizione kms:MultiRegion è true, e negare ReplicateKey, impedisce che il key material venga copiato in altre Region in ogni account.","I proprietari delle chiavi scrivono le proprie key policy, quindi questo non può essere imposto centralmente né nei confronti degli amministratori.","Questo è solo un controllo di rilevamento; il key material potrebbe essere già stato replicato prima che qualcuno reagisca.","I boundary vanno gestiti per singolo account e non vincolano gli amministratori degli account, che possono rimuoverli."]},
  "1313": {"h":"d9ad6eff","question":"Un'azienda vuole reagire automaticamente quando Amazon GuardDuty segnala che un'istanza Amazon EC2 comunica con un server di command-and-control. Entro pochi minuti, l'istanza deve essere isolata dalla rete e i suoi volumi Amazon EBS devono essere preservati per l'analisi forense. La soluzione deve avere il MINOR carico operativo. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Creare una regola Amazon EventBridge che corrisponda ai tipi di finding GuardDuty pertinenti.","Configurare GuardDuty per arrestare automaticamente l'istanza interessata quando viene generato il finding.","Contrassegnare l'istanza come non integra in modo che il suo Auto Scaling group la termini e la sostituisca.","Usare una custom action di Security Hub che gli analisti attivano dopo aver esaminato ogni finding.","Usare come target un runbook SSM Automation che applichi un security group di isolamento e crei snapshot dei volumi."],"explanation":"Una regola EventBridge sui finding di GuardDuty può avviare un runbook di Systems Manager Automation (o una funzione Lambda) che sostituisce i security group con un gruppo di isolamento e crea snapshot dei volumi EBS, preservando le prove. GuardDuty da solo non esegue remediation, e terminare l'istanza distrugge i dati forensi.","optionExplanations":["Corretto — GuardDuty pubblica i finding su EventBridge, quindi una regola può attivare la risposta automaticamente entro pochi minuti.","GuardDuty rileva le minacce ma non esegue autonomamente azioni di remediation sulle risorse.","La terminazione distrugge l'istanza e forse i suoi volumi, vanificando il requisito di preservazione forense.","Le custom action vengono avviate manualmente dagli analisti, quindi la risposta non sarebbe automatica entro pochi minuti.","Corretto — il runbook isola l'istanza mantenendola in esecuzione e acquisisce snapshot EBS come prove, senza server personalizzati."]},
  "1314": {"h":"1a13b3b3","question":"Un'azienda espone una funzione AWS Lambda tramite una function URL. L'azienda vuole anteporle Amazon CloudFront con AWS WAF e deve garantire che i client non possano invocare direttamente la function URL. Quale soluzione è la PIÙ sicura?","options":["Mantenere pubblica la function URL e far aggiungere a CloudFront un header personalizzato segreto che la funzione verifica.","Impostare la function URL sull'autenticazione IAM e usare l'origin access control di CloudFront per firmare le richieste.","Consentire la chiamata della function URL solo dalla managed prefix list di CloudFront degli IP origin-facing.","Collegare la funzione a un VPC e consentire nel suo security group il traffico in ingresso solo da CloudFront."],"explanation":"L'origin access control di CloudFront supporta le origini di tipo Lambda function URL: con la URL impostata sull'autenticazione IAM, sono autorizzate solo le richieste firmate da CloudFront per quella distribuzione. Un header segreto è più debole perché l'endpoint resta pubblico e la protezione dipende da un valore condiviso.","optionExplanations":["Funziona, ma si basa su un segreto condiviso che potrebbe trapelare, e la URL resta invocabile pubblicamente a livello di Lambda.","Corretto — con l'autenticazione IAM sono accettate solo richieste firmate, e OAC consente di firmarle solo alla distribuzione specifica, quindi le chiamate dirette vengono rifiutate.","Le function URL non possono essere limitate tramite prefix list di IP di origine, quindi questo controllo non può essere applicato.","Collegare una funzione a un VPC influisce solo sul suo traffico in uscita; le function URL non vengono raggiunte attraverso il VPC."]},
  "1315": {"h":"b538e999","question":"Un'azienda espone una REST API in Amazon API Gateway ai sistemi backend di diversi partner. I partner richiedono il flusso OAuth 2.0 client credentials, e ogni partner deve essere limitato a specifiche operazioni dell'API tramite scope. L'azienda vuole scrivere il minor codice di autenticazione personalizzato possibile. Quale soluzione soddisfa questi requisiti?","options":["Creare un utente IAM per ogni partner e richiedere richieste firmate SigV4 con autorizzazione IAM.","Rilasciare API key a ogni partner e associarle a usage plan che limitino i metodi consentiti.","Scrivere un Lambda authorizer che convalidi i token emessi da un authorization server OAuth 2.0 self-hosted.","Usare un user pool Cognito con scope personalizzati e un app client per partner, più un Cognito authorizer."],"explanation":"Gli user pool Amazon Cognito supportano il grant OAuth 2.0 client credentials con resource server e scope personalizzati, e un Cognito authorizer di API Gateway può richiedere scope specifici per ciascun metodo. Un Lambda authorizer con un token server self-hosted funzionerebbe, ma richiede molto più codice personalizzato, e le API key non sono pensate per l'autenticazione.","optionExplanations":["I partner deterrebbero chiavi AWS a lungo termine, e questo non è il flusso OAuth 2.0 client credentials che richiedono.","Le API key identificano i client per throttling e quote; non sono un meccanismo di autenticazione e non implementano gli scope OAuth.","È fattibile ma richiede di realizzare e gestire il token server e il codice di convalida, aggiungendo codice personalizzato.","Corretto — Cognito emette access token tramite il grant client credentials, e il Cognito authorizer di API Gateway convalida i token e i relativi scope senza codice personalizzato."]},
  "1316": {"h":"78852349","question":"Un'applicazione mantiene connection pool di lunga durata verso un database Amazon RDS for PostgreSQL e legge la password da AWS Secrets Manager. Durante la rotazione automatica, alcune istanze dell'applicazione non riescono ad aprire nuove connessioni finché non aggiornano il secret. La libreria client del database non supporta i token di autenticazione IAM. Quale soluzione eliminerà questi errori?","options":["Ruotare la password più frequentemente in modo che ogni rotazione interessi meno connessioni attive.","Disabilitare la rotazione automatica e cambiare la password manualmente durante le finestre di manutenzione pianificate.","Usare la strategia di rotazione a utenti alternati, in modo che le credenziali precedenti restino valide dopo ogni rotazione.","Abilitare l'autenticazione IAM del database sull'istanza DB e mantenere il secret esistente solo come opzione di riserva."],"explanation":"Con la strategia a utenti alternati, Secrets Manager alterna la rotazione tra due utenti del database, quindi le credenziali che le istanze dell'applicazione avevano in cache prima della rotazione restano valide finché non recuperano il nuovo valore. La rotazione a utente singolo invalida immediatamente la vecchia password, e l'autenticazione IAM è esclusa dalla libreria client.","optionExplanations":["Una rotazione a utente singolo più frequente produce più finestre in cui le password in cache diventano non valide.","Questo elimina il vantaggio di sicurezza della rotazione automatica e causa comunque errori a ogni cambio.","Corretto — la rotazione alterna tra due utenti del database, quindi un'istanza con il valore precedente del secret può ancora connettersi finché non lo aggiorna.","La libreria client non supporta i token di autenticazione IAM, quindi questa opzione non può essere usata."]},
  "1317": {"h":"89df4bb3","question":"Un'azienda replica un bucket Amazon S3 verso un bucket in un account separato di disaster recovery. Gli oggetti crittografati con SSE-S3 vengono replicati correttamente, ma quelli crittografati con SSE-KMS usando una chiave gestita dal cliente non vengono replicati. Le copie DR devono inoltre essere crittografate con una chiave controllata dall'account DR. Quale soluzione soddisfa questi requisiti?","options":["Abilitare la replica degli oggetti crittografati con KMS, indicare una chiave dell'account DR e consentire al ruolo di replica di usare entrambe le chiavi.","Modificare la crittografia predefinita del bucket di origine in SSE-S3 in modo che ogni nuovo oggetto venga replicato.","Eseguire ogni giorno S3 Batch Replication per copiare gli oggetti che la replica in tempo reale ha saltato.","Concedere all'account DR s3:ReplicateObject nella bucket policy di origine e copiare gli oggetti dal lato dell'account DR."],"explanation":"Amazon S3 salta gli oggetti SSE-KMS a meno che la regola di replica non li abiliti esplicitamente e specifichi una chiave KMS di destinazione, e il ruolo di replica deve poter decrittografare con la chiave di origine e crittografare con la chiave di destinazione (cosa che la key policy DR deve consentire). Batch Replication si basa sulla stessa configurazione, quindi fallirebbe allo stesso modo.","optionExplanations":["Corretto — la replica deve includere esplicitamente gli oggetti SSE-KMS, e il ruolo di replica necessita di decrypt sulla chiave di origine e di encrypt sulla chiave di destinazione.","Questo abbandona la chiave gestita dal cliente e non crittografa le copie DR con una chiave controllata dall'account DR.","Batch Replication usa la stessa configurazione di replica e lo stesso ruolo, quindi fallisce per lo stesso motivo legato ai permessi.","La replica viene eseguita in push dal ruolo di replica del bucket di origine; una bucket policy sull'origine non può rimediare ai permessi KMS mancanti."]},
  "1318": {"h":"f75d12f2","question":"Un penetration test ha mostrato che una vulnerabilità di server-side request forgery in un'applicazione web potrebbe leggere le credenziali dell'instance role dall'instance metadata service di EC2. Le applicazioni dell'azienda si basano sugli instance role. L'azienda vuole che tutte le istanze esistenti e future nella sua AWS organization siano protette da questo vettore di attacco. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Disattivare l'instance metadata service su ogni istanza per bloccare qualsiasi accesso alle credenziali del ruolo.","Aggiungere una regola in uscita al security group che blocchi il traffico verso l'indirizzo link-local dei metadati.","Associare una SCP che neghi l'avvio di istanze a meno che le metadata options richiedano session token (IMDSv2).","Modificare le metadata options delle istanze esistenti per richiedere IMDSv2 dopo aver verificato che gli SDK lo supportino.","Aggiungere sul load balancer una regola AWS WAF che blocchi le richieste contenenti l'indirizzo IP dei metadati."],"explanation":"IMDSv2 richiede un session token ottenuto con una richiesta PUT, che le tipiche vulnerabilità SSRF non riescono a eseguire, quindi imporlo mitiga l'attacco mantenendo funzionanti gli instance role. Una condizione SCP sull'impostazione del token dei metadati impone IMDSv2 per i nuovi avvii, e la modifica delle metadata options sistema le istanze esistenti. I security group non filtrano il traffico verso i metadati, e i pattern WAF sono aggirabili.","optionExplanations":["Le applicazioni si basano sugli instance role, che forniscono le credenziali tramite il metadata service, quindi disabilitarlo le bloccherebbe.","Il traffico verso l'instance metadata service non passa attraverso i security group, quindi questa regola non ha effetto.","Corretto — questo impedisce a qualsiasi nuova istanza in qualsiasi account di essere avviata con IMDSv1 abilitato.","Corretto — richiedere i session token sulle istanze in esecuzione chiude la strada alle semplici richieste SSRF, che non possono ottenere il token basato su PUT.","Il pattern matching aiuta contro alcuni payload, ma può essere aggirato con codifiche e non protegge le istanze che non si trovano dietro l'ALB."]},
  "1319": {"h":"828f8698","question":"Gli sviluppatori devono poter avviare istanze Amazon EC2 e associare loro ruoli IAM. Un audit recente ha rilevato che uno sviluppatore ha associato un ruolo da amministratore a un'istanza e lo ha usato per un'escalation di privilegi. Gli sviluppatori devono poter associare solo i ruoli creati dal team di piattaforma per i workload. Quale soluzione soddisfa questi requisiti?","options":["Negare iam:CreateRole agli sviluppatori in modo che non possano creare nuovi ruoli con permessi da amministratore.","Consentire iam:PassRole solo sugli ARN dei ruoli sotto un path per i workload e solo quando il ruolo è passato ad Amazon EC2.","Associare una SCP che neghi ec2:RunInstances agli sviluppatori in tutti gli account dell'organizzazione.","Richiedere l'MFA agli sviluppatori prima che possano avviare istanze EC2 che usano un instance profile."],"explanation":"L'associazione di un ruolo a un servizio è governata da iam:PassRole, quindi limitarlo agli ARN dei ruoli di workload approvati (e a EC2 con iam:PassedToService) impedisce agli sviluppatori di assegnare ruoli da amministratore alle istanze. Negare la creazione di ruoli non risolve il problema dei ruoli privilegiati esistenti, e l'MFA non limita quale ruolo viene passato.","optionExplanations":["L'escalation ha usato un ruolo da amministratore esistente, quindi bloccare la creazione di ruoli non ne impedisce il passaggio.","Corretto — PassRole controlla quali ruoli un principal può assegnare a un servizio, quindi limitarlo ai ruoli di workload e a EC2 impedisce di passare ruoli da amministratore.","Questo impedisce del tutto agli sviluppatori di avviare istanze, cosa che invece devono poter fare.","L'MFA conferma l'identità dello sviluppatore, ma non limita quali ruoli può associare."]},
  "1320": {"h":"a60a1648","question":"Un team di sicurezza ha bisogno di un ruolo IAM di sola lettura identico, considerato attendibile dal suo account di strumenti di sicurezza, in ogni account della AWS organization dell'azienda. Nuovi account vengono creati ogni settimana, e il ruolo deve comparire in essi automaticamente senza codice personalizzato. Quale soluzione soddisfa questi requisiti?","options":["Creare una funzione AWS Lambda, attivata dagli eventi di creazione degli account, che crei il ruolo in ogni nuovo member account.","Creare il ruolo una sola volta nel management account e condividerlo con tutti gli account usando AWS RAM.","Assegnare un permission set di IAM Identity Center con accesso di sola lettura a ogni account dell'organizzazione.","Distribuire il ruolo con CloudFormation StackSets usando permessi service-managed e distribuzione automatica sulle OU."],"explanation":"CloudFormation StackSets con permessi service-managed si integra con AWS Organizations e distribuisce automaticamente le istanze di stack negli account che entrano nelle OU di destinazione, mantenendo il ruolo identico ovunque. Una funzione Lambda potrebbe fare lo stesso ma richiede codice personalizzato, e i ruoli IAM non possono essere condivisi con AWS RAM.","optionExplanations":["Funziona, ma richiede di scrivere e mantenere codice personalizzato, cosa che il requisito esclude.","I ruoli IAM non possono essere condivisi tramite AWS Resource Access Manager; ogni account ha bisogno del proprio ruolo.","I permission set servono all'accesso delle persone tramite Identity Center e non possono essere assunti dal ruolo di un account di strumenti.","Corretto — StackSets con permessi service-managed distribuisce lo stack in tutti gli account delle OU di destinazione e automaticamente nei nuovi account aggiunti a esse."]},
  "1321": {"h":"ead421b0","question":"Un ruolo di deployment CI/CD ha la policy AdministratorAccess perché il team non sapeva con certezza di quali permessi avesse bisogno. Il ruolo esegue deployment da diversi mesi, e AWS CloudTrail è stato abilitato per tutto il tempo. Il team di sicurezza vuole una policy a privilegio minimo per il ruolo con il MINOR sforzo. Quale soluzione soddisfa questi requisiti?","options":["Usare IAM Access Analyzer per generare una policy dall'attività CloudTrail del ruolo e perfezionarla prima di associarla.","Sostituire AdministratorAccess con la managed policy PowerUserAccess e monitorare i deployment per individuare errori.","Interrogare i log CloudTrail con Amazon Athena e scrivere una policy personalizzata dall'elenco delle azioni trovate.","Esaminare i controlli di AWS Trusted Advisor per individuare i permessi che il ruolo non usa."],"explanation":"La generazione di policy di IAM Access Analyzer analizza l'attività CloudTrail di un ruolo e predispone una policy granulare basata sui servizi e sulle azioni effettivamente usati, che il team può rivedere e associare. Interrogare CloudTrail con Athena porta a un risultato simile con molto più lavoro manuale.","optionExplanations":["Corretto — Access Analyzer esamina la cronologia CloudTrail e produce una policy contenente le azioni e i servizi effettivamente usati dal ruolo.","PowerUserAccess è comunque estremamente ampia e non si basa sulle reali esigenze del ruolo.","Produce un risultato simile, ma richiede di costruire query e scrivere la policy a mano, con maggiore sforzo.","Trusted Advisor non analizza i permessi dei singoli ruoli né genera policy."]},
  "1322": {"h":"028d1c62","question":"Un'app mobile di notizie consente ai lettori di navigare senza effettuare l'accesso. L'app deve inviare eventi di clickstream direttamente a uno stream Amazon Data Firehose senza un servizio backend. L'app non deve contenere credenziali AWS a lungo termine, e gli utenti guest non devono poter fare nient'altro che scrivere in quello stream. Quale soluzione soddisfa questi requisiti?","options":["Incorporare nell'app una access key di un utente IAM la cui policy consenta solo la scrittura nello stream.","Usare un identity pool con accesso guest il cui ruolo non autenticato possa solo scrivere nello stream.","Usare un user pool Cognito ed emettere ID token per i lettori guest, che l'app invia poi direttamente a Firehose.","Inviare gli eventi a un endpoint API Gateway con una API key che li inoltri allo stream."],"explanation":"Un identity pool Cognito con identità non autenticate fornisce agli utenti guest credenziali AWS temporanee per un ruolo IAM con ambito ristretto, in questo caso limitato alla scrittura di record in un solo stream Firehose. Le access key incorporate sono credenziali a lungo termine, e i token di uno user pool non possono essere usati per chiamare direttamente Firehose.","optionExplanations":["Le chiavi incorporate sono credenziali a lungo termine che possono essere estratte dall'app e devono essere ruotate su tutte le installazioni.","Corretto — l'identity pool emette credenziali temporanee per gli utenti guest, e il ruolo non autenticato li limita all'inserimento di record in quel solo stream.","Gli user pool richiedono che gli utenti effettuino l'accesso, e Firehose accetta credenziali AWS SigV4, non token di user pool.","Questo aggiunge un livello backend escluso dal requisito, e la API key incorporata nell'app non è un meccanismo di autenticazione."]},
  "1323": {"h":"b59176b2","question":"Diverse applicazioni containerizzate condividono un unico file system Amazon EFS in modo che possa essere sottoposto a backup come un'unica unità. Ogni applicazione deve vedere solo la propria directory e deve scrivere i file come uno specifico utente POSIX, anche se un container viene eseguito come root. L'accesso deve essere controllato con IAM. Quale soluzione soddisfa questi requisiti?","options":["Creare un file system EFS separato per ogni applicazione e montare ciascuno nei rispettivi container.","Impostare i permessi POSIX delle directory in modo che ogni utente applicativo possa accedere solo alla propria directory.","Usare un security group separato per ogni applicazione che consenta il traffico NFS solo verso la directory di quell'applicazione sul file system.","Creare un access point EFS per applicazione con una root directory e un utente imposto, richiesti dalla file system policy."],"explanation":"Gli access point EFS impongono una root directory e un utente e gruppo POSIX per ogni richiesta effettuata tramite essi, indipendentemente dall'identità del client, e l'autorizzazione IAM nella file system policy può richiedere che ogni ruolo usi il proprio access point. I semplici permessi POSIX vengono aggirati dai container eseguiti come root.","optionExplanations":["Questo isola i dati, ma viola il requisito di mantenere un unico file system sottoposto a backup come un'unica unità.","I container eseguiti come root possono aggirare i permessi POSIX, quindi l'isolamento non è garantito.","I security group filtrano le connessioni di rete verso i mount target; non possono limitare l'accesso alle directory.","Corretto — gli access point vincolano ogni client alla propria directory e sovrascrivono l'utente POSIX, e la file system policy può richiedere che i client li usino."]},
  "1324": {"h":"16623e2a","question":"Task Amazon ECS su AWS Fargate vengono eseguiti in subnet private prive di NAT gateway o internet gateway, e il team di sicurezza vieta di aggiungerne uno. I task devono scaricare immagini da un repository Amazon ECR privato nella stessa Region. Esiste già un interface endpoint per CloudWatch Logs. Quale combinazione di passaggi è necessaria? (Seleziona DUE)","options":["Creare interface VPC endpoint per l'API ECR e per il Docker registry ECR.","Creare un NAT gateway solo per il pull delle immagini e rimuoverlo dopo l'avvio dei task.","Abilitare una regola di pull through cache ECR per il repository privato nella stessa Region.","Creare un gateway VPC endpoint per Amazon S3 e associarlo alle route table delle subnet private.","Copiare le immagini nella Amazon ECR Public Gallery in modo che i task possano scaricarle senza autenticazione."],"explanation":"Il pull da ECR privato senza accesso a internet richiede gli interface endpoint ecr.api ed ecr.dkr per l'autenticazione e i manifest, più un gateway endpoint S3, perché i layer delle immagini vengono serviti da Amazon S3. Un NAT gateway è vietato, e rendere pubbliche le immagini è un peggioramento della sicurezza.","optionExplanations":["Corretto — Fargate ha bisogno di entrambi gli interface endpoint ECR per autenticarsi e recuperare i manifest delle immagini in modo privato.","Qualsiasi NAT gateway, anche temporaneo, viola il divieto, e i task riavviati in seguito non riuscirebbero a scaricare le immagini.","La pull through cache si sincronizza da registry upstream; non fornisce accesso di rete a ECR dalle subnet.","Corretto — ECR archivia i layer delle immagini in Amazon S3, quindi i task hanno bisogno del gateway endpoint S3 per scaricarli.","Questo espone pubblicamente immagini private e richiede comunque un percorso di rete verso il registry pubblico."]},
  "1325": {"h":"c2b28cd2","question":"Un'azienda esegue workload su Amazon EKS. Le credenziali del database devono restare in AWS Secrets Manager con rotazione automatica, i pod devono utilizzarle come file montati, e le credenziali non devono essere memorizzate come oggetti Kubernetes Secret nel cluster. Quale soluzione soddisfa questi requisiti?","options":["Creare Kubernetes Secrets per le credenziali e abilitare la envelope encryption dei secret con una chiave KMS gestita dal cliente.","Usare il Secrets Store CSI Driver con il provider AWS e concedere al service account di ogni pod l'accesso ai propri secret.","Incorporare le credenziali nelle immagini dei container durante la build e ricostruire le immagini dopo ogni rotazione.","Memorizzare le credenziali in una ConfigMap e limitarne l'accesso con Kubernetes RBAC."],"explanation":"L'AWS Secrets and Configuration Provider per il Secrets Store CSI Driver monta i secret di Secrets Manager nei pod come file, usando il ruolo IAM del pod per l'accesso, così Secrets Manager resta l'unica fonte con rotazione. I Kubernetes Secrets con envelope encryption memorizzano comunque i valori nel cluster.","optionExplanations":["Le credenziali sarebbero comunque memorizzate nel cluster come oggetti Secret e non beneficerebbero della rotazione di Secrets Manager.","Corretto — il driver monta i secret di Secrets Manager nei pod come file in fase di esecuzione, senza creare oggetti Kubernetes Secret.","Le credenziali nelle immagini sono esposte a chiunque possa scaricarle, e ricostruire le immagini dopo ogni rotazione non è pratico.","Le ConfigMap non sono progettate per i secret, memorizzano i valori non crittografati nel cluster e non si integrano con la rotazione."]},
  "1326": {"h":"a4075285","question":"Un'azienda collega VPC di produzione, VPC di sviluppo e un VPC di servizi condivisi a un unico AWS Transit Gateway. I VPC di produzione e di sviluppo non devono mai poter instradare traffico gli uni verso gli altri, ma entrambi devono raggiungere il VPC dei servizi condivisi. La soluzione deve scalare man mano che si aggiungono VPC. Quale soluzione soddisfa questi requisiti?","options":["Usare route table del transit gateway separate per ambiente e propagare solo le route che ciascuno può usare.","Aggiungere in ogni subnet di produzione regole di network ACL che neghino il traffico dagli intervalli CIDR di sviluppo.","Creare un transit gateway separato per ogni ambiente ed eseguire il peering di entrambi con il VPC dei servizi condivisi.","Sostituire il transit gateway con un VPC peering tra ogni VPC e il VPC dei servizi condivisi."],"explanation":"Le route table del transit gateway segmentano i domini di routing: gli attachment di produzione e di sviluppo sono associati a tabelle che contengono solo le route dei servizi condivisi, mentre la tabella dei servizi condivisi propaga entrambi gli ambienti. Le network ACL potrebbero bloccare il traffico, ma vanno mantenute in ogni subnet al variare dei CIDR.","optionExplanations":["Corretto — la route table di ogni ambiente apprende solo le route dei servizi condivisi, mentre la tabella dei servizi condivisi le apprende entrambe, quindi produzione e sviluppo non possono instradare traffico tra loro.","Funziona solo finché gli elenchi CIDR sono mantenuti aggiornati in ogni subnet, il che è soggetto a errori e non scala.","I VPC non possono essere in peering con un transit gateway; questo design non è realizzabile come descritto e aggiunge costi.","Il peering funziona per pochi VPC, ma diventa una grande mesh da gestire man mano che si aggiungono VPC."]},
  "1327": {"h":"6c0ca835","question":"Un'azienda deve ispezionare tutto il traffico internet in ingresso verso il proprio VPC applicativo usando una flotta di appliance firewall virtuali di terze parti per cui il team di sicurezza ha già le licenze. Le appliance devono scalare orizzontalmente, ricevere il traffico in modo trasparente senza source NAT e mantenere i flussi simmetrici. Quale soluzione soddisfa questi requisiti?","options":["Posizionare le appliance dietro un Network Load Balancer e instradare il traffico internet verso il load balancer.","Distribuire AWS Network Firewall nel VPC e instradare il traffico in ingresso attraverso i suoi endpoint.","Distribuire un Gateway Load Balancer con le appliance come target e instradare il traffico in ingresso attraverso i suoi endpoint.","Posizionare un Application Load Balancer davanti alle appliance e inoltrare il traffico consentito all'applicazione."],"explanation":"Gateway Load Balancer è progettato per inserire in modo trasparente appliance virtuali di terze parti nel percorso del traffico, preservando gli indirizzi di origine e la simmetria dei flussi e scalando la flotta di appliance. Network Firewall ispezionerebbe il traffico, ma non usa le appliance di terze parti con licenza.","optionExplanations":["Un NLB non inserisce le appliance in modo trasparente nel percorso di routing e non può garantire che il traffico di ritorno passi simmetricamente attraverso di esse.","Network Firewall è un servizio AWS gestito, non le appliance di terze parti che il team deve usare.","Corretto — Gateway Load Balancer distribuisce in modo trasparente il traffico alle appliance con incapsulamento GENEVE, mantiene i flussi sticky e scala la flotta.","Un ALB termina le connessioni HTTP e non è progettato per far passare tutto il traffico in modo trasparente attraverso i firewall."]},
  "1328": {"h":"d3609466","question":"Collaboratori esterni che lavorano dai propri laptop devono accedere alle porte SSH e di database di risorse in subnet private di un VPC. Devono autenticarsi con l'identity provider SAML 2.0 dell'azienda, e l'accesso a ciascuna subnet deve dipendere dal gruppo del collaboratore. L'azienda vuole una soluzione completamente gestita. Quale soluzione soddisfa questi requisiti?","options":["Creare una connessione Site-to-Site VPN per il laptop di ogni collaboratore e aggiungere route per le subnet private.","Distribuire un bastion host con un indirizzo IP pubblico e creare account Linux per ogni collaboratore.","Ordinare una hosted connection AWS Direct Connect e condividerla con le reti domestiche dei collaboratori.","Distribuire AWS Client VPN con autenticazione federata SAML e regole di autorizzazione basate sui gruppi."],"explanation":"AWS Client VPN fornisce accesso remoto gestito dai dispositivi degli utenti, supporta la federazione SAML con l'identity provider aziendale e usa regole di autorizzazione per consentire a ogni gruppo l'accesso solo a subnet specifiche. Un bastion host richiederebbe la gestione di server e credenziali e una porta esposta su internet.","optionExplanations":["Site-to-Site VPN collega reti tramite customer gateway, non singoli laptop, e non offre autenticazione SAML per utente.","Richiede di gestire un server, account utente e chiavi SSH, ed espone una porta in ingresso su internet.","Direct Connect collega sedi fisse ad AWS; non è adatto a singoli laptop remoti.","Corretto — Client VPN è un servizio gestito di accesso remoto che autentica gli utenti tramite SAML e autorizza l'accesso agli intervalli di rete in base al gruppo."]},
  "1329": {"h":"29c55041","question":"Gli analisti di dati eseguono query Amazon Athena su dati sensibili. Ogni risultato di query scritto in Amazon S3 deve essere crittografato con una specifica chiave AWS KMS gestita dal cliente, e gli analisti non devono poter scegliere un'impostazione di crittografia o una posizione dei risultati diverse. Quale soluzione soddisfa questi requisiti?","options":["Abilitare la crittografia predefinita con la chiave KMS sul bucket dei risultati e lasciare che gli analisti scelgano le proprie posizioni di output.","Usare un workgroup Athena che crittografi i risultati con la chiave e sovrascriva le impostazioni client, e limitare gli analisti a esso.","Abilitare Amazon Macie sul bucket dei risultati per rilevare i risultati di query non crittografati e avvisare il team.","Registrare il bucket dei risultati in AWS Lake Formation e concedere agli analisti l'accesso solo alle tabelle crittografate."],"explanation":"I workgroup Athena possono imporre una posizione dei risultati delle query e una configurazione di crittografia che sovrascrivono qualsiasi impostazione lato client, e le policy IAM possono limitare gli analisti a quel workgroup. La sola crittografia predefinita del bucket non impedisce agli analisti di scegliere posizioni o opzioni di crittografia diverse.","optionExplanations":["Gli analisti potrebbero comunque scrivere i risultati in altre posizioni o specificare un'altra crittografia, quindi l'impostazione non è imposta.","Corretto — le impostazioni del workgroup che sovrascrivono quelle lato client impongono la posizione dei risultati e la crittografia per ogni query nel workgroup.","Macie rileva dati sensibili e problemi di configurazione dei bucket, ma non impone la crittografia dei risultati.","Lake Formation governa l'accesso ai dati catalogati, non la crittografia dei file dei risultati delle query Athena."]},
  "1330": {"h":"a67ba335","question":"Il data lake di un'azienda in Amazon S3 è catalogato nell'AWS Glue Data Catalog. Analisti in diversi account AWS lo interrogano con Amazon Athena. Gli analisti di marketing non devono vedere le colonne che contengono dati personali, e i team regionali devono vedere solo le righe della propria regione. I permessi devono essere gestiti centralmente. Quale soluzione soddisfa questi requisiti?","options":["Creare copie S3 separate dei dati, rimuovendo le colonne con dati personali e suddividendo le righe per regione.","Creare un S3 access point per ogni team con una policy che limiti gli oggetti che il team può leggere.","Usare data filter di AWS Lake Formation con restrizioni su colonne e righe e concederli ai team tra account diversi.","Scrivere policy IAM con condition key di Athena che blocchino qualsiasi query che selezioni colonne contenenti dati personali."],"explanation":"AWS Lake Formation fornisce permessi granulari e gestiti centralmente sulle tabelle del Data Catalog, inclusi data filter a livello di colonna e di riga, e può concederli a principal di altri account. Gli S3 access point operano sugli oggetti e non possono limitare colonne o righe all'interno dei dati.","optionExplanations":["Le copie moltiplicano storage e pipeline e devono essere mantenute sincronizzate, aumentando il carico operativo.","Gli access point controllano l'accesso a livello di oggetto; non possono nascondere colonne né filtrare righe all'interno dei file.","Corretto — i data filter di Lake Formation forniscono sicurezza a livello di colonna e di riga per le query Athena e supportano concessioni cross-account da un unico punto.","Le policy IAM non possono esaminare quali colonne o righe legge una query, quindi non possono imporre questo vincolo."]},
  "1331": {"h":"0b8b48b2","question":"Un sito di e-commerce dietro Amazon CloudFront raccoglie numeri di carte di pagamento in un modulo web. I dati attraversano diversi servizi backend e sistemi di logging. Solo il microservizio dei pagamenti può vedere il numero della carta in chiaro, e ogni altro componente deve gestire solo testo cifrato. Quale soluzione soddisfa questi requisiti?","options":["Configurare la field-level encryption di CloudFront con una chiave pubblica, in modo che solo il servizio dei pagamenti possa decrittografare.","Usare HTTPS tra viewer, CloudFront e il load balancer di origine con policy TLS moderne.","Crittografare i database e lo storage dei log di tutti i servizi backend con chiavi SSE-KMS gestite dal cliente in AWS KMS.","Aggiungere una regola AWS WAF che blocchi le richieste contenenti numeri di carta non inviate tramite HTTPS."],"explanation":"La field-level encryption di CloudFront crittografa specifici campi POST all'edge con una chiave pubblica, così i dati restano crittografati attraverso l'intero stack applicativo finché il servizio dei pagamenti non li decrittografa con la chiave privata. HTTPS da solo termina all'origine, dopodiché tutti i componenti possono leggere il campo.","optionExplanations":["Corretto — CloudFront crittografa all'edge il campo del modulo specificato con la chiave pubblica, e solo il servizio dei pagamenti, che possiede la chiave privata, può decrittografarlo.","TLS protegge i dati solo in transito; il numero della carta viene decrittografato all'origine ed è visibile a ogni componente backend.","La crittografia at rest non impedisce ai servizi backend e ai log di elaborare il numero della carta in chiaro.","WAF ispeziona e filtra le richieste, ma non crittografa singoli campi per i componenti a valle."]},
  "1332": {"h":"2a294313","question":"I partner commerciali chiamano un'applicazione HTTPS di un'azienda eseguita dietro un Application Load Balancer. L'azienda deve autenticare ogni partner con un certificato client emesso dalla propria certificate authority privata e vuole evitare di modificare il codice dell'applicazione per convalidare i certificati. Quale soluzione soddisfa questi requisiti?","options":["Abilitare la modalità verify del mutual TLS sul listener dell'ALB con un trust store contenente il certificato della CA privata.","Sostituire l'ALB con un Network Load Balancer in TLS passthrough e convalidare i certificati nell'applicazione.","Autenticare i partner con un user pool Amazon Cognito e l'autenticazione utente dell'ALB.","Aggiungere una regola AWS WAF che consenta solo le richieste contenenti un header di certificato specifico del partner."],"explanation":"Gli Application Load Balancer supportano il mutual TLS: in modalità verify il listener controlla i certificati client rispetto a un trust store contenente la CA dell'azienda e rifiuta le richieste che non superano la convalida, quindi l'applicazione non richiede modifiche. Il passthrough dell'NLB richiederebbe all'applicazione di eseguire autonomamente la convalida.","optionExplanations":["Corretto — l'ALB convalida i certificati client rispetto al trust store e rifiuta quelli non validi prima che le richieste raggiungano l'applicazione.","Funziona, ma sposta la convalida dei certificati nel codice dell'applicazione, cosa che l'azienda vuole evitare.","Cognito autentica gli utenti con credenziali o federazione, non client macchina con certificati della CA privata.","Un header può essere falsificato da qualsiasi client e non fornisce un'autenticazione crittografica basata su certificato."]},
  "1333": {"h":"4ef6bb54","question":"Gli amministratori di database devono collegare un client SQL desktop a un'istanza Amazon RDS for MySQL in subnet private. L'azienda vieta bastion host con porte in ingresso, connessioni VPN ed endpoint di database pubblici, e ogni accesso deve essere autorizzato con IAM e registrato. Nel VPC sono in esecuzione istanze EC2 gestite con l'SSM Agent. Quale soluzione soddisfa questi requisiti?","options":["Rendere l'istanza DB accessibile pubblicamente e consentire nel suo security group solo gli indirizzi IP pubblici degli amministratori.","Aprire un tunnel SSH attraverso un bastion host in una subnet pubblica e registrare le sessioni SSH.","Usare il port forwarding di Session Manager verso l'host remoto del database tramite un'istanza gestita nel VPC.","Configurare AWS Client VPN per gli amministratori e instradare il loro traffico verso le subnet private."],"explanation":"Il port forwarding di Session Manager verso un host remoto consente a un amministratore di aprire una porta locale che crea un tunnel, attraverso un'istanza gestita da SSM, verso l'endpoint RDS, senza porte in ingresso, con autorizzazione basata su IAM e registrazione delle sessioni. Le altre opzioni si basano su bastion, VPN o endpoint pubblici, che sono vietati.","optionExplanations":["Gli endpoint di database pubblici sono esplicitamente vietati, e gli allow list di IP non forniscono autorizzazione IAM.","Un bastion host con una porta SSH in ingresso è esplicitamente vietato.","Corretto — Session Manager inoltra una porta locale al database attraverso l'istanza gestita senza porte in ingresso, e l'accesso è controllato da IAM e registrato.","Le connessioni VPN sono esplicitamente vietate dall'azienda."]},
  "1334": {"h":"a1ed324b","question":"Gli amministratori hanno bisogno di accesso SSH a istanze Linux in subnet private prive di accesso a internet. Le istanze eseguono un'immagine con hardening del fornitore su cui non è possibile installare agent aggiuntivi. Gli amministratori devono usare client SSH standard, e l'accesso deve essere controllato con IAM senza bastion host né indirizzi IP pubblici. Quale soluzione soddisfa questi requisiti?","options":["Usare Systems Manager Session Manager per avviare sessioni shell sulle istanze.","Creare un EC2 Instance Connect Endpoint nel VPC e consentire SSH verso le istanze dal suo security group.","Assegnare indirizzi Elastic IP alle istanze e limitare SSH nei security group all'intervallo IP aziendale.","Avviare un bastion host con hardening in un Auto Scaling group di una sola istanza in una subnet pubblica."],"explanation":"EC2 Instance Connect Endpoint fornisce connettività SSH e RDP privata verso istanze in subnet private, autorizzata tramite IAM, senza indirizzi IP pubblici, accesso a internet, bastion o agent aggiuntivi per gli utenti che si connettono con le proprie chiavi SSH. Session Manager richiederebbe l'SSM Agent, che non può essere installato.","optionExplanations":["Session Manager richiede l'SSM Agent sulle istanze, che non può essere installato su questa immagine.","Corretto — l'endpoint fornisce connettività privata autorizzata da IAM per client SSH standard, senza agent, IP pubblici o bastion.","Questo assegna indirizzi IP pubblici alle istanze e si basa sul filtro per IP anziché sull'autorizzazione IAM.","I bastion host sono esplicitamente esclusi e devono essere aggiornati con patch e monitorati."]},
  "1335": {"h":"a7532707","question":"Un'azienda vuole che il team di sicurezza venga avvisato entro pochi minuti ogni volta che l'utente root del suo account AWS di produzione accede alla console o effettua una qualsiasi chiamata API. Quale soluzione soddisfa questi requisiti con il MINOR carico operativo?","options":["Abilitare la regola gestita AWS Config che verifica se l'MFA è abilitata per l'utente root.","Eseguire ogni giorno una query Amazon Athena sui log CloudTrail per cercare eventi eseguiti dall'utente root.","Esaminare ogni giorno il credential report IAM per individuare utilizzi recenti della password o delle access key di root.","Creare una regola EventBridge che corrisponda agli eventi CloudTrail dell'utente root e invii una notifica a un topic SNS."],"explanation":"CloudTrail consegna gli eventi di gestione, inclusi gli eventi di accesso alla console, ad Amazon EventBridge, dove una regola che corrisponde all'identità dell'utente root può pubblicare su un topic SNS entro pochi minuti. Query giornaliere o revisioni del credential report non possono soddisfare il requisito di tempestività.","optionExplanations":["Questa regola verifica la configurazione MFA dell'utente root; non segnala quando l'utente root viene usato.","Una query giornaliera non invia notifiche entro pochi minuti e richiede pianificazione e manutenzione.","Una revisione manuale giornaliera non fornisce notifiche quasi in tempo reale.","Corretto — gli eventi CloudTrail, inclusi gli accessi alla console, raggiungono EventBridge quasi in tempo reale, quindi una regola può avvisare il team entro pochi minuti."]},
  "1336": {"h":"84e4f810","question":"Un'azienda vuole centralizzare AWS CloudTrail, VPC Flow Logs, i log delle query di Route 53 Resolver e i finding di AWS Security Hub di tutti gli account e le Region in un unico data lake. I dati devono essere normalizzati in uno schema aperto comune, e gli strumenti SIEM di terze parti devono potervisi abbonare. L'azienda desidera il MINOR carico operativo. Quale soluzione soddisfa questi requisiti?","options":["Realizzare in ogni account stream Amazon Data Firehose e job AWS Glue per trasformare e consegnare i log.","Abilitare Amazon Security Lake per l'organizzazione con un delegated administrator e aggiungere i subscriber.","Inviare tutti i log a CloudWatch Logs in un account centrale e concedere agli strumenti SIEM l'accesso in lettura.","Abilitare Amazon Detective per l'organizzazione ed esportare il suo behavior graph verso gli strumenti SIEM."],"explanation":"Amazon Security Lake raccoglie automaticamente le fonti di sicurezza AWS tra gli account e le Region di un'organizzazione, le normalizza nell'Open Cybersecurity Schema Framework (OCSF) in Amazon S3 e offre l'accesso tramite subscriber agli strumenti di terze parti. Una pipeline personalizzata con Firehose e Glue potrebbe fare lo stesso con molta più manutenzione.","optionExplanations":["Può raggiungere l'obiettivo, ma richiede di realizzare e mantenere pipeline personalizzate di acquisizione e trasformazione.","Corretto — Security Lake raccoglie queste fonti tra account e Region, le normalizza in OCSF su S3 e supporta subscriber come gli strumenti SIEM.","CloudWatch Logs non normalizza le fonti in uno schema comune, e la raccolta dei log deve essere realizzata per ogni fonte.","Detective è un servizio di indagine; non fornisce un data lake di sicurezza normalizzato con subscriber."]},
  "1337": {"h":"8ae35c3c","question":"Le chiavi AWS KMS gestite dal cliente di un'azienda proteggono dati critici in molti account. Il mese scorso un ingegnere ha pianificato l'eliminazione di una chiave in uso, e l'errore è stato scoperto solo per caso. L'azienda vuole impedire eliminazioni non autorizzate ed essere avvisata rapidamente se una chiave in attesa di eliminazione è ancora necessaria. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Associare una SCP che neghi la pianificazione dell'eliminazione delle chiavi a ogni principal tranne un ruolo di sicurezza designato.","Impostare a zero giorni il periodo di attesa per l'eliminazione delle chiavi, in modo che gli errori vengano rilevati subito.","Creare un allarme CloudWatch sugli eventi CloudTrail che mostrano tentativi di usare una chiave in attesa di eliminazione.","Abilitare la rotazione automatica delle chiavi in modo che venga generata una nuova chiave se quella corrente viene eliminata.","Spostare i workload sulle chiavi gestite da AWS, che non possono essere pianificate per l'eliminazione dai clienti."],"explanation":"Una SCP che limita kms:ScheduleKeyDeletion a un ruolo di sicurezza impedisce eliminazioni non autorizzate in tutti gli account, e un allarme sugli eventi CloudTrail relativi a tentativi di usare una chiave in attesa di eliminazione rileva che la chiave è ancora in uso quando l'eliminazione può ancora essere annullata. La rotazione non impedisce l'eliminazione, e il periodo di attesa non può essere inferiore a sette giorni.","optionExplanations":["Corretto — questo impedisce centralmente a chiunque non sia il ruolo di sicurezza di pianificare l'eliminazione delle chiavi in tutti gli account.","Un periodo di attesa di almeno sette giorni è obbligatorio, e ridurlo diminuisce soltanto il tempo disponibile per annullare un errore.","Corretto — un allarme sulle richieste fallite che usano una chiave in attesa di eliminazione rivela che la chiave è ancora necessaria, così l'eliminazione può essere annullata durante il periodo di attesa.","La rotazione cambia il key material di una chiave esistente; non protegge dall'eliminazione della chiave né consente di recuperarla.","Le chiavi gestite da AWS fanno rinunciare al controllo sulle key policy e sull'uso cross-account su cui l'azienda fa affidamento."]},
  "1338": {"h":"5d34d6b0","question":"Un istituto di ricerca archivia dati in Amazon S3. Un accordo sulla protezione dei dati richiede che AWS non abbia mai accesso ai dati in chiaro né alle chiavi di crittografia, che devono rimanere negli hardware security module on-premises dell'istituto. Quale soluzione soddisfa questi requisiti?","options":["Usare SSE-KMS con un external key store di AWS KMS che mantenga le chiavi negli HSM on-premises.","Usare SSE-C e inviare la chiave di crittografia dagli HSM on-premises con ogni richiesta di caricamento e download.","Crittografare i dati on-premises con chiavi degli HSM prima di caricare il testo cifrato in Amazon S3.","Usare SSE-KMS con una chiave gestita dal cliente il cui key material è importato dagli HSM on-premises."],"explanation":"Solo la crittografia lato client tiene sia i dati in chiaro sia le chiavi lontani da AWS: i dati vengono crittografati on-premises con chiavi custodite negli HSM e viene caricato solo il testo cifrato. Un external key store mantiene le chiavi fuori da AWS, ma S3 riceve comunque i dati in chiaro per eseguire la crittografia lato server.","optionExplanations":["Le chiavi restano on-premises, ma Amazon S3 riceve comunque i dati in chiaro e li crittografa lato server, quindi AWS elabora i dati in chiaro.","Con SSE-C, Amazon S3 riceve la chiave con ogni richiesta e crittografa i dati in chiaro lato server.","Corretto — con la crittografia lato client, ad AWS arriva solo il testo cifrato e le chiavi non lasciano mai gli HSM dell'istituto.","Il key material importato viene archiviato e usato all'interno di AWS KMS, e S3 gestisce comunque i dati in chiaro."]},
  "1339": {"h":"f5ff5b3d","question":"La pagina di login di un'applicazione web dietro Amazon CloudFront è bersaglio di credential stuffing da migliaia di indirizzi IP, ciascuno dei quali invia poche richieste usando coppie di nome utente e password trafugate da altri siti. L'azienda vuole una soluzione gestita che rilevi le credenziali compromesse e blocchi questi tentativi con un minimo di regole personalizzate. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere una regola rate-based di AWS WAF che limiti il numero di richieste di login che ogni indirizzo IP può inviare.","Sottoscrivere AWS Shield Advanced e abilitare la mitigazione automatica degli attacchi DDoS a livello applicativo.","Abilitare Amazon GuardDuty e bloccare automaticamente gli indirizzi IP che compaiono nei suoi finding.","Aggiungere per il percorso di login il managed rule group AWS WAF Fraud Control account takeover prevention."],"explanation":"Il managed rule group AWS WAF Fraud Control account takeover prevention (ATP) ispeziona le richieste di login, rileva l'uso di credenziali compromesse e mitiga i pattern di login anomali. Una regola rate-based per IP è inefficace perché l'attacco distribuisce volumi ridotti di richieste su migliaia di indirizzi.","optionExplanations":["L'attacco è distribuito su molti indirizzi IP che inviano poche richieste ciascuno, quindi i limiti di frequenza per IP vengono facilmente elusi.","Shield Advanced è rivolto agli attacchi DDoS volumetrici, non al credential stuffing a basso volume che usa credenziali trafugate.","GuardDuty monitora l'attività degli account e dei workload AWS; non ispeziona i tentativi di login applicativi all'edge.","Corretto — il managed rule group ispeziona le richieste di login, confronta le credenziali con database di credenziali rubate e blocca i tentativi sospetti."]},
  "1340": {"h":"7f8b5719","question":"Istanze Amazon EC2 in subnet private accedono a una tabella Amazon DynamoDB tramite un gateway VPC endpoint, e le subnet non hanno altre route in uscita dal VPC. Il team di sicurezza teme che un attaccante possa usare credenziali di un altro account AWS per copiare dati in tabelle esterne all'azienda. Quale soluzione impedirà questo percorso di esfiltrazione?","options":["Limitare la policy IAM dell'instance role in modo che consenta l'accesso solo alla tabella dell'azienda.","Aggiungere regole di network ACL che neghino il traffico in uscita verso tutte le destinazioni tranne DynamoDB.","Aggiungere una regola in uscita al security group che consenta il traffico solo verso la managed prefix list di DynamoDB.","Associare una endpoint policy che consenta le azioni DynamoDB solo sugli ARN delle tabelle dell'azienda."],"explanation":"Una VPC endpoint policy viene valutata per ogni richiesta che passa attraverso l'endpoint, indipendentemente dalle credenziali usate, quindi limitarla agli ARN delle tabelle dell'azienda blocca le scritture verso tabelle di altri account. Le policy IAM sull'instance role non vincolano le credenziali che un attaccante porta da un altro account.","optionExplanations":["Un attaccante che usa credenziali di un altro account non è vincolato dalla policy dell'instance role.","Come la regola del security group, una network ACL opera sugli indirizzi IP e non può limitare l'accesso a tabelle specifiche.","La prefix list copre tutto DynamoDB nella Region, quindi non può distinguere la tabella dell'azienda dalle altre.","Corretto — ogni richiesta che passa per l'endpoint viene verificata rispetto alla endpoint policy, indipendentemente dalle credenziali usate, quindi le altre tabelle non sono raggiungibili."]},
  "1341": {"h":"39fe3f02","question":"Un'azienda finanziaria esegue Amazon Aurora PostgreSQL. Le autorità di regolamentazione richiedono il monitoraggio quasi in tempo reale di tutta l'attività del database da parte del team di sicurezza. Gli amministratori di database, che hanno privilegi completi all'interno del database, non devono poter leggere, alterare o disattivare il flusso di audit. Quale soluzione soddisfa questi requisiti?","options":["Abilitare l'estensione pgAudit e pubblicare i log del database in Amazon CloudWatch Logs.","Abilitare Database Activity Streams con una chiave KMS del team di sicurezza e consumare lo stream Kinesis.","Abilitare i data event di AWS CloudTrail per il cluster Aurora per acquisire ogni istruzione SQL eseguita.","Abilitare Performance Insights e concedere al team di sicurezza l'accesso alla relativa dashboard."],"explanation":"Database Activity Streams inviano un flusso crittografato e quasi in tempo reale dell'attività del database ad Amazon Kinesis, protetto da una chiave KMS controllata dal team di sicurezza, e gli utenti del database non possono disabilitarlo dall'interno del database. I log di pgAudit possono essere riconfigurati da utenti privilegiati del database, quindi non soddisfano il requisito di separazione dei compiti.","optionExplanations":["Gli amministratori di database con privilegi completi possono modificare le impostazioni di pgAudit, quindi potrebbero sopprimere o alterare l'audit.","Corretto — gli activity stream inviano record di attività crittografati a uno stream Kinesis esterno al database, quindi i privilegi interni al database non permettono di leggerli o fermarli.","CloudTrail registra le chiamate alle API RDS, non le istruzioni SQL eseguite all'interno del database.","Performance Insights mostra il carico e le query SQL principali per il tuning, non un audit trail completo e resistente alle manomissioni."]},
  "1342": {"h":"bb0acd37","question":"Un'azienda distribuisce funzioni AWS Lambda tramite diverse pipeline CI/CD. Dopo un incidente nella supply chain, il team di sicurezza richiede che sulle funzioni di produzione possano essere distribuiti solo pacchetti di codice prodotti e approvati dalla pipeline ufficiale, e che qualsiasi pacchetto modificato venga rifiutato. Quale soluzione soddisfa questi requisiti?","options":["Attivare S3 Versioning per il bucket degli artifact di deployment e distribuire sempre solo l'ultima versione dell'oggetto.","Analizzare ogni pacchetto con la scansione del codice Lambda di Amazon Inspector prima di ogni deployment.","Firmare i pacchetti con AWS Signer nella pipeline ufficiale e imporre una configurazione di code signing Lambda.","Limitare lambda:UpdateFunctionCode al ruolo della pipeline ufficiale e richiedere l'MFA per gli altri utenti."],"explanation":"Il code signing di Lambda con AWS Signer consente alle funzioni di accettare solo pacchetti firmati da signing profile approvati; con l'enforcement abilitato, il codice non firmato o modificato viene rifiutato al momento del deployment. Limitare il ruolo di deployment aiuta, ma non verifica l'integrità del pacchetto stesso.","optionExplanations":["Il versioning conserva la cronologia ma non dimostra chi ha prodotto un pacchetto né se è stato modificato.","Inspector individua vulnerabilità nel codice ma non verifica l'origine o l'integrità del pacchetto.","Corretto — Lambda verifica la firma rispetto ai signing profile consentiti e rifiuta i pacchetti non firmati o modificati quando l'enforcement è impostato.","Questo limita chi esegue il deploy, ma non rileva un pacchetto manomesso che passa attraverso la pipeline stessa."]},
  "1343": {"h":"37583846","question":"Il ruolo di una pipeline di deployment ha attualmente ampi permessi per creare tutte le risorse contenute nei template AWS CloudFormation dell'azienda. Il team di sicurezza vuole che il ruolo della pipeline non possa creare o modificare risorse direttamente, pur continuando a distribuire gli stack. Quale soluzione soddisfa questi requisiti?","options":["Concedere al ruolo della pipeline accesso di sola lettura e lasciare che gli sviluppatori distribuiscano gli stack manualmente con le proprie credenziali.","Usare sul ruolo della pipeline un permissions boundary corrispondente alle risorse presenti nei template.","Archiviare i template in un bucket Amazon S3 privato che solo il ruolo della pipeline può leggere.","Creare un service role CloudFormation con i permessi sulle risorse; la pipeline gestisce solo gli stack e lo passa."],"explanation":"Con un service role CloudFormation, le operazioni sugli stack usano i permessi del service role per effettuare il provisioning delle risorse, quindi il ruolo della pipeline necessita solo delle azioni sugli stack CloudFormation e di iam:PassRole su quel ruolo specifico. Un permissions boundary consente comunque al ruolo della pipeline di creare direttamente le risorse.","optionExplanations":["Questo elimina l'automazione e sposta permessi ampi sugli sviluppatori invece di ridurli.","Il ruolo della pipeline potrebbe comunque creare quelle risorse direttamente, al di fuori di CloudFormation.","Questo protegge i template, ma non cambia ciò che il ruolo della pipeline può fare direttamente.","Corretto — CloudFormation usa il service role per creare le risorse, quindi la pipeline necessita solo delle azioni sugli stack e di iam:PassRole per quel ruolo."]},
  "1344": {"h":"337ae847","question":"Un progetto AWS CodeBuild definisce una password di database e un token API di terze parti come variabili d'ambiente in chiaro, visibili a chiunque possa visualizzare la configurazione del progetto. I valori devono essere crittografati, gestiti centralmente e leggibili solo dalla build in fase di esecuzione. Quale soluzione soddisfa questi requisiti?","options":["Memorizzare i valori in AWS Secrets Manager, referenziarli nel buildspec e consentire al service role di leggerli.","Crittografare gli artifact di build del progetto CodeBuild con una chiave AWS KMS gestita dal cliente.","Spostare i valori nel file buildspec nel repository sorgente, in modo che siano versionati insieme al codice.","Limitare il permesso codebuild:BatchGetProjects in modo che solo gli amministratori possano visualizzare le impostazioni del progetto."],"explanation":"CodeBuild può referenziare secret di AWS Secrets Manager (o parametri SecureString di Parameter Store) nel buildspec e li recupera in fase di esecuzione con il service role del progetto, mantenendoli crittografati e gestiti centralmente. Limitare chi può visualizzare il progetto nasconde i valori in chiaro, ma non li protegge.","optionExplanations":["Corretto — CodeBuild risolve i riferimenti a Secrets Manager durante la build con il proprio service role, quindi i valori non compaiono mai nella configurazione del progetto.","La crittografia degli artifact protegge gli output della build, non le variabili d'ambiente mostrate nella configurazione del progetto.","Questo espone i secret a chiunque possa leggere il repository e la sua cronologia.","Questo nasconde la configurazione ad alcuni utenti, ma lascia i secret non crittografati e non gestiti."]},
  "1345": {"h":"b3647fab","question":"Un'app mobile usa un user pool Amazon Cognito con due gruppi, Editors e Viewers. Gli Editors devono poter caricare oggetti in un bucket Amazon S3, mentre i Viewers devono poterli solo leggere. Gli utenti accedono direttamente a S3 con credenziali AWS temporanee fornite da un identity pool Cognito. Quale soluzione soddisfa questi requisiti?","options":["Assegnare un ruolo IAM a ogni gruppo dello user pool e lasciare che l'identity pool scelga il ruolo dal token dell'utente.","Usare un unico ruolo autenticato con permessi di caricamento e nascondere il pulsante di caricamento ai Viewers nell'app.","Creare un identity pool separato per ogni gruppo e far selezionare all'app il pool in base al gruppo dell'utente.","Creare un utente IAM per ogni Editor e incorporarne le access key nell'app dopo l'accesso."],"explanation":"Gli identity pool Cognito supportano il controllo degli accessi basato sui ruoli: i ruoli IAM associati ai gruppi dello user pool compaiono nel token, e l'identity pool può assegnare il ruolo in base al token (o tramite regole), così Editors e Viewers ricevono credenziali temporanee diverse. Un unico ruolo con controlli nell'interfaccia lascia ai Viewers la possibilità di caricare.","optionExplanations":["Corretto — i ruoli dei gruppi sono trasportati nel token, e l'identity pool emette credenziali per il ruolo corrispondente, quindi i permessi seguono l'appartenenza ai gruppi.","I Viewers riceverebbero comunque credenziali che consentono i caricamenti, quindi la restrizione è solo estetica.","Funziona, ma duplica la configurazione e si affida al client per la scelta del pool corretto.","Questo introduce credenziali a lungo termine nell'app, una soluzione insicura e difficile da gestire."]},
  "1346": {"h":"8c5a7c0a","question":"Un produttore collega migliaia di sensori ad AWS IoT Core tramite MQTT. Una IoT rule scrive ogni messaggio di telemetria direttamente in una tabella Amazon DynamoDB. Durante brevi periodi di throttling della tabella, l'azione della regola fallisce e i messaggi interessati vanno persi. L'azienda vuole conservare ogni messaggio per una successiva rielaborazione senza aggiungere server né modificare il firmware dei dispositivi. Quale soluzione soddisferà questi requisiti con il MINOR carico operativo?","options":["Configurare sulla IoT rule una error action che invii i messaggi delle azioni fallite a una coda Amazon SQS.","Far sì che ogni dispositivo memorizzi i messaggi in un buffer locale e li reinvii quando non riceve una conferma a livello applicativo.","Sostituire la regola con una flotta di istanze EC2 che si iscrivono ai topic MQTT e scrivono nella tabella.","Abilitare DynamoDB Streams sulla tabella e riprodurre i record mancanti dallo stream."],"explanation":"La error action di una IoT rule si attiva ogni volta che un'azione della regola fallisce, quindi instradarla verso Amazon SQS conserva in modo durevole ogni messaggio non riuscito per la rielaborazione, senza server da gestire. Il buffering sui dispositivi richiederebbe modifiche al firmware, che l'azienda ha escluso.","optionExplanations":["Corretto — la error action acquisisce i messaggi la cui scrittura su DynamoDB è fallita e li archivia in modo durevole in SQS per una successiva rielaborazione.","Questo richiede di modificare il firmware dei dispositivi, e le conferme MQTT di IoT Core non indicano se l'azione della regola a valle è riuscita.","Istanze subscriber autogestite aggiungono server e carico operativo, e incontrerebbero lo stesso problema di throttling.","DynamoDB Streams contiene solo gli elementi scritti con successo, quindi i messaggi la cui scrittura è fallita non vi compaiono mai."]},
  "1347": {"h":"5f66c82a","question":"Un'API di pagamento è eseguita su Amazon API Gateway e AWS Lambda e scrive gli addebiti in Amazon DynamoDB. I client mobili ritentano una richiesta quando non ricevono risposta entro pochi secondi, e talvolta la richiesta originale era già andata a buon fine, per cui ai clienti viene addebitato due volte. L'azienda deve rendere sicuri i retry senza ridurre la disponibilità. Quale soluzione soddisferà questi requisiti?","options":["Disattivare i retry dei client e mostrare ai clienti un messaggio di errore ogni volta che una richiesta impiega troppo tempo.","Far inviare ai client una chiave di idempotenza univoca e registrarla con una scrittura condizionale prima dell'addebito.","Aumentare timeout e memoria della funzione Lambda in modo che le richieste si completino prima che i client ritentino.","Abilitare il caching di API Gateway per il metodo di addebito, in modo che le richieste ripetute restituiscano il risultato in cache."],"explanation":"Una chiave di idempotenza generata dal client e memorizzata con una scrittura condizionale DynamoDB consente al servizio di rilevare una richiesta ripetuta e restituire il risultato originale invece di addebitare di nuovo, così i client possono continuare a ritentare in sicurezza. Rendere la funzione più veloce restringe solo la finestra; i guasti di rete possono comunque causare duplicati.","optionExplanations":["Eliminare i retry riduce la disponibilità, perché errori di rete transitori farebbero fallire richieste che avrebbero potuto riuscire.","Corretto — la scrittura condizionale sulla chiave di idempotenza garantisce che ogni richiesta logica venga applicata una sola volta, indipendentemente da quanti retry arrivino.","Un'elaborazione più rapida non impedisce i duplicati causati da risposte perse o timeout di rete, quindi possono ancora verificarsi doppi addebiti.","Il caching è pensato per metodi GET idempotenti e si basa sui parametri della richiesta; non è un meccanismo di deduplicazione affidabile per le scritture di pagamento."]},
  "1348": {"h":"75758d62","question":"Un'applicazione web su istanze EC2 dietro un Application Load Balancer usa un endpoint /health che interroga anche il database Amazon RDS. L'Auto Scaling group usa gli health check ELB. Durante un failover RDS Multi-AZ di 60 secondi, ogni istanza ha fallito il proprio health check e il gruppo ha terminato e sostituito l'intera flotta, trasformando un breve evento del database in un lungo disservizio. Cosa dovrebbe raccomandare un solutions architect?","options":["Aumentare la dimensione dell'istanza di database in modo che i failover Multi-AZ si completino in meno tempo dell'intervallo dell'health check.","Impostare l'Auto Scaling group sui soli status check EC2 e rimuovere completamente l'health check del load balancer.","Usare un health check superficiale che verifichi solo il processo locale e gestire gli errori del database nell'applicazione.","Configurare l'health check perché venga eseguito ogni pochi secondi con una soglia unhealthy più bassa, così da rilevare prima i guasti."],"explanation":"Gli health check che sostituiscono le istanze dovrebbero verificare solo ciò che la sostituzione dell'istanza può risolvere; il guasto di una dipendenza condivisa in un check profondo fa apparire non integra l'intera flotta contemporaneamente e scatena una sostituzione di massa. Un controllo di liveness superficiale mantiene le istanze in servizio mentre l'applicazione degrada in modo controllato durante il failover. Eliminare del tutto gli health check ELB impedirebbe al gruppo di sostituire le istanze il cui processo si blocca davvero.","optionExplanations":["La dimensione dell'istanza non controlla in modo affidabile la durata del failover, e l'health check profondo farebbe comunque fallire l'intera flotta in caso di qualsiasi problema di una dipendenza.","Gli status check EC2 non rilevano un processo applicativo bloccato, quindi le istanze non integre non verrebbero più sostituite.","Corretto — un check superficiale evita la sostituzione dell'intera flotta causata da una dipendenza condivisa, mentre l'applicazione gestisce la breve indisponibilità del database.","Un rilevamento più rapido peggiora il problema, perché la flotta verrebbe contrassegnata come non integra e sostituita ancora prima durante il failover."]},
  "1349": {"h":"ee5a12a7","question":"Le pagine prodotto di un negozio online leggono da un database Amazon RDS for MySQL. Quando un prodotto viene presentato in televisione, il traffico in lettura per alcuni articoli molto richiesti aumenta nel giro di pochi secondi, la CPU del database si satura e l'intero sito smette di funzionare. I dati dei prodotti possono essere obsoleti fino a un minuto. L'azienda vuole proteggere il database da questi picchi improvvisi. Quale soluzione soddisferà questi requisiti nel modo PIÙ efficace?","options":["Configurare lo storage autoscaling di RDS in modo che il database ottenga automaticamente capacità quando il carico aumenta.","Convertire l'istanza DB in un deployment Multi-AZ in modo che l'istanza standby possa condividere il traffico in lettura.","Aggiungere una policy di Auto Scaling che crei read replica aggiuntive quando l'utilizzo della CPU del database aumenta.","Memorizzare in cache i dati dei prodotti in Amazon ElastiCache con un TTL breve e leggere dalla cache prima che dal database."],"explanation":"Una cache davanti al database assorbe istantaneamente le letture ripetute degli stessi articoli molto richiesti, e un TTL breve mantiene i dati entro il limite di obsolescenza di un minuto. L'aggiunta di read replica in risposta alla CPU richiede molti minuti, quindi il database sarebbe già saturo quando il picco arriva nel giro di pochi secondi.","optionExplanations":["Lo storage autoscaling aggiunge spazio su disco, non CPU né capacità di lettura, quindi non serve a nulla per un picco di letture.","Lo standby di un deployment Multi-AZ di un'istanza DB non serve traffico in lettura.","La creazione di nuove read replica richiede minuti, troppo lenta per un picco che arriva in pochi secondi.","Corretto — ElastiCache serve gli articoli molto richiesti dalla memoria, proteggendo il database, e il TTL rispetta la tolleranza all'obsolescenza."]},
  "1350": {"h":"0cf34816","question":"Un'azienda usa il failover routing di Amazon Route 53 tra due Region. L'applicazione della Region primaria è eseguita su istanze EC2 in subnet private dietro un Application Load Balancer interno raggiungibile solo dall'interno del VPC. L'azienda vuole che Route 53 esegua il failover quando il tasso di errore dell'applicazione nella Region primaria supera una soglia. Quale soluzione soddisferà questi requisiti?","options":["Creare un health check di endpoint che punti agli indirizzi IP privati dell'Application Load Balancer interno.","Creare un health check di Route 53 che monitori lo stato di un allarme CloudWatch sul tasso di errore dell'applicazione.","Associare un indirizzo Elastic IP a un'istanza e far puntare a quell'indirizzo un health check di endpoint Route 53.","Creare un calculated health check che combini lo stato di salute dell'indirizzo IP privato di ogni istanza."],"explanation":"Gli health checker di Route 53 operano su internet e non possono raggiungere endpoint privati, ma un health check può basarsi sullo stato di un allarme CloudWatch, che può misurare il tasso di errore di un'applicazione privata. Puntare un check verso indirizzi IP privati fallirebbe, perché gli health checker non hanno un percorso di rete verso di essi.","optionExplanations":["Gli health checker di Route 53 non possono raggiungere indirizzi IP privati all'interno di un VPC, quindi questo check non rifletterebbe mai lo stato reale.","Corretto — gli health check basati su allarmi consentono a Route 53 di agire su metriche provenienti da risorse private, come il tasso di errore dell'applicazione.","Esporre pubblicamente una singola istanza indebolisce la sicurezza e riflette solo quell'istanza, non il tasso di errore complessivo dell'applicazione.","I calculated health check combinano altri health check, ma i check figli dovrebbero comunque raggiungere indirizzi privati."]},
  "1351": {"h":"814daaf8","question":"In ogni Region l'applicazione di un'azienda dipende da tre componenti: un endpoint web, un endpoint API e un endpoint di reporting, ciascuno con il proprio health check di Route 53. L'azienda vuole che Route 53 esegua il failover verso la Region secondaria solo quando almeno due dei tre componenti non sono integri, in modo che un problema del solo endpoint di reporting non provochi un failover di Region. Quale soluzione soddisfa questi requisiti?","options":["Associare tutti e tre gli health check dei componenti al record di failover primario, in modo che ciascuno venga valutato in modo indipendente.","Creare un calculated health check con i tre check come figli, che risulti integro se almeno due di essi sono integri.","Usare una routing policy weighted con tre record per Region, in modo che ogni componente rimuova un terzo del traffico.","Aumentare la soglia di errore dell'health check dell'endpoint di reporting, in modo che segnali raramente uno stato non integro."],"explanation":"Un calculated health check combina più health check figli e risulta integro solo quando è integro un numero minimo configurato di figli, il che corrisponde a una regola «due su tre». Un record può avere un solo health check associato, quindi i componenti non possono essere semplicemente collegati singolarmente.","optionExplanations":["Un record di Route 53 ha un solo health check associato, quindi non può valutare tre check separati con una regola «due su tre».","Corretto — Impostare a due la soglia di integrità del calculated check esprime esattamente la condizione di failover richiesta.","Il routing weighted ripartisce il traffico in proporzione e non implementa una decisione di failover di Region del tipo «due su tre».","Ritardare un check nasconde soltanto i guasti e comunque non esprime la regola secondo cui devono guastarsi due componenti."]},
  "1352": {"h":"ee85c085","question":"Un'azienda sta spostando un'applicazione di content management su Amazon ECS con AWS Fargate. Ogni task salva i file multimediali caricati in una directory locale e diversi task distribuiti su tre Availability Zone devono vedere gli stessi file. I file devono sopravvivere alla sostituzione dei task e alla perdita di una Availability Zone. Quale soluzione di storage soddisfa questi requisiti con il MINOR onere operativo?","options":["Montare come volume nella task definition un file system Amazon EFS che usa una storage class Regional.","Collegare un volume Amazon EBS separato a ogni task e sincronizzare i volumi con un container sidecar.","Usare lo storage effimero di ogni task Fargate e copiare frequentemente i nuovi file su Amazon S3 in modo pianificato.","Eseguire un server NFS autogestito su un'istanza EC2 in una Availability Zone e montarlo in ogni task."],"explanation":"Amazon EFS è supportato nativamente come volume dei task Fargate, è condiviso da tutti i task e, con una storage class Regional, memorizza i dati in modo ridondante su più Availability Zone. I volumi EBS per singolo task sono legati a una sola zona e non sono condivisi, quindi mantenerli sincronizzati aggiunge complessità e rischi.","optionExplanations":["Corretto — EFS fornisce uno storage di file condiviso, persistente e multi-AZ che i task Fargate possono montare direttamente.","I volumi EBS sono zonali e collegati ciascuno a un solo task; una sincronizzazione personalizzata aggiunge onere e può perdere scritture o generare conflitti.","Lo storage effimero si perde quando un task si arresta, e le copie pianificate lasciano una finestra di perdita dati senza una vista condivisa.","Un singolo server NFS è un single point of failure in una sola zona e deve essere aggiornato e gestito."]},
  "1353": {"h":"9a079fdd","question":"Un'azienda esegue un'applicazione Java che usa JMS e il protocollo OpenWire per scambiare messaggi tramite un broker Apache ActiveMQ autogestito su una singola istanza EC2. Quando il mese scorso l'istanza si è guastata, la messaggistica si è fermata per ore. L'azienda vuole che il broker sopravviva al guasto di una Availability Zone senza modificare il codice applicativo. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Sostituire il broker con una coda Amazon SQS standard e aggiornare l'applicazione affinché usi l'SDK di SQS.","Eseguire due istanze ActiveMQ autogestite in Availability Zone diverse dietro un Network Load Balancer.","Distribuire un broker Amazon MQ for ActiveMQ active/standby che si estende su due Availability Zone.","Inserire l'istanza del broker esistente in un Auto Scaling group con dimensione minima e massima pari a uno."],"explanation":"Amazon MQ for ActiveMQ supporta i client JMS e OpenWire esistenti e fornisce un broker gestito active/standby su due Availability Zone, con storage durevole condiviso e failover automatico. Passare ad Amazon SQS richiederebbe di riscrivere il codice di messaggistica, cosa non consentita.","optionExplanations":["SQS non supporta OpenWire, quindi il codice dell'applicazione dovrebbe cambiare.","Due broker autogestiti richiedono di configurare storage condiviso, failover e patching, con un onere operativo molto maggiore.","Corretto — Amazon MQ fornisce un broker ActiveMQ gestito e ad alta disponibilità che i client esistenti possono usare senza modifiche al codice.","Sostituire l'istanza riavvia un broker vuoto, a meno di riprogettare lo storage, e i messaggi in transito sull'istanza guasta possono andare persi."]},
  "1354": {"h":"5fe990fd","question":"Un'applicazione web memorizza le sessioni utente in un cluster Amazon ElastiCache (Redis OSS) con un solo nodo e cluster mode disabilitato. Quando il nodo si è guastato durante un'interruzione di una Availability Zone, tutti gli utenti sono stati disconnessi e l'applicazione non ha potuto creare nuove sessioni finché non è stato avviato un nuovo nodo. Quale modifica migliora la resilienza con il MINOR numero di modifiche all'applicazione?","options":["Eseguire backup orari del nodo e ripristinare il backup più recente quando il nodo si guasta.","Spostare i dati di sessione su un cluster Redis autogestito eseguito su istanze EC2 in tre Availability Zone.","Memorizzare le sessioni in cookie sticky sul load balancer, in modo che la cache non sia più necessaria.","Aggiungere una replica in un'altra Availability Zone e abilitare Multi-AZ con failover automatico sul cluster."],"explanation":"Aggiungere una replica in un'altra Availability Zone e abilitare Multi-AZ consente a ElastiCache di promuovere automaticamente la replica se il primario o la sua zona si guastano, mentre l'applicazione continua a usare lo stesso endpoint primario. Il ripristino dei backup richiede tempo e perde le sessioni create dopo l'ultimo backup.","optionExplanations":["Il ripristino da backup causa downtime e perde le sessioni recenti, quindi gli utenti subiscono comunque l'impatto.","Un cluster autogestito aggiunge un onere operativo significativo rispetto alla funzionalità di failover gestito.","La stickiness del load balancer indirizza solo gli utenti verso la stessa istanza; non memorizza i dati di sessione e li perde quando un'istanza si guasta.","Corretto — Multi-AZ con failover automatico promuove la replica dietro lo stesso endpoint, quindi non serve alcuna modifica all'applicazione."]},
  "1355": {"h":"ea37d421","question":"Un'azienda esegue un deployment Multi-AZ DB instance di Amazon RDS for PostgreSQL. Il business ora richiede che i failover del database si completino più velocemente di oggi e vuole che la capacità di standby già pagata serva query di reporting in sola lettura. L'azienda non vuole migrare a un motore di database diverso. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere una read replica cross-Region e inviarle le query di reporting mantenendo il deployment attuale.","Passare a un deployment RDS Multi-AZ DB cluster con un writer e due istanze di standby leggibili.","Migrare il database ad Amazon Aurora PostgreSQL e aggiungere Aurora Replica in altre zone per scalare le letture e per il failover.","Creare un RDS Proxy davanti al database e instradare le connessioni in sola lettura verso lo standby."],"explanation":"Un deployment RDS Multi-AZ DB cluster usa due istanze di standby leggibili in Availability Zone diverse e in genere esegue il failover più velocemente di un deployment Multi-AZ DB instance. Anche la migrazione ad Aurora funzionerebbe tecnicamente, ma cambia il motore, cosa che l'azienda non vuole.","optionExplanations":["Una replica cross-Region aggiunge costi e non rende più veloce il failover del deployment primario.","Corretto — Il deployment Multi-AZ DB cluster offre un failover più rapido e standby in grado di servire traffico di lettura.","Aurora PostgreSQL è un motore diverso e richiede una migrazione, che l'azienda vuole evitare.","Lo standby di un deployment Multi-AZ DB instance non accetta connessioni, quindi RDS Proxy non può inviargli letture."]},
  "1356": {"h":"e1105fd6","question":"Un'azienda replica oggetti Amazon S3 cifrati e dati di una global table Amazon DynamoDB in una seconda Region per il disaster recovery. Tutti i dati sono cifrati con una customer managed key AWS KMS nella Region primaria. L'azienda teme che i dati nella seconda Region non possano essere decifrati se il servizio KMS della Region primaria non fosse disponibile. Quale soluzione risolve questo problema con il MINOR onere operativo?","options":["Usare una multi-Region key AWS KMS con una replica key nella seconda Region per la cifratura in ciascuna Region.","Esportare il materiale della chiave dalla Region primaria e importarlo in una nuova chiave nella seconda Region.","Passare a SSE-S3 per gli oggetti S3 e mantenere la customer managed key per le tabelle DynamoDB.","Creare una customer managed key separata nella seconda Region e ricifrare ogni notte tutti i dati replicati."],"explanation":"Le multi-Region key di KMS condividono lo stesso key ID e lo stesso materiale della chiave tra le Region, quindi i dati cifrati in una Region possono essere decifrati nell'altra senza alcuna chiamata alla Region primaria. AWS KMS non consente di esportare il materiale delle chiavi che ha generato, e la ricifratura notturna aggiunge un onere pesante e una lacuna nella protezione dei dati.","optionExplanations":["Corretto — Una replica key multi-Region consente alla seconda Region di decifrare i dati indipendentemente dalla Region primaria.","Il materiale delle chiavi generato da AWS KMS non può essere esportato, quindi questo approccio non è possibile per la chiave esistente.","I dati DynamoDB dipenderebbero ancora dalla chiave della Region primaria, e la modifica riduce il controllo sulle chiavi di cifratura di S3.","La ricifratura notturna è operativamente onerosa e lascia illeggibili i dati replicati di recente durante un'interruzione della Region primaria."]},
  "1357": {"h":"072587fd","question":"Una funzione Lambda consuma una coda Amazon SQS standard dotata di dead-letter queue. Un bug in una nuova release ha inviato migliaia di messaggi alla dead-letter queue nel corso di una notte. Il bug ora è corretto e l'azienda vuole che questi messaggi vengano elaborati dalla funzione corretta nel modo normale. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Scrivere uno script che riceva ogni messaggio dalla dead-letter queue e lo invii di nuovo alla coda di origine.","Configurare in modo permanente la dead-letter queue come seconda event source della stessa funzione Lambda.","Usare il redrive della dead-letter queue di SQS per riportare i messaggi nella coda di origine e rielaborarli.","Aumentare il maximum receive count sulla coda di origine, in modo che meno messaggi raggiungano la dead-letter queue."],"explanation":"Il redrive della dead-letter queue di SQS sposta i messaggi dalla dead-letter queue alla coda di origine come attività gestita, così la funzione corretta li elabora attraverso il percorso normale. Uno script personalizzato ottiene lo stesso risultato, ma deve essere scritto, eseguito e monitorato.","optionExplanations":["Uno script personalizzato funziona, ma aggiunge un impegno di sviluppo e operativo che la funzionalità di redrive gestita evita.","Consumare in modo permanente la dead-letter queue ritenterebbe all'infinito i poison message, vanificandone lo scopo di isolamento.","Corretto — Il redrive della DLQ riporta i messaggi nella coda di origine senza codice personalizzato.","Modificare il receive count influisce solo sui guasti futuri e non agisce sui messaggi già presenti nella dead-letter queue."]},
  "1358": {"h":"5f521c4b","question":"Un'applicazione di biglietteria memorizza le prenotazioni in una tabella Amazon DynamoDB che usa capacità provisioned con auto scaling. Quando vanno in vendita eventi popolari, il traffico di scrittura sale in pochi secondi a molte volte il livello normale, le richieste vengono limitate (throttling) prima che l'auto scaling reagisca e le prenotazioni falliscono. Gli orari di vendita non sono annunciati in anticipo. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Alzare il target utilization dell'auto scaling, in modo che la tabella scali più aggressivamente all'aumentare delle scritture.","Aggiungere un cluster DynamoDB Accelerator (DAX) davanti alla tabella per assorbire il traffico di scrittura.","Creare un global secondary index per distribuire le scritture su un maggior numero di partizioni.","Passare la tabella alla modalità di capacità on-demand, così gestisce il traffico improvviso senza pianificare la capacità."],"explanation":"La modalità di capacità on-demand gestisce picchi improvvisi e imprevedibili senza pianificazione della capacità, perché non attende che l'auto scaling regoli il throughput provisioned. DAX è una cache read-through e write-through; accelera le letture, ma ogni scrittura consuma comunque capacità della tabella.","optionExplanations":["L'auto scaling reagisce comunque dopo l'inizio del throttling, e un target utilization più alto lascia in realtà meno margine.","DAX scrive in modalità write-through sulla tabella, quindi la capacità di scrittura viene comunque consumata e il throttling continua.","Un global secondary index aggiunge ulteriore consumo di scrittura e non aumenta il throughput della tabella di base.","Corretto — La modalità on-demand gestisce picchi imprevedibili senza pianificazione della capacità né ritardi di scaling."]},
  "1359": {"h":"4510574f","question":"Un'azienda memorizza immagini di prodotto in bucket Amazon S3 in due Region, mantenuti sincronizzati con S3 Replication. Applicazioni in diverse Region accedono alle immagini. L'azienda vuole che le applicazioni usino un unico endpoint globale e vuole spostare tutte le richieste sul bucket secondario entro pochi minuti durante un incidente di Region, senza modificare la configurazione delle applicazioni. Quale soluzione soddisfa questi requisiti?","options":["Creare un record di failover Route 53 che punti agli endpoint REST S3 dei due bucket.","Creare un S3 Multi-Region Access Point in modalità active-passive e usarne i failover control.","Configurare una distribuzione CloudFront con un origin group che contenga entrambi i bucket per tutte le richieste.","Aggiornare il nome del bucket nella configurazione di ogni applicazione tramite AWS Systems Manager Parameter Store."],"explanation":"Gli S3 Multi-Region Access Point forniscono un unico endpoint globale per bucket in più Region, e i loro failover control spostano le richieste dal bucket attivo a quello passivo entro pochi minuti. Gli origin group di CloudFront eseguono il failover solo per le richieste GET, HEAD e OPTIONS, quindi i caricamenti tramite CloudFront non andrebbero in failover.","optionExplanations":["Le richieste REST S3 devono essere firmate e indirizzate a uno specifico nome di bucket, quindi il failover DNS tra due bucket diversi non funziona in modo affidabile.","Corretto — I failover control del Multi-Region Access Point reindirizzano tutte le richieste al bucket passivo senza modifiche alle applicazioni.","L'origin failover di CloudFront si applica solo alle richieste GET, HEAD e OPTIONS, quindi le scritture non andrebbero in failover.","Modificare la configurazione di ogni applicazione è lento e soggetto a errori, e viola il requisito di evitare modifiche di configurazione."]},
  "1360": {"h":"d7f4a6fa","question":"Un'azienda esegue un piccolo cluster di cinque istanze EC2 che ospitano un servizio di coordinamento basato su quorum. Le istanze si trovano in una sola Availability Zone a causa di requisiti di latenza stringenti. L'azienda vuole ridurre il rischio che un singolo guasto hardware colpisca più di un'istanza contemporaneamente. Quale soluzione soddisfa questi requisiti?","options":["Avviare le istanze in un spread placement group, in modo che ogni istanza venga eseguita su hardware distinto.","Avviare le istanze in un cluster placement group per mantenerle fisicamente vicine tra loro.","Avviare le istanze come Dedicated Instances, in modo che nessun altro cliente condivida il loro hardware.","Abilitare l'automatic recovery di EC2 su ogni istanza, in modo che si riavvii su nuovo hardware dopo qualsiasi guasto."],"explanation":"Uno spread placement group colloca ogni istanza su rack distinti con alimentazione e rete separate, riducendo al minimo i guasti hardware correlati all'interno di una Availability Zone. Un cluster placement group fa l'opposto, raggruppando le istanze vicine tra loro, il che aumenta il rischio che un singolo evento hardware ne colpisca diverse.","optionExplanations":["Corretto — Gli spread placement group collocano ogni istanza su rack hardware sottostanti separati.","I cluster placement group raggruppano le istanze per le prestazioni di rete, aumentando il rischio di guasti correlati.","Le Dedicated Instances isolano l'hardware dagli altri account, ma non mantengono le proprie istanze su rack separati.","L'automatic recovery aiuta dopo un guasto, ma non impedisce che un singolo guasto hardware colpisca più istanze contemporaneamente."]},
  "1361": {"h":"438e6529","question":"Un'azienda esegue un'applicazione su istanze EC2 dietro un Application Load Balancer su tre Availability Zone. Durante un recente incidente, una zona ha subito una perdita di pacchetti intermittente: le istanze superavano gli health check, ma molte richieste erano lente o fallivano. L'azienda vuole che gli operatori possano spostare il traffico da una zona compromessa entro pochi minuti, senza ripetere il deployment né modificare la configurazione dell'Auto Scaling. Quale soluzione soddisfa questi requisiti?","options":["Rimuovere le subnet della zona compromessa dall'Application Load Balancer e dall'Auto Scaling group durante un incidente.","Configurare record weighted di Route 53 per le istanze di ciascuna zona e impostare a zero il peso della zona compromessa.","Rendere più rigorosi gli health check del load balancer, in modo che le istanze di una zona degradata risultino non integre.","Usare lo zonal shift di Amazon Application Recovery Controller per spostare il traffico del load balancer dalla zona compromessa."],"explanation":"Lo zonal shift di Amazon Application Recovery Controller sposta temporaneamente il traffico del load balancer da una Availability Zone, e lo spostamento può essere annullato o scade da solo, senza modificare il load balancer o l'Auto Scaling group. Rimuovere le subnet richiede modifiche di configurazione e può terminare istanze, cosa che l'azienda vuole evitare.","optionExplanations":["Modificare le subnet cambia la configurazione del load balancer e dell'Auto Scaling e può causare terminazioni e ribilanciamenti delle istanze.","Record DNS per zona aggirano il design basato sul load balancer, aggiungono complessità e sono soggetti al caching DNS dei client.","I guasti «grigi» spesso superano gli health check, e check più rigorosi rischiano falsi positivi che rimuovono capacità integra altrove.","Corretto — Uno zonal shift allontana rapidamente il traffico dalla zona compromessa ed è facilmente reversibile."]},
  "1362": {"h":"b2b03743","question":"Una piattaforma video orchestra l'elaborazione con AWS Step Functions. Uno step attualmente invoca una funzione Lambda che avvia un job AWS Elemental MediaConvert e poi interroga lo stato del job in un ciclo. I video lunghi richiedono più di 15 minuti di transcodifica, quindi la funzione va in timeout e il workflow fallisce anche se il job ha successo. Quale soluzione risolve il problema con il MINOR onere operativo?","options":["Aumentare il timeout e la memoria della funzione Lambda, in modo che possa attendere i job di transcodifica più lunghi.","Spostare il ciclo di polling in un container su Amazon ECS che la state machine avvia e di cui attende il completamento.","Usare l'integrazione MediaConvert di Step Functions con il pattern run a job, così lo stato attende il completamento.","Fare in modo che la funzione scriva l'ID del job in una coda SQS e aggiungere una seconda funzione che interroghi MediaConvert ogni minuto."],"explanation":"L'integrazione ottimizzata di Step Functions per MediaConvert può avviare un job e attenderne il completamento con il pattern run a job (.sync), quindi nessun codice deve eseguire polling e non si applica alcun timeout di Lambda. Lambda ha un timeout massimo fisso che i job lunghi superano, quindi la regolazione della funzione non può risolvere il problema.","optionExplanations":["Il timeout massimo di Lambda è fisso, quindi i job più lunghi di quel limite causeranno comunque errori.","Un container può attendere più a lungo, ma aggiunge infrastruttura e codice di polling personalizzato che l'integrazione nativa evita.","Corretto — L'integrazione .sync consente alla state machine di attendere il job MediaConvert senza polling personalizzato né timeout.","Una funzione di polling separata e una coda aggiungono componenti e richiedono comunque un modo per riprendere il workflow."]},
  "1363": {"h":"76033e4b","question":"Un'azienda di genomica esegue job di analisi containerizzati su AWS Batch con un compute environment che usa Spot Instances. Ogni job dura circa un'ora e scrive checkpoint su Amazon S3 ogni pochi minuti. Quando la capacità Spot viene recuperata, i job interessati falliscono e i ricercatori devono reinviarli manualmente. Quale soluzione riduce il lavoro manuale mantenendo i risparmi di Spot?","options":["Configurare una retry strategy dei job che ritenti automaticamente i job falliti perché l'host Spot è stato recuperato.","Passare il compute environment a istanze On-Demand, in modo che i job di lunga durata non vengano mai interrotti dal recupero di capacità.","Eseguire i job su un unico tipo di istanza Spot più grande, in modo che la capacità abbia meno probabilità di essere recuperata.","Creare un allarme CloudWatch sui job falliti che notifichi via email ai ricercatori di reinviarli."],"explanation":"Una retry strategy di AWS Batch può ritentare automaticamente un job un numero prestabilito di volte, e le exit condition possono individuare i fallimenti causati dalla terminazione dell'host Spot; i job riprendono dai checkpoint su S3. Passare a On-Demand elimina le interruzioni, ma rinuncia ai risparmi di Spot che l'azienda vuole mantenere.","optionExplanations":["Corretto — I retry automatici sui fallimenti dovuti al recupero dell'host reinviano i job senza lavoro manuale, e i checkpoint limitano i progressi persi.","La capacità On-Demand evita le interruzioni ma perde i risparmi di Spot, che l'azienda vuole mantenere.","Affidarsi a un solo tipo di istanza riduce la diversità della capacità e in genere aumenta, anziché ridurre, l'impatto delle interruzioni.","Le notifiche lasciano comunque ai ricercatori il reinvio manuale dei job, quindi non riducono il lavoro."]},
  "1364": {"h":"61c7c17b","question":"Un'applicazione si connette a un DB cluster Amazon Aurora MySQL con un writer e due Aurora Replica. L'applicazione era configurata con l'endpoint della specifica istanza writer per tutte le scritture. Dopo che un failover automatico ha promosso una replica, tutte le scritture sono fallite finché un tecnico non ha modificato la configurazione. Cosa dovrebbe raccomandare un solutions architect per evitarlo?","options":["Configurare l'applicazione per inviare tutte le istruzioni di scrittura al reader endpoint del DB cluster.","Configurare l'applicazione per usare il cluster endpoint, che punta sempre al writer corrente.","Creare un custom endpoint che contenga solo l'istanza writer originale per il traffico di scrittura.","Assegnare un indirizzo Elastic IP all'istanza writer e connettere l'applicazione a tale indirizzo."],"explanation":"Il cluster endpoint di Aurora si risolve sempre nell'istanza writer corrente, quindi dopo un failover l'applicazione si riconnette automaticamente al writer appena promosso. Un instance endpoint continua a puntare a un'istanza specifica, che ora potrebbe essere un reader o non essere disponibile.","optionExplanations":["Il reader endpoint bilancia il carico tra le Aurora Replica, che rifiutano le scritture.","Corretto — Il cluster endpoint segue il ruolo di writer attraverso i failover senza modifiche di configurazione.","Un custom endpoint con un membro fisso punta ancora alla vecchia istanza dopo il failover, quindi le scritture fallirebbero.","Alle istanze Aurora non si possono assegnare indirizzi Elastic IP, e un indirizzo fisso non seguirebbe il ruolo di writer."]},
  "1365": {"h":"afa8bb8a","question":"Un'azienda espone un'API REST tramite Amazon CloudFront, con un Application Load Balancer in una Region primaria come origin. Un deployment di standby è in esecuzione in una seconda Region. L'azienda ha configurato un origin group di CloudFront per il failover, ma durante un'interruzione di prova le richieste GET sono passate in failover, mentre le richieste POST e PUT per creare ordini hanno continuato a fallire. Tutti i metodi devono andare in failover. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere altri origin all'origin group, in modo che CloudFront abbia destinazioni aggiuntive per le richieste di scrittura.","Aggiungere una funzione Lambda@Edge che riscriva le richieste POST e PUT in richieste GET con il body nell'URL.","Usare un record di failover Route 53 con health check per entrambe le Region come nome di dominio di un unico origin CloudFront.","Disabilitare il caching per il path dell'API, in modo che CloudFront inoltri le richieste di scrittura all'origin secondario."],"explanation":"L'origin failover di CloudFront si applica solo alle richieste GET, HEAD e OPTIONS, quindi i metodi di scrittura non vanno mai in failover. Usare un record di failover Route 53 come nome di dominio dell'origin fa sì che il DNS risolva verso la Region integra per ogni metodo. Disabilitare il caching non cambia quali richieste sono idonee all'origin failover.","optionExplanations":["Gli origin group supportano un origin primario e uno secondario e comunque non eseguono mai il failover delle richieste POST o PUT.","Riscrivere le scritture come richieste GET viola la semantica dell'API ed espone i body delle richieste negli URL.","Corretto — Il failover di Route 53 dietro un unico hostname di origin sposta tutti i metodi di richiesta verso la Region integra.","Il comportamento di caching non ha relazione con l'idoneità all'origin failover, che esclude i metodi di scrittura."]},
  "1366": {"h":"e19ea671","question":"Una funzione Lambda deve raggiungere un database Amazon RDS in subnet private, quindi è stata collegata al VPC. Lo sviluppatore ha selezionato una sola subnet privata in una singola Availability Zone. Durante un evento che ha colpito la Availability Zone, la funzione non è riuscita a essere eseguita, anche se il deployment RDS Multi-AZ aveva completato con successo il failover. Quale modifica rende la funzione resiliente a questo guasto?","options":["Aumentare la reserved concurrency della funzione, in modo che siano disponibili più ambienti di esecuzione.","Configurare la funzione con subnet private in più Availability Zone.","Rimuovere la configurazione VPC e connettersi al database tramite il suo endpoint pubblico.","Distribuire una copia della funzione in una seconda Region e invocarla se la prima fallisce."],"explanation":"Una funzione Lambda collegata a un VPC viene eseguita nelle subnet con cui è configurata, quindi selezionare subnet in più Availability Zone consente a Lambda di continuare a funzionare se una zona è compromessa. Esporre pubblicamente il database aggirerebbe il problema, ma riduce la sicurezza ed è superfluo.","optionExplanations":["Più concurrency non aiuta quando la zona dell'unica subnet configurata è compromessa.","Corretto — Subnet in più Availability Zone consentono a Lambda di eseguire la funzione nelle zone integre.","Rendere pubblico il database aumenta la superficie di attacco e non è necessario per ottenere la resilienza.","Una copia in una seconda Region aggiunge complessità e comunque non potrebbe raggiungere il database privato nella prima Region."]},
  "1367": {"h":"7d135b49","question":"Centinaia di istanze di microservizi chiamano un servizio di inventario interno. Quando il servizio di inventario ha brevemente rallentato, ogni client ha ritentato le chiamate fallite immediatamente e ripetutamente, il carico sul servizio si è moltiplicato e il servizio non è riuscito a riprendersi per 30 minuti. L'azienda vuole evitare che i retry trasformino un breve degrado in un'interruzione prolungata. Quale combinazione di modifiche lato client dovrebbe raccomandare un solutions architect? (Seleziona DUE)","options":["Configurare i client per ritentare un numero limitato di volte usando un exponential backoff con jitter.","Configurare i client per ritentare le chiamate fallite a un intervallo breve e fisso finché la chiamata non riesce.","Aggiungere una retry quota o un circuit breaker lato client che interrompa i retry quando la maggior parte delle chiamate recenti fallisce.","Rimuovere tutti i retry, in modo che i client restituiscano subito un errore a qualsiasi guasto.","Aggiungere in modo permanente altre istanze al servizio di inventario, in modo che possa assorbire le ondate di retry."],"explanation":"Retry limitati con exponential backoff e jitter distribuiscono i tentativi nel tempo, così i client non ritentano a ondate sincronizzate, e una retry quota o un circuit breaker smette di aggiungere carico di retry quando la dipendenza è chiaramente in errore, lasciandole il margine per riprendersi. Anche rimuovere tutti i retry impedisce le ondate, ma trasforma ogni errore transitorio in un errore visibile all'utente.","optionExplanations":["Corretto — Il backoff con jitter e un limite ai retry evitano ondate di retry sincronizzate, gestendo comunque gli errori transitori.","Retry illimitati a intervallo fisso mantengono il servizio sovraccarico e sincronizzano i client, ed è ciò che ha causato l'interruzione.","Corretto — Interrompere i retry quando la maggior parte delle chiamate fallisce impedisce ai client di moltiplicare il carico su un servizio degradato.","Eliminare i retry riduce la disponibilità, perché i guasti transitori che sarebbero andati a buon fine vengono mostrati agli utenti.","Il sovradimensionamento permanente è costoso e non affronta l'amplificazione causata dai retry."]},
  "1368": {"h":"de92d650","question":"Un workflow di pagamento ha cinque step brevi e viene eseguito circa 2.000 volte al minuto. Uno step addebita la carta del cliente tramite un'API esterna che non supporta le chiavi di idempotenza, quindi lo step non deve mai essere eseguito due volte per lo stesso pagamento. L'azienda vuole orchestrare il workflow con AWS Step Functions. Quale tipo di workflow dovrebbe scegliere un solutions architect?","options":["Express workflow avviati in modo asincrono, perché sono progettati per l'elaborazione di eventi ad alto volume.","Express workflow avviati in modo sincrono, perché restituiscono il risultato direttamente al chiamante.","Standard workflow, perché forniscono un'esecuzione exactly-once di ciascuno step del workflow.","Uno qualsiasi dei due tipi, perché Step Functions garantisce sempre che ogni step venga eseguito esattamente una volta."],"explanation":"Gli Standard workflow usano un modello di esecuzione exactly-once, quindi uno step non idempotente come l'addebito sulla carta non viene eseguito due volte da Step Functions. Gli Express workflow asincroni sono at-least-once e quelli sincroni sono at-most-once, quindi nessuno dei due garantisce un singolo addebito.","optionExplanations":["Gli Express workflow asincroni usano un'esecuzione at-least-once, quindi lo step di addebito potrebbe essere eseguito più di una volta.","Gli Express workflow sincroni sono at-most-once, quindi dopo un guasto uno step potrebbe non essere eseguito affatto.","Corretto — Gli Standard workflow garantiscono un'esecuzione exactly-once, necessaria per un addebito non idempotente.","I due tipi di workflow hanno garanzie di esecuzione diverse, quindi la scelta è rilevante per gli step non idempotenti."]},
  "1369": {"h":"3bf9b3a8","question":"Un'azienda gestisce una piattaforma di ricerca dei log su un dominio Amazon OpenSearch Service con due data node in una sola Availability Zone e nessun dedicated master node. Un'interruzione della zona ha reso il dominio non disponibile per ore. L'azienda ha bisogno che il dominio resti disponibile e continui a servire le ricerche se una Availability Zone si guasta. Quale soluzione soddisfa questi requisiti?","options":["Eseguire snapshot manuali orari su Amazon S3 e ripristinarli in un nuovo dominio dopo un guasto.","Aggiungere altri data node nella stessa Availability Zone e aumentare il numero di primary shard.","Creare un secondo dominio in un'altra Region e inviare ogni voce di log a entrambi i domini dai log shipper.","Abilitare Multi-AZ with Standby su tre zone, con dedicated master node e replica shard."],"explanation":"Distribuire il dominio su tre Availability Zone con dedicated master node e replica shard mantiene un quorum e una copia dei dati nelle zone integre, e Multi-AZ with Standby tiene pronta una capacità di riserva per il guasto di una zona. Gli snapshot consentono solo il recupero dopo un lungo ripristino, non la continuità della disponibilità.","optionExplanations":["Il ripristino da snapshot comporta ore di downtime e la perdita dei dati scritti dopo l'ultimo snapshot.","Più nodi nella stessa zona non proteggono dalla perdita di quella zona.","Una seconda Region con doppia scrittura è molto più complessa e costosa del Multi-AZ nella stessa Region, e le doppie scritture possono divergere.","Corretto — Un deployment su tre zone con dedicated master e repliche mantiene il dominio disponibile anche in caso di guasto di una zona."]},
  "1370": {"h":"68282330","question":"Un'applicazione HR interna usa un'istanza DB Single-AZ di Amazon RDS for MySQL. Una nuova policy richiede la possibilità di ripristinare il database in una seconda Region dopo un disastro regionale con un RPO di minuti; un RTO di diverse ore è accettabile. L'azienda vuole il costo più basso e non vuole alcuna istanza di database in esecuzione nella seconda Region. Quale soluzione soddisfa questi requisiti?","options":["Creare una read replica cross-Region e promuoverla a istanza autonoma se la Region primaria diventa non disponibile.","Abilitare la replica cross-Region degli automated backup ed eseguire un ripristino point-in-time nella seconda Region.","Copiare una volta al giorno uno snapshot DB manuale nella seconda Region usando una funzione Lambda pianificata.","Convertire l'istanza DB in un deployment Multi-AZ, in modo che lo standby possa subentrare in caso di disastro."],"explanation":"La replica cross-Region degli automated backup copia snapshot e log delle transazioni nella seconda Region, consentendo lì un ripristino point-in-time con un RPO di minuti e senza istanze in esecuzione. Una read replica cross-Region soddisferebbe l'RPO, ma richiede un'istanza di database in esecuzione nella seconda Region, cosa che l'azienda non vuole.","optionExplanations":["Una read replica è un'istanza in esecuzione nella seconda Region, che aggiunge costi e viola il vincolo indicato.","Corretto — Gli automated backup replicati supportano il ripristino point-in-time nella seconda Region senza un'istanza sempre attiva.","Gli snapshot giornalieri danno un RPO fino a un giorno, molto peggiore dei minuti richiesti.","Multi-AZ protegge dal guasto di una Availability Zone in una Region, non da un disastro regionale."]},
  "1371": {"h":"f648ae92","question":"Un servizio ordini invia messaggi a una coda Amazon SQS. Un nuovo requisito prevede di allegare a ogni messaggio il documento completo dell'ordine, e alcuni documenti superano la dimensione massima dei messaggi SQS, quindi gli invii falliscono e gli ordini vanno persi. I consumer devono comunque ricevere il documento completo. Quale soluzione soddisfa questi requisiti con il MINOR sforzo di sviluppo?","options":["Memorizzare ogni documento in Amazon S3 e inviarne un riferimento con la SQS Extended Client Library.","Comprimere ogni documento e suddividere quelli troppo grandi su più messaggi SQS che i consumer ricompongono nel codice.","Sostituire la coda con un topic Amazon SNS, in modo che i payload più grandi possano essere consegnati ai consumer.","Scrivere i documenti direttamente in una tabella Amazon RDS e fare in modo che i consumer interroghino la tabella per i nuovi ordini."],"explanation":"La SQS Extended Client Library implementa il pattern claim-check: memorizza i payload di grandi dimensioni in Amazon S3 e invia un piccolo messaggio che vi fa riferimento, e la libreria lato consumer recupera il payload in modo trasparente. Suddividere i messaggi richiede una logica di ricomposizione personalizzata e la gestione di parti fuori ordine o mancanti.","optionExplanations":["Corretto — La Extended Client Library memorizza i payload grandi in S3 e passa i riferimenti tramite SQS con poco codice personalizzato.","Suddividere e ricomporre i messaggi è complesso e fragile, soprattutto con la consegna non ordinata delle code standard.","SNS ha un limite di dimensione dei messaggi simile, quindi i documenti grandi fallirebbero comunque.","Interrogare una tabella di database sostituisce la coda con un design personalizzato e fortemente accoppiato, con maggiore sforzo."]},
  "1372": {"h":"0e3842cf","question":"Un'API di generazione report è basata su Amazon API Gateway e AWS Lambda. I report di grandi dimensioni ora richiedono diversi minuti per essere generati, superando il timeout di integrazione di API Gateway, quindi i client ricevono errori anche se i report vengono infine creati. L'azienda vuole un design affidabile che scali con la domanda. Quale soluzione soddisfa questi requisiti?","options":["Spostare l'API su un Application Load Balancer con un idle timeout molto più lungo e mantenere l'attuale design sincrono.","Aumentare il timeout HTTP del client, in modo che attenda finché la funzione Lambda non restituisce il report.","Restituire subito un ID di job, accodare il lavoro in Amazon SQS, elaborarlo in modo asincrono e lasciare che i client interroghino lo stato.","Suddividere ogni report in parti più piccole e far chiamare ai client l'API una volta per ciascuna parte."],"explanation":"Un pattern asincrono request-reply risponde rapidamente con un ID di job, accoda il lavoro in modo che scali e sopravviva ai guasti, e consente ai client di recuperare il risultato quando è pronto. Modificare il timeout del client non serve, perché API Gateway applica il proprio timeout di integrazione.","optionExplanations":["Mantenere lunghe connessioni sincrone resta fragile, impegna risorse e perde il lavoro se la connessione cade.","Il timeout di integrazione di API Gateway è applicato lato server, quindi un timeout del client più lungo non aiuta.","Corretto — Il pattern asincrono disaccoppia l'elaborazione lunga dalla richiesta e sopravvive a retry e guasti.","Delegare ai client la composizione del report è complesso e comunque non garantisce che ogni parte rientri nel timeout."]},
  "1373": {"h":"d4745274","question":"Un'azienda esegue un servizio interno stateless su una singola istanza EC2 perché la licenza di un fornitore consente una sola copia in esecuzione. Il mese scorso la Availability Zone dell'istanza è stata compromessa e il servizio è rimasto inattivo per diverse ore. L'azienda vuole che il servizio torni disponibile automaticamente in un'altra Availability Zone senza pagare una seconda istanza in esecuzione. Quale soluzione soddisfa questi requisiti?","options":["Abilitare l'automatic recovery di EC2 sull'istanza con un allarme CloudWatch sul system status check.","Tenere una seconda istanza arrestata in un'altra Availability Zone e avviarla manualmente durante un'interruzione della Availability Zone.","Creare ogni giorno un'AMI dell'istanza e copiarla in ogni Availability Zone della Region.","Creare un Auto Scaling group con capacità minima, massima e desiderata pari a uno su più zone."],"explanation":"Un Auto Scaling group di una sola istanza che si estende su più Availability Zone sostituisce automaticamente un'istanza guasta e può avviare la sostituta in una zona integra, mentre è in esecuzione una sola copia alla volta. L'automatic recovery di EC2 riavvia l'istanza su nuovo hardware, ma nella stessa Availability Zone, quindi non aiuta quando quella zona è compromessa.","optionExplanations":["L'automatic recovery mantiene l'istanza nella sua Availability Zone originale, quindi non può recuperare da una compromissione della zona.","Un avvio manuale non è automatico, e il recupero dipende dal fatto che qualcuno si accorga dell'interruzione.","Le AMI sono regionali, e disporre di un'immagine non avvia automaticamente un'istanza sostitutiva.","Corretto — Un Auto Scaling group di una sola istanza su più zone si ripristina da solo in una zona integra con una sola copia in esecuzione."]},
  "1374": {"h":"10c4463b","question":"Un'applicazione Java su istanze EC2 si connette a un'istanza DB Multi-AZ di Amazon RDS for MySQL tramite il suo endpoint DNS. Dopo un failover, RDS ha completato il passaggio in circa un minuto, ma l'applicazione ha continuato a non riuscire a connettersi molto più a lungo, finché le istanze non sono state riavviate. Qual è la soluzione PIÙ probabile?","options":["Sostituire l'endpoint con l'indirizzo IP dell'istanza primaria per evitare le risoluzioni DNS.","Aumentare la classe dell'istanza di database, in modo che i failover si completino più velocemente.","Configurare la JVM dell'applicazione per memorizzare in cache le risoluzioni DNS solo per poco tempo.","Aggiungere una read replica e configurare l'applicazione per connettersi a essa dopo un failover."],"explanation":"Il failover Multi-AZ funziona aggiornando il record DNS dell'endpoint, quindi una JVM che memorizza in cache i risultati DNS a tempo indeterminato continua a connettersi al vecchio primario fino al riavvio. Impostare un TTL basso per la cache DNS consente all'applicazione di rilevare rapidamente il nuovo indirizzo. Inserire un indirizzo IP fisso rende il problema permanente.","optionExplanations":["Un indirizzo IP fisso non segue mai il failover, quindi le connessioni continuerebbero a fallire dopo ogni failover.","Il failover si era già completato in circa un minuto; il ritardo deriva dal client che mantiene in cache il vecchio indirizzo.","Corretto — Un TTL breve della cache DNS consente all'applicazione di risolvere l'endpoint verso il nuovo primario poco dopo il failover.","Una read replica non accetta scritture e non è la destinazione di ripristino di un failover Multi-AZ."]},
  "1375": {"h":"c41b4ba3","question":"Un'azienda invia eventi di business da diverse applicazioni a un event bus Amazon EventBridge personalizzato in una Region. Le regole sul bus attivano funzioni Lambda già distribuite in due Region. L'azienda vuole che l'acquisizione degli eventi passi automaticamente in failover alla seconda Region se EventBridge nella Region primaria è compromesso, senza modificare il codice dei producer durante un incidente. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Usare un global endpoint di EventBridge con un health check Route 53, un event bus secondario e la replica degli eventi abilitata.","Fare in modo che ogni producer invii ogni evento agli event bus di entrambe le Region e deduplicare nei consumer.","Configurare una regola cross-Region che inoltri tutti gli eventi dall'event bus primario a un event bus nella seconda Region per l'elaborazione.","Posizionare una coda Amazon SQS in ogni Region davanti all'event bus e commutare manualmente i producer tra le code."],"explanation":"I global endpoint di EventBridge forniscono ai producer un unico endpoint che passa automaticamente in failover a un event bus secondario in base a un health check Route 53, e la replica degli eventi mantiene il flusso verso entrambe le Region. Una regola di inoltro cross-Region dipende comunque dal fatto che il bus primario riceva gli eventi, quindi non può aiutare quando quel bus è compromesso.","optionExplanations":["Corretto — Un global endpoint fornisce un failover regionale automatico per l'acquisizione degli eventi senza modifiche ai producer.","La doppia pubblicazione richiede modifiche al codice di ogni producer e aggiunge logica di deduplicazione nei consumer.","L'inoltro avviene dal bus primario, quindi se quel bus è compromesso nessun evento raggiunge la seconda Region.","La commutazione manuale è lenta, soggetta a errori e richiede modifiche alla configurazione dei producer durante l'incidente."]},
  "1376": {"h":"f5bbcf3d","question":"Un'azienda di videogiochi usa un cluster Amazon ElastiCache (Redis OSS) come unico archivio per gli inventari dei giocatori, perché l'applicazione richiede letture in microsecondi e le strutture dati di Redis. Dopo il guasto di un nodo, le modifiche recenti agli inventari sono andate perse e i giocatori si sono lamentati. L'azienda ha bisogno di uno storage durevole compatibile con Redis e con prestazioni elevate, senza un database separato. Quale soluzione soddisfa questi requisiti?","options":["Abilitare i backup automatici sul cluster ElastiCache con l'intervallo di backup più breve disponibile.","Migrare i dati su Amazon MemoryDB, che memorizza i dati in modo durevole in un transaction log Multi-AZ.","Aggiungere read replica al cluster ElastiCache in altre due Availability Zone.","Spostare gli inventari dei giocatori su Amazon DynamoDB e usare DynamoDB Accelerator per letture veloci."],"explanation":"Amazon MemoryDB è compatibile con Redis, mantiene i dati in memoria per un accesso rapido e rende persistente ogni scrittura in un transaction log Multi-AZ distribuito, quindi può fungere da database primario durevole. La replica di ElastiCache è asincrona, quindi aggiungere repliche può comunque perdere le scritture più recenti durante un failover.","optionExplanations":["I backup periodici lasciano una finestra di scritture perse tra uno snapshot e l'altro e non rendono durevole la cache.","Corretto — MemoryDB unisce la compatibilità con Redis e la velocità in memoria a uno storage durevole Multi-AZ.","La replica asincrona verso le repliche può comunque perdere le scritture recenti quando un primario si guasta.","DynamoDB con DAX richiederebbe di riscrivere il modello dati e non offre le strutture dati di Redis."]},
  "1377": {"h":"944a8866","question":"Un'azienda esegue un database autogestito su un'istanza EC2. I suoi file di dati sono distribuiti in striping su quattro volumi Amazon EBS. I backup vengono eseguiti con uno snapshot di ciascun volume tramite job pianificati separati, e un ripristino di prova ha prodotto un database corrotto perché gli snapshot erano stati eseguiti in momenti leggermente diversi. L'azienda vuole backup coerenti senza arrestare il database. Quale soluzione soddisfa questi requisiti con il MINOR onere operativo?","options":["Creare snapshot multi-volume dell'istanza, in modo che tutti i volumi collegati vengano acquisiti nello stesso istante.","Pianificare i quattro job di snapshot in modo che partano esattamente nello stesso secondo ogni notte.","Sostituire i quattro volumi in striping con un unico volume più grande ed eseguirne lo snapshot notturno con Amazon Data Lifecycle Manager.","Copiare ogni notte i file di dati su Amazon S3 con uno script ed eseguire il ripristino dai file copiati."],"explanation":"Gli snapshot multi-volume acquisiscono tutti i volumi EBS collegati a un'istanza nello stesso istante, producendo backup crash-consistent sull'intero set in striping senza arrestare il database. Avviare job separati nello stesso secondo non garantisce comunque un unico istante coerente.","optionExplanations":["Corretto — Gli snapshot multi-volume sono crash-consistent su tutti i volumi collegati, il che elimina la corruzione al ripristino.","Job indipendenti partono comunque in momenti leggermente diversi, quindi i volumi restano incoerenti tra loro.","Riprogettare lo storage richiede una migrazione e potrebbe non garantire le prestazioni offerte dallo striping.","Copiare file di database attivi non è coerente e aggiunge script personalizzati e tempi di ripristino lunghi."]},
  "1378": {"h":"9e15fe41","question":"Una piattaforma di ordini pubblica eventi su un topic Amazon SNS e un servizio di spedizione li consuma tramite una coda Amazon SQS sottoscritta. Il servizio di spedizione deve elaborare gli eventi di ciascun ordine esattamente nell'ordine in cui sono stati pubblicati, e gli eventi duplicati pubblicati durante i retry dei producer devono essere scartati. Gli eventi di ordini diversi possono essere elaborati in parallelo. Quale soluzione soddisfa questi requisiti?","options":["Usare un topic SNS standard con una coda SQS standard e ordinare gli eventi per timestamp nel servizio di spedizione.","Usare un topic SNS standard con una coda SQS FIFO, in modo che la coda imponga l'ordinamento degli eventi in ingresso.","Usare un topic SNS FIFO con una coda SQS FIFO, l'ID dell'ordine come message group ID e la deduplicazione abilitata.","Usare un Kinesis data stream al posto di SNS ed elaborare ogni shard con un'unica funzione Lambda."],"explanation":"I topic SNS FIFO consegnano i messaggi in ordine e li deduplicano, e possono effettuare il fan-out solo verso code SQS FIFO, che preservano tale ordine per message group ID. Un topic SNS standard non può avere come sottoscrittore una coda FIFO e non garantisce l'ordinamento, quindi la sola coda FIFO non basta.","optionExplanations":["Topic e code standard offrono un ordinamento best-effort e una consegna at-least-once, e l'ordinamento per timestamp non può gestire eventi tardivi o duplicati.","Le code SQS FIFO possono sottoscriversi solo a topic SNS FIFO, e un topic standard comunque non preserverebbe l'ordinamento.","Corretto — SNS FIFO più SQS FIFO con l'ID dell'ordine come group ID fornisce ordinamento per ordine, deduplicazione e parallelismo tra ordini.","Kinesis non deduplica i retry dei producer e sostituisce inutilmente il design di fan-out esistente."]},
  "1379": {"h":"82bf76fe","question":"Un'azienda sta migrando un'applicazione monolitica di gestione ordini verso i microservizi, una funzionalità alla volta. Il monolite gira su istanze EC2 dietro un Application Load Balancer, e i client devono continuare a usare lo stesso hostname. Il nuovo servizio dei resi gira su Amazon ECS, e l'azienda vuole spostarvi gradualmente il traffico dei resi e tornare indietro istantaneamente se gli errori aumentano. Quale soluzione soddisfa questi requisiti?","options":["Creare un nuovo hostname per il servizio dei resi e chiedere ai client di passarvi quando sono pronti.","Aggiungere una listener rule per il path dei resi che inoltri a target group pesati per il monolite e per il nuovo servizio.","Distribuire il servizio dei resi all'interno delle istanze del monolite e abilitarlo con una variabile d'ambiente.","Usare record weighted di Route 53 per ripartire il traffico dell'intero hostname tra il monolite e il nuovo servizio dei resi."],"explanation":"Una listener rule dell'ALB può inoltrare un path a più target group con dei pesi, quindi il traffico dei resi può essere spostato gradualmente sul nuovo servizio e riportato indietro istantaneamente modificando i pesi, mentre tutti gli altri path continuano a raggiungere il monolite. Il weighting di Route 53 ripartirebbe tutti i path, inviando traffico non relativo ai resi a un servizio che non può gestirlo, e il caching DNS rallenta il rollback.","optionExplanations":["Un nuovo hostname viola il requisito che i client continuino a usare lo stesso hostname.","Corretto — Target group pesati su una regola basata sul path consentono una migrazione graduale e un rollback immediato per una singola funzionalità.","Eseguire il nuovo servizio all'interno del monolite li mantiene accoppiati e vanifica l'obiettivo della migrazione.","Il weighting DNS si applica all'intero hostname, non a un singolo path, e il caching DNS dei client ritarda il rollback."]},
  "1380": {"h":"995ed545","question":"Un'azienda sta preparando un warm standby di un'applicazione ECS su Fargate in una seconda Region. L'applicazione scarica le immagini dei container da Amazon ECR e legge le credenziali del database da AWS Secrets Manager, entrambi presenti solo nella Region primaria. Un test di DR ha mostrato che i task nella seconda Region non riuscivano ad avviarsi mentre la Region primaria era simulata come non disponibile. Quale combinazione di passaggi elimina queste dipendenze regionali? (Seleziona DUE)","options":["Configurare la replica cross-Region di ECR, in modo che le immagini siano disponibili nel registry della seconda Region.","Memorizzare le credenziali del database nella task definition come variabili d'ambiente in chiaro.","Replicare il secret nella seconda Region con Secrets Manager e fare riferimento alla replica in quella Region.","Configurare una connessione VPC peering affinché i task della seconda Region possano raggiungere ECR e Secrets Manager della Region primaria.","Compilare le immagini dei container all'avvio di ogni task da un repository di sorgenti invece di scaricarle da ECR."],"explanation":"La replica di ECR e i secret replica di Secrets Manager collocano sia le immagini sia le credenziali nella seconda Region, così i task possono avviarsi lì senza chiamare alcun servizio nella Region primaria. Il peering per raggiungere gli endpoint della Region primaria mantiene proprio la dipendenza che ha fatto fallire il test di DR.","optionExplanations":["Corretto — Le immagini replicate consentono alla seconda Region di scaricare i container dal proprio registry.","Credenziali in chiaro nelle task definition non sono sicure e non rappresentano un design di DR valido.","Corretto — Un secret replica è leggibile nella seconda Region anche quando la Region primaria non è disponibile.","La connessione ai servizi della Region primaria fallisce comunque quando quella Region non è disponibile.","Compilare le immagini all'avvio è lento e fragile, e il repository di sorgenti potrebbe a sua volta dipendere dalla Region primaria."]},
  "1381": {"h":"e04ff572","question":"Un'azienda esegue un'applicazione in subnet private su tre Availability Zone. Tutte le istanze raggiungono internet tramite un unico NAT gateway nella prima zona, e raggiungono AWS Systems Manager e Amazon SQS tramite interface VPC endpoint creati solo in quella stessa zona. Quando la prima zona è stata compromessa, anche le istanze nelle altre zone hanno perso la connettività. Quale combinazione di passaggi elimina questi single point of failure? (Seleziona DUE)","options":["Creare un NAT gateway in ogni Availability Zone e instradare le subnet private di ciascuna zona verso il NAT gateway della stessa zona.","Sostituire il NAT gateway con una NAT instance in un Auto Scaling group di una sola istanza.","Aggiungere per ogni interface VPC endpoint un'interfaccia di rete dell'endpoint in una subnet di ciascuna Availability Zone.","Rimuovere gli interface endpoint e inviare tutto il traffico verso i servizi AWS tramite l'internet gateway.","Spostare tutte le istanze nella prima Availability Zone, in modo che condividano le stesse risorse di rete."],"explanation":"I NAT gateway e le interfacce di rete degli interface endpoint sono risorse zonali, quindi ogni Availability Zone ha bisogno del proprio NAT gateway e della propria interfaccia di endpoint, con route table che indirizzano il traffico all'interno della stessa zona. Una singola NAT instance resta un single point of failure e aggiunge lavoro di gestione.","optionExplanations":["Corretto — NAT gateway locali a ciascuna zona mantengono funzionante l'uscita verso internet quando un'altra zona si guasta.","Una singola NAT instance è comunque un single point of failure e richiede patching e scaling.","Corretto — Interfacce di endpoint in ogni zona mantengono disponibile l'accesso privato ai servizi AWS durante il guasto di una zona.","Le subnet private non hanno una route diretta verso un internet gateway, e rimuovere gli endpoint riduce la sicurezza senza risolvere la resilienza.","Concentrare tutto in una sola zona aumenta, anziché eliminare, l'impatto del guasto di una zona."]},
  "1382": {"h":"8bb7b60b","question":"Un'azienda esegue un'applicazione web active-passive in due Region con record di failover Route 53. I record sono record A con un TTL di 24 ore che puntano a indirizzi Elastic IP, e l'health check usa un intervallo di 30 secondi con una soglia di errore elevata. In una recente interruzione, molti utenti hanno continuato a raggiungere la Region guasta per ore. Quale combinazione di passaggi rende effettivo il failover più rapidamente? (Seleziona DUE)","options":["Aumentare il TTL dei record di failover, in modo che i resolver interroghino Route 53 meno spesso durante un'interruzione.","Ridurre il TTL dei record di failover a un valore breve, ad esempio 60 secondi.","Cambiare i record in una routing policy simple che restituisca gli indirizzi IP di entrambe le Region.","Configurare l'health check con l'intervallo veloce e una soglia di errore più bassa.","Disabilitare l'health check ed eseguire il failover manualmente modificando il record primario durante un incidente."],"explanation":"Il tempo di failover è all'incirca il tempo di rilevamento dell'health check più il tempo per cui i resolver mantengono in cache le risposte, quindi un TTL breve e un rilevamento più rapido da parte dell'health check lo riducono entrambi. Un TTL di 24 ore consente ai resolver di continuare a restituire l'indirizzo della Region guasta molto tempo dopo che Route 53 ha cambiato la propria risposta.","optionExplanations":["Un TTL più lungo fa sì che i resolver mantengano in cache l'indirizzo della Region guasta ancora più a lungo, ritardando il failover.","Corretto — Un TTL breve limita il tempo per cui i resolver continuano a restituire il vecchio indirizzo dopo il failover.","Il routing simple non prevede failover basato sull'integrità e continuerebbe a inviare utenti alla Region guasta.","Corretto — Un intervallo più breve e una soglia più bassa rilevano prima il guasto, quindi Route 53 cambia prima le risposte.","Le modifiche manuali ai record sono più lente e soggette a errori, e il TTL lungo ritarderebbe comunque la modifica."]},
  "1383": {"h":"a09a80a1","question":"Un sito di notizie gira su istanze EC2 dietro un Application Load Balancer con Amazon CloudFront davanti. Durante un picco di traffico, una funzionalità non critica di raccomandazioni personalizzate ha sovraccaricato il database e l'intero sito ha restituito errori. L'azienda vuole che il sito degradi in modo controllato: gli articoli principali devono restare leggibili anche se l'origin è in difficoltà, e gli operatori devono poter disattivare le funzionalità non critiche in pochi secondi senza un deployment. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Aumentare l'idle timeout dell'ALB, in modo che le richieste lente verso l'origin sovraccarico possano infine completarsi.","Configurare l'origin per inviare header Cache-Control con stale-if-error, così CloudFront serve gli articoli in cache quando l'origin fallisce.","Disabilitare il caching di CloudFront per gli articoli, in modo che i lettori ottengano sempre l'ultima versione dall'origin.","Usare feature flag di AWS AppConfig verificati dall'applicazione per disattivare a runtime la funzionalità di raccomandazioni.","Aggiungere un'azione di Auto Scaling pianificata che raddoppi la flotta ogni mattina nell'orario di maggior traffico."],"explanation":"La direttiva stale-if-error consente a CloudFront di continuare a servire gli articoli in cache quando l'origin restituisce errori, e i feature flag di AppConfig permettono agli operatori di disattivare istantaneamente le raccomandazioni senza un nuovo deployment. Timeout più lunghi mantengono solo più connessioni aperte su un origin già sovraccarico.","optionExplanations":["Timeout più lunghi impegnano più risorse su un origin sovraccarico e peggiorano il guasto.","Corretto — Servire articoli in cache non aggiornati in caso di errori dell'origin mantiene leggibili i contenuti principali durante il picco.","Disabilitare il caching invia ogni lettura all'origin e aumenta il carico durante un picco.","Corretto — I feature flag a runtime consentono agli operatori di disattivare la funzionalità non critica in pochi secondi senza un deployment.","Un'azione pianificata non gestisce picchi imprevisti né consente di rinunciare alle funzionalità non critiche."]},
  "1384": {"h":"5394e2a1","question":"Un'azienda sta scomponendo un monolite di gestione ordini in servizi. Oggi il monolite, dopo aver salvato un ordine, chiama in modo sincrono i servizi di fatturazione, fidelizzazione ed email, quindi un'interruzione di uno qualsiasi di essi fa fallire l'inserimento dell'ordine. L'azienda pubblicherà invece un evento OrderPlaced su un event bus personalizzato di Amazon EventBridge. Gli ordini devono essere accettati anche quando un consumer è inattivo per ore, e gli eventi che non possono essere consegnati non devono andare persi silenziosamente. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Creare una regola per ogni consumer che abbia come target una coda Amazon SQS di proprietà di quel consumer, che elabora i messaggi al proprio ritmo.","Creare un'unica regola il cui target sia una funzione Lambda che chiama in sequenza e in modo sincrono tutti e tre i servizi.","Configurare una retry policy e una dead-letter queue SQS su ogni target delle regole per acquisire gli eventi che non possono essere consegnati.","Mantenere le chiamate sincrone nel monolite e aggiungere una regola EventBridge solo per il servizio email.","Configurare ogni consumer per interrogare direttamente l'event bus ogni minuto alla ricerca di nuovi eventi OrderPlaced."],"explanation":"Instradare gli eventi verso una coda SQS durevole per ciascun consumer consente a ogni servizio di restare offline per ore e recuperare in seguito, mentre il percorso degli ordini dipende solo da EventBridge. Una retry policy più una dead-letter queue su ogni target conserva gli eventi che EventBridge non riesce a consegnare invece di scartarli. Un unico target Lambda che chiama tutti i servizi ricrea l'accoppiamento, perché un servizio guasto blocca gli altri.","optionExplanations":["Corretto — Code dedicate a ciascun consumer accumulano gli eventi in modo durevole, così ogni servizio può essere non disponibile senza influire sugli ordini.","Un'unica funzione che chiama in sequenza ogni servizio li mantiene fortemente accoppiati, quindi un'interruzione influisce su tutte le consegne.","Corretto — I retry sui target e una dead-letter queue preservano gli eventi che non possono essere consegnati.","Mantenere le chiamate sincrone per fatturazione e fidelizzazione significa che le loro interruzioni bloccano ancora l'inserimento degli ordini.","EventBridge è un router di tipo push; i consumer non possono interrogare un event bus per ottenere gli eventi."]},
  "1385": {"h":"13507ace","question":"Un'azienda manifatturiera sta dismettendo i propri file server on-premises. Le sue applicazioni Linux on-premises leggono e scrivono file tramite NFS, non possono essere modificate e necessitano di un accesso a bassa latenza ai file usati di recente. I file devono essere memorizzati come oggetti nativi in Amazon S3, in modo che i servizi di analisi nel cloud possano elaborarli. Quale soluzione soddisfa questi requisiti?","options":["Distribuire Amazon S3 File Gateway on-premises con una share NFS.","Montare Amazon EFS on-premises tramite Direct Connect.","Mantenere un NAS locale e usare AWS DataSync per copiarne i file su Amazon S3 ogni ora.","Distribuire AWS Storage Gateway Volume Gateway in modalità cached con volumi iSCSI."],"explanation":"Amazon S3 File Gateway presenta una share NFS on-premises, memorizza ogni file come oggetto S3 nativo e mantiene i dati usati di recente in una cache locale per un accesso a bassa latenza. Volume Gateway è allettante perché anch'esso usa una cache locale, ma espone volumi a blocchi iSCSI, non file NFS, e i suoi dati non sono leggibili come singoli oggetti S3.","optionExplanations":["Corretto — il gateway scrive i file come oggetti S3 e serve i dati più usati dalla propria cache locale tramite NFS.","EFS non memorizza i file come oggetti S3, e ogni accesso attraversa la rete senza una cache locale.","L'azienda sta dismettendo i propri file server, quindi mantenere un NAS on-premises non soddisfa il requisito.","Volume Gateway fornisce storage a blocchi tramite iSCSI, non NFS, e i dati non sono accessibili come singoli oggetti S3."]},
  "1386": {"h":"725e4f12","question":"Un'azienda SaaS invia eventi di migliaia di tenant tramite Amazon Data Firehose ad Amazon S3, dove gli oggetti sono organizzati solo per orario di arrivo. La maggior parte delle query Amazon Athena analizza un singolo tenant, ma ogni query esegue la scansione dei dati di tutti i tenant ed è lenta. L'azienda vuole i dati organizzati in base all'ID del tenant contenuto in ogni record, senza scrivere né gestire codice personalizzato. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere una funzione Lambda che copi ogni oggetto consegnato in prefissi distinti per tenant.","Abilitare il dynamic partitioning in Firehose usando l'ID del tenant estratto da ogni record.","Configurare la partition projection di Athena sulla tabella esistente usando l'ID del tenant.","Ridurre il buffer interval di Firehose, in modo che vengano consegnati più spesso oggetti più piccoli."],"explanation":"Il dynamic partitioning di Firehose estrae l'ID del tenant da ogni record e scrive i dati in prefissi S3 distinti per tenant, così Athena può escludere le partizioni non necessarie e leggere solo i dati di un tenant. La partition projection è allettante, ma descrive solo come i prefissi esistenti corrispondono alle partizioni; non può riorganizzare dati memorizzati solo per orario di arrivo.","optionExplanations":["Richiede codice personalizzato da sviluppare e gestire, e memorizza i dati due volte.","Corretto — Firehose scrive i record di ogni tenant nel suo prefisso, così Athena legge solo la partizione corrispondente.","La projection mappa solo prefissi esistenti a partizioni; gli oggetti non sono organizzati per tenant, quindi non viene escluso nulla.","Oggetti più piccoli e più frequenti non organizzano i dati per tenant e aggiungono overhead per file alle query."]},
  "1387": {"h":"20bad5a5","question":"Un'azienda di logistica invia in streaming eventi GPS da centinaia di migliaia di camion ad Amazon Kinesis Data Streams. Un'applicazione consumer deve elaborare gli eventi di ciascun camion esattamente nell'ordine in cui sono stati prodotti, e il carico deve restare distribuito uniformemente su molti shard. Attualmente i producer usano una partition key casuale per ogni record. Cosa dovrebbe modificare un solutions architect?","options":["Mantenere le chiavi casuali e fare in modo che il consumer ordini i record per timestamp su tutti gli shard.","Ridurre lo stream a un unico shard.","Usare l'ID del camion come partition key per ogni record.","Sostituire lo stream con una coda Amazon SQS standard e riordinare gli eventi per timestamp."],"explanation":"Kinesis Data Streams garantisce l'ordinamento solo all'interno di uno shard, e tutti i record con la stessa partition key finiscono nello stesso shard, quindi usare l'ID del camion mantiene in ordine gli eventi di ciascun camion, mentre l'elevato numero di camion distribuisce il carico sugli shard. Ridurre lo stream a un unico shard garantirebbe anch'esso l'ordine, ma limita il throughput dello stream molto al di sotto di quanto produce la flotta.","optionExplanations":["Il riordinamento tra shard è complesso e non può garantire l'ordine quando i record arrivano in ritardo su shard diversi.","Un solo shard non può assorbire il throughput dell'intera flotta, quindi i producer subirebbero throttling.","Corretto — i record con la stessa partition key sono ordinati all'interno di uno shard, e molti ID di camion distinti mantengono bilanciati gli shard.","Le code standard offrono solo un ordinamento best-effort, quindi l'ordine per camion non è garantito."]},
  "1388": {"h":"039fcc48","question":"Una piattaforma di pagamento pubblica eventi di transazione su una coda Amazon SQS FIFO. Gli eventi dello stesso conto devono essere elaborati in ordine, mentre gli eventi di conti diversi possono essere elaborati in parallelo. Attualmente tutti i messaggi condividono un unico message group ID, e il throughput è molto inferiore alle diverse migliaia di messaggi al secondo di cui la piattaforma ha ora bisogno. Quale combinazione di azioni aumenta il throughput preservando l'ordinamento per conto? (Seleziona DUE)","options":["Impostare il message group ID sull'ID del conto, in modo che conti diversi possano essere consumati in parallelo.","Passare a una coda SQS standard e rimuovere i messaggi duplicati nel codice del consumer.","Assegnare un deduplication ID univoco a ogni messaggio mantenendo l'unico message group.","Abilitare la modalità high throughput sulla coda FIFO, in modo che possa scalare su molti message group.","Aumentare il visibility timeout, in modo che i consumer abbiano più tempo per elaborare ogni messaggio."],"explanation":"Le code FIFO preservano l'ordine per message group, quindi usare l'ID del conto come group ID consente ai consumer di elaborare conti diversi in parallelo mantenendo in ordine ciascun conto. Abilitare la modalità high throughput per la coda FIFO aumenta il throughput che la coda può sostenere su molti gruppi. Passare a una coda standard consentirebbe di scalare, ma rinuncia alla garanzia di ordinamento.","optionExplanations":["Corretto — l'ordinamento è imposto per message group, quindi molti gruppi consentono un'elaborazione parallela senza compromettere l'ordine per conto.","Le code standard non garantiscono l'ordine, il che viola il requisito di ordinamento per conto.","I deduplication ID influiscono solo sul rilevamento dei duplicati; un unico gruppo impone comunque un'elaborazione strettamente seriale.","Corretto — la FIFO high throughput aumenta la frequenza di messaggi per coda quando il traffico è distribuito su più message group.","Un visibility timeout più lungo non aggiunge parallelismo e può ritardare i retry dei messaggi falliti."]},
  "1389": {"h":"2335408f","question":"L'istanza DB Amazon RDS for PostgreSQL di un'azienda di e-commerce funziona con un utilizzo della CPU costantemente elevato. Performance Insights mostra che una query eseguita di frequente, che filtra una tabella degli ordini molto grande per customer_id e order_date, è responsabile della maggior parte del carico del database ed esegue scansioni sequenziali complete. L'azienda vuole ridurre il carico al costo più basso. Quale azione è la PIÙ efficace?","options":["Scalare l'istanza DB a una classe di istanza più grande con più vCPU e memoria.","Instradare questa query verso una nuova read replica.","Cambiare lo storage da gp3 a volumi Provisioned IOPS io2 con più IOPS.","Creare un indice composito su customer_id e order_date."],"explanation":"Un indice composito sulle colonne di filtro consente a PostgreSQL di leggere solo le righe corrispondenti invece di eseguire la scansione dell'intera tabella, eliminando la principale fonte di carico della CPU senza costi infrastrutturali aggiuntivi. Una classe di istanza più grande aggiungerebbe capacità, ma costa di più e le scansioni complete inefficienti continuerebbero a crescere con la tabella.","optionExplanations":["Aumenta i costi e nasconde soltanto la query inefficiente, che continua a eseguire la scansione dell'intera tabella.","La replica eseguirebbe le stesse scansioni costose e aggiunge il costo di un'altra istanza.","Il collo di bottiglia è la CPU impegnata dalla scansione, non l'I/O dello storage, quindi più IOPS non ridurrebbero il carico.","Corretto — l'indice trasforma le scansioni complete in ricerche mirate, riducendo il carico della CPU senza costi infrastrutturali aggiuntivi."]},
  "1390": {"h":"1457fe8f","question":"Il cluster Amazon Redshift di un'azienda esegue join tra una grande fact table delle vendite e una grande tabella dei clienti su customer_id, e la maggior parte delle query filtra le vendite su un intervallo recente di valori di sale_date. I query plan mostrano grandi volumi di dati redistribuiti tra i nodi durante i join, e le query leggono i blocchi di tutte le date. Quale combinazione di modifiche al design delle tabelle migliora le prestazioni delle query? (Seleziona DUE)","options":["Usare la distribuzione ALL per la grande fact table delle vendite, in modo che ogni nodo ne contenga una copia completa.","Usare la distribuzione KEY su customer_id sia per la tabella delle vendite sia per quella dei clienti.","Definire sale_date come sort key della tabella delle vendite, in modo che le zone map possano saltare i blocchi non necessari.","Usare la distribuzione EVEN per entrambe le tabelle, in modo che le righe siano distribuite uniformemente tra le slice.","Abilitare il concurrency scaling per la coda di workload management usata da queste query."],"explanation":"Distribuire entrambe le tabelle sulla colonna di join colloca le righe corrispondenti sulle stesse slice, così i join non devono più redistribuire i dati. Rendere sale_date la sort key consente a Redshift di usare le zone map per saltare i blocchi al di fuori dell'intervallo di date richiesto. La distribuzione ALL evita la redistribuzione solo per le piccole dimension table; copiare una grande fact table su ogni nodo spreca storage e rallenta i caricamenti.","optionExplanations":["La distribuzione ALL è adatta alle piccole dimension table; per una grande fact table moltiplica lo storage e i tempi di caricamento.","Corretto — collocare le righe sulla chiave di join elimina la fase di redistribuzione dei dati durante i join.","Corretto — i dati ordinati consentono ai filtri per intervallo su sale_date di saltare i blocchi che contengono altre date.","La distribuzione EVEN non colloca insieme le chiavi di join, quindi i join redistribuirebbero comunque i dati.","Il concurrency scaling aggiunge capacità per le query in coda, ma non corregge un piano inefficiente della singola query."]},
  "1391": {"h":"4db65721","question":"Una pipeline IoT scrive dati su Amazon S3 in formato Apache Parquet, partizionati per data. Un job di streaming scrive un nuovo file ogni pochi secondi, quindi ogni partizione contiene centinaia di migliaia di file da pochi kilobyte ciascuno. Le query Amazon Athena che leggono un singolo giorno sono lente, soprattutto a causa dell'overhead di elencazione e apertura dei file. Cosa dovrebbe fare un solutions architect per migliorare le prestazioni delle query?","options":["Compattare periodicamente i file piccoli di ogni partizione in un numero molto minore di file più grandi.","Aggiungere colonne di partizione per ora e minuto, in modo che ogni query legga una partizione più piccola.","Convertire i file da Parquet a CSV compresso con gzip per ridurre la quantità di dati letti.","Acquistare capacità provisioned di Athena, in modo che le query vengano eseguite su risorse di calcolo dedicate."],"explanation":"Athena offre le prestazioni migliori quando i dati sono memorizzati in meno file e più grandi, quindi compattare periodicamente i file piccoli di ogni partizione elimina gran parte dell'overhead di elencazione e apertura per file. Aggiungere partizioni per ora e minuto è allettante, ma crea ancora più partizioni con file ancora più piccoli e peggiora il problema.","optionExplanations":["Corretto — meno file Parquet e più grandi riducono notevolmente l'overhead per file nelle query Athena.","Partizioni più granulari producono ancora più file minuscoli e più metadati di partizione da elaborare.","Il CSV, basato su righe, è meno efficiente per l'analisi rispetto al Parquet colonnare e non riduce il numero di file.","La capacità dedicata aiuta con la concorrenza, non con l'overhead di apertura di centinaia di migliaia di file minuscoli."]},
  "1392": {"h":"0820275c","question":"Una startup del settore media consente agli utenti di caricare video in un bucket Amazon S3. Ogni video deve essere riprodotto in modo fluido su telefoni, tablet e smart TV tramite streaming adaptive bitrate, e gli spettatori di tutto il mondo hanno bisogno di un avvio rapido della riproduzione. L'azienda non vuole gestire alcun server di transcodifica. Quale combinazione di passaggi soddisfa questi requisiti? (Seleziona DUE)","options":["Eseguire FFmpeg su un Auto Scaling group EC2 che prende i job di transcodifica da una coda SQS.","Abilitare S3 Transfer Acceleration e fornire agli spettatori l'endpoint accelerato per la riproduzione.","Transcodificare ogni video caricato con AWS Elemental MediaConvert in rendition HLS a più bitrate.","Memorizzare i video su Amazon EFS e trasmetterli in streaming da web server EC2 in una sola Region.","Distribuire l'output HLS memorizzato in Amazon S3 tramite una distribuzione Amazon CloudFront."],"explanation":"AWS Elemental MediaConvert è un servizio gestito di transcodifica basata su file che può produrre rendition HLS adaptive bitrate quando viene caricato un video. Amazon CloudFront memorizza poi in cache i segmenti HLS nelle edge location vicine agli spettatori per un avvio rapido. S3 Transfer Acceleration è pensato per velocizzare i trasferimenti da e verso un bucket su lunghe distanze, ma non memorizza contenuti in cache nell'edge né crea rendition a diversi bitrate.","optionExplanations":["Funziona, ma richiede all'azienda di gestire e aggiornare server di transcodifica, cosa che vuole evitare.","Transfer Acceleration non memorizza contenuti in cache nell'edge, quindi ogni visualizzazione viene servita dal bucket.","Corretto — MediaConvert è completamente gestito e produce gli output adaptive bitrate senza server da gestire.","Servire da una sola Region comporta un avvio lento per gli spettatori lontani e aggiunge server da gestire.","Corretto — CloudFront memorizza in cache i segmenti video nelle edge location, così gli spettatori di tutto il mondo avviano rapidamente la riproduzione."]},
  "1393": {"h":"5174edd2","question":"Un'azienda esegue task worker su Amazon ECS con AWS Fargate che elaborano messaggi da una coda Amazon SQS. Il servizio scala in base all'utilizzo medio della CPU, ma i task trascorrono la maggior parte del tempo in attesa di un'API di terze parti, quindi la CPU resta bassa mentre il backlog della coda cresce durante picchi imprevedibili. L'azienda vuole che il numero di task segua la quantità di lavoro in attesa. Quale soluzione soddisfa questi requisiti?","options":["Abbassare il target value della scaling policy basata sull'utilizzo della CPU a una percentuale molto più bassa.","Usare il target tracking su una metrica personalizzata pari ai messaggi visibili in coda divisi per i task in esecuzione.","Aggiungere azioni di scaling pianificate che aumentino il numero di task negli orari di maggior carico previsti.","Aumentare CPU e memoria nella task definition, in modo che ogni task lavori più velocemente."],"explanation":"Scalare in base al backlog per task (messaggi visibili divisi per task in esecuzione) lega direttamente il numero di task al lavoro in attesa nella coda, che è il segnale corretto per consumer vincolati dall'I/O. Abbassare il target della CPU è allettante, ma la CPU si muove appena quando i task attendono un'API esterna, quindi non seguirebbe comunque il backlog.","optionExplanations":["La CPU resta bassa per i task vincolati dall'I/O, quindi la policy non reagirebbe comunque a un backlog in crescita.","Corretto — il backlog per task riflette direttamente il lavoro in attesa, quindi il servizio scala in aumento e in diminuzione insieme alla coda.","I picchi sono imprevedibili, quindi pianificazioni fisse li mancherebbero o sovradimensionerebbero le risorse.","I task attendono un'API esterna; task più grandi non aggiungono il parallelismo necessario per svuotare la coda."]},
  "1394": {"h":"d114ebc0","question":"Un'azienda esegue un'applicazione web su Amazon EKS con managed node group. Durante le vendite lampo le richieste aumentano nel giro di minuti, ma il numero di pod resta fisso. Quando gli operatori aggiungono pod manualmente, molti restano in stato Pending perché nessun nodo ha capacità libera. L'azienda vuole che pod e nodi scalino automaticamente e rapidamente, con nodi dimensionati per i pod in attesa. Quale combinazione di azioni soddisfa questi requisiti? (Seleziona DUE)","options":["Configurare il Kubernetes Horizontal Pod Autoscaler per scalare il deployment in base alle metriche delle risorse.","Configurare il Vertical Pod Autoscaler per aumentare le request di CPU e memoria dei pod.","Aumentare la dimensione massima dei managed node group senza aggiungere alcun autoscaler.","Installare Karpenter, in modo che vengano avviati rapidamente nodi di dimensioni adeguate per i pod in attesa.","Sostituire i node group con poche istanze molto grandi per ospitare più pod per nodo."],"explanation":"L'Horizontal Pod Autoscaler aggiunge repliche dei pod quando il carico aumenta, e Karpenter rileva i pod non schedulabili e avvia rapidamente nodi con tipi di istanza adatti a ospitarli. Il Vertical Pod Autoscaler modifica solo le request di risorse dei pod esistenti, il che non aggiungerebbe repliche e potrebbe lasciare ancora più pod non schedulabili.","optionExplanations":["Corretto — l'HPA aggiunge automaticamente repliche dei pod man mano che il carico sul deployment cresce.","Il VPA ridimensiona i pod esistenti invece di aggiungere repliche e non fornisce nuovi nodi.","Un massimo più alto consente solo la crescita; nulla aggiungerebbe effettivamente nodi quando ci sono pod in attesa.","Corretto — Karpenter fornisce istanze corrispondenti ai requisiti dei pod in attesa pochi secondi dopo averli rilevati.","È una modifica di capacità fissa che non scala con la domanda né dimensiona correttamente i nodi."]},
  "1395": {"h":"b1a1143c","question":"Una coda Amazon SQS è la event source di una funzione AWS Lambda che chiama un'API di un partner. L'API del partner può gestire solo un numero limitato di richieste concorrenti. Durante i backlog di grandi dimensioni Lambda è scalata fino a centinaia di invocazioni concorrenti, quindi il team ha impostato la reserved concurrency sulla funzione, ma ora molte invocazioni subiscono throttling e i messaggi finiscono nella dead-letter queue. Quale soluzione limita la concurrency senza questi errori di throttling?","options":["Aumentare il visibility timeout della coda e il maximum receive count della redrive policy.","Configurare sulla funzione una provisioned concurrency pari al limite dell'API del partner.","Impostare la maximum concurrency sull'event source mapping SQS in modo che corrisponda al limite dell'API del partner.","Sostituire la coda con un topic Amazon SNS che invochi la funzione in modo asincrono."],"explanation":"La maximum concurrency sull'event source mapping SQS limita il numero di invocazioni concorrenti avviate dal poller, quindi i messaggi restano semplicemente in attesa nella coda invece di subire throttling ed essere ritentati fino alla dead-letter queue. Un visibility timeout più lungo rallenta la velocità con cui i messaggi falliscono, ma con la sola reserved concurrency il poller continua a invocare la funzione e il throttling si verifica comunque.","optionExplanations":["Ritarda soltanto i fallimenti; il poller continua a invocare oltre la reserved concurrency e a subire throttling.","La provisioned concurrency pre-inizializza gli ambienti, ma non limita quanto la funzione può scalare.","Corretto — l'event source mapping smette di invocare oltre il limite, quindi i messaggi restano in coda invece di subire throttling.","SNS non accumula il lavoro come una coda, e le invocazioni asincrone scalerebbero comunque oltre il limite."]},
  "1396": {"h":"27511b7b","question":"Una funzione AWS Lambda consuma record da uno stream Amazon Kinesis Data Streams. La metrica IteratorAge continua ad aumentare perché ogni record richiede una chiamata lenta a un servizio a valle, mentre l'account è lontano dal proprio limite di concurrency Lambda. L'ordinamento è richiesto solo per partition key. L'azienda vuole aumentare il throughput di elaborazione senza eseguire il resharding dello stream. Cosa dovrebbe fare un solutions architect?","options":["Registrare la funzione come consumer enhanced fan-out dello stream.","Aumentare il periodo di conservazione dei dati dello stream, in modo che i record non vadano persi.","Aumentare il timeout della funzione.","Aumentare il parallelization factor dell'event source mapping."],"explanation":"Aumentare il parallelization factor sull'event source mapping consente a Lambda di elaborare ogni shard con più invocazioni concorrenti, preservando comunque l'ordine per partition key. L'enhanced fan-out è allettante, ma aumenta il throughput di lettura per consumer; qui il collo di bottiglia è il tempo di elaborazione, e senza un parallelization factor più alto ogni shard ha comunque una sola invocazione alla volta.","optionExplanations":["Un throughput di lettura dedicato non aiuta quando la parte lenta è l'elaborazione di ciascun record.","Una conservazione più lunga evita la perdita di dati, ma non velocizza l'elaborazione né riduce l'iterator age.","Un timeout più lungo non aggiunge parallelismo, quindi l'elaborazione resterebbe altrettanto lenta.","Corretto — più batch concorrenti per shard aumentano il throughput mantenendo l'ordine per partition key."]},
  "1397": {"h":"1ca6385f","question":"Un'azienda dispone di un AWS Transit Gateway in us-east-1 e di un altro in eu-west-1, ciascuno con decine di VPC collegati. Le applicazioni in molti VPC di entrambe le Region ora devono comunicare tra loro. Il traffico deve restare sulla rete globale AWS, e l'azienda vuole il MINOR onere operativo man mano che vengono aggiunti altri VPC. Quale soluzione soddisfa questi requisiti?","options":["Collegare in peering i due transit gateway con un peering attachment e aggiungere le route.","Creare connessioni VPC peering inter-Region tra ogni coppia di VPC che deve comunicare.","Collegare i transit gateway con connessioni Site-to-Site VPN su internet pubblico.","Instradare il traffico attraverso il data center tramite Direct Connect."],"explanation":"Il peering inter-Region di Transit Gateway collega i due hub sulla rete globale AWS con cifratura, quindi ogni VPC collegato può raggiungere l'altra Region solo tramite voci nelle route table. Anche il VPC peering inter-Region usa la rete AWS, ma una mesh completa di connessioni di peering tra decine di VPC è difficile da gestire e cresce con ogni nuovo VPC.","optionExplanations":["Corretto — un solo peering attachment collega gli hub sulla backbone AWS, e i nuovi VPC necessitano solo di route.","Una mesh di peering tra decine di VPC è complessa da gestire e deve essere estesa per ogni nuovo VPC.","Una VPN su internet non mantiene il traffico sulla rete AWS e limita il throughput per tunnel.","Far passare il traffico attraverso il data center aggiunge latenza ed esce dalla rete AWS."]},
  "1398": {"h":"aa03f82d","question":"Un'azienda collega il proprio data center a un VPC con una connessione AWS Site-to-Site VPN che termina su un virtual private gateway. I trasferimenti di dati sono cresciuti e ora sono limitati dal throughput di un singolo tunnel VPN. L'azienda non può usare AWS Direct Connect nel breve termine. Quale combinazione di passaggi aumenta la banda VPN aggregata? (Seleziona DUE)","options":["Abilitare l'accelerazione sulla connessione VPN esistente sul virtual private gateway.","Terminare la VPN su un AWS Transit Gateway con il routing equal-cost multi-path abilitato.","Passare la VPN al routing statico, in modo che il traffico sia bilanciato su entrambi i tunnel.","Aumentare l'MTU sul customer gateway, in modo che vengano inviati jumbo frame attraverso i tunnel.","Aggiungere altre connessioni Site-to-Site VPN che annuncino gli stessi prefissi tramite BGP."],"explanation":"AWS Transit Gateway supporta il routing equal-cost multi-path (ECMP) tra tunnel VPN, a differenza di un virtual private gateway, quindi spostare la VPN su un transit gateway con ECMP abilitato consente al traffico di usare più tunnel contemporaneamente. Aggiungere altre connessioni VPN che annunciano gli stessi prefissi tramite BGP fornisce a ECMP tunnel aggiuntivi su cui distribuire il traffico. Il routing statico è allettante, ma ECMP su VPN richiede il routing dinamico BGP.","optionExplanations":["L'accelerazione richiede un transit gateway e non aumenta il limite di throughput di ciascun tunnel.","Corretto — Transit Gateway può distribuire il traffico su più tunnel VPN con ECMP, a differenza di un virtual private gateway.","ECMP su VPN richiede BGP; con route statiche il traffico non viene bilanciato tra i tunnel.","Site-to-Site VPN non supporta i jumbo frame, quindi questo non aumenterebbe il throughput.","Corretto — tunnel BGP aggiuntivi forniscono a ECMP più percorsi, quindi la banda aggregata cresce con ogni connessione."]},
  "1399": {"h":"2d695d27","question":"Un'azienda ha uffici in Asia e in Sud America che si collegano tramite AWS Site-to-Site VPN a un transit gateway in us-east-1. Poiché i tunnel attraversano lunghi tratti di internet pubblico, latenza e jitter variano molto. AWS Direct Connect non è disponibile in questi uffici. L'azienda vuole prestazioni di rete più costanti con il MINOR sforzo. Quale soluzione soddisfa questi requisiti?","options":["Aggiungere una seconda connessione VPN da ogni ufficio allo stesso transit gateway in us-east-1.","Convertire le connessioni VPN in connessioni Site-to-Site VPN accelerate.","Eseguire appliance VPN software su Amazon EC2.","Posizionare una distribuzione Amazon CloudFront davanti agli endpoint VPN del transit gateway."],"explanation":"La Site-to-Site VPN accelerata usa AWS Global Accelerator, in modo che il traffico VPN entri nella rete globale AWS presso la edge location più vicina a ciascun ufficio, evitando la maggior parte del percorso internet imprevedibile. Aggiungere una seconda connessione VPN aggiunge ridondanza e banda, ma il suo traffico attraversa comunque lo stesso percorso internet congestionato, quindi latenza e jitter non migliorano.","optionExplanations":["Entrambe le connessioni attraversano comunque il lungo percorso su internet pubblico, quindi jitter e latenza restano invariati.","Corretto — il traffico entra nella rete globale AWS presso una edge location vicina, il che riduce latenza e jitter.","Appliance autogestite aggiungono impegno operativo e usano comunque lo stesso percorso internet.","CloudFront distribuisce contenuti HTTP e non può trasportare tunnel VPN IPsec."]},
  "1400": {"h":"80844862","question":"Un'azienda sta progettando una tabella Amazon DynamoDB per un servizio di storico ordini. La tabella usa customerId come partition key e orderId come sort key. L'applicazione deve anche recuperare gli ordini di un cliente ordinati per totale dell'ordine, e queste query devono usare letture strongly consistent. La tabella non è ancora stata creata. Quale design soddisfa questi requisiti?","options":["Creare un global secondary index con customerId come partition key e orderTotal come sort key.","Eseguire uno scan della tabella con un filtro su customerId e ordinare i risultati nell'applicazione.","Definire un local secondary index su customerId e orderTotal al momento della creazione della tabella.","Posizionare un cluster DynamoDB Accelerator davanti alla tabella per servire i risultati ordinati."],"explanation":"Un local secondary index condivide la partition key della tabella, fornisce una sort key alternativa e supporta le letture strongly consistent; deve essere definito al momento della creazione della tabella, cosa qui possibile. Un global secondary index potrebbe usare le stesse chiavi, ma i GSI supportano solo letture eventually consistent.","optionExplanations":["I global secondary index supportano solo letture eventually consistent, il che non soddisfa il requisito di consistenza.","Gli scan leggono l'intera tabella, il che è lento e consuma molta più capacità di lettura di una query.","Corretto — un LSI fornisce una sort key alternativa sulla stessa partition key e supporta letture strongly consistent.","DAX memorizza in cache le letture ma non può fornire un nuovo ordinamento, e le letture strongly consistent bypassano la cache."]},
  "1401": {"h":"d555fe4e","question":"Un'applicazione social utilizza Amazon ElastiCache (Redis OSS) con cluster mode disabilitato: un nodo primario e due repliche. Le letture hanno buone prestazioni, ma il volume di scritture sta saturando il nodo primario e il dataset si avvicina alla memoria del nodo. Si prevede che entrambi continuino a crescere ben oltre la capacità di qualsiasi singolo nodo. Quale soluzione soddisfa questi requisiti?","options":["Passare a cluster mode abilitato e partizionare i dati su più shard.","Aggiungere altre read replica al replication group esistente per distribuire il carico tra i nodi.","Scalare il primario al tipo di nodo più grande.","Migrare la cache ad Amazon ElastiCache (Memcached) per ottenere prestazioni multithread."],"explanation":"Con il cluster mode abilitato, lo spazio delle chiavi viene partizionato su più shard, ciascuno con il proprio primario, quindi sia il throughput in scrittura sia la memoria scalano orizzontalmente man mano che si aggiungono shard. Aggiungere read replica è allettante, ma le repliche servono solo le letture; ogni scrittura va comunque al singolo primario e ogni replica contiene l'intero dataset.","optionExplanations":["Corretto — ogni shard ha il proprio primario, quindi scritture e memoria scalano orizzontalmente aggiungendo shard.","Le repliche servono solo le letture; tutte le scritture arrivano comunque a un unico primario e ogni replica memorizza l'intero dataset.","Un nodo più grande fa guadagnare tempo, ma non può reggere una crescita oltre la capacità di un singolo nodo.","L'applicazione dipende da funzionalità e replica di Redis, che Memcached non offre."]},
  "1402": {"h":"a5cd0294","question":"Una software house distribuisce installer da diversi gigabyte da un bucket Amazon S3 in un'unica AWS Region. Quando esce una nuova release, milioni di utenti in tutto il mondo scaricano gli stessi file nel giro di pochi giorni, e gli utenti lontani dalla Region segnalano download lenti. L'azienda vuole migliorare la velocità di download con il MINIMO overhead operativo. Quale soluzione soddisfa questi requisiti?","options":["Abilitare S3 Transfer Acceleration e pubblicare l'endpoint accelerato come link di download.","Replicare il bucket in diverse Region e instradare gli utenti con record Route 53 latency-based.","Distribuire gli oggetti su un numero maggiore di prefissi S3.","Servire gli installer tramite Amazon CloudFront con il bucket come origin."],"explanation":"Amazon CloudFront memorizza in cache gli installer nelle edge location di tutto il mondo, quindi dopo le prime richieste la maggior parte degli utenti scarica da un edge vicino anziché dal bucket lontano. Anche S3 Transfer Acceleration usa le edge location, ma velocizza solo i trasferimenti da e verso il bucket e non memorizza contenuti in cache, quindi ogni download viene comunque servito dalla Region.","optionExplanations":["Transfer Acceleration non memorizza contenuti in cache, quindi ogni download viene comunque servito dalla Region del bucket.","Gestire repliche e routing in molte Region aggiunge overhead e copre comunque meno località di una rete edge.","Il problema è la distanza dagli utenti, non il tasso di richieste S3 per prefisso.","Corretto — i file più richiesti vengono messi in cache nelle edge location vicine agli utenti, velocizzando i download con poca gestione."]},
  "1403": {"h":"47d6b4d3","question":"Un'azienda esegue un'applicazione in us-east-1, eu-west-1 e ap-southeast-1. In ogni Region l'applicazione legge e scrive oggetti in Amazon S3. L'azienda vuole che gli oggetti siano replicati tra i bucket di tutte e tre le Region e un unico endpoint globale che invii automaticamente ogni richiesta al bucket con la latenza più bassa, senza dover sviluppare logica di routing. Quale soluzione soddisfa questi requisiti?","options":["Usare un unico bucket in us-east-1 con S3 Transfer Acceleration abilitato per tutte e tre le Region.","Creare un S3 Multi-Region Access Point sui bucket replicati nelle tre Region.","Mettere una distribuzione Amazon CloudFront davanti a un unico bucket per letture e scritture.","Creare record Route 53 latency-based che puntano all'endpoint del bucket di ciascuna Region."],"explanation":"Un S3 Multi-Region Access Point fornisce un unico endpoint globale che instrada le richieste sulla rete AWS verso il bucket più vicino, e le sue regole di replica mantengono sincronizzati i bucket nelle tre Region. Un unico bucket con Transfer Acceleration è allettante, ma tutti gli oggetti risiederebbero comunque in una sola Region, quindi letture e scritture dalle altre Region continuerebbero a subire la latenza cross-Region.","optionExplanations":["I dati restano in un'unica Region, quindi l'accesso dalle altre Region subisce ancora la latenza cross-Region.","Corretto — un unico endpoint globale instrada ogni richiesta al bucket con latenza più bassa e la replica mantiene sincronizzate le copie.","Le scritture vanno comunque a una sola Region e CloudFront non replica gli oggetti su altri bucket.","Ogni bucket ha un proprio nome, quindi l'applicazione avrebbe bisogno di una propria logica per scegliere il bucket giusto."]},
  "1404": {"h":"bb202772","question":"Un'azienda sta spostando dei microservizi che comunicano tramite gRPC su istanze Amazon EC2 dietro un load balancer. Il load balancer deve bilanciare le singole chiamate gRPC che arrivano su connessioni HTTP/2 di lunga durata, instradare le chiamate verso servizi diversi in base al path del metodo gRPC e usare i codici di stato gRPC negli health check. Quale soluzione soddisfa questi requisiti?","options":["Usare un Network Load Balancer con listener TCP che inoltrano il traffico alle istanze.","Usare un Gateway Load Balancer con GENEVE.","Usare un Network Load Balancer con un listener TLS e target group per ciascuna porta di servizio.","Usare un ALB i cui target group usano la protocol version gRPC."],"explanation":"Un Application Load Balancer supporta gRPC come protocol version del target group: bilancia ogni chiamata su HTTP/2, instrada in base al path della richiesta e verifica lo stato con i codici di stato gRPC. Un Network Load Balancer bilancia a livello di connessione, quindi le connessioni HTTP/2 di lunga durata vincolano tutte le loro chiamate a un unico target, e non può instradare in base al path.","optionExplanations":["L'NLB bilancia connessioni, non chiamate, quindi le connessioni di lunga durata restano legate a un target, e non può instradare per path.","Il Gateway Load Balancer serve per appliance di rete in linea, non per instradare chiamate gRPC applicative.","La terminazione TLS non aggiunge bilanciamento per singola richiesta né routing basato sul path per gRPC.","Corretto — l'ALB bilancia le singole chiamate gRPC, instrada per path del metodo e supporta health check gRPC."]},
  "1405": {"h":"2edf3615","question":"Un'azienda esegue on-premises un database OLTP Oracle e sta costruendo un data lake su Amazon S3. Ha bisogno di una copia iniziale di alcune tabelle in S3 seguita dalla replica continua delle modifiche in corso, con un impatto minimo sul database sorgente e senza scrivere codice personalizzato. Quale soluzione soddisfa questi requisiti?","options":["Eseguire un task AWS DMS con full load e replica continua verso un target S3.","Esportare le tabelle ogni notte e caricare i file di dump su Amazon S3 con AWS DataSync.","Eseguire ogni pochi minuti un job Glue JDBC sulle tabelle complete.","Usare AWS Schema Conversion Tool per convertire lo schema e replicare le modifiche su S3."],"explanation":"Un task AWS DMS con full load più change data capture copia i dati esistenti e poi legge le modifiche in corso dai log del database, scrivendole su S3 con poco carico sulla sorgente. AWS Schema Conversion Tool è allettante perché viene usato nelle migrazioni di database, ma converte schemi e codice; non replica le modifiche ai dati.","optionExplanations":["Corretto — DMS copia i dati esistenti, poi cattura le modifiche dai log e le scrive su S3 in modo continuo.","Gli export notturni non sono una replica continua e aggiungono un carico pesante sulla sorgente durante l'export.","Letture ripetute di intere tabelle caricano pesantemente la sorgente e non catturano le singole modifiche.","SCT converte schemi e codice, ma non replica le modifiche continue ai dati."]},
  "1406": {"h":"306678d1","question":"Un'azienda di ride-hailing invia in streaming gli eventi delle corse su Amazon Kinesis Data Streams. Deve calcolare metriche di domanda per città su finestre scorrevoli di un minuto con latenza inferiore al secondo, il che richiede un'elaborazione stateful tra gli eventi. L'azienda vuole un servizio gestito con il MINIMO overhead operativo e nessun cluster da gestire. Quale soluzione soddisfa questi requisiti?","options":["Consegnare gli eventi su S3 con Amazon Data Firehose ed eseguire query Athena ogni minuto.","Eseguire un'applicazione Amazon Managed Service for Apache Flink sullo stream.","Usare un consumer Lambda con lo stato delle finestre in memoria.","Eseguire Spark Structured Streaming su un cluster Amazon EMR che legge lo stream in modo continuo."],"explanation":"Amazon Managed Service for Apache Flink esegue applicazioni di streaming stateful con windowing integrato direttamente sullo stream, senza cluster da gestire. AWS Lambda può consumare lo stream con poco overhead, ma le sue invocazioni sono stateless, quindi mantenere finestre scorrevoli tra eventi e shard richiederebbe uno stato esterno e logica personalizzata.","optionExplanations":["Il buffering di Firehose e le query pianificate aggiungono una latenza ben superiore al secondo.","Corretto — Flink offre un'elaborazione gestita, stateful e a finestre sullo stream con latenza inferiore al secondo.","Le invocazioni Lambda sono stateless, quindi lo stato delle finestre in memoria non viene mantenuto in modo affidabile tra gli eventi.","Spark può farlo, ma gestire un cluster EMR aggiunge l'overhead operativo che l'azienda vuole evitare."]},
  "1407": {"h":"b5e6c8f1","question":"Un'azienda esegue ogni notte un job ETL AWS Glue che elabora i file presenti in un prefisso Amazon S3. Ogni giorno vengono aggiunti nuovi file, ma il job rielabora a ogni esecuzione tutti i file del prefisso, per cui durata e costo crescono costantemente. L'azienda vuole che ogni esecuzione elabori solo i file arrivati dopo l'esecuzione precedente, con il MINIMO sforzo. Cosa dovrebbe fare un solutions architect?","options":["Aumentare il numero di worker assegnati al job in modo che ogni esecuzione termini più velocemente.","Aggiungere una funzione Lambda che sposta i file elaborati in un prefisso di archivio dopo ogni esecuzione.","Abilitare i job bookmark sul job AWS Glue in modo da saltare i file già elaborati.","Convertire il job in un job Python shell che elenca il prefisso e salta i file più vecchi in base alla data."],"explanation":"I job bookmark di Glue conservano lo stato dei dati già elaborati, quindi ogni esecuzione legge solo i nuovi file senza codice per tenerne traccia. Aggiungere worker rende ogni esecuzione più veloce, ma il job continuerebbe a rielaborare l'intero prefisso e il costo continuerebbe a crescere.","optionExplanations":["Il job rielaborerebbe comunque tutti i file, quindi il costo continua ad aumentare con la dimensione del prefisso.","Funziona, ma aggiunge codice personalizzato e un nuovo punto di guasto, il che richiede più sforzo di una funzionalità integrata.","Corretto — i bookmark tengono traccia dei dati elaborati, così ogni esecuzione gestisce solo i nuovi file, senza codice personalizzato.","Riscrivere il job per tracciare lo stato manualmente richiede più sforzo e perde l'elaborazione parallela di Spark."]},
  "1408": {"h":"49d73565","question":"Un'azienda carica dati giornalieri in Amazon Redshift con un'applicazione che esegue istruzioni INSERT a riga singola, e il caricamento richiede diverse ore. I dati provengono da file di estrazione giornalieri dei sistemi sorgente. L'azienda vuole rendere il caricamento il più veloce possibile. Quale approccio dovrebbe raccomandare un solutions architect?","options":["Unire l'estrazione di ogni giorno in un unico file grande non compresso su S3 e caricarlo con COPY.","Inviare al cluster istruzioni INSERT multiriga da molte connessioni al database in parallelo.","Aggiungere altri nodi di calcolo al cluster.","Suddividere le estrazioni in molti file compressi su S3 e caricarli con COPY."],"explanation":"Il comando COPY carica i dati da Amazon S3 in parallelo su tutte le slice del cluster, e suddividere l'input in più file compressi consente a ogni slice di lavorare contemporaneamente. Caricare un unico file grande è allettante perché usa anch'esso COPY, ma un singolo file non può essere letto in parallelo da tutte le slice.","optionExplanations":["Un unico file limita il parallelismo tra le slice, quindi il caricamento è più lento che con più file.","Gli insert passano comunque dal leader node e sono molto più lenti di un COPY massivo in parallelo.","Più nodi aumentano il costo, ma non risolvono l'inefficienza del caricamento riga per riga.","Corretto — COPY legge i file in parallelo su tutte le slice, molto più velocemente degli insert riga per riga."]},
  "1409": {"h":"79ac9493","question":"Un'azienda esegue on-premises applicazioni Linux che usano un file server NFS basato su ZFS. Il workload è composto da file piccoli e richiede latenza inferiore al millisecondo con IOPS molto elevati, e gli script esistenti si basano sulle funzionalità di snapshot e clone di ZFS. L'azienda vuole un servizio di file AWS completamente gestito che richieda il minor numero di modifiche. Quale servizio dovrebbe raccomandare un solutions architect?","options":["Amazon FSx for OpenZFS con accesso tramite NFS","Amazon EFS con la modalità di prestazioni General Purpose","Amazon FSx for Lustre con un deployment SSD persistente","Mountpoint for Amazon S3"],"explanation":"Amazon FSx for OpenZFS fornisce file system ZFS completamente gestiti, accessibili via NFS, con latenza inferiore al millisecondo e snapshot e clone ZFS nativi. Anche Amazon EFS è uno storage NFS gestito, ma non offre le funzionalità di snapshot e clone di ZFS, quindi gli script esistenti dovrebbero essere modificati.","optionExplanations":["Corretto — offre ZFS gestito su NFS con latenza inferiore al millisecondo e snapshot e clone nativi.","EFS non fornisce snapshot e clone ZFS, quindi gli script che li usano dovrebbero essere riscritti.","Lustre è pensato per il throughput parallelo HPC e richiede un client Lustre anziché NFS con funzionalità ZFS.","S3 è uno storage a oggetti, quindi non ha snapshot ZFS né la semantica completa di un file system per workload con file piccoli."]},
  "1410": {"h":"bd2953a0","question":"Ogni notte un'azienda deve elaborare milioni di immagini archiviate in Amazon S3. Ogni immagine passa per un workflow in più fasi (ridimensionamento, rilevamento delle etichette e memorizzazione dei metadati) implementato con funzioni AWS Lambda, e ogni fase richiede propri retry e tracciamento degli errori. L'azienda vuole un parallelismo massivo con il MINIMO overhead operativo. Quale soluzione soddisfa questi requisiti?","options":["Usare uno stato Inline Map di AWS Step Functions in un unico workflow per iterare sugli oggetti.","Usare uno stato Distributed Map di Step Functions con un child workflow per ogni oggetto.","Usare S3 Batch Operations per invocare una singola funzione Lambda per ciascuno degli oggetti immagine.","Elaborare tutte le immagini in un ciclo all'interno di un'unica funzione Lambda."],"explanation":"Uno stato Distributed Map di Step Functions può iterare su milioni di oggetti S3 ed eseguire un child workflow per ciascuno, con elevata concorrenza e retry e gestione degli errori per ogni fase. Uno stato Inline Map supporta la stessa logica di workflow, ma i suoi limiti di concorrenza e di execution history lo rendono inadatto a milioni di elementi in una singola esecuzione.","optionExplanations":["Inline Map ha concorrenza ed execution history limitate, quindi non può elaborare milioni di elementi in un'unica esecuzione.","Corretto — Distributed Map scala a milioni di oggetti con elevato parallelismo e retry per fase in ogni child workflow.","Batch Operations chiama una funzione per oggetto e non orchestra un workflow in più fasi con retry per ciascuna fase.","Una singola funzione è limitata dal suo timeout massimo e non offre parallelismo né gestione dei retry per fase."]},
  "1411": {"h":"05ea843e","question":"Un'azienda crea spesso volumi Amazon EBS da snapshot per avviare copie di database per i test. Per molto tempo dopo ogni avvio, le prime query sono molto lente perché i blocchi vengono caricati da Amazon S3 la prima volta che vengono letti. I tester hanno bisogno che i volumi ripristinati offrano subito tutte le prestazioni provisioned. Quale soluzione soddisfa questi requisiti?","options":["Leggere ogni blocco di ciascun nuovo volume con un'utility prima di avviare il database.","Creare i volumi come volumi io2 con IOPS provisioned molto più elevati rispetto a gp3.","Abilitare EBS fast snapshot restore sugli snapshot nelle AZ utilizzate.","Avviare le copie del database su tipi di istanza con maggiore banda EBS dedicata."],"explanation":"EBS fast snapshot restore crea volumi completamente inizializzati già alla creazione, che quindi offrono subito le prestazioni provisioned senza penalità alla prima lettura. Anche leggere ogni blocco dopo la creazione inizializza il volume, ma su volumi grandi richiede molto tempo, quindi le prestazioni non sono disponibili immediatamente.","optionExplanations":["Così si inizializza il volume, ma su volumi grandi richiede molto tempo, quindi le prestazioni non sono immediate.","IOPS provisioned più elevati non eliminano la latenza del recupero dei blocchi da S3 al primo accesso.","Corretto — i volumi creati da questi snapshot sono completamente inizializzati e offrono subito tutte le prestazioni.","La banda dell'istanza non è il collo di bottiglia; il ritardo deriva dal caricamento lazy dei blocchi dallo snapshot."]},
  "1412": {"h":"e56bcad1","question":"Delle istanze Amazon EC2 in subnet private scaricano diversi terabyte al giorno da bucket Amazon S3 nella stessa Region tramite un NAT gateway. Il NAT gateway è diventato un collo di bottiglia per il throughput e i suoi costi di elaborazione dati sono elevati. Le istanze devono restare in subnet private. Cosa dovrebbe fare un solutions architect?","options":["Aggiungere NAT gateway in altre Availability Zone e suddividere tra di essi le route predefinite delle subnet.","Spostare le istanze in subnet pubbliche e assegnare loro indirizzi IP pubblici per raggiungere S3 direttamente.","Abilitare S3 Transfer Acceleration sui bucket e scaricare tramite l'endpoint accelerato.","Creare un gateway VPC endpoint per Amazon S3 e aggiungerlo alle route table delle subnet private."],"explanation":"Un gateway VPC endpoint per S3 consente alle istanze nelle subnet private di raggiungere S3 direttamente tramite una voce della route table, aggirando il NAT gateway, così il collo di bottiglia e i relativi costi di elaborazione dati scompaiono. Aggiungere NAT gateway distribuisce il carico, ma ognuno addebita comunque ogni gigabyte elaborato.","optionExplanations":["Il carico viene distribuito, ma ogni gigabyte comporta ancora costi di elaborazione NAT e più gateway da gestire.","Questo viola il requisito di mantenere le istanze in subnet private.","L'accelerazione aiuta i trasferimenti a lunga distanza, e il traffico passerebbe comunque dal NAT gateway.","Corretto — il traffico S3 aggira completamente il NAT gateway, eliminando il collo di bottiglia e i relativi costi di elaborazione."]},
  "1413": {"h":"58439f44","question":"Un'azienda del settore media esegue un'applicazione di video editing i cui artisti si trovano a Los Angeles. L'applicazione richiede una latenza nell'ordine di pochi millisecondi tra le workstation degli artisti e il suo livello di calcolo e storage, e la AWS Region più vicina aggiunge troppa latenza. L'azienda non vuole acquistare, installare o gestire hardware proprio. Quale soluzione soddisfa questi requisiti?","options":["Distribuire il livello sensibile alla latenza in una AWS Local Zone a Los Angeles.","Installare un rack AWS Outposts nello studio dell'azienda ed eseguirvi il livello applicativo.","Distribuire l'applicazione in una AWS Wavelength Zone sulla rete di un operatore di telecomunicazioni.","Mettere Amazon CloudFront davanti all'applicazione."],"explanation":"Le AWS Local Zone collocano capacità di calcolo e storage gestite da AWS in aree metropolitane come Los Angeles, estendendo una Region padre e offrendo una latenza di pochi millisecondi agli utenti vicini. Anche AWS Outposts offre bassa latenza, ma viene installato nella struttura del cliente, cosa che l'azienda vuole evitare.","optionExplanations":["Corretto — le Local Zone offrono infrastruttura gestita da AWS vicino agli utenti, con latenza di pochi millisecondi.","Outposts deve essere installato e ospitato nella struttura del cliente, cosa che l'azienda vuole evitare.","Wavelength è pensato per dispositivi mobili 5G sulle reti degli operatori, non per workstation su una rete aziendale.","Il traffico di editing interattivo non può essere messo in cache, quindi CloudFront non garantirebbe la latenza richiesta."]},
  "1414": {"h":"f02f014b","question":"Un emittente di carte deve elaborare ogni evento di transazione con codice antifrode personalizzato entro un secondo dall'arrivo. Una seconda applicazione deve leggere in modo indipendente gli stessi eventi a fini di audit e, dopo aver corretto un bug, il team deve poter rielaborare gli eventi delle ultime 24 ore. Quale servizio di ingestion soddisfa questi requisiti?","options":["Amazon Kinesis Data Streams con applicazioni consumer separate","Amazon Data Firehose che consegna gli eventi al codice antifrode","Un topic SNS in fan-out verso due code SQS","Un'unica coda Amazon SQS standard interrogata da entrambe le applicazioni"],"explanation":"Kinesis Data Streams consente a più consumer di leggere gli stessi record in modo indipendente con latenza inferiore al secondo, e i record restano nello stream per tutto il periodo di retention, quindi possono essere rielaborati. Un topic SNS in fan-out verso code SQS consegna rapidamente gli eventi a entrambe le applicazioni, ma una volta consumati ed eliminati i messaggi non possono essere rielaborati.","optionExplanations":["Corretto — più consumer indipendenti, latenza inferiore al secondo e replay entro il periodo di retention.","Firehose bufferizza i record prima della consegna e non può rieseguire i dati verso più consumer indipendenti.","Il fan-out funziona, ma i messaggi consumati vengono eliminati, quindi le ultime 24 ore non possono essere rielaborate.","Ogni messaggio viene consumato da una sola applicazione e i messaggi elaborati non possono essere rieseguiti."]},
  "1415": {"h":"ef29211b","question":"Gli analisti eseguono ogni notte scansioni complete di una tabella Amazon DynamoDB di produzione per alimentare un sistema di analytics. Le scansioni consumano grandi quantità di capacità di lettura e, mentre sono in esecuzione, l'applicazione rivolta ai clienti subisce throttling. Gli analisti hanno bisogno di una copia completa dei dati in Amazon S3 da interrogare con Amazon Athena, senza influire sulle prestazioni della tabella. Quale soluzione soddisfa questi requisiti?","options":["Passare a una parallel scan con più segmenti, in modo che la scansione notturna termini prima.","Abilitare il point-in-time recovery e usare ogni notte la funzionalità DynamoDB export to S3.","Creare un global secondary index per gli analisti ed eseguire la scansione dell'indice anziché della tabella.","Instradare le scansioni degli analisti attraverso un cluster DynamoDB Accelerator davanti alla tabella."],"explanation":"DynamoDB export to S3 usa i dati del point-in-time recovery, quindi non consuma la capacità di lettura della tabella e produce in S3 una copia completa interrogabile con Athena. Una parallel scan termina più velocemente, ma consuma la stessa capacità di lettura in meno tempo, il che peggiora il throttling.","optionExplanations":["Una parallel scan usa la stessa capacità di lettura in meno tempo, aumentando il throttling durante l'esecuzione.","Corretto — gli export leggono dai dati di backup, quindi non viene consumata capacità di lettura e l'applicazione non ne risente.","L'indice duplica le scritture e la sua scansione consuma comunque capacità, senza fornire una copia in S3.","DAX è pensato per letture ripetute di item e query; una scansione completa legge comunque la capacità della tabella."]},
  "1416": {"h":"c523ce04","question":"Un'applicazione gira su istanze Amazon EC2 in un Auto Scaling group dietro un Application Load Balancer. Mantiene le sessioni utente nella memoria dell'istanza e si basa sulle sticky session. Durante lo scale-out le nuove istanze ricevono poco traffico mentre quelle esistenti restano sovraccariche, e durante lo scale-in gli utenti vengono disconnessi. Quale soluzione migliorerà la distribuzione del carico e manterrà gli utenti autenticati?","options":["Impostare sul target group l'algoritmo least outstanding requests e mantenere le sticky session.","Aumentare la durata della stickiness in modo che gli utenti restino più a lungo sulla stessa istanza.","Memorizzare lo stato delle sessioni in Amazon ElastiCache e disabilitare le sticky session sul target group.","Sostituire l'Application Load Balancer con un Network Load Balancer con affinità sull'IP del client."],"explanation":"Spostare lo stato delle sessioni in Amazon ElastiCache rende ogni istanza stateless, quindi la stickiness può essere disabilitata e il load balancer può distribuire le richieste in modo uniforme, e terminare un'istanza non fa più perdere sessioni. Cambiare l'algoritmo di routing è allettante, ma finché la stickiness è abilitata gli utenti esistenti restano legati alle istanze originali.","optionExplanations":["La stickiness mantiene gli utenti esistenti legati alle loro istanze, quindi il carico resta sbilanciato e le sessioni si perdono comunque allo scale-in.","Una stickiness più lunga peggiora lo squilibrio e non protegge le sessioni quando le istanze vengono terminate.","Corretto — le istanze stateless permettono all'ALB di bilanciare le richieste in modo uniforme e le sessioni sopravvivono alla terminazione delle istanze.","L'affinità vincola comunque gli utenti alle istanze e le sessioni in memoria vanno comunque perse allo scale-in."]},
  "1417": {"h":"632c42e6","question":"Un'applicazione di biglietteria memorizza gli acquisti in una tabella Amazon DynamoDB che usa capacità provisioned con auto scaling. Le vendite dei biglietti si aprono in orari non annunciati e il traffico in scrittura passa da quasi zero a molte volte il livello abituale nel giro di secondi. Le scritture subiscono throttling per diversi minuti finché l'auto scaling non si adegua. Quale soluzione gestirà questi picchi improvvisi con il MINIMO overhead operativo?","options":["Abbassare il target utilization della policy di auto scaling per mantenere più capacità di scrittura di riserva.","Mettere un cluster DynamoDB Accelerator davanti alla tabella per assorbire le scritture degli acquisti.","Aggiungere un global secondary index in modo che le scritture degli acquisti siano distribuite su più partizioni.","Passare la tabella alla modalità di capacità on-demand in modo che assorba i picchi improvvisi di scrittura."],"explanation":"La modalità di capacità on-demand serve le richieste senza pianificazione della capacità e si adatta istantaneamente ad aumenti improvvisi di traffico fino a ben oltre i picchi precedenti, quindi i picchi di scrittura vengono assorbiti senza attendere le azioni di scaling. Abbassare il target utilization dell'auto scaling aggiunge margine, ma l'auto scaling reagisce comunque nell'arco di minuti, quindi i picchi improvvisi di grande entità subirebbero ancora throttling.","optionExplanations":["L'auto scaling ha comunque bisogno di minuti per reagire, quindi i picchi molto improvvisi subiscono throttling nonostante il margine extra.","DAX accelera le letture; le scritture vanno comunque alla tabella e subiscono lo stesso throttling.","Un GSI aggiunge lavoro di scrittura anziché capacità e non evita il throttling sulla tabella di base.","Corretto — la modalità on-demand si adatta agli aumenti improvvisi di traffico senza pianificazione della capacità né ritardi di scaling."]},
  "1418": {"h":"4683dfac","question":"Una startup sta lanciando un'applicazione che necessita di una cache compatibile con Redis OSS. Il traffico è sconosciuto e si prevede che vari molto, e il team non vuole scegliere tipi di nodo, pianificare shard o gestire lo scaling. La cache deve scalare automaticamente in base alla domanda. Quale soluzione soddisfa questi requisiti con il MINIMO overhead operativo?","options":["Creare una cache Amazon ElastiCache Serverless che usa il motore Redis OSS.","Creare un cluster ElastiCache basato su nodi con il tipo di nodo più grande per coprire la domanda di picco.","Eseguire Redis OSS su istanze Amazon EC2 in un Auto Scaling group dietro un load balancer.","Usare Amazon DynamoDB con un cluster DynamoDB Accelerator come cache dell'applicazione."],"explanation":"Amazon ElastiCache Serverless fornisce una cache compatibile con Redis OSS che scala automaticamente la capacità in base alla domanda, senza scegliere tipi di nodo né gestire shard. Un cluster ElastiCache basato su nodi dimensionato per il picco funzionerebbe, ma richiede pianificazione della capacità e fa pagare la capacità inutilizzata nei periodi di calma.","optionExplanations":["Corretto — la cache scala automaticamente, senza tipi di nodo o shard da gestire.","Richiede pianificazione della capacità e fa pagare la capacità inattiva ogni volta che il traffico è basso.","Gestire in autonomia clustering e scaling di Redis su EC2 crea un overhead operativo significativo.","DAX non fornisce l'API Redis OSS richiesta dall'applicazione."]},
  "1419": {"h":"e273483e","question":"Un'azienda esegue un servizio di reportistica su istanze burstable T3 in standard credit mode. Il servizio ora esegue job ad alta intensità di CPU in modo continuo durante tutta la giornata, quindi le istanze esauriscono i crediti CPU e scendono alle prestazioni di baseline. L'azienda vuole prestazioni CPU costantemente elevate al costo più basso. Cosa dovrebbe fare un solutions architect?","options":["Abilitare l'unlimited credit mode sulle istanze T3 esistenti per evitare il throttling.","Spostare il servizio su istanze C compute optimized dimensionate per il carico CPU sostenuto.","Passare a una dimensione di istanza burstable T3 più grande, che accumula crediti CPU a un ritmo maggiore.","Spostare il servizio su istanze R memory optimized con più memoria per vCPU."],"explanation":"Le istanze C compute optimized offrono prestazioni CPU piene e sostenute senza crediti, ed è la scelta più conveniente per un workload che gira ad alto utilizzo di CPU tutto il giorno. La modalità unlimited mantiene veloci le istanze T3, ma l'uso prolungato sopra la baseline comporta addebiti per crediti in eccesso che la rendono più costosa di un'istanza a prestazioni fisse.","optionExplanations":["Un uso prolungato e intenso della CPU in modalità unlimited comporta addebiti aggiuntivi, che costano più delle istanze a prestazioni fisse.","Corretto — le istanze compute optimized a prestazioni fisse sono adatte a lavori continui e intensivi di CPU al costo più basso.","Una T3 più grande dipende comunque dai crediti e li esaurirebbe con un uso intenso e continuo della CPU.","Il workload è limitato dalla CPU, quindi la memoria aggiuntiva aumenta il costo senza risolvere il limite di CPU."]},
  "1420": {"h":"68250e95","question":"Un istituto di ricerca trasferisce ogni giorno decine di terabyte di dati strumentali dal proprio data center ad Amazon S3 tramite una Site-to-Site VPN su internet. Il throughput varia molto e i trasferimenti spesso non rientrano nella finestra di elaborazione. L'istituto ha bisogno di prestazioni di rete costanti, ad alta larghezza di banda e prevedibili per questi trasferimenti giornalieri. Quale soluzione soddisfa questi requisiti?","options":["Convertire la connessione VPN esistente in una connessione Site-to-Site VPN accelerata.","Spedire i dati giornalieri su dispositivi AWS Snowball Edge anziché usare la rete.","Attivare una connessione AWS Direct Connect con una public VIF per raggiungere Amazon S3.","Abilitare S3 Transfer Acceleration sul bucket e caricare i file tramite l'endpoint accelerato."],"explanation":"AWS Direct Connect fornisce una connessione privata dedicata con larghezza di banda e latenza costanti, e una public virtual interface dà accesso agli endpoint pubblici di Amazon S3 per i trasferimenti giornalieri. La VPN accelerata migliora il percorso entrando nella rete AWS da una edge location vicina, ma dipende comunque da internet e dal throughput per tunnel, quindi le prestazioni restano meno prevedibili.","optionExplanations":["Si basa comunque su internet e sul throughput per tunnel, quindi le prestazioni restano meno prevedibili.","Spedire dispositivi ogni giorno è poco pratico dal punto di vista operativo e aggiunge giorni di ritardo a ogni dataset.","Corretto — una connessione dedicata offre larghezza di banda elevata e costante e latenza prevedibile per i trasferimenti massivi giornalieri.","Il traffico attraversa comunque internet pubblico fino a una edge location, quindi il throughput può ancora variare."]},
  "1421": {"h":"58ea5a9a","question":"Un'azienda sta migrando su Amazon EC2 40 VM Windows Server che eseguono Microsoft SQL Server Enterprise. Possiede licenze SQL Server per core fisico, senza Software Assurance né License Mobility, per cui le licenze devono restare su server fisici dedicati all'azienda. L'azienda vuole riutilizzare queste licenze e deve comunicare agli auditor il numero di socket e core. Quale soluzione soddisferà questi requisiti nel modo PIÙ conveniente?","options":["Avviare le istanze su EC2 Dedicated Hosts e tracciare l'uso delle licenze con AWS License Manager.","Avviare le istanze come Dedicated Instances e portare le licenze SQL Server esistenti.","Avviare istanze SQL Server License Included in tenancy condivisa con un Savings Plan di 3 anni.","Migrare i database su Amazon RDS for SQL Server e portare le licenze esistenti sulle istanze DB."],"explanation":"Le licenze senza License Mobility legate ai core fisici possono essere portate su AWS solo su hardware dedicato al cliente con visibilità di socket e core, ciò che forniscono gli EC2 Dedicated Hosts, e License Manager semplifica la reportistica per gli audit. Le Dedicated Instances sono il distrattore allettante, ma non espongono socket e core dell'host fisico, quindi non possono essere usate per questo tipo di BYOL.","optionExplanations":["Corretto — i Dedicated Hosts forniscono un server fisico dedicato all'azienda con visibilità di socket e core, come richiesto dal BYOL per core senza License Mobility; License Manager traccia i consumi per gli audit.","Le Dedicated Instances girano su hardware dedicato ma non espongono socket e core fisici né offrono affinità con l'host, quindi non rispettano questi termini di licenza né il requisito di reportistica.","Le istanze License Included pagano nuove licenze SQL Server nella tariffa oraria, quindi le licenze già possedute dall'azienda andrebbero sprecate.","Amazon RDS for SQL Server usa prezzi License Included e, in ogni caso, le licenze senza License Mobility non possono essere spostate su infrastruttura AWS condivisa."]},
  "1422": {"h":"38ad1ef9","question":"Un'azienda esegue on-premises un Oracle Database Enterprise Edition da 3 TB per un sistema ordini interno. Licenze e supporto Oracle sono la voce di spesa IT più alta e il rinnovo scade tra 9 mesi. L'applicazione usa SQL standard e un numero moderato di stored procedure PL/SQL e, dopo la migrazione, il database deve essere altamente disponibile con un'amministrazione minima. Quale soluzione ridurrà MAGGIORMENTE i costi nel lungo periodo?","options":["Eseguire il rehost del database su istanze Amazon EC2 portando le licenze Oracle esistenti.","Convertire lo schema con AWS SCT e migrare i dati con AWS DMS verso Aurora PostgreSQL.","Migrare ad Amazon RDS for Oracle con prezzi License Included in un deployment Multi-AZ.","Migrare ad Amazon RDS Custom for Oracle in modo da poter riutilizzare le licenze esistenti."],"explanation":"Le licenze sono il costo dominante, quindi il risparmio maggiore a lungo termine deriva dal passaggio a un motore compatibile open source; AWS SCT e AWS DMS rendono fattibile una migrazione eterogenea di SQL standard e di una quantità moderata di PL/SQL, e Aurora fornisce disponibilità Multi-AZ gestita. RDS for Oracle License Included riduce l'amministrazione, ma addebita comunque le licenze Oracle per ogni ora di utilizzo.","optionExplanations":["Mantiene i costi di licenza e supporto Oracle e aggiunge il lavoro di gestire il database e la sua alta disponibilità su EC2.","Corretto — la conversione ad Aurora compatibile con PostgreSQL elimina completamente le licenze Oracle, SCT converte automaticamente la maggior parte del codice PL/SQL e Aurora fornisce alta disponibilità gestita.","Il costo della licenza Oracle viene comunque pagato tramite la tariffa oraria, quindi la principale voce di costo rimane.","RDS Custom mantiene i costi di licenza e supporto Oracle e richiede più amministrazione di un motore completamente gestito."]},
  "1423": {"h":"9680dd61","question":"Un'azienda esegue in us-east-1 un'applicazione rivolta ai clienti su istanze EC2 in un Auto Scaling group con un database Amazon Aurora MySQL. Per il disaster recovery mantiene sempre in esecuzione in us-west-2 una copia a dimensione piena della flotta applicativa e vi replica il database. Il business ha concordato un RTO di 4 ore e un RPO di 15 minuti in caso di interruzione di una Region. Quale approccio di DR soddisferà questi requisiti nel modo PIÙ conveniente?","options":["Mantenere la flotta di standby a dimensione piena e coprire le istanze della Region di DR con un Savings Plan.","Copiare i backup giornalieri di Aurora in us-west-2 con AWS Backup ed eliminare tutte le altre risorse di DR.","Continuare a replicare il database in us-west-2 e avviare il livello applicativo da template al failover.","Eseguire un active-active in entrambe le Region con routing Route 53 latency-based per sfruttare la capacità di DR."],"explanation":"Con un RTO di 4 ore, il livello applicativo non deve essere in esecuzione nella Region di DR; può essere avviato da AMI e template durante il failover, mentre la replica continua del database mantiene l'RPO entro 15 minuti (pilot light). Backup and restore sarebbe ancora più economico, ma con copie giornaliere non può rispettare un RPO di 15 minuti.","optionExplanations":["Uno sconto su una flotta a dimensione piena inattiva fa comunque pagare capacità che un RTO di 4 ore non richiede.","Le copie di backup giornaliere consentono una perdita di dati fino a 24 ore, il che viola l'RPO di 15 minuti.","Corretto — questo approccio pilot light mantiene la replica continua del database per l'RPO di 15 minuti ed effettua il provisioning del livello applicativo da AMI e infrastructure as code entro l'RTO di 4 ore, evitando una flotta inattiva.","L'active-active è la strategia più costosa e richiede una progettazione dei dati multi-writer; va ben oltre quanto serve per un RTO di 4 ore."]},
  "1424": {"h":"5dd3aaea","question":"Un'azienda espone un'API pubblica tramite una REST API di Amazon API Gateway che invoca funzioni AWS Lambda e gestisce miliardi di richieste al mese. L'API usa solo l'autorizzazione JWT da un provider OIDC, integrazioni Lambda proxy e CORS. Non usa API key, usage plan, request validation né AWS WAF. L'azienda vuole ridurre i costi di API Gateway senza modificare il backend. Quale soluzione soddisferà questi requisiti?","options":["Abilitare il caching di API Gateway sullo stage della REST API per ridurre il numero di richieste fatturate.","Sostituire API Gateway con un Network Load Balancer che invia le richieste direttamente alle funzioni Lambda.","Creare una REST API privata ed esporla ai client tramite un interface VPC endpoint.","Migrare l'API a una HTTP API di API Gateway con un JWT authorizer e integrazioni Lambda proxy."],"explanation":"Le HTTP API costano molto meno per richiesta rispetto alle REST API e supportano tutte le funzionalità usate da questa API: JWT authorizer, integrazioni Lambda proxy e CORS. Le funzionalità esclusive delle REST API che giustificherebbero il prezzo più alto (API key, usage plan, request validation, AWS WAF) non sono in uso; il caching non riduce le richieste fatturate.","optionExplanations":["Le richieste servite dalla cache vengono comunque fatturate come chiamate API e la cache aggiunge un costo orario, quindi il costo per richiesta non diminuisce.","I Network Load Balancer non possono usare funzioni Lambda come target e non forniscono autorizzazione JWT.","Un'API privata è raggiungibile solo dai VPC, quindi i client pubblici non potrebbero più chiamarla, e si applicano comunque i prezzi delle REST API.","Corretto — le HTTP API supportano nativamente JWT authorizer, integrazioni Lambda proxy e CORS a un prezzo per richiesta significativamente inferiore rispetto alle REST API."]},
  "1425": {"h":"7f343741","question":"Un'azienda esegue un cluster Amazon Redshift di nodi DC2. Il team continua ad aggiungere nodi solo perché il cluster sta esaurendo lo storage, mentre l'utilizzo della CPU resta basso. Circa l'80% dei dati ha più di un anno e viene interrogato poche volte a trimestre, ma gli analisti devono comunque poterlo interrogare in SQL insieme ai dati recenti. Quale combinazione di azioni ridurrà MAGGIORMENTE i costi? (Seleziona DUE)","options":["Migrare il cluster su nodi RA3 in modo che lo storage scali nel managed storage indipendentemente dal calcolo.","Abilitare il concurrency scaling in modo che le query di picco girino su cluster transitori aggiuntivi.","Spostare i dati storici su un'istanza Amazon RDS for PostgreSQL con storage gp3.","Scaricare i dati storici su Amazon S3 in formato Parquet e interrogarli con Redshift Spectrum.","Acquistare reserved node triennali per il numero attuale di nodi DC2."],"explanation":"Il cluster è limitato dallo storage, quindi separare lo storage dal calcolo (RA3 con managed storage) e spostare i dati interrogati raramente su S3 (interrogati tramite Redshift Spectrum) eliminano entrambi la necessità di nodi aggiuntivi, mantenendo l'accesso SQL a tutti i dati. I reserved node applicherebbero solo uno sconto a un'architettura dimensionata in modo errato.","optionExplanations":["Corretto — i nodi RA3 separano il calcolo da Redshift Managed Storage, quindi il cluster può essere dimensionato per le sue basse esigenze di calcolo anziché per lo storage.","Il concurrency scaling aggiunge calcolo per i picchi di query; non serve a nulla per un cluster limitato dallo storage e può aumentare i costi.","Aggiunge un altro database da gestire e impedisce agli analisti di interrogare insieme dati vecchi e recenti in SQL su Redshift.","Corretto — i dati freddi su S3 costano molto meno dello storage del cluster e Redshift Spectrum consente agli analisti di metterli in join con i dati recenti nelle stesse query SQL.","La prenotazione vincolerebbe un cluster sovradimensionato per il calcolo solo per contenere lo storage, invece di eliminare i nodi in eccesso."]},
  "1426": {"h":"32984afa","question":"Un'azienda usa AWS Organizations e assegna a ogni sviluppatore un account sandbox in una OU Sandbox. Di recente alcuni sviluppatori hanno avviato grandi istanze GPU in diverse Region che l'azienda non usa, e alcune sono rimaste in esecuzione inosservate per settimane. L'azienda vuole impedirlo in modo centralizzato per tutti gli account sandbox attuali e futuri, consentendo comunque tipi di istanza piccoli nelle Region approvate. Quale combinazione di azioni soddisferà questi requisiti? (Seleziona DUE)","options":["Creare in ogni account sandbox un avviso AWS Budgets che invia un'email allo sviluppatore quando la spesa è elevata.","Associare alla OU Sandbox una SCP che nega le azioni al di fuori delle Region approvate.","Associare alla OU Sandbox una SCP che nega l'avvio di tipi di istanza EC2 non presenti in un elenco consentito.","Creare nel management account un IAM permissions boundary che limita i tipi di istanza.","Abilitare in ogni account i controlli di AWS Trusted Advisor per segnalare le istanze inattive e costose."],"explanation":"Le service control policy associate a una OU sono il controllo centralizzato e preventivo ereditato da tutti gli account al suo interno, compresi quelli nuovi. Una SCP limita le Region e un'altra limita i tipi di istanza consentiti; Budgets e Trusted Advisor rilevano la spesa solo dopo che è avvenuta.","optionExplanations":["Gli avvisi di budget notificano solo dopo che il denaro è stato speso e vanno configurati per ogni account, quindi non impediscono gli avvii.","Corretto — una SCP sulla OU si applica automaticamente a ogni account sandbox attuale e futuro e blocca la creazione di risorse nelle Region non approvate.","Corretto — questo guardrail preventivo blocca i tipi di istanza costosi, come le istanze GPU, in tutti gli account sandbox, consentendo i tipi piccoli approvati.","I permissions boundary si applicano solo ai principal IAM dell'account in cui sono associati, quindi un boundary nel management account non limita gli account membri.","Trusted Advisor è un controllo detective e per singolo account; segnala i problemi quando le istanze sono già in esecuzione."]},
  "1427": {"h":"efae8bd0","question":"Un'azienda ha 120 account in AWS Organizations. Lo scorso trimestre un job configurato male in un account ha generato un picco di costi di trasferimento dati, notato solo all'arrivo della fattura mensile. I modelli di spesa variano molto tra account e servizi, quindi mantenere soglie fisse per ciascuno è impraticabile. L'azienda vuole ricevere un avviso entro un giorno in caso di spesa anomala, con il MINIMO overhead operativo. Quale soluzione soddisferà questi requisiti?","options":["Configurare monitor di AWS Cost Anomaly Detection per gli account collegati con sottoscrizioni agli avvisi.","Creare AWS Budgets con soglie mensili fisse per ogni combinazione di account e servizio in uso.","Esportare il Cost and Usage Report su Amazon S3 e creare query giornaliere di rilevamento anomalie in Athena.","Creare allarmi di fatturazione Amazon CloudWatch sulla metrica degli addebiti stimati per l'organizzazione."],"explanation":"AWS Cost Anomaly Detection apprende i valori di riferimento della spesa per account, servizio o cost category e invia avvisi quando la spesa se ne discosta, il che si adatta a modelli molto variabili senza soglie da mantenere. AWS Budgets è la scelta allettante, ma richiede una soglia fissa per ogni ambito.","optionExplanations":["Corretto — Cost Anomaly Detection usa il machine learning per apprendere la spesa normale di ogni account e servizio e segnala i picchi anomali senza soglie impostate manualmente.","Centinaia di soglie fisse andrebbero mantenute manualmente, cosa che l'azienda ha già giudicato impraticabile.","Sviluppare e mantenere una logica personalizzata di rilevamento anomalie richiede molto più impegno operativo di un servizio gestito.","Gli allarmi di fatturazione usano soglie statiche sugli addebiti totali e non possono rilevare un andamento anomalo in un singolo account o servizio."]},
  "1428": {"h":"e5fc489b","question":"Un team QA ha bisogno ogni mattina di una copia aggiornata di un database Amazon Aurora compatibile con PostgreSQL di produzione da 10 TB per eseguire per alcune ore test distruttivi. Oggi uno script ripristina l'ultimo snapshot in un nuovo cluster, operazione che richiede ore e duplica l'intero storage finché la copia esiste. I test modificano solo una piccola parte dei dati. Quale soluzione ridurrà MAGGIORMENTE costi e tempi di preparazione?","options":["Aggiungere un'Aurora Replica al cluster di produzione ed eseguire su di essa i test QA.","Creare ogni mattina un clone Aurora del cluster di produzione ed eliminarlo dopo i test.","Esportare uno snapshot giornaliero su Amazon S3 e caricarlo in un nuovo cluster per ogni esecuzione dei test.","Usare AWS DMS per replicare continuamente la produzione in un cluster QA permanente con provisioning separato."],"explanation":"Il fast database cloning di Aurora crea in pochi minuti una copia scrivibile che condivide le pagine di storage con l'origine, quindi lo storage viene consumato solo per i dati modificati: ideale per test distruttivi di breve durata. Un'Aurora Replica si crea rapidamente, ma è di sola lettura e fa parte del cluster di produzione.","optionExplanations":["Le Aurora Replica sono di sola lettura e condividono lo storage di produzione, quindi non vi si possono eseguire test distruttivi e potrebbero influire sulle prestazioni della produzione.","Corretto — il cloning di Aurora usa il copy-on-write, quindi il clone viene creato rapidamente e solo le pagine modificate dai test consumano storage aggiuntivo.","Esportare e ricaricare 10 TB ogni giorno è più lento di un ripristino da snapshot e crea comunque una copia completa dei dati.","Un cluster permanente a dimensione piena costa di più e i test distruttivi entrerebbero in conflitto con la replica in corso."]},
  "1429": {"h":"8975247e","question":"Un team di sicurezza abilita i VPC Flow Logs per 200 VPC e li pubblica in Amazon CloudWatch Logs. I flow log vengono usati solo per indagini occasionali, eseguite come query SQL su pochi giorni o settimane di dati, e devono essere conservati per 1 anno. Ingestion e storage dei flow log in CloudWatch Logs sono diventati un costo rilevante. Quale soluzione è la PIÙ conveniente?","options":["Continuare a pubblicare in CloudWatch Logs e impostare un periodo di retention di 1 anno su tutti i log group dei flow log.","Continuare a pubblicare in CloudWatch Logs ed esportare ogni giorno i log group su Amazon S3.","Pubblicare i flow log direttamente su Amazon S3 in formato Parquet e interrogarli con Athena.","Inviare i flow log ad Amazon OpenSearch Service e mantenere i dati più vecchi in UltraWarm."],"explanation":"I VPC Flow Logs possono essere pubblicati direttamente su S3 in Apache Parquet con partizioni orarie compatibili con Hive, il che elimina l'ingestion in CloudWatch Logs e rende le query Athena economiche e veloci. Impostare la retention in CloudWatch Logs aiuta sullo storage, ma lascia invariati i costi di ingestion.","optionExplanations":["La retention limita la crescita dello storage, ma i costi di ingestion di CloudWatch Logs, la voce principale, rimangono.","I log vengono comunque prima acquisiti in CloudWatch Logs, quindi i costi di ingestion restano e si aggiunge un processo di export.","Corretto — consegnare i flow log direttamente a S3 evita l'ingestion in CloudWatch Logs, Parquet con partizioni riduce i costi di storage e di scansione delle query, e Athena addebita solo quando si eseguono indagini.","Un dominio OpenSearch sempre attivo è costoso per dati interrogati solo occasionalmente."]},
  "1430": {"h":"499cd389","question":"Un'applicazione invia grandi volumi di log di debug dettagliati ad Amazon CloudWatch Logs. Gli ingegneri usano questi log solo per analizzare gli incidenti con query di CloudWatch Logs Insights; nessun metric filter, subscription filter o allarme dipende da essi. I costi di ingestion di questi log sono la parte più grande della fattura CloudWatch e i log devono restare ricercabili in CloudWatch. Quale soluzione ridurrà i costi con il MINIMO sforzo?","options":["Inviare in streaming i log di debug su Amazon S3 tramite Data Firehose e interrogarli con Athena.","Ridurre il periodo di retention dei log group di debug da 30 a 7 giorni.","Pubblicare l'output di debug come metriche personalizzate in embedded metric format anziché come log.","Inviare i log di debug a nuovi log group che usano la log class Infrequent Access."],"explanation":"La log class Infrequent Access di CloudWatch Logs è pensata per log conservati per query ad hoc e analisi forensi: l'ingestion costa meno e Logs Insights continua a funzionare. Ridurre la retention è la scelta allettante, ma non riduce i costi di ingestion che dominano la fattura.","optionExplanations":["I log non sarebbero più ricercabili in CloudWatch e il team dovrebbe realizzare una nuova configurazione di consegna e interrogazione.","La retention incide solo sui costi di storage, mentre qui il costo dominante è l'ingestion.","Le metriche non possono sostituire le righe di log dettagliate necessarie per il troubleshooting, e le metriche personalizzate ad alta cardinalità hanno un proprio costo.","Corretto — la log class Infrequent Access ha un prezzo di ingestion più basso e supporta comunque le query di Logs Insights; non offre funzionalità come i metric filter, che questi log non usano."]},
  "1431": {"h":"22b38c7d","question":"Un'azienda di videogiochi memorizza i profili dei giocatori in una tabella Amazon DynamoDB in modalità di capacità provisioned. Durante i tornei, qualche migliaio di profili popolari viene letto milioni di volte al minuto e il team continua ad aumentare la capacità di lettura per evitare il throttling, con costi elevati. Le letture possono essere eventually consistent e l'applicazione deve continuare a usare l'API DynamoDB con modifiche minime al codice. Quale soluzione è la PIÙ conveniente?","options":["Aggiungere un cluster DynamoDB Accelerator (DAX) davanti alla tabella per servire le letture ripetute.","Passare la tabella alla modalità di capacità on-demand in modo che le letture scalino automaticamente.","Creare global secondary index per distribuire tra le partizioni le letture dei profili popolari.","Aggiungere un cluster Amazon ElastiCache e riscrivere l'accesso ai dati con logica cache-aside."],"explanation":"DAX è una cache in memoria write-through che usa la stessa API di DynamoDB, quindi le letture ripetute degli item più richiesti vengono servite senza consumare capacità di lettura della tabella e con modifiche minime al codice. Anche ElastiCache potrebbe assorbire le letture, ma richiede codice cache-aside personalizzato.","optionExplanations":["Corretto — DAX è compatibile con l'API di DynamoDB e serve dalla memoria le letture ripetute eventually consistent, quindi la tabella non necessita più di capacità di lettura per gli item più richiesti.","La modalità on-demand addebita comunque ogni richiesta di lettura, il che è più costoso della capacità provisioned con questo volume sostenuto.","Gli indici aggiungono costi di storage e di scrittura e non riducono il numero di letture degli stessi item più richiesti.","Il caching funzionerebbe, ma richiede di riscrivere il livello di accesso ai dati, a differenza di DAX, che usa l'API DynamoDB."]},
  "1432": {"h":"04038a5b","question":"Un'azienda prevede di migrare su AWS 600 VM VMware on-premises e ha bisogno di un business case per il management. Molte VM sono state dimensionate anni fa per i carichi di picco e sono poco utilizzate. Il management vuole una stima dei costi AWS basata sull'utilizzo misurato dei server, con raccomandazioni di istanze correttamente dimensionate e opzioni di licenza, prima di avviare qualsiasi attività di migrazione. Quale soluzione soddisferà questi requisiti con il MINIMO sforzo?","options":["Associare vCPU e memoria allocate a ogni VM a un'istanza EC2 equivalente in AWS Pricing Calculator.","Usare AWS Migration Evaluator per raccogliere i dati di utilizzo e produrre un assessment correttamente dimensionato.","Migrare un campione di server con AWS Application Migration Service ed estrapolarne i costi.","Eseguire AWS Compute Optimizer sui server on-premises per ottenere raccomandazioni di rightsizing."],"explanation":"AWS Migration Evaluator è pensato per i business case pre-migrazione: usa l'utilizzo effettivo dei server on-premises per raccomandare istanze correttamente dimensionate e stimare i costi, inclusi scenari di licenza come il BYOL. Compute Optimizer fornisce raccomandazioni simili, ma solo per workload già presenti in AWS.","optionExplanations":["Le risorse allocate sovrastimano le esigenze delle VM poco utilizzate, e associare manualmente 600 VM richiede un impegno notevole.","Corretto — Migration Evaluator raccoglie i dati di utilizzo on-premises e produce un business case con raccomandazioni EC2 correttamente dimensionate e opzioni di licenza.","Richiede attività di migrazione prima dell'approvazione, e un campione non riflette l'utilizzo di tutte le 600 VM.","Compute Optimizer analizza solo le risorse già in esecuzione in AWS, non i server on-premises."]},
  "1433": {"h":"3634a2ce","question":"Un'azienda esegue una build farm Jenkins autogestita su sei grandi istanze EC2 On-Demand attive 24/7. Le build avvengono a raffiche durante l'orario di lavoro, le istanze restano inattive la maggior parte delle notti e dei fine settimana e gli ingegneri dedicano tempo all'applicazione delle patch ai build server. L'azienda vuole ridurre costi e manutenzione mantenendo i propri script di build containerizzati. Quale soluzione soddisferà questi requisiti?","options":["Acquistare un EC2 Instance Savings Plan triennale che copra le sei istanze di build.","Consolidare la build farm su un numero minore di istanze On-Demand più grandi che restano sempre in esecuzione.","Eseguire le build in AWS CodeBuild in modo che il calcolo sia fatturato solo per i minuti di esecuzione delle build.","Eseguire gli agent Jenkins come pod Amazon EKS su un managed node group dimensionato per il carico di picco."],"explanation":"I workload di build a raffiche si adattano a un servizio gestito con pagamento a consumo: AWS CodeBuild esegue le build in immagini container e fattura solo i minuti di build, quindi tempi di inattività e patching scompaiono. Un Savings Plan abbassa la tariffa, ma fa comunque pagare ogni ora di inattività.","optionExplanations":["Abbassa la tariffa oraria, ma si continua a pagare per istanze inattive e i server richiedono ancora patch.","Le istanze consolidate resterebbero comunque inattive di notte e nei fine settimana e richiederebbero ancora patch.","Corretto — CodeBuild è un servizio di build gestito che esegue le build in container e addebita per minuto di build, eliminando la capacità inattiva e il patching dei server.","Un node group dimensionato per il picco è inattivo la maggior parte del tempo e aggiunge la gestione del cluster."]},
  "1434": {"h":"fbd36210","question":"Un'azienda esegue decine di microservizi su un cluster Amazon EKS che usa managed node group con un insieme fisso di tipi di istanza grandi. I nodi lavorano spesso a basso utilizzo perché i pod sono distribuiti in modo sparso. La maggior parte dei servizi è stateless e tollera le interruzioni. L'azienda vuole ridurre i costi di calcolo con il MINIMO sforzo manuale continuativo. Quale soluzione soddisferà questi requisiti?","options":["Esaminare ogni settimana l'utilizzo dei nodi e ridimensionare manualmente i managed node group.","Abilitare il Kubernetes Horizontal Pod Autoscaler per ogni deployment del cluster.","Spostare ogni microservizio su profili AWS Fargate in modo che non restino worker node da gestire.","Usare Karpenter con la consolidation abilitata e consentire tipi di istanza diversi, inclusi gli Spot."],"explanation":"Karpenter effettua il provisioning di nodi adatti ai pod in attesa scegliendo da un'ampia gamma di tipi di istanza, consolida continuamente i nodi sottoutilizzati e può usare istanze Spot per i workload che tollerano le interruzioni, il tutto senza tuning manuale. L'Horizontal Pod Autoscaler scala i pod, non l'efficienza dei nodi sottostanti.","optionExplanations":["Il ridimensionamento manuale settimanale richiede un impegno continuo e reagisce lentamente ai cambiamenti della domanda dei pod.","L'Horizontal Pod Autoscaler cambia il numero di pod, ma non ricompatta i pod su nodi meno numerosi o più economici.","Fargate su EKS addebita per pod con un sovrapprezzo e non supporta Spot per EKS, quindi i microservizi a carico costante possono costare di più.","Corretto — Karpenter avvia nodi correttamente dimensionati, consolida i pod su meno nodi e può usare automaticamente capacità Spot per i pod che tollerano le interruzioni."]},
  "1435": {"h":"0349a051","question":"Un'azienda usa Amazon FSx for Windows File Server con storage SSD in un deployment Multi-AZ per le home directory di 3.000 dipendenti. I dati sono per lo più documenti d'ufficio con molte copie duplicate, l'accesso è leggero e la capacità di storage è la principale voce di costo. Il file system deve restare Multi-AZ e mantenere l'accesso SMB con integrazione Active Directory. Quale soluzione è la PIÙ conveniente?","options":["Spostare i dati su un nuovo file system Multi-AZ con storage HDD e abilitare la deduplicazione dei dati.","Migrare le home directory su Amazon S3 e dare agli utenti accesso tramite la console S3.","Passare il file system a un deployment Single-AZ mantenendo lo storage SSD.","Migrare le home directory su Amazon EFS e usare la lifecycle management per spostarle in EFS Infrequent Access."],"explanation":"Per workload leggeri guidati dalla capacità, lo storage HDD di FSx for Windows File Server è l'opzione più economica, e la deduplicazione dei dati riduce in genere in modo significativo lo spazio occupato dalle condivisioni di file di uso generale. Anche il Single-AZ ridurrebbe i costi, ma viola il requisito di disponibilità indicato.","optionExplanations":["Corretto — lo storage HDD costa molto meno per GB ed è adatto a workload leggeri, e la deduplicazione elimina le copie duplicate, mantenendo Multi-AZ, SMB e integrazione AD.","S3 non fornisce condivisioni di file SMB con permessi Active Directory per le home directory.","Viola il requisito di restare Multi-AZ, e lo storage SSD resta la componente costosa.","Amazon EFS fornisce accesso NFS e non supporta SMB con integrazione Active Directory per i client Windows."]},
  "1436": {"h":"d8362884","question":"Un team di ricerca esegue una volta al mese, durante un fine settimana, una grande simulazione HPC. Il dataset di input è archiviato in Amazon S3, il job necessita di un file system POSIX condiviso ad alto throughput per centinaia di nodi di calcolo e alla fine i risultati vengono riscritti su S3. Oggi un file system persistente contenente una copia completa dei dati resta attivo tutto il mese. Quale soluzione è la PIÙ conveniente?","options":["Usare un file system Amazon EFS in modalità Max I/O mantenuto tra un'esecuzione mensile e l'altra.","Creare per ogni esecuzione un file system FSx for Lustre scratch collegato al bucket, poi eliminarlo.","Mantenere il file system FSx for Lustre persistente e ridurne il throughput tra un'esecuzione e l'altra.","Montare il bucket su ogni nodo di calcolo con Mountpoint for Amazon S3 ed eseguire lì tutto l'I/O della simulazione."],"explanation":"I file system FSx for Lustre scratch sono pensati per elaborazioni a breve termine e ad alto throughput, e il collegamento al data repository S3 importa i dati di input ed esporta i risultati, quindi il file system può esistere solo per la durata del job. Un file system persistente fattura lo storage per tutto il mese anche quando è inattivo.","optionExplanations":["EFS continua ad addebitare l'intero dataset per tutto il mese e non offre il throughput di Lustre per questo workload HPC.","Corretto — un file system Lustre scratch collegato a S3 carica i dati per l'esecuzione, esporta i risultati su S3 e non costa nulla una volta eliminato dopo il fine settimana.","Lo storage viene comunque fatturato per tutto il mese per un file system usato solo un fine settimana.","Mountpoint for Amazon S3 non fornisce la piena semantica POSIX, come la modifica dei file sul posto, richiesta dai workload HPC condivisi."]},
  "1437": {"h":"dc5288b5","question":"Un livello applicativo mantiene una cache locale da 2 TB su ogni istanza EC2, memorizzata su volumi Amazon EBS io2 con IOPS provisioned elevati. La cache viene ricostruita automaticamente da Amazon S3 a ogni avvio di un'istanza, quindi perderla causa solo un breve periodo di riscaldamento. Le istanze girano in un Auto Scaling group su due Availability Zone. Quale modifica ridurrà i costi mantenendo un accesso alla cache a latenza molto bassa?","options":["Sostituire i volumi io2 con volumi st1 della stessa dimensione per ridurre il prezzo dello storage.","Spostare la cache su un file system Amazon EFS condiviso montato da tutte le istanze.","Usare un tipo di istanza con volumi instance store NVMe e mantenere lì la cache.","Mantenere i volumi io2 ed eseguire snapshot giornalieri in modo che le cache possano essere ripristinate più velocemente."],"explanation":"I dati rigenerabili non hanno bisogno di uno storage a blocchi durevole: l'instance store NVMe offre IOPS molto elevati e bassa latenza senza costi aggiuntivi oltre all'istanza. I volumi st1 costano meno per GB, ma sono basati su HDD e non adatti a una cache ad accesso casuale.","optionExplanations":["I volumi Throughput Optimized HDD hanno latenza elevata per l'I/O casuale, il che vanifica lo scopo di una cache a bassa latenza.","Un file system di rete aggiunge latenza rispetto allo storage locale e comporta comunque costi di storage.","Corretto — l'instance store è incluso nel prezzo dell'istanza e offre latenza molto bassa; la perdita dei dati in caso di arresto o guasto è accettabile perché la cache viene ricostruita.","Gli snapshot aggiungono costi e non riducono i costosi addebiti per gli IOPS provisioned."]},
  "1438": {"h":"3c346d00","question":"Un'azienda esegue un'applicazione di business su Amazon RDS for SQL Server Enterprise Edition (License Included) in un deployment Multi-AZ. Un'analisi mostra che il database non usa funzionalità esclusive della Enterprise e richiede meno core e meno memoria dei limiti della Standard Edition. L'azienda deve mantenere l'alta disponibilità Multi-AZ ed evitare modifiche all'applicazione, e prevede di usare il database per altri 3 anni. Quale soluzione è la PIÙ conveniente?","options":["Acquistare Reserved Instances triennali per l'attuale istanza DB Enterprise Edition.","Migrare ad Aurora compatibile con PostgreSQL con Babelfish per eliminare le licenze SQL Server.","Spostare il database su EC2 Dedicated Hosts e licenziare SQL Server Enterprise Edition per core fisico.","Passare a RDS for SQL Server Standard Edition in Multi-AZ e acquistare Reserved Instances."],"explanation":"Quando non si usano funzionalità esclusive della Enterprise e le esigenze di risorse rientrano nei limiti della Standard Edition, passare alla Standard Edition elimina il forte sovrapprezzo della licenza Enterprise mentre RDS mantiene la disponibilità Multi-AZ; le Reserved Instances scontano poi l'utilizzo costante. Le sole Reserved Instances continuano a pagare la licenza Enterprise ogni ora.","optionExplanations":["Le Reserved Instances scontano l'istanza, ma il costo molto più alto della licenza Enterprise Edition incluso nel prezzo rimane.","Babelfish richiede test di compatibilità ed eventuali modifiche al codice, in contrasto con il requisito di evitare modifiche all'applicazione.","Mantiene la licenza Enterprise e aggiunge l'amministrazione di SQL Server autogestito e della sua alta disponibilità.","Corretto — la Standard Edition License Included costa molto meno della Enterprise, supporta Multi-AZ su RDS e le Reserved Instances riducono ulteriormente il costo costante su 3 anni."]},
  "1439": {"h":"5e101427","question":"Un'azienda replica un intero bucket S3 da 2 PB in un'altra Region con S3 Cross-Region Replication per il disaster recovery e archivia le repliche in S3 Standard. Solo gli oggetti sotto il prefisso contracts/ sono critici per il business e devono essere recuperabili nella seconda Region; tutti gli altri dati possono essere rigenerati. Le repliche vengono lette solo durante un disastro, quando è comunque richiesto un recupero in millisecondi. Quale combinazione di azioni ridurrà MAGGIORMENTE i costi soddisfacendo questi requisiti? (Seleziona DUE)","options":["Sostituire la Cross-Region Replication con la Same-Region Replication verso un secondo bucket.","Abilitare S3 Transfer Acceleration sul bucket di origine per ridurre i costi di replica.","Aggiungere un filtro alla regola di replica in modo che venga replicato solo il prefisso contracts/.","Impostare S3 Glacier Deep Archive come storage class di destinazione delle repliche.","Impostare S3 Glacier Instant Retrieval come storage class di destinazione delle repliche."],"explanation":"Le regole di replica possono essere limitate per prefisso o tag e possono scrivere le repliche direttamente in una storage class più economica. Replicare solo contracts/ e archiviare le repliche in S3 Glacier Instant Retrieval mantiene l'accesso in millisecondi per la copia di DR letta raramente; Deep Archive costerebbe meno, ma non rispetta il tempo di recupero.","optionExplanations":["Una copia nella stessa Region non protegge da un disastro a livello di Region.","Transfer Acceleration serve per upload e download dei client su lunghe distanze, aggiunge costi e non si applica alla replica.","Corretto — replicare solo il prefisso critico elimina il trasferimento tra Region e lo storage delle repliche per i dati rigenerabili.","Il recupero da Deep Archive richiede ore, il che viola il requisito di recupero in millisecondi durante un disastro.","Corretto — Glacier Instant Retrieval ha un costo di storage molto più basso per i dati letti raramente e restituisce comunque gli oggetti in millisecondi."]},
  "1440": {"h":"d42354c7","question":"Un'azienda collega 40 VPC in una Region tramite un AWS Transit Gateway. Due di essi, un VPC di analytics e un VPC di ingestion dei dati, si scambiano centinaia di terabyte al mese, e i costi di elaborazione dati del transit gateway per questo traffico dominano la fattura di rete. Tutti gli altri VPC devono mantenere la connettività e il routing centralizzato esistenti. Quale soluzione è la PIÙ conveniente?","options":["Creare una VPC peering connection tra i due VPC e instradarvi il traffico reciproco.","Creare un secondo transit gateway dedicato al traffico tra i due VPC.","Sostituire il transit gateway con VPC peering connection tra tutti i 40 VPC.","Instradare il traffico tra i due VPC attraverso una connessione AWS Site-to-Site VPN."],"explanation":"Transit Gateway addebita per GB elaborato, mentre il VPC peering non ha costi di elaborazione, quindi una peering connection mirata per l'unica coppia ad alto volume è l'opzione più economica; il transit gateway mantiene il routing centralizzato per tutto il resto. Sostituire completamente il transit gateway violerebbe il requisito di routing.","optionExplanations":["Corretto — il VPC peering non ha costi di elaborazione dati, quindi spostare sul peering solo la coppia con traffico elevato elimina la maggior parte del costo, mentre il transit gateway continua a servire tutti gli altri VPC.","Ogni transit gateway addebita attachment ed elaborazione dati, quindi questo non elimina i costi di elaborazione.","Una full mesh di centinaia di peering connection è difficile da gestire e rinuncia al routing centralizzato che va mantenuto.","Le connessioni VPN aggiungono costi orari, limitano il throughput e fanno comunque passare il traffico da un gateway, quindi non sono né più economiche né più veloci."]},
  "1441": {"h":"b8863950","question":"Un'applicazione memorizza gli item delle sessioni utente in una tabella Amazon DynamoDB. Le sessioni scadono dopo 24 ore e un job notturno esegue la scansione dell'intera tabella ed elimina gli item scaduti, consumando grandi quantità di capacità di lettura e scrittura. Gli item scaduti non devono essere rimossi in un momento preciso, ma non devono mai essere restituiti agli utenti. Quale soluzione ridurrà i costi con il MINIMO overhead operativo?","options":["Eseguire il job di pulizia ogni ora anziché ogni notte, in modo che ogni esecuzione elimini meno item.","Abilitare DynamoDB TTL su un attributo di scadenza e filtrare gli item scaduti in lettura.","Creare ogni giorno una nuova tabella ed eliminare la tabella che contiene le sessioni del giorno precedente.","Aggiungere un global secondary index sull'orario di scadenza in modo che il job possa eseguire query anziché scansioni."],"explanation":"Il Time to Live di DynamoDB rimuove automaticamente gli item scaduti senza costi di capacità di scrittura; poiché l'eliminazione può essere ritardata, l'applicazione filtra gli item il cui orario di scadenza è già passato. Un GSI renderebbe più economico trovare gli item scaduti, ma si pagherebbe comunque ogni eliminazione e l'indice stesso.","optionExplanations":["Il numero totale di scansioni ed eliminazioni, e quindi la capacità consumata, resta uguale o aumenta.","Corretto — il TTL elimina gli item scaduti in background senza consumare capacità di scrittura, e un filtro in lettura copre gli item non ancora eliminati.","Ruotare le tabelle aggiunge complessità operativa e interrompe le sessioni a cavallo della mezzanotte.","L'indice aggiunge costi di scrittura e di storage, e le eliminazioni consumano comunque capacità di scrittura."]},
  "1442": {"h":"5f04008b","question":"Ogni notte un team di dati esegue un job Spark che effettua la scansione di una tabella Amazon DynamoDB da 5 TB in modalità provisioned per generare report in Amazon S3. Per evitare il throttling dell'applicazione di produzione, il team aumenta la capacità di lettura per diverse ore ogni notte, il che è diventato costoso. I report possono usare i dati aggiornati alla notte precedente. Quale soluzione ridurrà i costi con il MINIMO impatto sulla produzione?","options":["Passare la tabella alla modalità di capacità on-demand durante la finestra della scansione notturna.","Creare una replica global table in un'altra Region ed eseguire la scansione sulla replica.","Usare DynamoDB export to S3 dal point-in-time recovery e interrogare i dati esportati.","Aggiungere un cluster DAX in modo che la scansione completa notturna sia servita dalla cache."],"explanation":"DynamoDB export to S3 legge dai backup di point-in-time recovery, quindi non consuma capacità di lettura e non ha alcun impatto sulle prestazioni della tabella; Athena o Spark possono poi elaborare i dati esportati in S3. La modalità on-demand evita la pianificazione della capacità, ma addebita comunque ogni lettura della scansione completa.","optionExplanations":["La modalità on-demand addebita comunque ogni lettura della scansione da 5 TB e condivide la tabella con il traffico di produzione.","Una replica aggiunge costi di scrittura replicata e di storage e consuma comunque capacità di lettura per la scansione.","Corretto — gli export usano i dati del point-in-time recovery e non consumano capacità di lettura della tabella, quindi la produzione non ne risente e la capacità per la scansione non serve più.","Una scansione completa legge quasi ogni item una volta, quindi una cache non offre alcun vantaggio e aggiunge il costo del cluster."]},
  "1443": {"h":"2ffd5bc4","question":"Un'azienda acquisisce eventi di clickstream in Amazon Kinesis Data Streams con shard provisioned. Una funzione AWS Lambda legge lo stream solo per raggruppare i record in batch e scriverli su Amazon S3 per interrogarli in seguito; non ci sono altri consumer e un ritardo di consegna di qualche minuto è accettabile. Il team dedica tempo al resharding dello stream al variare del traffico. Quale soluzione ridurrà MAGGIORMENTE costi e overhead operativo?","options":["Passare il data stream alla modalità di capacità on-demand e mantenere la funzione Lambda.","Sostituire la funzione Lambda con una flotta di consumer EC2 che usano la Kinesis Client Library.","Abilitare l'enhanced fan-out in modo che la funzione Lambda legga con throughput dedicato.","Inviare gli eventi ad Amazon Data Firehose, che li bufferizza e li consegna direttamente su S3."],"explanation":"Quando l'unico scopo di uno stream è far arrivare i dati su S3 con una latenza di minuti, Amazon Data Firehose gestisce da solo buffering, batching e consegna, senza shard o codice consumer da gestire. Kinesis on-demand elimina il resharding, ma si continua a pagare uno stream più un consumer personalizzato.","optionExplanations":["Il resharding scompare, ma si continuano a pagare e mantenere sia lo stream sia la funzione Lambda.","Eseguire consumer EC2 aggiunge server da gestire e non elimina i costi dello stream.","L'enhanced fan-out aggiunge costi ed è utile solo con più consumer che richiedono bassa latenza.","Corretto — Firehose è completamente gestito, scala automaticamente, bufferizza e raggruppa i record su S3 e sostituisce sia lo stream sia la funzione Lambda."]},
  "1444": {"h":"749bf493","question":"Un'azienda usa workflow Standard di AWS Step Functions per orchestrare un processo di arricchimento degli ordini che viene eseguito milioni di volte al giorno. Ogni esecuzione si completa in pochi secondi, chiama tre funzioni Lambda ed è idempotente, quindi un'esecuzione at-least-once è accettabile. I costi delle state transition sono diventati una parte consistente della fattura. Quale soluzione ridurrà i costi con il MINIMO sforzo?","options":["Trasformare le state machine in workflow Express di Step Functions.","Sostituire la state machine con code Amazon SQS tra le tre funzioni Lambda.","Unire le tre funzioni Lambda in un'unica funzione e mantenere il workflow Standard.","Aumentare la memoria delle funzioni Lambda in modo che ogni esecuzione termini più velocemente."],"explanation":"I workflow Express sono pensati per l'elaborazione di eventi ad alto volume e di breve durata e vengono fatturati in base a esecuzioni, durata e memoria anziché alle state transition; la loro semantica at-least-once è accettabile per lavori idempotenti. Unire le funzioni riduce in parte le transizioni, ma richiede modifiche al codice e usa comunque il modello di prezzo costoso.","optionExplanations":["Corretto — i workflow Express sono tariffati in base al numero di esecuzioni e alla durata anziché per state transition, il che si adatta a esecuzioni brevi, idempotenti e ad alto volume.","Richiede di riprogettare l'orchestrazione e la gestione degli errori, con uno sforzo molto maggiore.","Unire le funzioni richiede modifiche al codice e si paga comunque per ogni state transition.","I workflow Standard sono fatturati per state transition, non per durata, quindi funzioni più veloci non riducono questi costi."]},
  "1445": {"h":"1a08aca1","question":"Le funzioni AWS Lambda rivolte ai clienti di un'azienda usano una provisioned concurrency impostata al livello richiesto dal picco dell'orario lavorativo, 24 ore al giorno. Il traffico è prevedibile: alto dalle 8 alle 20 e molto basso di notte, quando qualche cold start occasionale è accettabile. L'azienda vuole evitare i cold start durante l'orario lavorativo. Quale soluzione ridurrà MAGGIORMENTE i costi soddisfacendo questo requisito?","options":["Rimuovere la provisioned concurrency e affidarsi sempre alla concurrency on-demand.","Usare azioni di scaling pianificate per applicare la provisioned concurrency solo durante l'orario lavorativo.","Impostare sulle funzioni una reserved concurrency pari al livello di picco dell'orario lavorativo.","Mantenere la provisioned concurrency costante tutto il giorno e acquistare un Compute Savings Plan per coprirne il costo."],"explanation":"La provisioned concurrency può essere gestita con Application Auto Scaling, comprese le azioni pianificate, in modo da applicarla solo durante il picco prevedibile dell'orario lavorativo. Un Savings Plan abbassa il prezzo della configurazione sempre attiva, ma fa comunque pagare capacità non necessaria durante la notte.","optionExplanations":["Si verificherebbero cold start durante l'orario lavorativo, il che viola il requisito.","Corretto — lo scaling pianificato mantiene le funzioni pre-inizializzate durante il picco prevedibile ed elimina i costi della provisioned concurrency durante la notte.","La reserved concurrency limita e garantisce solo la concurrency; non pre-inizializza gli ambienti di esecuzione, quindi i cold start restano.","Un Savings Plan sconta la tariffa, ma pagare una provisioned concurrency inutilizzata per metà di ogni giornata comporta uno spreco molto maggiore."]},
  "1446": {"h":"46e693c4","question":"Un'azienda di e-commerce esegue il proprio livello web su una flotta fissa di 30 istanze EC2 dimensionata per il picco serale giornaliero. Il traffico segue un andamento giornaliero e settimanale costante, e le nuove istanze impiegano circa 10 minuti per avviarsi e riscaldarsi, quindi uno scaling puramente reattivo causa risposte lente all'inizio della crescita serale. L'azienda vuole ridurre i costi senza peggiorare le prestazioni. Quale soluzione soddisferà questi requisiti?","options":["Usare una simple scaling policy basata sull'utilizzo della CPU con un breve periodo di cooldown.","Eseguire l'intera flotta fissa su Spot Instances per ridurre il costo della flotta dimensionata per il picco.","Usare il predictive scaling nell'Auto Scaling group insieme a una target tracking policy.","Ridurre la flotta alla dimensione necessaria per il carico medio e affidarsi al load balancer durante i picchi."],"explanation":"Il predictive scaling usa il carico storico per pianificare la capacità in anticipo rispetto alla domanda ciclica, il che risolve il problema del lungo riscaldamento, e il target tracking reagisce ai cambiamenti imprevisti; insieme eliminano il costo di mantenere tutto il giorno la capacità di picco. Un semplice scaling reattivo fa risparmiare, ma è in ritardo sulle crescite del mattino e della sera.","optionExplanations":["Lo scaling reattivo inizia ad avviare istanze solo dopo l'aumento del carico, quindi i 10 minuti di riscaldamento causano ancora risposte lente.","La flotta resterebbe dimensionata per il picco tutto il giorno e le interruzioni Spot potrebbero degradare un livello web rivolto ai clienti.","Corretto — il predictive scaling prevede l'andamento ricorrente e avvia capacità prima della crescita, mentre il target tracking gestisce gli scostamenti, quindi la flotta si riduce fuori dal picco.","Un load balancer non aggiunge capacità, quindi la flotta sottodimensionata peggiorerebbe le prestazioni nel picco."]},
  "1447": {"h":"cf0b25c1","question":"Un'azienda ha 60 VPC distribuiti su diversi account, tutti collegati a un transit gateway in una Region. Ogni VPC ha i propri interface VPC endpoint per gli stessi 12 servizi AWS in tre Availability Zone, e i costi orari degli endpoint sono ormai significativi. Il traffico verso questi servizi è moderato e i workload devono continuare a raggiungerli in modo privato senza attraversare internet. Quale soluzione è la PIÙ conveniente?","options":["Eliminare gli interface endpoint e inviare il traffico verso i servizi AWS tramite NAT gateway in ogni VPC.","Sostituire tutti gli interface endpoint con gateway VPC endpoint in ogni VPC.","Mantenere gli endpoint in ogni VPC, ma distribuire ciascun endpoint in una sola Availability Zone per ridurre i costi orari.","Centralizzare gli endpoint in un VPC di servizi condivisi e condividere il DNS tramite private hosted zone di Route 53."],"explanation":"Centralizzare gli interface endpoint in un VPC di servizi condivisi, raggiungibile tramite il transit gateway esistente e risolto attraverso private hosted zone di Route 53 associate a tutti i VPC, elimina la maggior parte dei costi orari duplicati degli endpoint mantenendo il traffico privato. Con un traffico moderato, i costi aggiuntivi di elaborazione del transit gateway sono inferiori alle ore di endpoint eliminate.","optionExplanations":["Il traffico userebbe gli endpoint pubblici dei servizi sul percorso internet, violando il requisito di accesso privato, e i NAT gateway aggiungono costi propri.","I gateway endpoint esistono solo per Amazon S3 e DynamoDB, non per gli altri servizi.","Si pagano comunque 60 copie di ogni endpoint e l'accesso dipende da una sola Availability Zone.","Corretto — un unico set di endpoint raggiunto tramite il transit gateway sostituisce 60 copie, e le private hosted zone condivise permettono a ogni VPC di risolvere verso di essi i nomi dei servizi."]},
  "1448": {"h":"1ff3c898","question":"Un'azienda esegue il backup dei server on-premises su una tape library fisica con il software di backup esistente e spedisce i nastri a un caveau esterno. La manutenzione dell'hardware a nastro e i costi del caveau sono elevati, i backup più vecchi di 90 giorni non vengono quasi mai ripristinati e i ripristini dei backup vecchi possono richiedere fino a 2 giorni. L'azienda vuole mantenere il proprio software e i propri processi di backup. Quale soluzione è la PIÙ conveniente?","options":["Distribuire Tape Gateway e archiviare i nastri virtuali più vecchi in S3 Glacier Deep Archive.","Distribuire S3 File Gateway e far scrivere al software di backup i file di backup su una condivisione SMB.","Sostituire la tape library con un array di dischi on-premises e replicarlo su Amazon EBS.","Spedire ogni mese i dati di backup in S3 Standard con dispositivi AWS Snowball Edge."],"explanation":"Tape Gateway sostituisce i nastri fisici con nastri virtuali senza modificare l'applicazione di backup, e archiviare i nastri in S3 Glacier Deep Archive offre il costo di storage più basso con recupero entro la finestra accettata di 2 giorni. Anche S3 File Gateway raggiungerebbe S3, ma imporrebbe il passaggio da processi di backup su nastro a processi basati su file.","optionExplanations":["Corretto — Tape Gateway presenta una tape library virtuale al software di backup esistente, e i nastri archiviati in Deep Archive sono lo storage più economico con recupero entro la finestra di 2 giorni.","Passare da destinazioni a nastro a condivisioni di file modifica i job e i processi di backup, che l'azienda vuole mantenere.","Richiede nuovo hardware e costoso storage a blocchi per backup ripristinati raramente.","Le spedizioni mensili di dispositivi aggiungono un impegno continuo, e S3 Standard è costoso per dati che non vengono quasi mai ripristinati."]},
  "1449": {"h":"0f4302a3","question":"Un'azienda esegue ogni notte decine di job ETL Spark di AWS Glue per preparare i dati per report necessari il pomeriggio successivo. I job non sono urgenti ed è accettabile che partano più tardi o durino di più quando la capacità è limitata. L'azienda vuole ridurre i costi di Glue senza riscrivere i job. Quale soluzione soddisferà questi requisiti?","options":["Riscrivere i job come job Python shell eseguiti su un unico worker piccolo.","Eseguire i job con la execution class AWS Glue Flex anziché con quella standard.","Spostare i job su un cluster Amazon EMR sempre attivo che usa istanze On-Demand.","Aumentare il numero di worker di ciascun job in modo che i job terminino più velocemente."],"explanation":"AWS Glue Flex è pensato per ETL non urgenti come la preparazione notturna e i test: i job girano su capacità di calcolo inutilizzata a una tariffa più bassa e possono partire più tardi o durare di più. Aggiungere worker accorcia solo le esecuzioni, mentre la capacità fatturata resta uguale o aumenta.","optionExplanations":["Richiede di riscrivere i job Spark e potrebbe non reggere il volume di dati.","Corretto — la execution class Flex esegue i job non urgenti su capacità inutilizzata a un prezzo più basso, accettando tempi di avvio e di esecuzione variabili, senza modifiche al codice.","Un cluster permanente resta inattivo per gran parte della giornata e richiede migrazione e gestione del cluster.","Più worker aumentano la capacità fatturata per esecuzione, quindi il totale delle DPU-ore non diminuisce."]},
  "1450": {"h":"729a7263","question":"Un'azienda esegue un'applicazione web su otto grandi istanze EC2 On-Demand in due Availability Zone dietro un Application Load Balancer, dimensionate due anni fa per un evento di lancio. L'utilizzo medio della CPU è ora inferiore al 10%, il traffico varia moderatamente durante la giornata, le sessioni sono memorizzate in Amazon ElastiCache e l'applicazione deve restare disponibile in caso di guasto di una Availability Zone. Quale combinazione di azioni ridurrà i costi soddisfacendo questi requisiti? (Seleziona DUE)","options":["Spostare tutte le istanze in un'unica Availability Zone per eliminare il trasferimento dati cross-AZ.","Sostituire la flotta con tipi di istanza più piccoli in un Auto Scaling group distribuito su entrambe le AZ.","Eseguire l'intera flotta su Spot Instances da un unico pool di istanze per massimizzare lo sconto.","Aggiungere una target tracking scaling policy con una capacità minima che mantenga istanze in entrambe le AZ.","Acquistare Reserved Instances triennali per le otto istanze attuali."],"explanation":"La flotta è fortemente sovradimensionata, quindi il risparmio maggiore deriva da istanze più piccole e dal lasciare che un Auto Scaling group adegui la capacità alla domanda, con un minimo che mantenga istanze in esecuzione in entrambe le AZ. Le Reserved Instances sulla flotta attuale applicherebbero uno sconto a capacità di cui l'applicazione non ha bisogno.","optionExplanations":["Un'unica AZ viola il requisito di restare disponibili in caso di guasto di una Availability Zone.","Corretto — il rightsizing su istanze più piccole corrisponde al basso utilizzo, e la distribuzione su entrambe le AZ preserva la disponibilità.","Un unico pool Spot può essere recuperato tutto in una volta, mettendo potenzialmente offline l'intera applicazione.","Corretto — il target tracking aggiunge e rimuove istanze al variare del traffico giornaliero, e il minimo mantiene capacità in ogni AZ per la disponibilità.","La prenotazione vincolerebbe per tre anni una flotta sovradimensionata invece di eliminare la capacità in eccesso."]},
};
